/* ÇEVİRİ it · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("it","olay",{
"KRONOLOJI_COK_ARABISTAN2:1538-01-01:0":{"b": ["Hadramaut diventa sanjak ottomano — l'amministrazione interna resta ai capi Kasīrī", "d80f8d20"], "d": ["L'Hadramaut, entrato sotto amministrazione ottomana durante la campagna d'India di Hadım Süleyman Pascià, fu organizzato come sanjak dipendente dallo Yemen. Tuttavia all'interno dell'Hadramaut l'amministrazione restò di fatto nelle mani dei capi della tribù Kasīrī; il dominio ottomano rimase limitato alla costa e al vincolo fiscale.", "93dd8a13"]},
"KRONOLOJI_COK_ARABISTAN2:1659-01-01:0":{"b": ["L'imam zaydita al-Mutawakkil Allāh invade l'Hadramaut — il Sultanato Kasīrī è legato all'imamato dello Yemen", "21ad9c85"], "d": ["Dopo il ritiro ottomano dallo Yemen nel 1635, l'imamato zaydita, rafforzatosi, inviò un esercito ai tempi dell'imam al-Mutawakkil Allāh e invase l'Hadramaut. Così il dominio dei Kasīrī nell'Hadramaut interno rimase per quasi mezzo secolo soggetto all'imamato dello Yemen; quando, nella prima metà del XVIII secolo, l'influenza degli imam e dei Kasīrī si indebolì, l'amministrazione passò di nuovo alle tribù locali.", "e5a06ff4"]},
"KRONOLOJI_COK_ARABISTAN2:1835-01-01:0":{"b": ["'Abd Allāh b. Rashīd prende l'emirato di Ha'il alla famiglia Ibn 'Alī — nasce l'Emirato Shammar (Rashīdide)", "357cc1a0"], "d": ["'Abd Allāh b. Rashīd, appartenente al ramo più grande della tribù Shammar, quello degli 'Abda, vinse nel 1835, insieme al fratello 'Ubayd, la lotta avviata contro la famiglia Ibn 'Alī, che governava Ha'il, e prese l'emirato. Ha'il, per la sua posizione sulla via commerciale e di pellegrinaggio tra Mesopotamia e Hegiaz, divenne il centro del dominio dei Rashīdidi sul Gebel Shammar, destinato a durare fino al 1921.", "dc0300b5"]},
"OLAYLAR:1299-01:0":{"b": ["Fondazione del beylik ottomano", "9f0b7c0a"], "d": ["L'inizio dell'autonomia di Osman Gazi, della tribù dei Kayı, nella regione di Söğüt e Domaniç è considerato per tradizione l'avvio della fondazione dello Stato ottomano; alcuni storici ritengono invece la vittoria di Bapheus del 1302 il vero punto di svolta. Grazie alla sua posizione sul confine bizantino, il beylik crebbe rapidamente in forza con le incursioni dei ghazi. In questo contesto di dissoluzione dell'eredità selgiuchide, Osman Gazi raccolse attorno a sé ahi, ghazi e turcomanni nomadi; il legame con lo sceicco Edebali è considerato il fondamento della legittimità spirituale del beylik. Altri luoghi annessi nella stessa data: İnegöl, Yarhisar.", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["Conquista di Bursa", "98c727fa"], "d": ["Bursa, tenuta sotto blocco per anni, si arrese a Orhan Gazi, che guidò la fase finale dell'assedio; la città divenne la prima grande capitale del beylik. Si narra che la notizia della conquista sia stata portata a Osman Gazi sul letto di morte; per sua volontà Osman Gazi fu sepolto a Bursa. In breve tempo la città fu dotata di moschee, imaret e madrase e divenne il modello dell'urbanistica ottomana delle origini.", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["Conquista di İznik", "a846a811"], "d": ["İznik (Nicea), uno dei più importanti centri bizantini in Anatolia, perduta ogni speranza di resistere dopo la vittoria di Pelekanon del 1329, si arrese a Orhan Gazi. Qui fu fondata la prima madrasa ottomana e studiosi come Dâvûd-i Kayserî vi iniziarono a insegnare; la città divenne il centro del sapere del primo periodo. La chiesa di Santa Sofia fu trasformata in moschea, un esempio precoce della tradizione della conquista.", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["Conquista di İzmit", "06a35035"], "d": ["Con la caduta di İzmit (Nicomedia) anche l'ultima importante fortezza bizantina sulla sponda anatolica passò sotto il dominio ottomano; l'intera penisola di Kocaeli, fino alla riva opposta a Costantinopoli, divenne territorio ottomano. Il beylik, dominando così tutte le coste meridionali e orientali del Marmara, preparò le basi del passaggio in Rumelia.", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["Fortezza di Çimpe — il passaggio in Rumelia", "c2f0a07d"], "d": ["Süleyman Paşa, figlio di Orhan Gazi, aveva fatto della fortezza di Çimpe, concessa durante la guerra civile bizantina, la propria base nel 1352; dopo il grande terremoto che nel marzo 1354 distrusse Gallipoli, le fortezze rimaste vuote furono rapidamente fortificate e la penisola divenne una testa di ponte ottomana stabile. Sostenuto dall'insediamento di popolazione turcomanna condotta dall'Anatolia, questo passo segna l'inizio di una presenza ottomana sul continente europeo destinata a superare i 550 anni.", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["Conquista di Edirne", "2f54ebb0"], "d": ["La presa di Edirne (Adrianopoli), città chiave della Tracia, determinò la base principale e la direzione delle conquiste balcaniche; la data della conquista è controversa nelle fonti, tra il 1361 e il 1369. Poco dopo la città fu fatta capitale, annunciando lo spostamento del baricentro dello Stato verso la Rumelia; rimase capitale per circa 90 anni, fino alla conquista di Costantinopoli.", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["Murad I salì al trono", "f8d48a26"], "d": ["Murad I (Hüdavendigâr), salito al trono con la morte di Orhan Gazi, nei 27 anni del suo regno portò lo Stato da beylik di frontiera a ossatura di impero. Con il sistema del pençik fu posta la base del corpo dei Giannizzeri, il sistema del timar fu esteso, fu istituito il Beylerbeylik di Rumelia e fu rafforzata l'istituzione del vizirato. Le conquiste balcaniche divennero sotto di lui una politica statale sistematica.", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["Prima battaglia di Kosovo — il martirio di Murad I", "10b8ddc9"], "d": ["L'alleanza balcanica guidata dal knez Lazar fu sconfitta in modo decisivo nella Piana del Kosovo; la Serbia entrò sotto la sovranità ottomana. Murad I, che percorreva il campo di battaglia, fu pugnalato dal nobile serbo Miloš Obilić e cadde martire: è l'unico sultano ottomano morto sul campo di battaglia. Nell'accampamento gli succedette Yıldırım Bayezid; il fratello Yakub Çelebi fu fatto strangolare, uno dei primi esempi noti di fratricidio dinastico.", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["Vittoria di Nicopoli", "75716e96"], "d": ["Il grande esercito crociato, riunito per l'appello del re ungherese Sigismondo e al quale parteciparono anche cavalieri francesi e borgognoni, fu duramente sconfitto da Yıldırım Bayezid davanti a Nicopoli, sulle rive del Danubio. La vittoria consolidò il dominio ottomano sulla Bulgaria; in Europa per una generazione non fu possibile organizzare una grande crociata.", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["Battaglia di Ankara — inizio del Fetret Devri", "b4a99d96"], "d": ["Nella pesante sconfitta subita nella piana di Çubuk contro l'esercito di Tamerlano, Yıldırım Bayezid fu fatto prigioniero e morì in prigionia pochi mesi dopo. Tamerlano fece rivivere i beylik anatolici; i territori ottomani furono spartiti tra i figli di Bayezid e iniziò una lotta per il trono destinata a durare 11 anni (Fetret Devri). Questo periodo, la crisi più grave dalla fondazione dello Stato, impresse nella memoria ottomana l'importanza della struttura centralizzata. Altri insediamenti perduti nella stessa data: Datça, Marmaris, Fethiye (Makri), Söke, Kütahya, Afyon, Isparta, Manisa, Aydın, Denizli, Muğla, Antalya, Konya, Karaman, Kayseri, Kastamonu, Bartın, Safranbolu, Samsun, Sivas, Malatya, Beyşehir, Sivrihisar, Kırşehir, Çorum, Çankırı, Yenişehir (Bursa), İnegöl, Aydos Kalesi, Geyve, Köprühisar (Yenişehir), Marmaracık, Akhisar (Pamukova), Mekece, Kestel, Ulubat, Harmankaya, Akyazı, İmralı Adası, Kandıra, Mudanya, Yalova, Karamürsel, Armutlu, Gemlik (Kios), Söğüt, Bilecik, Eskişehir, Bursa, İznik, İzmit, Balıkesir, Çanakkale, Bergama, Amasya, Tokat, Çorlu, Lüleburgaz, Malkara, Keşan, İpsala, Kilitbahir, Çirmen, Eski Zağra (Stara Zagora), Tatarpazarcığı, İhtiman, Köstendil, Petriç, Nevrokop (Gotse Delçev), Drama, Gelibolu, Çimpe, Edirne, Dimetoka, Kırklareli, Tekirdağ, Filibe, Sofya, Niş, Vidin, Tırnova, Varna, Şumnu, Silistre, Niğbolu, Rusçuk, Selanik, Serez, Kavala, Üsküp, Manastır, Ohri, Yenişehir (Larissa), Tırhala, İzdin (Lamia), Plevne, Gümülcine, Biga, Domaniç, Kulacahisar, Karacahisar, Yarhisar, Dimbos, Kite (Kete), Lefke (Osmaneli), Leblebicihisar, Karaçepüş, Karatigin, Absu (Hypsu), Adranos (Orhaneli), Pelekanon (Eskihisar), Gebze, Hereke, Samandıra, Kirmasti (M.Kemalpaşa), Mihaliç (Karacabey), Köstence, Gölyazı (Apollonia).", "d34e55d5"]},
"OLAYLAR:1413-07-05:0":{"b": ["Çelebi Mehmed ricostituì l'unità", "03413dfd"], "d": ["Sconfitto Mûsâ Çelebi a Çamurlu nel regolamento di conti finale tra i fratelli, Mehmed I riunì i territori del paese sotto un'unica amministrazione; per questo è considerato il «secondo fondatore dello Stato». Durante il suo regno la struttura statale logorata fu riparata, i rapporti con i beylik anatolici furono riequilibrati e in Rumelia fu seguita una cauta politica di pace.", "d8f535c2"]},
"OLAYLAR:1416-05-01:0":{"b": ["Rivolta dello sceicco Bedreddin", "e0a072ca"], "d": ["Il movimento religioso e sociale sviluppatosi attorno allo sceicco Bedreddin, grande giurista e mistico che era stato kazasker durante il Fetret Devri, esplose in contemporanea con le rivolte di Börklüce Mustafa a Karaburun e di Torlak Kemal a Manisa. Le rivolte furono represse nel sangue; Bedreddin, catturato nel Deliorman, fu giustiziato a Serez. L'evento lasciò una traccia profonda nella letteratura e nella storiografia come la più antica grande rivolta sociale e mahdista della storia ottomana.", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["Vittoria di Varna", "f739eedc"], "d": ["L'esercito crociato ungaro-polacco, che aveva rotto il trattato di Seghedino e marciava verso sud, fu annientato a Varna da Murad II, tornato alla testa dell'esercito dopo l'abdicazione; il giovane re Ladislao III morì sul campo di battaglia. La vittoria eliminò l'ultima grande possibilità di intervento esterno volto a liquidare la presenza ottomana nei Balcani e mise al sicuro la strada verso la conquista di Costantinopoli.", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["Seconda battaglia di Kosovo", "ebe0b662"], "d": ["L'esercito di Giovanni Hunyadi, che voleva vendicare Varna, fu sconfitto in modo decisivo da Murad II in tre giorni di aspra battaglia. È l'ultima grande battaglia campale intrapresa dai crociati contro gli Ottomani nei Balcani; con la vittoria il dominio ottomano a sud del Danubio si consolidò in modo ormai irreversibile.", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["Conquista di Costantinopoli", "583d5e3e"], "d": ["Dopo un assedio durato cinquantaquattro giorni (6 aprile–29 maggio 1453), la mattina del 29 maggio l'esercito ottomano superò le mura ed entrò in città; l'ultimo imperatore, Costantino XI, morì nei combattimenti e l'Impero romano d'Oriente, vecchio di 1100 anni, scomparve dalla storia. Il giovane sultano assunse il titolo di «Fâtih», fece della città la capitale e trasformò Santa Sofia in moschea; la città fu presto rianimata da insediamenti e ricostruzioni. Secondo il TDV, Silivri e Vize furono conquistate definitivamente solo nel 1453; secondo la voce Limni del TDV, l'isola entrò sotto l'amministrazione ottomana subito dopo la conquista e fu lasciata alla famiglia Gattilusio a condizione di un tributo. Nell'atlante Silivri, Vize e Limni sono registrate in questo giorno come passate da Bisanzio agli Ottomani (Limni tributaria). La fusione di cannoni giganteschi, il trasporto delle navi via terra e lo schieramento d'assedio davanti alle mura sono considerati il vertice dell'ingegneria militare dell'epoca. Nella storiografia europea la conquista è tra le date simbolo della fine del Medioevo.", "d4b39486"]},
"OLAYLAR:1461-08-15:0":{"b": ["Conquista di Trebisonda", "15f52403"], "d": ["Al termine della difficile campagna del Mar Nero condotta da Mehmed il Conquistatore simultaneamente con esercito e flotta, l'Impero greco di Trebisonda si arrese; con la liquidazione di quest'ultimo residuo del mondo bizantino in Anatolia, l'intera costa meridionale del Mar Nero entrò sotto il dominio ottomano. La fine della dinastia dei Comneni rafforzò la pretesa del Conquistatore di essere «sovrano di due mari e due terre». Altri luoghi annessi nella stessa data: Giresun, Rize.", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["Conquista definitiva di Silifke — spezzata l'ultima resistenza dei Karamanidi", "d988bee4"], "d": ["La fortezza di Silifke si era arresa una volta a Gedik Ahmed Paşa nel 1472, ma nello stesso anno il karamanide Kasım Bey, con l'aiuto della flotta crociata nel Mediterraneo, l'aveva ripresa. Dopo la vittoria di Otlukbeli, il Conquistatore incaricò suo figlio e Gedik Ahmed Paşa di impadronirsi definitivamente della regione; con l'aiuto degli antichi artiglieri ottomani il deposito di polvere fu incendiato e la fortezza cadde rapidamente. Così fu spezzata l'ultima resistenza dei Karamanidi sulle montagne del Taşeli e dell'İçel; la liquidazione del beylik sarebbe stata completata nel 1474.", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["Battaglia di Otlukbeli", "42c7194e"], "d": ["Uzun Hasan, sovrano degli Aqquyunlu divenuto una grande potenza a oriente e alleato di Venezia, fu duramente sconfitto a Otlukbeli dall'esercito del Conquistatore, dotato di armi da fuoco. La vittoria consolidò la supremazia ottomana in Anatolia e fu anche una prova precoce della superiorità di un esercito centrale che impiegava cannoni e fucili contro un esercito classico. Secondo la voce Gümüşhane del TDV, la città era sotto il dominio degli Aqquyunlu dal 1467; tale dominio terminò con la sconfitta di Otlukbeli e Gümüşhane passò definitivamente sotto il dominio ottomano.", "63e0811f"]},
"OLAYLAR:1475-06-06:0":{"b": ["La Crimea passa sotto la protezione ottomana", "44e3f7c8"], "d": ["La flotta al comando di Gedik Ahmed Paşa conquistò le città della costa meridionale della Crimea, a cominciare da Kefe, in mano ai Genovesi; queste coste furono rese sancak direttamente ottomano. Il Khanato di Crimea, con Mengli Giray, divenne invece uno Stato vassallo privilegiato che riconosceva la sovranità ottomana e per tre secoli fu un pilastro della politica settentrionale; il Mar Nero si trasformò di fatto in un mare interno ottomano. Altri luoghi annessi nella stessa data: Bahçesaray, Kerç, Azak.", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["Morte del Conquistatore — la questione del principe Cem", "190ecf01"], "d": ["Alla morte improvvisa del Conquistatore durante la campagna salì al trono Bayezid II; il fratello Cem Sultan, avanzando pretese al sultanato, fece leggere la khutba e coniare moneta a suo nome a Bursa. Sconfitto, si rifugiò prima presso i Mamelucchi, poi presso i cavalieri di Rodi; divenuto nelle mani dei cavalieri e del papato una carta di scambio della diplomazia europea, Cem morì a Napoli nel 1495. Questo episodio costrinse la politica estera ottomana alla cautela per quindici anni.", "7e488d7b"]},
"OLAYLAR:1514-08-23:0":{"b": ["Vittoria di Çaldıran", "fea64ebb"], "d": ["Selim I il Severo, volendo risolvere alla radice la minaccia creata in Anatolia dalla propaganda safavide, sconfisse duramente nella piana di Çaldıran l'esercito dello shah Ismail grazie alla superiorità di cannoni e fucili. Si entrò a Tabriz; l'Anatolia orientale e sud-orientale e la linea Mosul-Diyarbakır furono incorporate nell'amministrazione ottomana. Con l'impegno di İdrîs-i Bitlisî, il legame dei principi curdi con gli Ottomani stabilì il quadro del confine orientale per i secoli a venire.", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["Vittoria di Marj Dabiq", "07d254d3"], "d": ["L'esercito mamelucco fu disperso in poche ore a Marj Dabiq, a nord di Aleppo; l'anziano sultano Qansuh al-Ghawri morì durante la battaglia. Con la vittoria che spalancò le porte di Aleppo e Damasco, Siria, Libano e Palestina passarono sotto il dominio ottomano; si aprì la strada alla campagna d'Egitto che avrebbe posto fine al Sultanato mamelucco.", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["Ridaniye — conquista dell'Egitto e califfato", "caf378d6"], "d": ["L'esercito ottomano, attraversato rapidamente il deserto del Sinai, sfondò a Ridaniye la linea difensiva di Tumanbay ed entrò al Cairo; Tumanbay, che continuava la resistenza, fu catturato e giustiziato e il Sultanato mamelucco scomparve dalla storia. Egitto, Hegiaz e città sante entrarono sotto il dominio ottomano; il califfo abbaside e le sacre reliquie furono portati a Costantinopoli. Con il passaggio del califfato alla dinastia ottomana, i sultani assunsero la pretesa di guida del mondo islamico; il controllo della Via delle Spezie procurò inoltre all'impero grandi entrate. Altri luoghi annessi nella stessa data: Akkâ, Maan, Sayda, Kerak.", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["Solimano il Legislatore salì al trono", "f6512269"], "d": ["Il regno di 46 anni di Solimano I, salito al trono come unico figlio maschio alla morte di Selim il Severo, è considerato l'apice politico, militare, giuridico e culturale dell'impero. I kanunname, che sistematizzarono il diritto consuetudinario, gli valsero il titolo di «Kanunî» (il Legislatore); in Occidente fu chiamato «il Magnifico». Le opere dell'architetto Sinan, l'età d'oro della letteratura di divan e la supremazia della flotta nel Mediterraneo sono i simboli di questo periodo.", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["Conquista di Belgrado", "59ef5cec"], "d": ["Belgrado, che il Conquistatore non aveva potuto prendere nel 1456 e che era considerata la «chiave dell'Europa centrale», cadde nella prima campagna di Solimano dopo un assedio alla confluenza di Danubio e Sava. La linea difensiva meridionale dell'Ungheria crollò; con questa conquista si aprì la porta della campagna in Europa centrale, che si estese a Mohács cinque anni dopo e all'annessione di Buda vent'anni dopo.", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["Conquista di Rodi", "807bbb1e"], "d": ["Rodi, base dei cavalieri di San Giovanni che minacciavano le rotte marittime del Mediterraneo orientale e la via dei pellegrini, si arrese per patto dopo un sanguinoso assedio durato mesi; ai cavalieri fu permesso di lasciare liberamente l'isola (si sarebbero poi stabiliti a Malta). Fu assicurata la sicurezza delle coste anatoliche e la linea marittima Costantinopoli-Egitto passò sotto ininterrotto controllo ottomano.", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["Battaglia di Mohács", "f3418b0d"], "d": ["L'esercito ungherese fu annientato nella piana di Mohács in circa due ore dal fuoco dell'artiglieria e dalla superiorità di manovra; il re Luigi II morì in una palude mentre fuggiva. Mohács, una delle grandi battaglie campali vinte più rapidamente nella storia ottomana, pose di fatto fine al regno ungherese indipendente e aprì in Europa centrale l'epoca della rivalità ottomano-asburgica.", "48967894"]},
"OLAYLAR:1529-09-27:0":{"b": ["Primo assedio di Vienna", "dc49ea4f"], "d": ["Nella campagna organizzata contro le mire asburgiche sul trono ungherese l'esercito ottomano assediò Vienna; per l'abbandono dei cannoni pesanti lungo la strada, l'inverno precoce e le difficoltà di vettovagliamento l'assedio fu tolto dopo tre settimane. Pur non essendo stata presa la città, l'influenza ottomana sull'Ungheria fu mantenuta; le porte di Vienna indicarono il limite dell'accesso logistico dell'impero in Europa centrale.", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["Conquista di Baghdad — campagna dei Due Iraq", "897092c3"], "d": ["Nella campagna condotta sui «due Iraq» (Iraq arabo e Iraq persiano) si entrò prima a Tabriz, poi senza combattere a Baghdad; la presa dell'antica capitale degli Abbasidi diede al sovrano ottomano grande prestigio nel mondo islamico. Fu restaurato il mausoleo dell'Imam-ı Âzam Abu Hanifa; con l'annessione di Baghdad e Bassora i territori ottomani raggiunsero il Golfo Persico. Altri luoghi annessi nella stessa data: Kerkük, Kerbelâ.", "f3f80434"]},
"OLAYLAR:1538-09-28:0":{"b": ["Vittoria navale di Prevesa", "30dc0f97"], "d": ["La flotta crociata costituita sotto la guida del papa, benché numericamente superiore, fu dispersa al largo di Prevesa dalla tattica di Barbarossa, che sfruttò con maestria vento e costa; Andrea Doria abbandonò il campo di battaglia. La vittoria stabilì una supremazia navale ottomana incontrastata nel Mediterraneo destinata a durare circa 33 anni; è la data simbolo della Giornata della Marina nella tradizione marinara turca. Altri luoghi annessi nella stessa data: Aden, Bender.", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["Annessione di Buda — l'Ungheria provincia ottomana", "db53b244"], "d": ["Partito in campagna per l'assedio asburgico di Buda, Solimano, dopo aver liberato la città, pose l'Ungheria centrale sotto amministrazione ottomana diretta istituendo il Beylerbeylik di Buda; la Transilvania fu invece resa principato autonomo vassallo degli Ottomani. Questo assetto dell'Ungheria divisa in tre durò circa 150 anni e costituì l'ossatura stabile del governo ottomano in Europa centrale.", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["Pace di Amasya", "a5afe0d1"], "d": ["È il primo trattato di pace ufficiale che pose fine alle guerre ottomano-safavidi durate anni. Baghdad e l'Iraq rimasero agli Ottomani, il confine dell'Anatolia orientale fu per la prima volta riconosciuto reciprocamente; i Safavidi si impegnarono a fermare la propaganda sciita nel territorio ottomano e gli Ottomani a garantire la sicurezza di transito dei pellegrini iraniani. Il trattato fu il primo esempio del quadro giuridico delle relazioni tra i due Stati.", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["Szigetvár — la morte di Solimano", "e2917ed2"], "d": ["Solimano, settantaduenne, morì nella sua tenda pochi ore prima della caduta della fortezza di Szigetvár, che assediava nella sua tredicesima campagna; Sokullu Mehmed Paşa nascose la morte per settimane perché l'esercito non si disperdesse. La fortezza fu presa, ma lo Stato aveva perso il sultano dal regno più lungo e più splendido; salì al trono il figlio Selim II e il peso dei grandi visir nell'amministrazione dello Stato cominciò ad aumentare.", "62c468a1"]},
"OLAYLAR:1571-08-01:0":{"b": ["Conquista di Cipro", "e364a2b3"], "d": ["Nel 1570 fu effettuato lo sbarco a Cipro, sotto dominio veneziano; Nicosia cadde rapidamente, mentre Famagosta si arrese solo nell'agosto 1571, dopo un assedio di undici mesi. L'isola, cruciale per la sicurezza delle rotte commerciali e dei pellegrinaggi del Mediterraneo orientale, fu organizzata come beylerbeylik e vi fu insediata popolazione dall'Anatolia; la conquista fu anche il pretesto della grande alleanza crociata che sarebbe giunta a Lepanto.", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["Sconfitta di Lepanto (İnebahtı)", "6a1d44a9"], "d": ["La flotta crociata, unitasi per la conquista di Cipro, colse la flotta ottomana nel golfo di Lepanto e ne distrusse la maggior parte; il kapudan paşa Müezzinzâde Ali Paşa cadde martire e si salvò solo la squadra di Uluç Ali. Dopo il disastro il gran visir Sokullu Mehmed Paşa nominò Uluç Ali Paşa kapudan paşa affidandogli il compito di ricostituire la flotta dispersa e avviò la costruzione di una nuova flotta in tutti gli arsenali, da Costantinopoli ad Alanya; tuttavia la supremazia assoluta nel Mediterraneo era stata psicologicamente scossa.", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["Battaglia di Mezőkeresztes (Haçova)", "da308ec5"], "d": ["Nella più grande battaglia campale della Lunga Guerra (1593–1606), l'esercito guidato personalmente da Mehmed III, nel momento in cui stava per disperdersi, si riorganizzò per l'esortazione di Hoca Sâdeddin Efendi e travolse l'esercito asburgico. È considerata l'ultima grande battaglia campale classica vinta dagli Ottomani; tuttavia il fatto che non abbia mutato l'andamento generale della guerra fu visto anche come segno del logoramento del sistema militare.", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["Pace di Zsitvatorok", "39c01142"], "d": ["Con il trattato che pose fine alla logorante guerra di tredici anni, il sovrano asburgico fu per la prima volta considerato pari al sultano con il titolo di «imperatore romano» e il tributo annuale fu abolito. Le perdite territoriali furono quasi nulle; ma questo mutamento del linguaggio diplomatico è letto come il simbolo della fine della pretesa ottomana di assoluta superiorità nei confronti dell'Europa.", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["Trattato di Qasr-ı Şirin", "c1acf3af"], "d": ["Il trattato firmato dopo la riconquista di Baghdad da parte di Murad IV (1638) pose fine a oltre un secolo di guerre ottomano-safavidi. Baghdad e l'Iraq rimasero definitivamente agli Ottomani, Erevan fu lasciata ai Safavidi; la linea tracciata, con piccole modifiche, divenne la base dell'attuale confine turco-iraniano ed è considerata uno dei confini più longevi del mondo. Il trattato lasciò agli Ottomani Bedre, Cessân, Mendelî, Derteng e Derne; la fortezza di Zencir sul confine sarebbe stata demolita, i villaggi a ovest di essa sarebbero rimasti agli Ottomani, quelli a est all'Iran. L'area intorno alla fortezza di Zalim presso Şehrizor e Kızılca Kale rimasero agli Ottomani, Avroman e Mihriban all'Iran; le fortezze di Kotur, Mâkû e Mağazberd sarebbero state demolite da entrambe le parti.", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["Completata la conquista di Creta", "e0d85604"], "d": ["L'assedio di Candia, ultimo atto della guerra di Creta iniziata nel 1645, si concluse con la determinata campagna triennale di Fâzıl Ahmed Paşa; il comandante veneziano Morosini consegnò la città con un trattato. La lotta, durata circa un quarto di secolo, è registrata come il più lungo assedio della storia ottomana; anche l'ultima grande fortezza latina del Mediterraneo orientale passò sotto il dominio ottomano. Le tre piccole fortezze rocciose sulla costa settentrionale dell'isola — Suda, Spinalonga e Grabusa — rimasero ancora ai Veneziani; poiché sorgono su isolotti separati, sulla mappa non possono essere mostrate separatamente dal resto di Creta.", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["Pace di Buczacz — i confini più estesi", "b17b6e5a"], "d": ["Con la pace di Buczacz, firmata dopo la conquista di Kamianets nella campagna contro la Polonia, la Podolia fu annessa agli Ottomani e una parte dell'Ucraina fu posta sotto protezione. L'impero raggiunse così i suoi confini più ampi in Europa; questo punto è considerato l'apice e allo stesso tempo l'ultimo anello dell'epoca dell'espansione.", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["Disfatta del secondo assedio di Vienna", "7d889252"], "d": ["L'assedio di Vienna di due mesi condotto da Merzifonlu Kara Mustafa Paşa si trasformò in disfatta per l'improvviso colpo scagliato dalle colline del Kahlenberg dal re di Polonia Jan Sobieski; l'esercito si ritirò abbandonando i bagagli e Merzifonlu fu giustiziato a Belgrado. La guerra con la Lega Santa formatasi dopo la vittoria durò 16 anni; questa disfatta è indicata come il momento d'inizio del grande declino nella storia ottomana.", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["Conquista della fortezza di Grabusa — una delle fortezze rocciose di Creta rimaste ai Veneziani", "3ddf9eeb"], "d": ["Sebbene con la resa di Candia nel 1669 la conquista di Creta fosse considerata in gran parte completata, la fortezza insulare rocciosa di Grabusa, all'estremità nord-occidentale dell'isola, rimase in mano veneziana per altri ventitré anni. Con la sua presa nel 1692 fu eliminato uno dei tre residui veneziani a Creta; Suda e Spinalonga avrebbero atteso la campagna di Morea del 1715.", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["Pace di Karlowitz — la prima grande perdita territoriale", "8f7e2546"], "d": ["Con Karlowitz, che pose fine a sedici anni di guerre con la Lega Santa, Ungheria e Transilvania furono lasciate all'Austria, la Podolia alla Polonia, la Morea e le coste della Dalmazia a Venezia. Per la prima volta nella storia ottomana un territorio di tale entità andava perduto a tavolino e in modo permanente; il trattato è considerato il documento d'avvio della nuova epoca in cui l'impero passò sulla difensiva di fronte all'Europa, ed è anche una svolta della storia della diplomazia ottomana. Insediamenti che nello stesso giorno cambiano mano nell'atlante: Kostajnica e Jasenovac (dagli Ottomani agli Asburgo; il testo del trattato lascia Castanoviz nelle mani dell'imperatore, il giorno della consegna di Jasenovac non è nella fonte, è stato scritto il giorno del trattato) e Preveza (da Venezia agli Ottomani; TDV karlofca: secondo la disposizione firmata il 24 Receb 1110 / 26 gennaio 1699 furono restituiti i luoghi occupati da Venezia a nord del golfo di Lepanto). L'atlante assegna inoltre Kostayniçe (Kostajnica) e Jasenovaç al lato asburgico, Uman e Vinnitsa in Ucraina della riva destra dagli Ottomani alla Polonia (TDV merzifonlu-kara-mustafa-pasa; IEU Vinnytsia: dominio turco 1672-99) e Nadin in Dalmazia a Venezia (il giorno di consegna specifico dell'insediamento non è nella fonte, è stato scritto il giorno del trattato; gli estremi del periodo di Nadin non sono verificati con la fonte — approssimazione dichiarata). Anche Vonitsa, a nord del golfo di Lepanto, viene restituita da Venezia agli Ottomani (TDV karlofca); in Dalmazia Vrana (Urana) è tra i luoghi rimasti a Venezia (estremo del periodo non verificato — dichiarato).", "0909e24e"]},
"OLAYLAR:1711-07-19:0":{"b": ["Vittoria del Prut", "2583572f"], "d": ["Nella guerra scoppiata per la questione del re di Svezia, rifugiatosi presso gli Ottomani dopo la sconfitta di Poltava, l'esercito dello zar Pietro I, accerchiato sulle rive del Prut, dovette arrendersi. Con il trattato firmato Azov fu restituita; la decisione di non annientare l'esercito e di lasciare libero lo zar è entrata nella storia come decisione discussa fino a oggi.", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["Conquista delle fortezze di Suda e Spinalonga — cancellata l'ultima traccia veneziana a Creta", "7261f7ba"], "d": ["Ventitré anni dopo la caduta di Grabusa nel 1692, con una diramazione della campagna di Morea furono conquistate anche Suda e Spinalonga, gli ultimi due capisaldi veneziani a Creta. Così la conquista di Creta, iniziata nel 1645, fu completata dopo quarantasei anni fino all'ultimo centimetro dell'isola.", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["Rivolta di Patrona Halil", "100941a4"], "d": ["L'insuccesso sul fronte persiano, le tasse e la collera per il lusso della cerchia di palazzo si trasformarono in una grande insurrezione guidata dal bagnino Patrona Halil. Il gran visir İbrahim Paşa fu ucciso, Ahmed III fu deposto e l'Età dei Tulipani terminò; il fatto che i ribelli dominassero la città per mesi mostrò in modo impressionante la fragilità dell'autorità centrale.", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["Pace di Belgrado — la riconquista di Belgrado, Smederevo e della Serbia settentrionale", "ba7f8e46"], "d": ["Al termine della guerra condotta su due fronti contro Austria e Russia (1736–1739), Belgrado e la Serbia settentrionale furono riprese; la Russia accettò di smilitarizzare Azov e di non mantenere una flotta nel Mar Nero. Considerato l'ultimo grande successo della diplomazia e dell'esercito ottomano del XVIII secolo, il trattato procurò all'impero un periodo di pace di un quarto di secolo. Altri insediamenti che nello stesso giorno nell'atlante tornano dall'Austria agli Ottomani: Hisarcık (Grocka) (catena dell'abi-merkez di Belgrado; TDV belgrad), Krayova (Craiova), Rimnik (Râmnicu Vâlcea) e Turnu Severin (ritorno della Piccola Valacchia agli Ottomani, nel vassallaggio della Valacchia). Bosna Brod (Bosanski Brod) e Bosna Dubiça (Bosanska Dubica), sulla fascia della Sava, tornano invece agli Ottomani nell'atlante il 28 settembre 1739 (TDV bosna-hersek; TDV mahmud-i--osmanli: 28 settembre 1739). Anche Tırgu Jiu, nella Piccola Valacchia, torna agli Ottomani nello stesso giorno.", "118d49db"]},
"OLAYLAR:1770-07-06:0":{"b": ["Incursione di Çeşme", "840b30bd"], "d": ["La flotta russa, uscita nel Mediterraneo con l'appoggio degli Inglesi, assalì con brulotti la flotta ottomana rifugiata nel porto di Çeşme e la incendiò quasi per intero. La Russia apparve per la prima volta nel Mediterraneo come grande potenza navale; il disastro fu uno dei colpi che determinarono il destino della guerra conclusasi con Küçük Kaynarca nel 1774 e rese evidente la necessità di una riforma radicale della flotta.", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["Trattato di Küçük Kaynarca", "2776dcdb"], "d": ["Con Küçük Kaynarca, che pose fine alla guerra del 1768–1774 ed è considerato uno dei trattati più gravi della storia ottomana, fu concessa l'«indipendenza» al Khanato di Crimea — in pratica fu creata una sfera d'influenza russa. La Russia si insediò sulla costa del Mar Nero e ottenne il diritto di passaggio dagli Stretti per le navi mercantili e un'ambasciata permanente a Costantinopoli; la vaga clausola di protezione sui sudditi ortodossi aprì la porta ai pretesti di intervento del secolo successivo. Per la prima volta un territorio a popolazione musulmana veniva sottratto al dominio ottomano.", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["Annessione della Crimea alla Russia", "bdf6faa8"], "d": ["La Crimea «indipendente» creata da Küçük Kaynarca, con il pretesto dei disordini sotto l'ultimo khan Şahin Giray, fu annessa alla Russia con il manifesto di Caterina II. La partnership ottomano-crimeana di tre secoli finì; la perdita delle steppe settentrionali eliminò la profondità difensiva di Costantinopoli e avviò la prima grande ondata di migrazione di decine di migliaia di Tatari di Crimea verso le terre ottomane. In questo giorno la penisola di Crimea (Aluşta, Kefe, Sudak, Yalta, Balaklava, İnkirman, Mankup, Arabat) fu annessa alla Russia; Taman e Kuban passarono alla Russia con la stessa annessione (TDV Kırım: 8 aprile 1783 giuliano = 19 aprile gregoriano).", "aa59d3e1"]},
"OLAYLAR:1789-04-07:0":{"b": ["Selim III e il Nizâm-ı Cedîd", "d53aec21"], "d": ["Selim III, salito al trono in piena guerra, vedendo che le sconfitte erano strutturali, avviò un ampio programma di riforme sotto il nome di «Nizâm-ı Cedîd» (Nuovo Ordine): un nuovo esercito addestrato all'europea, un tesoro separato per finanziarlo (Îrâd-ı Cedîd), il rafforzamento delle scuole di ingegneria e le prime ambasciate permanenti nelle capitali europee. Il programma è considerato l'inizio della moderna tradizione riformatrice turca; ma per la resistenza dei corpi e degli âyân sarebbe stato abbattuto nel 1807.", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["Liquidazione dei cavalieri di Malta — tappa della flotta francese lungo la rotta", "d62f901d"], "d": ["La flotta francese diretta in Egitto fece scalo a Malta, sul suo percorso; i cavalieri di San Giovanni (di Malta) consegnarono l'isola senza grande resistenza. L'ultima fortezza dell'ordine cavalleresco, cacciato da Rodi nel 1522 e stabilitosi qui, finì così. Malta sarebbe passata all'Inghilterra due anni dopo, mentre Napoleone si diresse dall'isola direttamente ad Alessandria.", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["Occupazione dell'Egitto da parte di Napoleone", "93fede5f"], "d": ["L'esercito del generale Bonaparte sbarcò ad Alessandria e occupò l'Egitto; questa spedizione, mirante alla via dell'India dell'Inghilterra, fu il primo attacco diretto di una potenza europea ai territori centrali ottomani. L'incursione di Nelson ad Abukir e la difesa di Acri di Cezzâr Ahmed Paşa spezzarono la marcia francese; l'occupazione terminò nel 1801, ma nel vuoto lasciato iniziarono l'ascesa di Mehmed Ali Paşa di Kavala e l'epoca della «Questione d'Oriente».", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["Sened-i İttifak", "cce49ef5"], "d": ["Documento firmato tra il palazzo e le potenti famiglie di âyân di provincia sotto la guida di Alemdar Mustafa Paşa, âyân di Rusçuk che aveva portato al trono Mahmud II; mentre gli âyân si impegnavano alla fedeltà al sultano e al sostegno militare, lo Stato riconosceva la loro esistenza e i loro diritti. Essendo il primo esempio nella storia ottomana di limitazione dell'autorità del sultano tramite un documento, è considerato da alcuni storici il lontano inizio della tradizione costituzionale; in pratica perse efficacia nel giro di pochi mesi.", "2d97fdfe"]},
"OLAYLAR:1821-03-06:0":{"b": ["Inizio della rivolta greca", "a7293715"], "d": ["L'insurrezione preparata dall'organizzazione Filikí Etería scoppiò prima in Valacchia e poi, con la sua forza principale, in Morea; lo Stato, impegnato con la questione di Tepedelenli Ali Paşa, tardò a intervenire. Grazie alla forte simpatia greca dell'opinione pubblica europea (filellenismo), la rivolta si trasformò rapidamente in una causa internazionale; così fu accesa la miccia del primo movimento indipendentista riuscito dell'era del nazionalismo nelle terre ottomane. Altri insediamenti perduti nella stessa data: Atina, Balyabadra (Patrasso), İstefe (Tebe), Livadya, Eleusis (Attica), Missolonghi.", "f11097ac"]},
"OLAYLAR:1821-04-02:0":{"b": ["Primo levante armato in Morea", "77e6250f"], "d": ["Dopo il passaggio del Prut la rivolta si estese alla Morea: all'azione armata iniziata a Kalavryta (21 marzo giuliano) seguirono i movimenti di Patrasso, Kalamata e Mani; la Morea si trasformò rapidamente in un'insurrezione generale e l'amministrazione ottomana perse la maggior parte della penisola. Altri insediamenti perduti nella stessa data: Atina, Balyabadra (Patrasso), İstefe (Tebe), Livadya, Eleusis (Attica), Missolonghi.", "143953b8"]},
"OLAYLAR:1826-06-15:0":{"b": ["Vak'a-i Hayriyye — abolito il corpo dei Giannizzeri", "08c9372a"], "d": ["I giannizzeri, che avevano rovesciato le marmitte contro l'addestramento del neocostituito corpo Eşkinci, furono annientati nelle loro caserme dell'Etmeydanı dal fuoco dei cannoni delle truppe fedeli preparate in anticipo da Mahmud II; il corpo fu abolito insieme a tutte le sue sezioni e ai tekke bektashi collegati. Questa operazione, passata alla storia con il nome di «evento fausto», liquidando un'istituzione di quattro secoli aprì la strada all'esercito degli Asâkir-i Mansûre-i Muhammediyye e a tutte le successive riforme di centralizzazione.", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["Incursione di Navarino", "ee579e7f"], "d": ["La flotta ottomano-egiziana, impegnata a reprimere la rivolta greca, fu incendiata a Navarino dalla flotta combinata anglo-franco-russa entrata nel porto senza dichiarazione di guerra; andarono perduti quasi sessanta navi e migliaia di marinai. L'incursione, liquidata dalla diplomazia europea come «evento sfortunato», garantì di fatto l'indipendenza greca e aprì la strada alla guerra ottomano-russa del 1828–29.", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["Editto di Tanzimat", "5042ce7b"], "d": ["Con il Hatt-ı Hümâyun letto a Gülhane la sicurezza della vita, dei beni e dell'onore di tutti i sudditi, senza distinzione di religione, fu posta sotto garanzia dello Stato; furono proclamati i princìpi di giustizia nella tassazione, ordine nel servizio militare e nessuna pena senza processo. L'editto, opera di Mustafa Reşid Paşa, è considerato il primo grande documento di carattere costituzionale della modernizzazione ottomana e ha dato il nome all'epoca di riforme del «Periodo del Tanzimat» (1839–1876); in questo quadro furono condotte radicali ristrutturazioni dell'amministrazione, del diritto, dell'istruzione e delle finanze.", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["Inizio della guerra di Crimea", "3b9ca3c8"], "d": ["La crisi iniziata con la questione dei luoghi santi e la pretesa russa di protezione sui sudditi ortodossi si trasformò in conflitto aperto con la dichiarazione di guerra ottomana; dopo l'incursione di Sinope, Inghilterra e Francia (poi il Piemonte) entrarono in guerra dalla parte ottomana. La guerra, vinta con lo sbarco degli eserciti alleati in Crimea e la presa di Sebastopoli e conclusa con la pace di Parigi del 1856; tuttavia il primo debito estero contratto negli anni di guerra (1854) gettò l'impero in una spirale di dipendenza finanziaria destinata a durare mezzo secolo.", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["Editto di Riforma (Islahat Fermanı)", "78ff234d"], "d": ["L'editto proclamato prima dei negoziati di pace di Parigi, ampliando i princìpi del Tanzimat, riconobbe ai sudditi non musulmani ampi diritti di uguaglianza, inclusi l'impiego pubblico, il servizio militare e l'apertura di scuole; le organizzazioni comunitarie furono riordinate. Con il trattato di Parigi firmato subito dopo lo Stato ottomano fu ufficialmente ammesso alla famiglia del diritto internazionale europeo e la sua integrità territoriale fu posta sotto garanzia comune delle grandi potenze — garanzia che nella pratica sarebbe stata una nuova porta per gli interventi.", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["Kanûn-ı Esâsî — Prima Monarchia Costituzionale", "0fe052c1"], "d": ["Nel giorno dell'apertura della conferenza internazionale riunita a Costantinopoli per discutere la crisi balcanica fu proclamata con colpi di cannone la prima costituzione ottomana; con il Kanûn-ı Esâsî, opera del movimento dei «Giovani Ottomani» guidato da Midhat Paşa, fu istituito un parlamento bicamerale. Il Meclis-i Meb'ûsan fu aperto nel marzo 1877; ma Abdülhamid II, adducendo la guerra del '93, nel febbraio 1878 sospese il parlamento a tempo indeterminato e la costituzione rimase sospesa per trent'anni.", "c0f01a41"]},
"OLAYLAR:1877-04-24:0":{"b": ["Guerra del '93 (guerra russo-ottomana 1877–78)", "5bd96af7"], "d": ["Nella guerra detta «Guerra del '93» perché corrispondente all'anno rûmî 1293, gli eserciti russi attaccarono su due fronti; benché la difesa di Plevna di Gazi Osman Paşa e le battaglie del Caucaso di Ahmed Muhtar Paşa siano diventate epiche, il fronte crollò e i Russi avanzarono fino a Yeşilköy (Santo Stefano). La guerra avviò le grandi ondate di migrazione musulmana dai Balcani e dal Caucaso verso Costantinopoli, i cui effetti giungono fino a oggi; la struttura demografica e finanziaria dell'impero non tornò più com'era.", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["Trattato di Berlino", "47f76a49"], "d": ["Il Congresso di Berlino, che rivide nel nome dell'equilibrio delle grandi potenze la «Grande Bulgaria» creata da Santo Stefano, lasciò comunque un quadro pesante: Serbia, Montenegro e Romania divennero indipendenti; fu istituito il Principato autonomo di Bulgaria; Bosnia-Erzegovina fu lasciata all'occupazione austriaca, Cipro all'amministrazione inglese, Kars-Ardahan-Batum alla Russia. L'ordine ottomano di cinquecento anni in Rumelia si dissolse in gran parte; la «questione d'Oriente» divenne un tema costante della diplomazia europea. Altri insediamenti perduti nella stessa data: Filibe, Vidin, Tırnova, Varna, Şumnu, Silistre, Rusçuk, Bükreş, Yaş, Köstence. La Romania, in cambio della cessione della Bessarabia alla Russia, ottenne Tulça (Tulcea) e la Dobrugia: Tulça, Babadağı (Babadag), Maçin, İshakçı (Isaccea), Hırsova (Hârșova) e Mangalya (Mangalia), nella Dobrugia settentrionale, passarono alla Romania.", "5c7d5594"]},
"OLAYLAR:1881-05-12:0":{"b": ["Occupazione della Tunisia e Düyûn-ı Umûmiyye", "c7e25598"], "d": ["La Francia, col pretesto di incidenti sul confine algerino, occupò la Tunisia e la pose sotto il proprio protettorato con il trattato del Bardo; la presenza ottomana in Nord Africa si ridusse alla Tripolitania. Con il Decreto di Muharrem emanato nello stesso anno fu istituita l'Amministrazione del Debito Pubblico Ottomano (Düyûn-ı Umûmiyye), nella quale erano rappresentati i creditori per la gestione dei debiti esteri in bancarotta: entrate fondamentali come sale, tabacco e seta furono assegnate direttamente a questa amministrazione straniera e la sovranità finanziaria fu gravemente limitata. Altri insediamenti perduti nella stessa data: Kayrevan, Gabes, Sfaks, Cerbe (Djerba).", "64f23b86"]},
"OLAYLAR:1882-09-13:0":{"b": ["Occupazione britannica dell'Egitto", "f1269768"], "d": ["Il movimento di Urâbî Paşa, sorto in Egitto contro la bancarotta finanziaria e il controllo straniero, fu schiacciato dalla vittoria di Tell el-Kebir dell'esercito britannico sbarcato dopo il bombardamento di Alessandria, e il Cairo fu occupato. Sebbene giuridicamente l'Egitto restasse legato agli Ottomani, di fatto passò sotto amministrazione britannica; il controllo del Canale di Suez si collocò al centro della strategia imperiale britannica.", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["Proclamazione della Seconda Monarchia Costituzionale", "95ee2fd2"], "d": ["Di fronte al movimento cresciuto con la salita in montagna in Macedonia di ufficiali legati al Comitato Unione e Progresso, Abdülhamid II rimise in vigore il Kanûn-ı Esâsî; la «proclamazione della libertà» fu accolta con entusiasmo e si andò alle elezioni. Ma la stabilità non arrivò: dopo la repressione dell'Incidente del 31 Mart (aprile 1909) Abdülhamid fu deposto; in quei mesi convulsi si ebbero anche l'indipendenza della Bulgaria, l'annessione della Bosnia e l'orientamento di Creta verso la Grecia.", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["Guerra di Tripolitania", "ed441994"], "d": ["L'Italia, in cerca di colonie, dichiarò guerra alla Tripolitania, ultimo territorio ottomano in Nord Africa, e ne occupò le coste; poiché lo Stato, privo di flotta, non poteva inviare un esercito regolare, giovani ufficiali come Mustafa Kemal ed Enver Bey passarono segretamente nella regione e organizzarono con le tribù senussite una resistenza efficace. Con il trattato di Ouchy (18 ottobre 1912), firmato per lo scoppio della guerra balcanica, la Libia fu lasciata all'Italia; l'Italia occupò inoltre Rodi e il Dodecaneso.", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["Trattato di Londra — la perdita della Rumelia", "f3f976df"], "d": ["Con il trattato di Londra, che pose fine alla Prima guerra balcanica, furono perduti tutti i territori a ovest della linea Midye-Enez e le isole dell'Egeo; l'Albania divenne indipendente. Della Rumelia, per oltre cinquecento anni baricentro demografico, economico e culturale dell'impero, sarebbe rimasta solo la Tracia orientale (Edirne fu ripresa nella Seconda guerra balcanica); la perdita irrigidì radicalmente la politica di guerra e di insediamento dell'amministrazione unionista. Andarono perduti questi luoghi a ovest della linea Midye-Enez: Üsküp, Köprülü (Veles), İştip (Štip), Ustrumca, Doyran, Gevgili (Gevgelija), Manastır, Ohri, Debre (Dibra), Prizren, Priştine, Peç (Pejë), Yenipazar (Novi Pazar), Kosova Ovası (Kosovo Polje); Serez, Drama, Kavala, Petriç, Nevrokop, İskeçe, Gümülcine, Dedeağaç, Dimetoka, Çirmen, Ferecik (Feres), Sofulu (Soufli), Orestiada (Kumçiftliği), Praviște (Eleftheroupoli), Stérna, Távri, Umur Fakih (Fakia), Malak Dervent (Lalkovo); a Creta Hanya, Kandiye, Girit (Resmo), Sitiye (Sitia) e İsfakiye (Sfakia).", "b193bdae"]},
"OLAYLAR:1914-11-01:0":{"b": ["Ingresso nella Prima guerra mondiale", "05a0252e"], "d": ["L'ammissione attraverso lo Stretto, come se fossero state acquistate, delle corazzate Goeben e Breslau sfuggite agli Inglesi trascinò lo Stato passo dopo passo accanto alla Germania; con il bombardamento dei porti russi da parte della flotta al comando dell'ammiraglio Souchon (29 ottobre) la guerra iniziò di fatto e le dichiarazioni reciproche giunsero all'inizio di novembre. Nonostante la proclamazione del Cihâd-ı Ekber, l'effetto atteso non si produsse; per quattro anni l'impero si trovò in una guerra per l'esistenza su cinque diversi fronti, dal Caucaso alla Palestina.", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["Vittoria di Çanakkale", "95d888e8"], "d": ["L'armata alleata, che mirava a prendere Costantinopoli e a raggiungere la Russia, il 18 marzo fu respinta dallo Stretto dal fuoco dei campi minati e delle batterie; lo sbarramento posato dalla nave posamine Nusret decise le sorti della battaglia. Anche l'operazione terrestre di Gallipoli, iniziata in aprile, fu fermata ad Anafartalar e a Conkbayırı; gli alleati evacuarono completamente la penisola nel gennaio 1916. Il nome del tenente colonnello Mustafa Kemal si fece conoscere su questo fronte; la vittoria, ottenuta con circa un quarto di milione tra caduti e perdite, è considerata il luogo in cui nacquero i quadri e lo spirito della Guerra di Liberazione Nazionale.", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["Rivolta dello sceriffo Hussein", "75f7c58c"], "d": ["L'emiro della Mecca, lo sceriffo Hussein, dopo una corrispondenza segreta con gli Inglesi si sollevò con la promessa di un regno arabo indipendente; la ferrovia del Hegiaz divenne bersaglio di incursioni. Benché la leggendaria difesa di Medina da parte di Fahreddin Paşa, protrattasi fino a dopo l'armistizio, sia rimasta come simbolo di resistenza, la rivolta, unendosi all'avanzata britannica sul fronte della Palestina, accelerò la dissoluzione del dominio ottomano nelle province arabe. Altri insediamenti perduti nella stessa data: Tâif.", "a0e859bd"]},
"OLAYLAR:1918-10-30:0":{"b": ["Armistizio di Mudros", "9e87c767"], "d": ["Lo Stato ottomano, i cui fronti erano stati separati dal crollo della Bulgaria, uscì dalla guerra con l'armistizio firmato sulla corazzata Agamemnon. L'apertura degli Stretti e in particolare l'articolo 7, che consentiva l'occupazione dei luoghi la cui sicurezza fosse minacciata, divennero in breve il paravento giuridico di una spartizione di fatto: furono occupate Mosul, Alessandretta, poi Smirne e Costantinopoli. L'armistizio è considerato il documento della fine effettiva dell'impero. Altri insediamenti perduti nella stessa data: Hama, Şam, Humus.", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["Mustafa Kemal a Samsun — la Guerra di Liberazione Nazionale", "09a8f784"], "d": ["Nel clima di indignazione creato dall'occupazione di Smirne, Mustafa Kemal Paşa, sbarcato a Samsun come ispettore della 9ª Armata, volse il suo incarico ufficiale all'organizzazione della resistenza in Anatolia. La Circolare di Amasya e i congressi di Erzurum e Sivas ne sono la prosecuzione; il principio «l'indipendenza della nazione sarà salvata ancora dalla determinazione e dalla decisione della nazione» divenne il nucleo del programma politico della Guerra di Liberazione.", "330e4c51"]},
"OLAYLAR:1920-04-23:0":{"b": ["Apertura della Grande Assemblea Nazionale e Sèvres", "2008feec"], "d": ["Per l'occupazione ufficiale di Costantinopoli e lo scioglimento del Meclis-i Meb'ûsan, il 23 aprile 1920 fu aperta ad Ankara la Grande Assemblea Nazionale; l'assemblea, che concentrò in sé poteri straordinari, divenne il nucleo del nuovo Stato basato sulla volontà nazionale. Il trattato di Sèvres, firmato in agosto dal governo di Costantinopoli, spartiva l'Anatolia; la Grande Assemblea dichiarò traditori della patria i firmatari e Sèvres non poté mai essere applicato.", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["Battaglia del Sakarya", "f2f970a6"], "d": ["L'offensiva greca, giunta fino a 50 chilometri da Ankara, fu spezzata in una battaglia di 22 giorni e 22 notti condotta da Mustafa Kemal Paşa, che aveva assunto il comando supremo, con l'ordine «non esiste linea di difesa, esiste superficie di difesa». L'esercito greco passò per la prima volta alla difesa strategica; la vittoria portò a Mustafa Kemal i titoli di gazi e di müşir (maresciallo) e aprì la porta all'Accordo di Ankara con la Francia e al riconoscimento internazionale.", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["Grande Offensiva e liberazione di Smirne", "172a50c4"], "d": ["L'offensiva lanciata da Kocatepe la mattina del 26 agosto raggiunse il 30 agosto, a Dumlupınar, l'annientamento delle forze principali greche con la Battaglia del Comandante in Capo; con l'inseguimento condotto sotto l'ordine «Armate, il vostro primo obiettivo è il Mediterraneo, avanti!», il 9 settembre Smirne fu liberata. Con l'armistizio di Mudanya (11 ottobre) la Tracia orientale fu ripresa senza combattere; la vittoria militare determinò la forza al tavolo del nuovo Stato che sarebbe stato costituito a Losanna.", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["Abolizione del sultanato", "9f36a9f6"], "d": ["Poiché alle trattative di Losanna fu invitato anche il governo di Costantinopoli, il 1° novembre 1922 la Grande Assemblea Nazionale separò sultanato e califfato e abolì il sultanato; il dominio dinastico ottomano di 623 anni terminò giuridicamente. Mehmed VI Vahideddin il 17 novembre lasciò il paese su una corazzata inglese; alla carica di califfo fu chiamato con decisione dell'Assemblea Abdülmecid Efendi e anche questa carica sarebbe stata abolita il 3 marzo 1924.", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["Trattato di Losanna", "38c27f7d"], "d": ["Con il Trattato di pace di Losanna, firmato al termine di otto mesi di aspri negoziati, furono riconosciuti sul piano internazionale i confini, la piena indipendenza e la sovranità del nuovo Stato turco; le capitolazioni furono abolite, il Düyûn-ı Umûmiyye fu avviato alla liquidazione e fu regolato lo scambio di popolazioni. Losanna, che rese di fatto nullo Sèvres, è considerata la vittoria diplomatica della Guerra di Liberazione e il documento estero fondativo della Repubblica.", "6d498c3f"]},
"OLAYLAR:1923-10-29:0":{"b": ["Proclamazione della Repubblica", "d5bfcdfb"], "d": ["Con l'accettazione da parte della Grande Assemblea Nazionale, tramite modifica costituzionale, della disposizione «la forma di governo dello Stato turco è la repubblica», fu proclamata la Repubblica; Mustafa Kemal Paşa fu eletto primo presidente. Così si chiudeva l'avventura ottomana di 624 anni iniziata nel 1299 come beylik di frontiera; il nuovo Stato, in cui la sovranità appartiene incondizionatamente alla nazione, fu fondato sull'eredità dell'impero.", "f5cabb8c"]},
"OLAYLAR_2S0920:0224-04-28:0":{"b": ["Battaglia di Hormozgan: Ardashir sconfigge il sovrano part Artabano V — Isfahan entra nel nucleo sasanide", "3689fd45"], "d": ["Ardashir, sovrano locale del Fars, sconfisse a Hormozgan il sovrano part Artabano V; la dinastia part (arsacide) crollò e salì quella sasanide. L'atlante considera Isfahan territorio sasanide a partire da questo giorno.", "3551fe9f"]},
"OLAYLAR_2S0920:1387-05-08:0":{"b": ["L'ingresso di Karaferye (Veria) sotto il dominio ottomano", "b0ece3f3"], "d": ["Con la resa di Salonicco nel 1387, nello stesso anno anche Karaferye, nell'interno della Bassa Macedonia, entrò sotto il dominio ottomano. La città era il nodo della strada tra Salonicco e la Tessaglia.", "4e571f7b"]},
"OLAYLAR_2S0920:1506-07-08:0":{"b": ["Alberto IV promulga la Costituzione di Primogenitura dei Wittelsbach — i ducati bavaresi si riuniscono in un unico ducato indivisibile", "86ee6f77"], "d": ["Dopo la guerra di successione di Landshut (1503-1505), il duca Alberto IV, che riunì di nuovo in una sola mano i ducati bavaresi, emanò l'8 luglio 1506 la Costituzione di Primogenitura, che prevedeva l'indivisibilità del paese e il passaggio del trono al figlio maschio maggiore. Così ebbero fine le divisioni della Baviera in vigore dal 1255; la Baviera, con centro a Monaco, continuò a esistere tra gli Stati tedeschi come un unico ducato indivisibile.", "26058158"]},
"OLAYLAR_2S0920:1517-04-15:0":{"b": ["Āmir II è ucciso presso Sana'a — fine della dinastia dei Tahiridi", "713ae406"], "d": ["L'ultimo sovrano dei Tahiridi, Āmir II, in una guerra scoppiata per il deterioramento dei rapporti con la flotta mamelucca, con l'appoggio delle tribù yemenite e degli Zaydi ai Mamelucchi, fu sconfitto prima presso Zabid (novembre 1516), poi ucciso nella battaglia presso Sana'a. Così terminò la dinastia tahiride, che dominava lo Yemen dal 1454; le città della dinastia (Taiz compresa) non erano più legate alla sovranità tahiride.", "4b9725ef"]},
"OLAYLAR_2S0920:1552-08-01:0":{"b": ["Conquista delle fortezze di Lugoj e Karánsebes — prosecuzione della campagna di Timișoara", "1af5a2be"], "d": ["La fortezza di Timișoara si arrese il 26 luglio 1552 dopo tre settimane di resistenza. In agosto furono prese anche le fortezze di Lugoj e Karánsebes; lungo la valle del Mureș furono conquistate quindici fortezze e fu istituito un nuovo beylerbeylik con centro a Timișoara.", "ecd1e532"]},
"OLAYLAR_2S0920:1723-11-18:0":{"b": ["Fondata la fabbrica-fortezza del ferro di Ekaterinburg — centro della regione mineraria degli Urali", "c416e12e"], "d": ["Sul fiume Iset', nel luogo scelto da Tatiščev, furono messi in funzione i magli della fabbrica del ferro completata da de Gennin; Ekaterinburg conta da questo giorno la propria data di fondazione. L'insediamento, destinato a essere il centro della regione mineraria e siderurgica degli Urali, divenne la porta della strada siberiana dello Zarato russo.", "8d081bcf"]},
"OLAYLAR_2S0920:1902-03-01:0":{"b": ["Zaria (Zazzau) entra sotto il controllo amministrativo britannico — l'emirato di Zaria del Califfato di Sokoto è legato al Protettorato della Nigeria settentrionale", "c2e4131e"], "d": ["L'emirato di Zaria, dipendente dal Califfato di Sokoto, nel marzo 1902 fu posto sotto l'amministrazione britannica della Nigeria settentrionale; gli Inglesi insediarono a Zaria un Resident e una guarnigione. L'emiro Kwasau si arrese nel luglio 1902 e fu destituito in settembre.", "d2ce29e8"]},
"OLAYLAR_2S0920:1903-02-01:0":{"b": ["Gli Inglesi prendono Kano — il più grande emirato del Califfato di Sokoto passa al Protettorato della Nigeria settentrionale", "0484009d"], "d": ["La forza del colonnello Morland, agli ordini dell'Alto Commissario della Nigeria settentrionale Lugard, partita da Zaria, prese Kano nel febbraio 1903; l'emirato di Kano, dipendente dal Califfato di Sokoto, entrò sotto amministrazione britannica. Sokoto fu presa un mese dopo, il 15 marzo 1903.", "33350275"]},
"OLAYLAR_2S0920:1912-10-22:0":{"b": ["Pristina passa in mano all'esercito serbo", "2ef111c0"], "d": ["Nella prima guerra balcanica l'esercito serbo, entrato in Kosovo, prese Pristina e in città iniziò una nuova politica di serbizzazione. La caduta di Pristina è tra i primi anelli del dissolversi della resistenza ottomana nel vilayet del Kosovo.", "96fc25ba"]},
"OLAYLAR_2S0920:1912-11-18:0":{"b": ["L'occupazione di Monastir da parte delle forze serbe", "db9b3353"], "d": ["Nella prima guerra balcanica Monastir (Bitola), uno dei più importanti centri amministrativi e militari della Macedonia, passò in mano alle forze serbe dopo cinque giorni di combattimenti. La perdita della città significava la fine di fatto della presenza dello Stato ottomano in Macedonia.", "84736d79"]},
"OLAYLAR_2S0920:1912-11-28:0":{"b": ["Proclamazione dell'indipendenza dell'Albania — İsmâil Kemali a Valona", "2cdbd4d9"], "d": ["Mentre gli eserciti della guerra balcanica entravano nei vilayet albanesi, İsmâil Kemali proclamò a Valona l'indipendenza dell'Albania. Il litorale e l'entroterra che si estendono da Durazzo, Elbasan, Berat, Argirocastro e Korçë fino ad Ayasaranda (Saranda) uscirono così dall'amministrazione ottomana e formarono il nucleo del nuovo Stato albanese.", "bc8dc97c"]},
"OLAYLAR_2S0920:1912-11-29:0":{"b": ["Fine del dominio ottomano a Ocrida e Debar", "5273f1ec"], "d": ["Undici giorni dopo la caduta di Monastir, l'esercito serbo entrò nella regione dei laghi della Macedonia occidentale; a Ocrida terminò un dominio ottomano di cinque secoli e anche Debar, a nord, andò perduta nella stessa operazione.", "7cabdd2f"]},
"OLAYLAR_2S0920:1913-04-23:0":{"b": ["L'occupazione di Scutari da parte dei Montenegrini", "db704247"], "d": ["Uno degli assedi più lunghi della prima guerra balcanica ebbe luogo a Scutari (Shkodër); dopo una resistenza durata mesi la città fu lasciata alle forze montenegrine. Scutari fu una delle ultime fortezze ottomane a resistere fino alla fine della guerra.", "418ed9d4"]},
"OLAYLAR_2S0920:1913-05-14:0":{"b": ["Il Montenegro evacua Scutari; il corpo internazionale delle grandi potenze entra in città", "8a6593e9"], "d": ["Per la pressione delle grandi potenze, il Montenegro evacuò il 14 maggio 1913 Scutari, presa il 23 aprile 1913; in città entrò il corpo internazionale, che divenne parte dell'amministrazione costitutiva dell'Albania.", "5ef15370"]},
"OLAYLAR_2S0920:1913-07-08:0":{"b": ["Ibn Sa'ud prende al-Aḥsā' — fine del dominio ottomano sulla costa del Golfo", "505f26d5"], "d": ["L'emiro del Najd 'Abd al-'Azīz b. Sa'ūd, scacciata la guarnigione ottomana, prese la regione di al-Aḥsā' e si stabilì nel centro di Hofuf. Con i porti di Qatif e 'Uqayr, la costa occidentale del Golfo passò sotto l'amministrazione saudita; terminò l'amministrazione cinquantennale dello Stato ottomano nella regione.", "8ec53ab2"]},
"OLAYLAR_2S0920:1913-08-10:0":{"b": ["Trattato di Bucarest — la Tracia occidentale e il bacino di Kavala passano dalla Bulgaria alla Grecia", "56123a58"], "d": ["La seconda guerra balcanica si concluse con il Trattato di Bucarest, firmato tra la Bulgaria e la Serbia, la Grecia e il Montenegro. Il bacino di Kavala, Drama e Serres, passato alla Bulgaria nella prima guerra, fu lasciato con questo trattato alla Grecia. Con questo trattato Tutrakan (Turtukaya) passò alla Romania.", "dd427970"]},
"OLAYLAR_2S0920:1914-11-22:0":{"b": ["Lo sbarco allo Shatt al-Arab — la caduta di Bassora e l'apertura del fronte iracheno", "c0a87d5d"], "d": ["All'inizio della prima guerra mondiale il corpo di spedizione britannico venuto dall'India sbarcò a Fao, alla foce dello Shatt al-Arab, e in breve tempo prese Bassora. La caduta della città significava l'apertura del fronte iracheno e il passaggio dell'estremità settentrionale del Golfo sotto controllo britannico.", "3b98576d"]},
"OLAYLAR_2S0920:1918-05-26:0":{"b": ["La Georgia proclama l'indipendenza — la Dieta Transcaucasica si dissolve", "6c79a8c7"], "d": ["La Georgia, uscita dalla Dieta Transcaucasica costituita dopo Brest-Litovsk, proclamò l'indipendenza e fu fondata la Repubblica Democratica di Georgia. Insieme a Kutaisi, la Georgia occidentale passò sotto l'amministrazione del nuovo Stato. Con questa proclamazione Sukhumi, Poti, Zugdidi, Gori, Telavi e Dušeti passarono alla Repubblica Democratica di Georgia.", "5500d335"]},
"OLAYLAR_2S0920:1918-05-28:0":{"b": ["Proclamata la Repubblica Democratica dell'Azerbaigian", "8baecec3"], "d": ["Due giorni dopo la secessione della Georgia fu proclamata la Repubblica Democratica dell'Azerbaigian; il primo centro fu Ganja. Lo stesso giorno a Erevan fu fondata anche la Repubblica di Armenia e la Transcaucasia si divise in tre Stati distinti. Con questa proclamazione Shamakhi, Qabala, Ağdaş, Şabran, Salyan, Quba, Şəki e Barda passarono alla Repubblica Democratica dell'Azerbaigian.", "474c35d5"]},
"OLAYLAR_2S0920:1918-10-27:0":{"b": ["L'occupazione di Aleppo da parte delle forze arabe e britanniche", "00efb2da"], "d": ["Dopo il crollo del fronte palestinese, le forze avanzanti verso nord entrarono ad Aleppo; la città passò prima nelle mani delle truppe arabe, poi in quelle britanniche. Questa occupazione, avvenuta tre giorni prima dell'Armistizio di Mudros, pose di fatto fine all'amministrazione ottomana in Siria, durata quattro secoli.", "38b8fc55"]},
"OLAYLAR_2S0920:1920-04-27:0":{"b": ["L'Armata Rossa occupa l'Azerbaigian — fine della Repubblica Democratica", "ebbb4566"], "d": ["L'Armata Rossa entrò in Azerbaigian, sciolse il parlamento e il governo; la Repubblica Democratica dell'Azerbaigian, durata due anni, ebbe fine. Il bacino petrolifero di Baku e Ganja passarono così all'amministrazione sovietica. Con questa occupazione Shamakhi, Qabala, Ağdaş, Şabran, Salyan, Quba, Şəki e Barda passarono sotto il controllo della Russia sovietica.", "e475b579"]},
"OLAYLAR_2S0920:1920-07-24:0":{"b": ["Maysalun — termina l'epoca di Faysal, la Siria passa al mandato francese", "80a932b0"], "d": ["A Maysalun, sulla strada Beirut-Damasco, i Francesi inflissero una grave sconfitta alle forze siriane e il Regno arabo di Faysal a Damasco ebbe fine. La Francia stabilì di fatto l'autorità mandataria conferitale a Sanremo; la regione che si estende da Aleppo a Damasco, da Alessandretta a Deir ez-Zor fu legata all'amministrazione mandataria francese.", "81c76451"]},
"OLAYLAR_2S0920:1921-02-01:0":{"b": ["Fondato l'Emirato della Transgiordania — 'Abd Allāh b. Husayn proclama l'emirato", "5ef520c2"], "d": ["'Abd Allāh, figlio dello sharif Husayn, venuto verso nord passando per Ma'an, proclamò l'emirato della Transgiordania; l'Inghilterra riconobbe poco dopo questa amministrazione nel quadro del mandato. Amman divenne il centro dell'emirato e l'altopiano giordano, compresa Kerak, fu legato alla nuova amministrazione.", "113f01ba"]},
"OLAYLAR_2S0920:1941-05-03:0":{"b": ["L'Italia annette al Regno la Provincia di Lubiana — Lubiana si stacca dalla Jugoslavia", "c451f492"], "d": ["L'Italia, che nell'aprile 1941, con il crollo della Jugoslavia, aveva occupato Lubiana e la metà occidentale della Slovenia, con il decreto del 3 maggio 1941 annesse la regione al Regno con il nome di Provincia di Lubiana; alto commissario fu Grazioli. Lubiana uscì dalla Jugoslavia ed entrò sotto amministrazione italiana (fino al settembre 1943).", "894bdb8c"]},
"OLAYLAR_2S0920:1941-05-05:0":{"b": ["Hailé Selassié torna ad Addis Abeba — l'Abissinia si stacca dall'Africa Orientale Italiana", "42470af3"], "d": ["Dopo che le forze anglo-abissine ebbero preso Addis Abeba all'inizio di aprile, l'imperatore Hailé Selassié tornò trionfalmente nella capitale il 5 maggio 1941; questo giorno è considerato la fine ufficiale dell'occupazione italiana (1936-41). L'atlante usa questo giorno come limite del ritorno dell'Abissinia dall'Africa Orientale Italiana.", "b9c24f62"]},
"OLAYLAR_2S0920:1942-01-01:0":{"b": ["Le forze giapponesi occupano l'indifesa isola di Labuan — la Malesia britannica (Insediamenti dello Stretto) perde la sua isola nel Borneo settentrionale", "a946e926"], "d": ["Durante le operazioni nel Borneo, una piccola forza giapponese sbarcò sull'isola indifesa di Labuan e la prese; l'isola rimase sotto occupazione militare giapponese dal gennaio 1942 al settembre 1945. Il giorno varia nelle fonti tra il 1° e il 3 gennaio (cfr. ic_not).", "f83ac693"]},
"OLAYLAR_2S0920:1955-11-23:0":{"b": ["Le Isole Cocos (Keeling) sono tolte alla Colonia di Singapore e cedute all'Australia", "5c2d70c7"], "d": ["In forza dell'Order in Council emanato sulla base del Cocos Islands Act britannico del 1955 e il 23 novembre 1955, giorno della proclamazione (Proclamation) del Cocos (Keeling) Islands Act 1955 australiano, le isole cessarono di far parte della Colonia di Singapore ed entrarono sotto l'autorità del Commonwealth australiano. Home Island (proprietà della famiglia Clunies-Ross e insediamento cocos-malese) è da questo giorno sotto amministrazione australiana.", "0edcf278"]},
"OLAYLAR_2S0920:1958-10-01:0":{"b": ["L'Isola di Natale è ceduta dalla Gran Bretagna all'Australia", "c971c518"], "d": ["Il The Christmas Island (Transfer to Australia) Order in Council 1958 britannico entrò in vigore il 1° ottobre 1958; la sovranità dell'isola passò dalla Colonia britannica di Singapore al Commonwealth australiano. Flying Fish Cove è il centro abitato e portuale dell'isola.", "7c935123"]},
"OLAYLAR_2S0920:1991-11-18:0":{"b": ["Cade Vukovar — l'Armata Popolare Jugoslava e le unità serbe prendono la città dopo un assedio di tre mesi", "30db2698"], "d": ["I difensori croati rimasti nella città assediata di Vukovar si arresero il 18 novembre 1991; la città passò nelle mani dell'Armata Popolare Jugoslava e delle forze serbe. La città visse poi il periodo dell'Amministrazione Transitoria delle Nazioni Unite per la Slavonia Orientale (UNTAES).", "09aa356a"]},
"OLAYLAR_2S_0918:1284-01-01:0":{"b": ["Belgrado e Mačva sono date da re d'Ungheria a Dragutin", "a4c2c535"], "d": ["Nel 1284 il re d'Ungheria affidò al re serbo Stefan Dragutin, che aveva abdicato nel 1282, il governo di Mačva e Belgrado; Belgrado rimase per oltre trent'anni in mano a Dragutin (regno di Srem sotto la soggezione ungherese).", "2fb699cd"]},
"OLAYLAR_2S_0918:1293-01-01:0":{"b": ["Alanya (Alâiye) entra, dopo il periodo selgiuchide, sotto il controllo di un beylik locale", "7b1489b3"], "d": ["Con la dissoluzione di fatto dello Stato selgiuchide d'Anatolia negli anni 1290, il porto di Alâiye (Alanya), sulla costa mediterranea, si rese indipendente dall'autorità centrale ed entrò sotto il controllo dei beylik della regione (in questo periodo nella sfera d'influenza dei Karamanidi); la data precisa e quale beylik la dominasse direttamente non sono chiare nelle fonti.", "78a4ff46"]},
"OLAYLAR_2S_0918:1319-01-01:0":{"b": ["Gli Ungheresi riprendono Belgrado a Milutin", "16d254a2"], "d": ["Dopo la morte di Dragutin nel 1316 la Serbia volle conservare Belgrado e l'Ungheria ne chiese la restituzione; nel 1319 gli Ungheresi attaccarono e, dopo mesi di scontri, l'esercito serbo si ritirò: la città, devastata, fu annessa al banato ungherese di Mačva. Belgrado restò sotto amministrazione ungherese fino al 1403-04, quando fu lasciata a Stefan Lazarević.", "feb8ea91"]},
"OLAYLAR_2S_0918:1322-01-01:0":{"b": ["Sinope presa da Gazi Çelebi, entra nell'influenza dei Candaroğlu", "f107586a"], "d": ["Gazi Çelebi, appartenente alla famiglia fondatrice del beylik dei Candaroğlu (İsfendiyaroğlu), rafforzatosi nella regione di Kastamonu e Sinope con l'indebolirsi del dominio ilkhanide, prese Sinope intorno al 1322 e ne fece un centro portuale del beylik.", "35c2fa9c"]},
"OLAYLAR_2S_0918:1322-03-01:0":{"b": ["Sebenico, contesa tra i conti Šubić e Venezia, si lega a Venezia", "99b341e0"], "d": ["Sebenico (Šibenik), contesa tra i conti croati Šubić di Bribir, signori feudali, e Venezia, si dette a Venezia il 1° marzo 1322 e rimase sotto l'amministrazione veneziana fino al 1357.", "120581de"]},
"OLAYLAR_2S_0918:1322-04-17:0":{"b": ["Traù si lega a Venezia contro i cneze di Bribir", "4ccf9ce4"], "d": ["Traù (Trogir), sotto la pressione dei conti Šubić di Bribir, si dette a Venezia il 17 aprile 1322 per difendere le proprie libertà e rimase sotto la protezione veneziana fino al 1357.", "e69237c1"]},
"OLAYLAR_2S_0918:1327-09-18:0":{"b": ["A Spalato finisce la sovranità ungherese — inizia il dominio veneziano", "4b04ca1a"], "d": ["La sovranità ungherese sul comune di Spalato (Split), in vigore dal 1133, ebbe fine il 18 settembre 1327; la città entrò sotto l'amministrazione veneziana e vi rimase fino al 1357.", "75ef7dfc"]},
"OLAYLAR_2S_0918:1357-01-01:0":{"b": ["A Spalato finisce l'amministrazione veneziana — riprende la sovranità ungherese", "e99628fc"], "d": ["A Spalato l'amministrazione veneziana, iniziata nel 1327, terminò nel 1357; la città rientrò sotto la diretta sovranità ungherese (fino al 1420).", "84447172"]},
"OLAYLAR_2S_0918:1357-07-09:0":{"b": ["Traù esce dalla protezione veneziana — riprende la sovranità ungherese", "7f112aa8"], "d": ["Traù rimase fino al 9 luglio 1357 sotto la protezione e l'amministrazione di Venezia; mentre Luigi d'Angiò cominciava a strappare la Dalmazia a Venezia, uscì da quella protezione e tornò sotto la sovranità del regno croato-ungherese.", "6a7c7a44"]},
"OLAYLAR_2S_0918:1357-12-14:0":{"b": ["Sebenico si separa da Venezia — passa alla sovranità ungherese", "adb9d6ca"], "d": ["Sebenico si separò da Venezia il 14 dicembre 1357, mentre Luigi d'Angiò stava strappando la Dalmazia a Venezia, ed entrò sotto la sovranità ungherese.", "7af69a3b"]},
"OLAYLAR_2S_0918:1358-02-18:0":{"b": ["Trattato di Zara — Ragusa (Dubrovnik) passa da Venezia alla protezione ungherese", "57fb81f9"], "d": ["Il Trattato di Zara, firmato il 18 febbraio 1358, pose fine al dominio di Venezia sulla Dalmazia, durato 150 anni; Dubrovnik (Ragusa) uscì così dall'amministrazione veneziana e ottenne lo statuto di repubblica semiautonoma posta sotto la protezione del re d'Ungheria Luigi I.", "e207c893"]},
"OLAYLAR_2S_0918:1358-05-27:0":{"b": ["Privilegio di Visegrád — Ragusa (Dubrovnik) legata al re d'Ungheria Luigi I", "9d3d02a8"], "d": ["Quando, con la pace di Zara (febbraio 1358), Venezia rinunciò ai suoi diritti sulla Dalmazia, Ragusa negoziò separatamente con re Luigi I; nel maggio 1358, con il privilegio di Visegrád, fu legata alla corona ungherese (lealtà in cambio di protezione, tributo annuo e soldati).", "d37ccc8a"]},
"OLAYLAR_2S_0918:1390-06-01:0":{"b": ["Tvrtko I assume la sovranità sulle città costiere della Dalmazia (Sebenico compresa)", "c53aad4d"], "d": ["Il re di Bosnia Tvrtko I assunse nel 1390 la sovranità sulle città costiere della Dalmazia, eccetto Zara; anche Sebenico uscì dalla sovranità ungherese e riconobbe la supremazia del re di Bosnia.", "dfb86467"]},
"OLAYLAR_2S_0918:1391-01-01:0":{"b": ["Morte di Tvrtko I; Sebenico torna alla sovranità ungherese", "ef2d3b2f"], "d": ["Con la morte del re di Bosnia Tvrtko I nel 1391 finì la supremazia bosniaca su Sebenico; la città entrò sotto la sovranità del re d'Ungheria Sigismondo (1391-1402).", "0f8c4ab3"]},
"OLAYLAR_2S_0918:1408-01-01:0":{"b": ["La regione di Erzurum e Aşkale cambia di mano nella contesa tra Qara Qoyunlu e Timuridi", "ca64775a"], "d": ["Nel vuoto di potere seguito alla morte di Tamerlano nel 1405, il sovrano dei Qara Qoyunlu Qara Yusuf si mosse tra il 1406 e il 1408 contro i governatori timuridi dell'Anatolia orientale; in questa lotta Erzurum e la vicina Aşkale uscirono dal controllo timuride ed entrarono nell'influenza dei Qara Qoyunlu.", "10b1b07c"]},
"OLAYLAR_2S_0918:1409-07-31:0":{"b": ["Zara entra sotto l'amministrazione veneziana — Santa Intrada", "820c9276"], "d": ["Dopo che il re di Napoli Ladislao ebbe venduto la Dalmazia a Venezia, la popolazione di Zara scacciò dalla città i soldati napoletani; il 31 luglio 1409 i provveditori veneziani entrarono in città e stabilirono l'amministrazione veneziana, destinata a durare fino al 1797.", "06e4d6fa"]},
"OLAYLAR_2S_0918:1420-06-22:0":{"b": ["Traù entra sotto l'amministrazione veneziana", "fbca501f"], "d": ["Mentre Venezia era in guerra con l'Ungheria, con l'arrivo della flotta del capitano generale Piero Loredan Traù passò il 22 giugno 1420 sotto l'amministrazione veneziana; ultima tra le città dalmate ad essere annessa a Venezia, rimase sotto la bandiera veneziana fino al 1797.", "8ebaf8eb"]},
"OLAYLAR_2S_0918:1462-01-01:0":{"b": ["Uzun Hasan degli Aq Qoyunlu elimina il ramo ayyubide di Hisn Kayfa", "2b464a1f"], "d": ["Hisn Kayfa (Hasankeyf) e Siirt — uno degli ultimi due rami superstiti della dinastia ayyubide sull'Alto Tigri, insieme a quello di Hama — furono annesse nel 1462 da Uzun Hasan, sovrano degli Aq Qoyunlu, ponendo fine al dominio ayyubide.", "8bf494b3"]},
"OLAYLAR_2S_0918:1515-04-01:0":{"b": ["Il Portogallo completa il dominio sulle coste dello Stretto di Hormuz", "bef031f0"], "d": ["La campagna nel Golfo Persico avviata da Afonso de Albuquerque nel 1507 si concluse nel 1515 comprendendo l'isola di Hormuz, Qeshm sulla costa opposta e Buraimi; il Regno di Hormuz, vassallo della Persia, passò di fatto sotto protezione portoghese, e il Portogallo si impadronì del controllo del commercio del Golfo.", "117a5c7e"]},
"OLAYLAR_2S_0918:1569-07-01:0":{"b": ["Unione di Lublino — i territori ucraini passano dalla Lituania alla Polonia", "1881ceff"], "d": ["L'Unione di Lublino, firmata il 1° luglio 1569, unì il Granducato di Lituania e il Regno di Polonia in un unico Stato (la Rzeczpospolita). In forza delle clausole dell'accordo, la Podolia, la Volinia e la regione di Kiev (inclusi Bar, Berdyčiv, Białystok, Braslav) furono trasferite amministrativamente dalla Lituania direttamente al Regno di Polonia.", "184b03dd"]},
"OLAYLAR_2S_0918:1776-02-14:0":{"b": ["L'amministrazione di Fiume è trasferita alla Croazia soggetta alla corona ungherese", "dfedccf8"], "d": ["L'imperatrice Maria Teresa, con rescritto del 14 febbraio 1776, affidò l'amministrazione di Fiume all'Ungheria tramite il Consiglio di Zagabria; il Diploma del 1779 fece della città un corpo separato (corpus separatum) direttamente soggetto alla corona ungherese.", "bbf160dd"]},
"OLAYLAR_2S_0918:1809-10-14:0":{"b": ["Fiume è ceduta alla Francia con la pace di Schönbrunn (Province Illiriche)", "16bf1fca"], "d": ["Con la pace di Schönbrunn del 14 ottobre 1809 Fiume passò dall'Austria alla Francia e fino al 1813 fece parte delle Province Illiriche di Napoleone.", "417a8ae7"]},
"OLAYLAR_2S_0918:1813-01-01:0":{"b": ["Il ritorno di Fiume dall'amministrazione francese illirica agli Asburgo", "1b5b9954"], "d": ["Nel 1813, dopo la sconfitta di Napoleone in Russia, Fiume uscì dalle Province Illiriche e tornò all'Impero austriaco.", "5db16c92"]},
"OLAYLAR_2S_0918:1822-10-15:0":{"b": ["Fiume è restituita al Regno d'Ungheria", "aafdd0ee"], "d": ["In seguito alla decisione di Francesco I del 5 luglio 1822, il conte György Majláth, a nome del governo ungherese, prese in consegna la città il 15 ottobre 1822; Fiume tornò al Regno d'Ungheria.", "e30af380"]},
"OLAYLAR_2S_0918:1841-10-01:0":{"b": ["Le forze egiziane si ritirano dalla regione di al-Aḥsā' (Lahsa)", "5ea75c8d"], "d": ["Le forze egiziane di Mehmed Ali Pascià avevano occupato nel 1836 il Najd e l'Arabia orientale (compresi al-Aḥsā', Qatif, 'Uqayr, Jubayl); quando la Convenzione di Londra sugli Stretti del 1840 indusse l'Egitto a rinunciare alle conquiste nella penisola arabica, le forze si ritirarono dalla regione nel 1841 e l'amministrazione tornò alle potenze locali (influenza saudita/Āl Khalīfa).", "99ff8f81"]},
"OLAYLAR_2S_0918:1853-07-28:0":{"b": ["La fortezza di Ak-Mecit è presa dalle forze russe — crolla la linea del Sir Daria del Khanato di Kokand", "e9f9a9c7"], "d": ["Le forze russe al comando del generale Vasilij Perovskij presero nel luglio 1853, dopo un lungo assedio, la fortezza di Ak-Mecit sulla riva del Sir Daria, appartenente al Khanato di Kokand; la fortezza divenne in seguito, con il nome di Perovsk, avamposto del Turkestan russo.", "9e64a219"]},
"OLAYLAR_2S_0918:1881-01-24:0":{"b": ["Battaglia di Geok Tepe — i Turkmeni Akhal-Teke sconfitti dalla Russia", "76c7a102"], "d": ["Le forze russe al comando del generale Michail Skobelev, espugnando la fortezza di Geok Tepe il 24 gennaio 1881, spezzarono la resistenza dei Turkmeni Akhal-Teke; la regione turkmena transcaspica, compresi la piana del Dihistan, Abivard e Nisa, entrò nel processo di annessione all'Impero russo (la Regione Transcaspica fu istituita nel 1881). Con questo evento Kyzyl-Arvat e Ashgabat (territori turkmeni dell'Akhal) passarono alla Russia.", "f294fbe6"]},
"OLAYLAR_2S_0918:1881-03-26:0":{"b": ["Proclamato il Regno di Romania — il Principato diventa Regno", "4d413f0c"], "d": ["Il Principato di Romania, la cui indipendenza era stata riconosciuta al Congresso di Berlino dopo la guerra russo-turca del 1877-78, fu trasformato in Regno il 26 marzo 1881 (14 marzo del calendario giuliano) con l'incoronazione di re Carlo I; l'intero paese, compresi Babadag, Bârlad, Buzău e la capitale Bucarest, divenne amministrativamente parte del nuovo regno. Con la proclamazione del Regno, tutta la Romania (Iași, Galați, Brăila, Costanza, Tulcea, Calafat e le altre città) divenne Regno di Romania.", "fbab3abf"]},
"OLAYLAR_2S_0918:1889-01-01:0":{"b": ["L'Italia annette l'altopiano eritreo, compresi Asmara e Cheren", "31308dc8"], "d": ["Approfittando del vuoto di potere creatosi con la morte dell'imperatore d'Abissinia Giovanni IV nel 1889, l'Italia, dopo il Trattato di Uccialli (Wuchale, 2 maggio 1889), annetté di fatto l'altopiano eritreo, compresi Asmara e Cheren; il 1° gennaio 1890 fu proclamata ufficialmente la colonia con il nome di 'Eritrea'. Con questo evento Cheren passò sotto l'amministrazione italiana.", "b6bbb0a5"]},
"OLAYLAR_2S_0918:1895-07-01:0":{"b": ["La regione nord-orientale del Kenya (linea Garissa-Marsabit) è annessa al Protettorato dell'Africa Orientale Britannica", "e45c6d43"], "d": ["Il Protettorato dell'Africa Orientale Britannica, istituito con il trasferimento alla Corona della concessione della Compagnia Imperiale Britannica dell'Africa Orientale nel 1895, si estese fino a comprendere regioni nord-orientali come Garissa, Kitui, Marsabit e Wajir; la presa in amministrazione effettiva di queste regioni interne si distribuì lungo la seconda metà degli anni 1890.", "8cf3e473"]},
"OLAYLAR_2S_0918:1897-02-16:0":{"b": ["L'Emirato di Ilorin è conquistato dalle forze della Royal Niger Company", "b111cb7d"], "d": ["L'Emirato di Ilorin, soggetto al Califfato di Sokoto, fu conquistato nella campagna del febbraio 1897 dalle forze della Royal Niger Company al comando di Sir George Goldie; la potenza militare dell'emirato fu spezzata e la regione entrò di fatto nell'influenza britannica (l'annessione ufficiale si completò con la fondazione del Protettorato della Nigeria settentrionale nel 1900).", "95f49872"]},
"OLAYLAR_2S_0918:1899-04-09:0":{"b": ["Il re di Bunyoro Kabalega è catturato, il regno è legato al Protettorato britannico dell'Uganda", "62bc7c64"], "d": ["Il re di Bunyoro Kabalega, che resisteva alle forze britanniche dal 1894, fu catturato il 9 aprile 1899 nella regione di Lango (presso Dokolo) e mandato in esilio alle Seychelles; i territori del regno, compresa la capitale Hoima e Masindi, furono annessi al Protettorato britannico dell'Uganda.", "87bc3dd6"]},
"OLAYLAR_2S_0918:1900-06-26:0":{"b": ["Accordo di Toro — il Regno di Toro diventa parte autonoma del Protettorato britannico dell'Uganda", "c55340a2"], "d": ["Dopo la caduta di Bunyoro nel 1899, il vicino Regno di Toro formalizzò, nel quadro dell'Accordo dell'Uganda del 1900, la protezione britannica in corso dal 1896; il regno, con la capitale Fort Portal, ottenne all'interno del Protettorato britannico dell'Uganda lo statuto di amministrazione locale autonoma.", "8459a73a"]},
"OLAYLAR_2S_0918:1901-09-02:0":{"b": ["L'Emirato di Adamawa viene spartito tra Germania e Inghilterra", "b9230d3d"], "d": ["L'Emirato di Adamawa (Fombina), soggetto al Califfato di Sokoto, fu diviso in due al termine delle campagne coloniali tedesche e inglesi del 1899-1901: la parte orientale (compresi Garoua, Banyo, Marua, Ngaoundéré) fu annessa al Camerun tedesco, quella occidentale (capitale Yola) alla Nigeria settentrionale britannica; l'emiro Zubayr fu mandato in esilio. Con questo evento Rey Buba (Adamawa (quota tedesca)) passò sotto l'amministrazione del Camerun tedesco.", "e3ebfafa"]},
"OLAYLAR_2S_0918:1902-05-07:0":{"b": ["Battaglia di Tit — i Tuareg dell'Ahaggar sconfitti dalle forze francesi", "831143d6"], "d": ["Nella battaglia combattuta il 7 maggio 1902 presso l'oasi di Tit, durante la spedizione Cottenest, le forze francesi sconfissero in modo decisivo i Tuareg Kel Ahaggar; questa regione interna del Sahara, compresi Abalessa, centro dell'Ahaggar, e Idelès, passò sotto il controllo dell'Algeria francese.", "5c1e86d4"]},
"OLAYLAR_2S_0918:1903-01-01:0":{"b": ["Le forze francesi prendono l'interno dell'Ubangi-Shari (linea Bambari-Bria)", "0b9a9f72"], "d": ["Le campagne settentrionali del Congo francese posero di fatto sotto controllo l'entroterra dell'Ubangi-Shari, comprendente Bambari, Batangafo, Bossangoa e Bria, all'inizio del Novecento; la regione fu organizzata ufficialmente come colonia dell'Ubangi-Shari il 29 dicembre 1903 (parte dell'Africa Equatoriale Francese).", "ebbd38e7"]},
"OLAYLAR_2S_0918:1911-01-12:0":{"b": ["Il Sultanato di Dar al-Kuti del sultano Muḥammad al-Sanūsī è soppresso dalle forze francesi", "644b2c3f"], "d": ["Il Sultanato di Dar al-Kuti, fondato sulla tratta degli schiavi, con capitale Ndele e posto sotto protezione francese nel 1897, fu di fatto soppresso con una spedizione del 1911, poiché il sultano Muḥammad al-Sanūsī continuava a resistere all'autorità francese; al-Sanūsī fu ucciso in battaglia e il sultanato fu abolito ufficialmente nel 1912.", "3f913340"]},
"OLAYLAR_2S_0919:1328-01-01:0":{"b": ["L'Ordine di Livonia cede i territori di Klaipėda (Memel) al ramo prussiano dell'Ordine Teutonico", "e61e5d50"], "d": ["L'Ordine di Livonia cedette al ramo prussiano dell'Ordine Teutonico il castello di Klaipėda (Memel), alla foce del Niemen, e i territori circostanti; il vescovo di Curlandia cedette la propria parte allo stesso ramo nel 1392. Klaipėda rimase all'Ordine con le paci di Toruń (1411) e di Melno (1422) e nel 1525 passò al Ducato di Prussia.", "cad2853d"]},
"OLAYLAR_2S_0919:1329-01-01:0":{"b": ["Umur Bey prende ai Genovesi il castello portuale di Smirne", "ab92d96e"], "d": ["Umur Bey degli Aydınidi assediò per due anni e mezzo il castello portuale di Smirne, rimasto in mano ai Latini. L'amministratore genovese del castello, Martino Zaccaria, consegnò la fortezza e si recò a Chio.", "1bec5de9"]},
"OLAYLAR_2S_0919:1343-01-01:0":{"b": ["İbrâhim Şah dei Sutayidi domina Diyarbakır", "179196cf"], "d": ["Dopo la dissoluzione dello Stato ilkhanide, İbrâhim Şah dei Sutayidi dominò la regione di Diyarbakır, teatro di lotte tra Jalayiridi e Chobanidi; il suo dominio durò fino al 1353.", "6143de93"]},
"OLAYLAR_2S_0919:1343-01-01:1":{"b": ["Berat passa da Bisanzio ai Serbi — la conquista dell'Albania di Stefan Dušan", "1eba202e"], "d": ["La fortezza di Berat, che nel 1281 aveva spezzato l'assedio angioino ed era da allora il centro dell'ultima provincia bizantina sull'Adriatico, passò in mano serba durante l'avanzata di Stefan Dušan in Albania, mentre infuriava la guerra civile bizantina. Dopo la resa di Kruja nel maggio o giugno 1343, Berat, Kanina e Valona divennero serbe nel giro di due anni; a capo della provincia fu posto il cognato di Dušan, John Comneno Asen.", "21876887"]},
"OLAYLAR_2S_0919:1348-01-01:0":{"b": ["Gli Abd al-Wadidi (Zayyanidi) si liberano a Tlemcen dal dominio merinide", "a4aa9573"], "d": ["Gli Abd al-Wadidi di Tlemcen, sotto la guida di Osman II e del fratello Abu Thabit, si liberarono dal dominio dei Merinidi. Questa indipendenza fu di breve durata.", "0afdf111"]},
"OLAYLAR_2S_0919:1351-01-01:0":{"b": ["Bayram Hoca conquista l'indipendenza — nasce il Beylik dei Qara Qoyunlu", "37964815"], "d": ["Bayram Hoca, considerato il primo bey dei Qara Qoyunlu, uccise il sovrano dei Sutayidi Akçasakal Hüseyin Bey e conquistò l'indipendenza. Prese Mossul e ne affidò l'amministrazione al fratello Birdi Hoca.", "892dced7"]},
"OLAYLAR_2S_0919:1353-01-01:0":{"b": ["Con la morte di İbrâhim Şah Diyarbakır passa sotto l'amministrazione dei Jalayiridi", "11c338ef"], "d": ["Alla morte di İbrâhim Şah dei Sutayidi, che dominava la regione di Diyarbakır dal 1343, la regione passò sotto l'amministrazione dei Jalayiridi.", "155719ec"]},
"OLAYLAR_2S_0919:1355-01-01:0":{"b": ["Enez passa sotto l'amministrazione genovese (famiglia Gattilusio)", "5dc12940"], "d": ["Enez, importante città portuale in epoca bizantina, passò nel 1355 sotto l'amministrazione genovese e fu governata dalla famiglia Gattilusio.", "33faefdd"]},
"OLAYLAR_2S_0919:1356-01-01:0":{"b": ["Il Granduca di Lituania Algirdas (Olgerd) prende Brjansk", "3cad9caf"], "d": ["L'esercito del Granduca di Lituania Algirdas prese Brjansk. La città rimase legata al Granducato di Lituania fino al 1500.", "03107c6d"]},
"OLAYLAR_2S_0919:1362-01-01:0":{"b": ["Il Principato di Kiev passa sotto la sovranità lituana", "c4fda115"], "d": ["Il Principato di Kiev entrò sotto la sovranità lituana e divenne, nello Stato lituano-rutenico, un principato vassallo governato da principi della stirpe di Gediminas.", "d4a2f5ec"]},
"OLAYLAR_2S_0919:1368-01-01:0":{"b": ["Gli İnançoğulları riconoscono la sovranità dei Germiyanidi", "0679db27"], "d": ["Il Beylik degli İnançoğulları, che regnava nei dintorni di Denizli, riconobbe probabilmente nel 1368 la sovranità dei Germiyanidi.", "55ce9f1f"]},
"OLAYLAR_2S_0919:1371-11-01:0":{"b": ["Il despota di Tessalonica Manuele prende sotto amministrazione bizantina Serres e la regione di Drama", "abb99c3e"], "d": ["Con la morte di re Vukašin e del despota di Serres Uglješa a Çirmen (26 settembre 1371), terminò l'amministrazione serba nella regione di Serres. Il principe bizantino Manuele II Paleologo, che regnava a Tessalonica, nel novembre 1371 pose sotto amministrazione bizantina Serres e la regione in cui si trova Drama. La regione passò agli Ottomani nel settembre 1383.", "b0802648"]},
"OLAYLAR_2S_0919:1378-01-01:0":{"b": ["Con la morte di Pîr Hüseyin Bey Erzincan e Bayburt passano a Mutahharten", "3269e55d"], "d": ["Alla morte dell'emiro di Erzincan Pîr Hüseyin Bey, Erzincan e Bayburt passarono nelle mani di Mutahharten, uno degli emiri di Eretna; Mutahharten divenne emiro di Erzincan.", "4993bac9"]},
"OLAYLAR_2S_0919:1379-01-01:0":{"b": ["Tâceddin Bey sconfigge l'esercito di Eretna a Niksar e agisce in modo indipendente", "42982ea7"], "d": ["Nella primavera del 1379 Tâceddin Bey sconfisse le forze di Kadı Burhâneddin e del bey di Eretna Alâeddin Ali, che avevano attaccato Niksar. Cessò di pagare tributo al Beylik di Eretna e dall'anno 781 (1379) agì in modo indipendente.", "5d809820"]},
"OLAYLAR_2S_0919:1379-01-01:1":{"b": ["Tamerlano conquista definitivamente il Khwarezm", "ef76d2c9"], "d": ["Dopo la prima campagna del 1371 contro il Khwarezm, Tamerlano ne condusse altre tre. Con la campagna del 1379 prese definitivamente la regione, la saccheggiò e tornò con un ricco bottino.", "f2ebd27a"]},
"OLAYLAR_2S_0919:1382-01-01:0":{"b": ["Il re di Bosnia Tvrtko I fonda Herceg Novi", "1628221a"], "d": ["Il re di Bosnia Tvrtko I fondò una nuova cittadina nella baia di Topla, per fare concorrenza a Ragusa (Dubrovnik) nel commercio del sale; la cittadina fu poi chiamata Novi (Herceg Novi).", "b970dc7f"]},
"OLAYLAR_2S_0919:1383-01-01:0":{"b": ["Tamerlano prende Kandahar ai Kart e la dà al nipote Pir Muhammad", "84760f70"], "d": ["Kandahar, in mano dal 1281 ai Kart di Herat, vassalli degli Ilkhanidi, fu espugnata durante le campagne di Tamerlano nel Khorasan e data al nipote Pir Muhammad; da allora la città fu governata da governatori timuridi.", "c2470eb5"]},
"OLAYLAR_2S_0919:1384-01-01:0":{"b": ["Halil Bey Dulkadıroğlu riprende Elbistan ai Mamelucchi", "ee3da686"], "d": ["Elbistan, caduta in mano ai Mamelucchi nel 1381, fu ripresa nel 1384 da Halil Bey Dulkadıroğlu.", "104e231d"]},
"OLAYLAR_2S_0919:1394-04-25:0":{"b": ["Tamerlano espugna e saccheggia Diyarbakır (Amid)", "f8d200a8"], "d": ["Tamerlano espugnò Diyarbakır il 25 o 26 aprile 1394 e saccheggiò la città.", "b1186b21"]},
"OLAYLAR_2S_0919:1399-02-13:0":{"b": ["Gherardo Appiani cede Pisa ai Visconti e fonda la signoria di Piombino", "ac45a9dd"], "d": ["Gherardo Appiani, signore di Pisa, cedette la città per 200.000 fiorini a Gian Galeazzo Visconti, signore di Milano. Si riservò la signoria di Piombino, composta da Piombino, Suvereto, Scarlino e dalle isole d'Elba, Pianosa e Montecristo.", "68084c1c"]},
"OLAYLAR_2S_0919:1401-01-01:0":{"b": ["Diyarbakır è data a Kara Yülük Osman Bey — inizia il dominio degli Aq Qoyunlu", "38262401"], "d": ["Diyarbakır, espugnata da Tamerlano nel 1394, fu data nel 1401 a Kara Yülük Osman Bey, e così nella regione iniziò il dominio degli Aq Qoyunlu.", "de407b9c"]},
"OLAYLAR_2S_0919:1410-01-01:0":{"b": ["Erzincan entra sotto il dominio dei Qara Qoyunlu", "5729a50b"], "d": ["Dopo Mutahharten, Erzincan cadde nelle mani del sovrano dei Qara Qoyunlu Qara Yusuf. Qara Yusuf nominò governatore della città Pîr Ömer, uno dei suoi uomini di fiducia.", "69ef181d"]},
"OLAYLAR_2S_0919:1494-01-01:0":{"b": ["Askia Muhammad prende Zagha (Dia)", "24561a8c"], "d": ["Askia Muhammad, salito al trono songhai, alla fine dell'anno 899 dell'Egira prese, tramite il fratello Kurmina-Fari 'Umar Komzagho, la città di Zagha (Dia), a occidente del delta interno del Niger.", "f6d242d2"]},
"OLAYLAR_2S_0919:1500-01-01:0":{"b": ["Shaybani Khan prende Bukhara e Samarcanda", "8f8f40eb"], "d": ["Muhammad Shaybani Khan, approfittando dei disordini tra i Timuridi, prese Bukhara e Samarcanda e fondò la dinastia degli Shaybanidi (Uzbechi). Tra il 1500 e il 1507 si impadronì di quasi tutte le città della Transoxiana, del Khwarezm e del Khorasan.", "0e64ecae"]},
"OLAYLAR_2S_0919:1510-01-01:0":{"b": ["Gli Spagnoli occupano Bugia", "8faa0133"], "d": ["Un esercito spagnolo di 8000 uomini, giunto per mare, occupò Bugia; gli abitanti, presi dal panico, abbandonarono la città.", "364b6234"]},
"OLAYLAR_2S_0919:1515-01-01:0":{"b": ["Agadez è legata al Songhai", "997362b0"], "d": ["Agadez, centro della regione dell'Aïr, fu legata a Gao dal sultano songhai Askia Muhammad; la città mantenne questa dipendenza fino alla distruzione del Songhai a Tondibi nel 1591.", "b2b437a3"]},
"OLAYLAR_2S_0919:1522-01-01:0":{"b": ["Fondato il Sultanato del Baguirmi", "03829f94"], "d": ["La tribù dei Kenga, sotto la guida di Birni Besi, fondò un forte Stato con centro a Massenya, a est del lago Ciad. La fondazione della dinastia del Baguirmi è tradizionalmente datata al 1522.", "2bd4497c"]},
"OLAYLAR_2S_0919:1535-11-01:0":{"b": ["Muore l'ultimo duca Sforza, Milano passa a Carlo V", "53230b5c"], "d": ["Il duca di Milano Francesco II Sforza morì senza figli nella notte tra l'1 e il 2 novembre 1535. Il ducato passò all'imperatore Carlo V e fu governato da un governatore spagnolo.", "03b908c5"]},
"OLAYLAR_2S_0919:1544-01-01:0":{"b": ["I Genovesi si stabiliscono sull'isola di Tabarca", "0cb474f8"], "d": ["In forza dell'accordo di Carlo V con il sovrano di Tunisi, che permetteva di costruire una fortezza sulla costa e di praticare la pesca del corallo, una comunità genovese originaria di Pegli fu insediata sull'isola di Tabarca. L'isola divenne una base commerciale governata dalla famiglia Lomellini.", "74c7ab83"]},
"OLAYLAR_2S_0919:1556-01-01:0":{"b": ["Dopo la morte di Humayun, i Safavidi prendono Kandahar ai Mogul", "318eabc8"], "d": ["Dopo la morte di Humayun a Delhi nel 1556, Shah Tahmasp approfittò dei contrasti tra i governatori moghul di Kandahar e Zamindawar; un reparto safavide, giunto su invito del governatore di Zamindawar, entrò a Kandahar e Tahmasp nominò governatore della città il cugino Sultan Husayn Mirza. La città rimase in mano safavide fino al 1595.", "87ac27f5"]},
"OLAYLAR_2S_0919:1558-01-01:0":{"b": ["La Russia invade la Livonia, cade Dorpat", "dcb46a8a"], "d": ["Ivan IV, per aprirsi uno sbocco sul Baltico, invase la Livonia e diede inizio alla guerra di Livonia; prese Narva e Dorpat (Tartu) e assediò Reval.", "37f1dd66"]},
"OLAYLAR_2S_0919:1579-07-13:0":{"b": ["Fondata la fortezza di Karlovac", "9b28e6ad"], "d": ["Per difendere la Croazia e le terre ereditarie austriache dagli Ottomani, nella zona alluvionale tra la Kupa e la Korana fu fondata la fortezza di Karlovac; la fortezza fu fatta costruire dall'arciduca Carlo II, comandante della Frontiera militare croata.", "edc1a0fd"]},
"OLAYLAR_2S_0919:1580-04-10:0":{"b": ["Atto di fondazione (locazione) di Zamość", "e1157f3b"], "d": ["Jan Zamoyski, Gran Cancelliere della Corona polacca, emanò l'atto di fondazione (locazione) della città di Zamość.", "90df0b1c"]},
"OLAYLAR_2S_0919:1582-01-15:0":{"b": ["Tregua di Jam Zapolski — la Livonia e Dorpat passano alla Polonia", "7d02d8ad"], "d": ["Fu firmata la tregua di Jam Zapolski tra Polonia-Lituania e Russia; Mosca rinunciò alle sue pretese sulla Livonia e restituì i territori di Polock. Dorpat (Tartu) restò in mano polacca dal 1582.", "3aa35e5c"]},
"OLAYLAR_2S_0919:1589-07-02:0":{"b": ["La fortezza di Caricyn è citata per la prima volta in un documento", "ddf65b06"], "d": ["Il decreto dello zar Fëdor Ivanovič del 2 luglio 1589 menziona la fortezza di Caricyn, costruita per proteggere il confine meridionale del Volga; questa data è considerata il giorno di fondazione della città.", "fd3ba360"]},
"OLAYLAR_2S_0919:1590-07-12:0":{"b": ["Fondata la fortezza di Saratov", "a3ca702c"], "d": ["Saratov fu fondata dal principe Zasekin come fortezza-avamposto, per difendere la via del Volga e i confini orientali dello Stato dalle incursioni nomadi.", "07dcdc66"]},
"OLAYLAR_2S_0919:1593-01-01:0":{"b": ["Fondata la fortezza di Pelym", "baf3e7eb"], "d": ["Il voivoda Pëtr Gorčakov fondò Pelym sulla riva del fiume Tavda; la fortezza divenne uno dei capisaldi dell'avanzata russa nella Siberia occidentale.", "7511aeab"]},
"OLAYLAR_2S_0919:1598-01-01:0":{"b": ["Fondata la fortezza di Verchoturje", "81be29bb"], "d": ["Sulla riva della Tura, nel luogo dell'antico insediamento di Neromkar, fu fondato il presidio fortificato di Verchoturje; la sua fondazione è legata alla ricerca di una via più breve verso la Siberia.", "ac40c773"]},
"OLAYLAR_2S_0919:1600-01-01:0":{"b": ["Fondata la fortezza di Turinsk sulla Tura", "c1d8534e"], "d": ["Nell'anno 1600, nell'area dell'odierna Turinsk, fu fondata la fortezza cosacca-tributaria (ostrog) russa di Turinsk; la fortezza è una delle fortificazioni di tappa lungo l'avanzata della Russia nella Siberia occidentale.", "82075fd3"]},
"OLAYLAR_2S_0919:1611-01-01:0":{"b": ["Shah 'Abbas I fonda la città di Farahabad nel Mazandaran", "cab4d0fe"], "d": ["Il sovrano safavide 'Abbas I fece fondare la città di Farahabad nel Mazandaran, in un luogo vicino alla costa del Caspio, e vi insediò popolazioni provenienti da ogni parte del paese. La costruzione iniziò nel 1020/1611.", "cc05c705"]},
"OLAYLAR_2S_0919:1631-01-01:0":{"b": ["Fondata la fortezza russa di Bratsk sull'Angara", "e7b4be59"], "d": ["Durante l'avanzata della Russia nella Siberia orientale fu fondata la fortezza di Bratsk sul fiume Angara.", "eb1a1abd"]},
"OLAYLAR_2S_0919:1658-03-08:0":{"b": ["Trattato di Roskilde — Scania, Halland, Blekinge e Bornholm passano alla Svezia", "afcae41b"], "d": ["Fu firmato il Trattato di Roskilde, che pose fine alla prima guerra di Carlo Gustavo; la Danimarca-Norvegia cedette alla Svezia Scania, Halland, Blekinge e Bornholm.", "ac397fd6"]},
"OLAYLAR_2S_0919:1663-01-01:0":{"b": ["La Russia fonda la fortezza di Penza sulla Sura", "49e8d90b"], "d": ["Penza fu fondata come grande fortezza alla confluenza dei fiumi Penza e Sura; dopo il 1684 costituì l'estremità occidentale della linea difensiva di Syzran'.", "afba0eaa"]},
"OLAYLAR_2S_0919:1668-01-01:0":{"b": ["Marquette fonda la missione francese di Sault Ste. Marie", "86612bcd"], "d": ["Il gesuita Jacques Marquette fondò una missione presso le cascate di Sault Ste. Marie, tra il lago Superiore e il lago Huron.", "e90cdea2"]},
"OLAYLAR_2S_0919:1668-01-01:1":{"b": ["Fondato il primo avamposto della Hudson's Bay Company (Waskaganish)", "07b32d57"], "d": ["Nella baia di James, alla foce del fiume Rupert, Médard Chouart des Groseilliers fondò l'insediamento considerato poi il primo avamposto della Hudson's Bay Company.", "790b2f93"]},
"OLAYLAR_2S_0919:1700-01-01:0":{"b": ["L'amministrazione coloniale spagnola fonda Pitic (Hermosillo)", "11e5cc04"], "d": ["L'amministrazione coloniale spagnola fondò una cittadina nel luogo di un antico insediamento indigeno; nel 1828 la cittadina prese il nome di José María González de Hermosillo.", "4724e13c"]},
"OLAYLAR_2S_0919:1716-01-01:0":{"b": ["Fondata la fortezza russa di Omsk alla confluenza Irtyš-Om'", "13dcce5e"], "d": ["Omsk fu fondata come fortezza all'estremità orientale della linea fortificata dell'Išim, tra il Tobol e l'Irtyš; nel 1804 divenne città.", "45facb52"]},
"OLAYLAR_2S_0919:1717-11-30:0":{"b": ["I Dzungari assalgono Lhasa — Lhazang Khan è ucciso, il Tibet cade sotto occupazione dzungara", "65beea29"], "d": ["L'esercito dzungaro al comando di Tsering Döndup, dopo la mezzanotte, attaccò da ogni lato Lhasa, difesa dal sovrano khoshut Lhazang Khan; trovato un appoggio all'interno, i Dzungari presero e saccheggiarono la città e depredarono anche il Potala. Lhazang Khan fu ucciso mentre fuggiva; i Dzungari instaurarono un governo tibetano fantoccio guidato da sTag-rtse-pa.", "b6dcede2"]},
"OLAYLAR_2S_0919:1720-09-24:0":{"b": ["L'esercito Qing entra a Lhasa — termina l'occupazione dzungara, inizia il protettorato Qing", "083358c1"], "d": ["Dei due eserciti inviati da Kangxi in Tibet, la colonna del Sichuan al comando di Galbi, dopo una marcia faticosa, raggiunse Lhasa e prese la città senza resistenza; i Dzungari avevano concentrato tutte le loro forze a Dam contro l'esercito del Kokonor proveniente da nord. Con il ritiro dei Dzungari dal Tibet, i Qing instaurarono a Lhasa un ordinamento stabile di protettorato.", "e5c9dcf8"]},
"OLAYLAR_2S_0919:1721-01-01:0":{"b": ["La spedizione di Aguayo fonda il presidio di Los Adaes", "2031793a"], "d": ["La spedizione del marchese di Aguayo fondò un presidio (avamposto militare) a Los Adaes e ripopolò la missione; il presidio divenne il punto di frontiera del Texas orientale della Nuova Spagna contro la Louisiana francese.", "6ccb0ff2"]},
"OLAYLAR_2S_0919:1722-01-01:0":{"b": ["Fondato l'avamposto russo di Kainsk nella steppa di Baraba", "b14552a8"], "d": ["Dei tre stabili posti fortificati (pas) russi costruiti nella steppa di Baraba, il posto di Kainsk fu fondato sul corso medio del fiume Om', dove vi confluisce il torrente Kainka.", "17a78ef2"]},
"OLAYLAR_2S_0919:1743-01-01:0":{"b": ["Fondata la fortezza russa di Troick sul fiume Uj", "623d75f2"], "d": ["Troick fu fondata come fortezza dove l'Uvelka si getta nell'Uj, e nel 1784 ottenne la patente di città.", "49367d34"]},
"OLAYLAR_2S_0919:1749-12-15:0":{"b": ["Per decreto di Elisabetta è istituita la dogana di Temernik alla foce del Don (nucleo di Rostov)", "46519168"], "d": ["L'imperatrice Elisabetta Petrovna emanò il decreto per l'istituzione di una dogana sul Don, alla foce del fiume Temernik; la dogana di Temernik è l'inizio della storia antica della città di Rostov sul Don.", "51a82ea9"]},
"OLAYLAR_2S_0919:1750-01-01:0":{"b": ["I Francesi fondano un posto commerciale sull'Humber a Toronto", "18975f4c"], "d": ["I Francesi fondarono un secondo avamposto sul fiume Humber; l'anno seguente costruirono Fort Rouillé nell'odierna Exhibition Place.", "66aeb450"]},
"OLAYLAR_2S_0919:1750-01-01:1":{"b": ["Il qajar Muhammad Hasan Khan proclama l'indipendenza; prende Mazandaran e Gilan", "42fc62e8"], "d": ["Con la deposizione dell'afsharide Sulayman Shah, il capo qajar di Astarabad, Muhammad Hasan Khan, proclamò l'indipendenza; oltre ad Astarabad e Gurgan, pose sotto la sua amministrazione anche Mazandaran e Gilan.", "f5398386"]},
"OLAYLAR_2S_0919:1751-01-01:0":{"b": ["Ahmad Shah Durrani annette Balkh al suo paese", "12c6bbf1"], "d": ["Il sovrano afghano Ahmad Shah Durrani annesse Balkh alla sua sfera di sovranità.", "e3ef9016"]},
"OLAYLAR_2S_0919:1751-01-01:1":{"b": ["Karim Khan Zand domina Isfahan — in Persia il dominio afsharide cede il posto all'amministrazione zand", "73cdc1e8"], "d": ["Dopo la morte di Nadir Shah (1747), Isfahan e l''Iraq 'Ajami furono governati a nome degli scià afsharidi 'Adil Shah (6 luglio 1747) e Ibrahim Shah (8 dicembre 1748). Karim Khan Zand tornò a Isfahan nel gennaio 1751 e prese in mano la situazione. Il Khorasan rimase agli Afsharidi sotto l'amministrazione di Shahrukh.", "daab8159"]},
"OLAYLAR_2S_0919:1752-01-01:0":{"b": ["Fondata la fortezza russa di Petropavlovsk sull'Išim", "5d16ef42"], "d": ["Petropavlovsk fu fondata come fortezza russa e in breve tempo divenne un importante centro del commercio tra la Russia e l'Asia centrale e la steppa kazaka.", "f0724528"]},
"OLAYLAR_2S_0919:1759-01-01:0":{"b": ["I Tuareg di Agadez prendono la salina di Bilma al Kanem-Bornu", "1a563a74"], "d": ["Il Kanem-Bornu, in declino nel XVIII secolo, perse molti insediamenti del Sahara quando nel 1759 i Tuareg di Agadez gli sottrassero la salina di Bilma.", "ebfc53c3"]},
"OLAYLAR_2S_0919:1759-02-13:0":{"b": ["Il qajar Muhammad Hasan Khan è sconfitto e ucciso dall'esercito di Karim Khan Zand; Astarabad, Mazandaran e Gilan passano sotto l'amministrazione zand", "38f0a375"], "d": ["L'esercito di Karim Khan inflisse una pesante sconfitta ai Qajar; Muhammad Hasan Khan fu ucciso durante la fuga, e il figlio Agha Muhammad fu condotto a Shiraz. I territori del beylik qajar sulla costa del Caspio entrarono sotto l'amministrazione zand.", "aa7e4a1e"]},
"OLAYLAR_2S_0919:1806-01-01:0":{"b": ["L'esercito del jihad di 'Uthman dan Fodio prende Zaria", "41279ca7"], "d": ["Durante il jihad avviato da 'Uthman dan Fodio, il primo assalto ad Alkalawa, capitale del Gobir, fallì, ma nel 1806 fu presa Zaria.", "680cebf3"]},
"OLAYLAR_2S_0919:1808-01-01:0":{"b": ["Fondata la città di Sultanabad (Arak)", "674237a0"], "d": ["In epoca qajar il generale Yusuf Khan Gurji fondò l'odierna città di Arak e le diede il nome di Sultanabad.", "6ff3f6de"]},
"OLAYLAR_2S_0919:1818-01-01:0":{"b": ["Fondata la cittadina di Beaufort (Beaufort West)", "c5cb1776"], "d": ["Nella Colonia del Capo britannica, sulla fattoria di Hooyvlakte nel Karoo, fu fondata la cittadina di Beaufort.", "70ea5620"]},
"OLAYLAR_2S_0919:1826-01-01:0":{"b": ["Balkh subisce l'occupazione dell'emiro di Bukhara", "cd255a5d"], "d": ["Balkh, sotto il dominio afghano durrani, subì nel 1826 l'occupazione dell'emiro di Bukhara; la città fu ripresa dagli Afghani nel 1841.", "a3ecb1be"]},
"OLAYLAR_2S_0919:1830-01-01:0":{"b": ["La Russia fonda la fortezza di Akmola sull'Išim", "6c727ca9"], "d": ["La Russia costruì la fortezza di Akmola a Karautkul, sul fiume Išim, facendone il capoluogo del paese dei Kirghisi (Kazaki) di Siberia.", "9e7d586f"]},
"OLAYLAR_2S_0919:1847-01-01:0":{"b": ["Fondata la fortificazione di Kopal — il Semirecen'e settentrionale comincia a essere legato alla Russia", "8d4c24c6"], "d": ["La Russia, su richiesta dei Cosacchi dell'Orda Maggiore, fondò la fortificazione di Kopal ai piedi dell'Alatau del Semirecen'e. Secondo la fonte, ciò agevolò l'annessione alla Russia del Semirecen'e settentrionale fino al fiume Ili.", "ebe25fc6"]},
"OLAYLAR_2S_0919:1852-01-01:0":{"b": ["I mercanti della costa si stabiliscono a Kazeh (Tabora)", "173223b0"], "d": ["Dopo un conflitto con un governante locale, mercanti giunti dalla costa dell'Africa orientale emigrarono verso sud; il capo dell'Unyanyembe, Fundikira, diede loro un luogo di insediamento vicino al suo centro di Itetemia. Questo insediamento divenne il nucleo del centro carovaniero di Tabora.", "1261b92f"]},
"OLAYLAR_2S_0919:1861-01-01:0":{"b": ["I Fulani di al-Hajj 'Umar prendono Djenné", "aa4e37f8"], "d": ["Djenné, presidiata dallo Stato di Massina, passò nel 1861 nelle mani dei Fulani guidati da al-Hajj 'Umar.", "bfbc8ebe"]},
"OLAYLAR_2S_0919:1862-05-16:0":{"b": ["Al-Hajj 'Umar prende Hamdallahi — fine dello Stato di Massina", "542f1c0d"], "d": ["Furono sconfitte le truppe alleate di Massina, presso cui si era rifugiato Bina Ali in fuga da Ségou; Hamdallahi, centro di Massina, cadde in mano ad al-Hajj 'Umar, e Bina Ali e Ahmadu Ahmadu furono giustiziati.", "213cc232"]},
"OLAYLAR_2S_0919:1880-06-13:0":{"b": ["Brazza fonda Franceville", "d28410d7"], "d": ["Pierre Savorgnan de Brazza fondò a nome della Francia l'avamposto di Franceville, su uno sperone roccioso che si affaccia sul fiume Mpassa.", "c23dd54e"]},
"OLAYLAR_2S_0919:1885-02-14:0":{"b": ["Convenzione di confine tra lo Stato Libero del Congo e il Portogallo — la sponda sud della foce del Congo al Portogallo", "08a16627"], "d": ["Con la convenzione firmata durante la Conferenza di Berlino, il confine tra lo Stato Libero del Congo e il Portogallo fu tracciato, dalla foce del fiume Congo (Zaire) fino al torrente Uango-Uango, sul fiume stesso; la riva meridionale, dove si trova Soyo, restò al Portogallo, e Cabinda, a nord del fiume, rimase al Portogallo.", "947cb572"]},
"OLAYLAR_2S_0919:1888-05-01:0":{"b": ["La costa dell'Hadramaut (Mukalla) entra sotto protezione britannica", "dc824725"], "d": ["Fu firmato un trattato di protezione tra l'Inghilterra e gli Yafi'i (Qu'ayti), che dominavano la costa dell'Hadramaut, compresi Shihr e Mukalla; gli Inglesi assunsero interamente le relazioni esterne dell'amministrazione yafi'ita della costa.", "98bd94ee"]},
"OLAYLAR_2S_0919:1890-01-01:0":{"b": ["I Francesi dominano l'intero Ualo", "c6d28eaa"], "d": ["I Francesi, che colonizzavano la regione con accordi con i capi tribù, dominarono nel 1890 l'intero Ualo (Oualo).", "15595659"]},
"OLAYLAR_2S_0919:1893-01-01:0":{"b": ["Djenné è occupata dai Francesi", "b207bf62"], "d": ["Djenné, in mano allo Stato fondato da al-Hajj 'Umar, fu occupata nel 1893 dalle forze francesi e annessa al Sudan francese.", "5739cdc4"]},
"OLAYLAR_2S_0919:1894-01-01:0":{"b": ["Gweru fondata come avamposto militare", "bd37b323"], "d": ["Nella parte centrale dell'odierno Zimbabwe la città di Gweru fu fondata come avamposto militare; divenne poi un centro agricolo e nel 1914 ottenne lo statuto di municipalità.", "a8f323b9"]},
"OLAYLAR_2S_0919:1897-01-01:0":{"b": ["Il Sultanato del Baguirmi entra sotto protezione francese", "59f20c32"], "d": ["Di fronte alla minaccia di Rabih, il sovrano del Baguirmi Gaourang stipulò con la Francia un trattato di protezione obbligato. Quando Rabih, reagendo, mosse a occupare il Baguirmi, Gaourang incendiò di propria mano la capitale Massenya.", "fcb0958f"]},
"OLAYLAR_2S_0919:1897-10-01:0":{"b": ["Il Regno di Caffa è annesso all'Abissinia — l'ultimo re Gaki Sherocho è fatto prigioniero", "c03c44c5"], "d": ["Le forze di Menelik II al comando di ras Walda Giyorgis entrarono a Caffa nel marzo 1897. Dopo duri combattimenti Caffa fu conquistata; l'ultimo re, Gaki Sherocho, fu catturato e si arrese nell'ottobre 1897.", "a434cc44"]},
"OLAYLAR_2S_0919:1898-01-01:0":{"b": ["Gao è occupata dai Francesi", "01eabb4c"], "d": ["Gao, antica capitale songhai sulle rive del Niger, fu occupata dai Francesi nel 1898; dopo l'occupazione la città tornò a crescere e divenne il centro della regione.", "653ce49b"]},
"OLAYLAR_2S_0919:1899-01-01:0":{"b": ["Fondato il deposito di rifornimento di Nairobi della Ferrovia dell'Uganda", "a3ce3389"], "d": ["Nell'area paludosa, fino ad allora in gran parte disabitata, dove sorge l'odierna Nairobi, gli Inglesi fondarono il deposito di rifornimento della Ferrovia dell'Uganda, che collegava Mombasa all'Uganda.", "467c7577"]},
"OLAYLAR_2S_0919:1901-01-01:0":{"b": ["L'Adamawa è spartito — Yola resta nella Nigeria settentrionale britannica", "11104686"], "d": ["L'Adamawa fu spartito tra la Nigeria settentrionale, dipendente dall'Inghilterra, e il Camerun, dipendente dalla Germania; Bobbo Ahmadu, quarto figlio di Adama, divenne emiro di Yola nella zona britannica.", "aabd087e"]},
"OLAYLAR_2S_0919:1903-07-27:0":{"b": ["Battaglia di Burmi — termina il dominio politico del Califfato di Sokoto", "c7d87e2c"], "d": ["Il califfo Muhammad Tahir, fuggito dopo l'occupazione di Sokoto da parte degli Inglesi, fu ucciso in un nuovo scontro con gli Inglesi; terminò il dominio politico del califfato di Sokoto, durato circa un secolo.", "b37ec3fb"]},
"OLAYLAR_2S_0919:1904-01-01:0":{"b": ["Nakuru fondata ufficialmente come cittadina", "d82a2d76"], "d": ["Grazie alla sua posizione sulla ferrovia dell'Uganda, Nakuru fu fondata ufficialmente come cittadina e divenne centro dei prodotti agricoli della regione.", "bf30445b"]},
"OLAYLAR_2S_0919:1905-01-01:0":{"b": ["Aperta la stazione del Mar d'Aral sulla ferrovia Orenburg-Tashkent — nasce l'insediamento di Aralsk", "85803dcb"], "d": ["Quando la ferrovia dell'Impero russo che collegava Orenburg a Tashkent passò per l'estremità nord-orientale del Mar d'Aral, fu aperta sulla riva la stazione 'Aral'skoe More'; accanto alla stazione sorse un insediamento di pescatori. L'insediamento ottenne lo statuto di città nel 1938 e prese il nome di Aralsk.", "99e15bce"]},
"OLAYLAR_2S_0919:1909-06-02:0":{"b": ["I Francesi prendono Abéché — fine del Sultanato del Wadai", "3c9b117b"], "d": ["I Francesi, proseguendo l'avanzata verso est, presero Abéché (Abishe), capitale del Wadai, ponendo fine al Sultanato del Wadai; l'ultimo sultano si ritirò senza essere riuscito a salvare la capitale.", "1f305da8"]},
"OLAYLAR_2S_0919:1910-05-31:0":{"b": ["Fondata l'Unione Sudafricana", "7434a47f"], "d": ["In forza del South Africa Act del 1909, le colonie del Capo, del Natal, del Transvaal e del fiume Orange si unirono il 31 maggio 1910 con il nome di Unione Sudafricana, legata all'Impero britannico; il centro dell'esecutivo fu Pretoria, quello del legislativo Città del Capo. Con questa unione le città delle colonie del Capo, del Natal, del Transvaal e dell'Orange (Kimberley, Durban, Pietermaritzburg, Potchefstroom, Port Elizabeth ecc.) passarono all'Unione Sudafricana.", "7fc35ce0"]},
"OLAYLAR_2S_0919:1911-01-01:0":{"b": ["I Francesi occupano Djanet", "f32997c8"], "d": ["Djanet, nahiye ottomano dipendente da Ghat, fu occupata dai Francesi nel 1911. Lo sceicco Amud, direttore del nahiye, aveva ricevuto fino a quella data uno stipendio dallo Stato ottomano.", "7075093e"]},
"OLAYLAR_2S_0919:1915-01-01:0":{"b": ["Anchorage fondata come centro della Ferrovia dell'Alaska", "f5014711"], "d": ["Dopo l'approvazione dell'Alaska Railroad Act da parte del Congresso il 12 marzo 1914, nella primavera del 1915 la Commissione di Ingegneria dell'Alaska impiantò il cantiere ferroviario a Ship Creek; sulla riva sorse una città di tende e nell'aprile 1915 l'ufficio postale diede alla nuova cittadina il nome di Anchorage. La città divenne il centro della Ferrovia dell'Alaska, che si estendeva a nord fino a Fairbanks.", "ffe4cba5"]},
"OLAYLAR_7A4170:1856-01-01:0":{"b": ["Legame di Jaghbub, centro desertico dei Senussi, con l'ordinamento ottomano — firmano di esenzione di Abdülmecid", "039fce6d"], "d": ["Muhammad b. Ali al-Sanusi, rimasto a lungo alla Mecca, dopo il ritorno in Tripolitania si stabilì nell'oasi di Jaghbub al confine egiziano e vi fece costruire su una roccia dominante una grande zâviye; il luogo, composto di poche baracche, si trasformò presto in una città. Nel 1856, con il firmano del sultano Abdülmecid, i beni appartenenti ai membri della confraternita furono esentati dalle imposte e ai murid fu data l'autorità di raccogliere la zakat. Questo firmano fece dell'oasi, sulla via carovaniera che collega l'Africa occidentale e il Sudan al Cairo, una parte dell'ordinamento finanziario e amministrativo ottomano e rafforzò Jaghbub come centro commerciale. La fedeltà della popolazione della regione al califfo è confermata anche dal resoconto di viaggio del miralay Sadık el-Müeyyed, che visitò il luogo nel 1884 e nel 1893.", "dbe926fd"]},
"OLAYLAR_7A4170:1859-04-25:0":{"b": ["Inizio dello scavo del Canale di Suez e fondazione di Port Said", "cef0be8d"], "d": ["I lavori di scavo del progetto Lesseps, approvato dalla Sublime Porta il 5 gennaio 1856, iniziarono il 25 aprile 1859; il canale sarebbe stato completato dieci anni dopo, il 16 novembre 1869. All'estremità mediterranea dello scavo, sul cordone costiero tra il lago Menzaleh e il mare, il villaggio di baracche di cinque case costruito per gli operai costituì il nucleo di Port Said. Alla città fu dato nel 1860 dai dirigenti della società del canale questo nome, che significa 'porto di Said', in omaggio all'allora governatore d'Egitto Said Pascià. Così sulla mappa ottomana nacque un nuovo porto su una striscia costiera in cui non c'era stato prima alcun insediamento.", "3e95556e"]},
"OLAYLAR_7A4170:1863-04-03:0":{"b": ["Visita del sultano Abdülaziz in Egitto e fondazione di Ismailia sull'istmo di Suez", "bcfacf38"], "d": ["Il sultano Abdülaziz, su incoraggiamento del gran visir Yûsuf Kâmil Pascià, si recò in Egitto il 3 aprile 1863 e fu accolto con grandi manifestazioni; lo scopo era rafforzare il legame con il centro della provincia che dalla rivolta di Mehmed Ali Pascià di Kavala aveva cominciato di fatto a diventare uno Stato separato. Nello stesso anno sull'istmo, sulle colline di Tilâlülcisr sulla riva del lago Timsah, fu stabilito il centro amministrativo della società del canale: prima il villaggio di Karyetüttimsah per gli ingegneri, poi quello di Karyetülarab per gli operai. Poiché il khedivé İsmâil Pascià si interessava da vicino al canale d'acqua dolce e fece costruire per sé un padiglione su questa collina, l'insediamento fu detto con il suo nome Ismailia. La fondazione della città è datata al 1863; il giorno esatto non è noto.", "bab96585"]},
"OLAYLAR_7A4170:1869-01-01:0":{"b": ["Governatorato di Midhat Pascià a Baghdad e insediamento tribale — fondazione di Ramadi e Nasiriyya", "0fa98f06"], "d": ["Midhat Pascià, tolto dalla presidenza dello Şûrâ-yı Devlet e allontanato da Istanbul, governò la provincia di Baghdad, comprendente anche Mosul e Bassora, tra il 1869 e il 1872 con ampi poteri, avendo anche il comando della Sesta Armata. Applicandovi il Codice Fondiario (Arazi Kanunnâmesi) e la nuova legge sulle province, distribuì le terre con il tapu, legando le tribù nomadi all'ordinamento sedentario e all'autorità dello Stato. Come prodotto di questa politica di insediamento nel 1869 furono fondate Ramadi sull'Eufrate per la tribù dei Dulaym e, nel sud, Nasiriyya per mano del mutasarrıf dei Muntafiq Nâsır Pascià es-Sa'dûn; entrambe nacquero in punti in cui fino ad allora non c'erano insediamenti ed entrarono sulla mappa per la prima volta in questa data.", "7babb36f"]},
"OLAYLAR_AMERIKA0920:1511-08-15:0":{"b": ["Fondata Baracoa — prima cittadina della conquista spagnola di Cuba", "8c033cf1"], "d": ["Diego Velázquez de Cuéllar iniziò nel 1511 la conquista di Cuba con le forze portate da Hispaniola e fondò Nuestra Señora de la Asunción de Baracoa, prima cittadina spagnola dell'isola. Baracoa divenne la base delle spedizioni dirette verso il Messico nei venti anni successivi (Hernández de Córdoba, Grijalva, Cortés).", "e3cd5e94"]},
"OLAYLAR_AMERIKA0920:1519-03-25:0":{"b": ["Battaglia di Centla — cade la signoria maya di Potonchán, fondata Santa María de la Victoria", "8489a7d8"], "d": ["La flotta di Cortés, partita da Cuba, sbarcò a Potonchán, città maya chontal alla foce del fiume Grijalva. Gli Spagnoli, vittoriosi nella battaglia della piana di Centla grazie alla superiorità della cavalleria e delle armi da fuoco, fondarono al posto della città la cittadina di Santa María de la Victoria. È il primo insediamento spagnolo stabile sulla terraferma messicana; Malintzin (doña Marina), che sarebbe stata interprete di Cortés, era tra i doni offerti qui.", "8bbece52"]},
"OLAYLAR_AMERIKA0920:1519-08-15:0":{"b": ["Fondata Panamá — prima città europea sulla costa del Pacifico", "c0d86c22"], "d": ["Il governatore del Darién, Pedrarias Dávila, fondò la città di Panamá sul versante pacifico dell'istmo e vi trasferì l'amministrazione coloniale dalla costa caraibica. La città divenne il porto di partenza delle spedizioni di esplorazione e conquista dirette a sud; le spedizioni di Francisco Pizarro verso il Perù furono allestite da qui.", "ce7e51d9"]},
"OLAYLAR_AMERIKA0920:1520-09-04:0":{"b": ["La presa di Tepeaca — la prima conquista di Cortés dopo la Noche Triste", "a9c27711"], "d": ["Cortés, ritiratosi con gravi perdite da Tenochtitlan nella notte del 30 giugno 1520 (Noche Triste), dopo aver trovato rifugio a Tlaxcala sferrò il primo attacco al señorío di Tepeaca, legato alla Triplice Alleanza. Preso il centro, vi fondò una cittadina spagnola con il nome di Segura de la Frontera; così fu messa in sicurezza la via tra la costa di Veracruz e Tlaxcala e si preparò la base per la seconda marcia sulla capitale.", "a7a4b070"]},
"OLAYLAR_AMERIKA0920:1523-07-25:0":{"b": ["Fondata San Sebastián de Colima — la Nuova Spagna si apre alla costa del Pacifico", "30332cab"], "d": ["Gonzalo de Sandoval, uno dei comandanti di Cortés, sottomise la valle di Colima, nel Messico occidentale, e fondò la cittadina di San Sebastián de Colima. La cittadina divenne una delle prime basi della Nuova Spagna sulla costa del Pacifico e negli anni seguenti alimentò i cantieri delle spedizioni di esplorazione del Mar del Sud.", "f5225860"]},
"OLAYLAR_AMERIKA0920:1534-12-06:0":{"b": ["Fondata San Francisco de Quito — ordinamento spagnolo nella capitale settentrionale inca", "7bb9f316"], "d": ["Il generale inca Rumiñahui incendiò Quito, capitale del nord, prima di lasciarla agli Spagnoli. Sebastián de Benalcázar fondò San Francisco de Quito sulle rovine; così, dopo Cuzco, anche il secondo centro dello Stato inca fu legato all'amministrazione spagnola e di qui fu condotta la conquista nelle Ande settentrionali.", "569e8d50"]},
"OLAYLAR_AMERIKA0920:1535-01-18:0":{"b": ["Fondata Lima — la capitale del Perù spagnolo si sposta nella valle del Rímac", "1f15658c"], "d": ["Francisco Pizarro, poiché Cuzco, sulle montagne, era lontana dai collegamenti marittimi con la Spagna, fondò nella valle costiera del Rímac la Ciudad de los Reyes (Lima). La città divenne presto capitale del Vicereame del Perù e centro dell'amministrazione spagnola in America meridionale.", "97bcf9d0"]},
"OLAYLAR_AMERIKA0920:1537-01-13:0":{"b": ["Fondata Popayán — ponte tra Quito e il paese dei Muisca", "bf451979"], "d": ["Benalcázar, in marcia verso nord da Quito, fondò Popayán nella valle del Cauca. La città divenne l'estremità settentrionale dell'avanzata spagnola proveniente dal Perù e, l'anno seguente, aprì la strada all'incontro con Quesada nel paese dei Muisca.", "fe54a6a7"]},
"OLAYLAR_AMERIKA0920:1537-08-01:0":{"b": ["La presa di Hunza — sconfitta dello zaque Quemuenchatocha", "e8c1b661"], "d": ["Gonzalo Jiménez de Quesada, salito all'altopiano dal fiume Magdalena, travolse Hunza, centro del zacazgo, una delle due teste della Confederazione Muisca, e catturò lo zaque Quemuenchatocha. L'oro preso in città fu il vero bottino che alimentò la voce dell'Eldorado; la metà settentrionale del paese dei Muisca passò così sotto il dominio spagnolo.", "78bf5be1"]},
"OLAYLAR_AMERIKA0920:1537-08-15:0":{"b": ["Fondata Asunción — base spagnola sul fiume Paraguay", "9a6dfa42"], "d": ["Poiché la spedizione del Río de la Plata non riuscì a mantenersi a Buenos Aires, gli Spagnoli risalirono il fiume e Juan de Salazar de Espinosa fondò Nuestra Señora de la Asunción, basandosi sull'alleanza stretta con le comunità guaraní. Per un secolo la cittadina rimase il centro dell'amministrazione spagnola nel bacino del Río de la Plata.", "451f5b55"]},
"OLAYLAR_AMERIKA0920:1538-08-06:0":{"b": ["Fondata Santa Fe de Bogotá — capitale spagnola nel paese dei Muisca", "3ed6c301"], "d": ["Quesada fondò Santa Fe de Bogotá accanto a Bacatá, centro dello zipa. Subito dopo la fondazione, le colonne di conquista giunte da tre direzioni diverse — Quesada, Benalcázar e il comandante tedesco Federmann — si incontrarono sullo stesso altopiano e convennero di risolvere le loro rivendicazioni in Spagna. La città divenne capitale del Nuovo Regno di Granada.", "cd8c76fd"]},
"OLAYLAR_AMERIKA0920:1539-01-09:0":{"b": ["Fondata San Juan de la Frontera de Huamanga — la serratura della strada Lima-Cuzco", "3f1cfdbf"], "d": ["La resistenza condotta da Manco Inca da Vilcabamba interrompeva la strada tra Lima e Cuzco. Francisco Pizarro, per mettere in sicurezza questa strada, fondò San Juan de la Frontera de Huamanga a metà tra le due capitali; la parola 'frontera' (frontiera) nel nome della cittadina dichiara direttamente lo scopo della fondazione.", "fcd683ec"]},
"OLAYLAR_AMERIKA0920:1539-08-06:0":{"b": ["Tunja rifondata come città spagnola", "c3a12867"], "d": ["Dopo il ritorno di Quesada in Spagna, Gonzalo Suárez Rendón rifondò, secondo l'ordinamento spagnolo, la città di Tunja nel luogo di Hunza, centro dello zaque. Così la metà settentrionale del paese dei Muisca, come quella di Bogotá, fu legata a un ordinamento municipale e di encomienda stabile.", "fdbb81cc"]},
"OLAYLAR_AMERIKA0920:1540-10-04:0":{"b": ["Fondata San Francisco de Campeche — terzo e duraturo tentativo di conquista dello Yucatán", "62af9901"], "d": ["Dopo due spedizioni fallite per prendere lo Yucatán, Francisco de Montejo (il figlio) fondò la cittadina di San Francisco de Campeche nel luogo della città maya di Can Pech. Questo porto divenne la base di rifornimento delle forze che avrebbero marciato all'interno della penisola e il punto di partenza della spedizione che portò, due anni dopo, alla fondazione di Mérida.", "079bb50a"]},
"OLAYLAR_AMERIKA0920:1541-02-12:0":{"b": ["Fondata Santiago del Nuevo Extremo — inizia la conquista del Cile", "04cd7c3b"], "d": ["Pedro de Valdivia, in marcia verso sud dal Perù, fondò Santiago del Nuevo Extremo nella valle del Mapocho. La cittadina fu incendiata nel settembre dello stesso anno da un attacco indigeno guidato da Michimalonco e rifondata; ciononostante la conquista spagnola del Cile fu condotta a partire da questo punto.", "7cfe7c18"]},
"OLAYLAR_AMERIKA0920:1545-01-01:0":{"b": ["Il señorío dei Cocom di Sotuta entra sotto il dominio spagnolo", "db6a6487"], "d": ["Sotuta, uno dei più potenti señoríos maya dell'interno dello Yucatán, resistette a lungo all'avanzata spagnola sotto la dinastia dei Cocom. Negli anni seguenti alla fondazione di Mérida nel 1542 il señorío accettò il dominio spagnolo; dopo la repressione della grande rivolta orientale del 1546-47, questa sottomissione divenne stabile.", "461a3b98"]},
"OLAYLAR_AMERIKA0920:1571-08-15:0":{"b": ["Fondata la Villa de Oropesa — popolamento della valle dei cereali che avrebbe rifornito Potosí", "d6821cbf"], "d": ["Per ordine del viceré Francisco de Toledo fu fondata la Villa de Oropesa nella valle di Cochabamba. Il fertile suolo della valle fu organizzato come zona cerealicola per nutrire la numerosa manodopera delle miniere d'argento di Potosí; la cittadina divenne il granaio dell'Alto Perù coloniale.", "52cdfafe"]},
"OLAYLAR_AMERIKA0920:1572-06-24:0":{"b": ["La caduta di Vilcabamba — fine dello Stato inca indipendente", "31b5a95d"], "d": ["Dopo la caduta di Cuzco nel 1533, Manco Inca e i suoi successori mantennero per quarant'anni nelle montagne di Vilcabamba uno Stato inca indipendente. La spedizione organizzata dal viceré Francisco de Toledo prese la capitale abbandonata; l'ultimo sovrano, Túpac Amaru, catturato durante la fuga, fu condotto a Cuzco e lì giustiziato. Così terminò l'esistenza politica della dinastia inca, durata quattro secoli nel mondo andino.", "957d76a8"]},
"OLAYLAR_AMERIKA0920:1596-09-20:0":{"b": ["Fondata Monterrey — capitale del Nuevo León", "ec6e44bc"], "d": ["Diego de Montemayor, dopo due tentativi falliti, fondò la Ciudad Metropolitana de Nuestra Señora de Monterrey presso la sorgente di Santa Lucía. Questo insediamento sulla frontiera settentrionale divenne il punto d'appoggio della duratura espansione della Nuova Spagna verso nord-est (Nuevo León).", "6bfa991f"]},
"OLAYLAR_AMERIKA0920:1619-01-01:0":{"b": ["Fondata San Francisco de Borja — dominio spagnolo a Maynas", "7ee32d19"], "d": ["Diego Vaca de Vega fondò San Francisco de Borja a valle dello stretto del Pongo de Manseriche sul fiume Marañón e legò la regione di Maynas all'amministrazione spagnola. La cittadina divenne il punto di partenza della rete di missioni gesuite dell'alto Rio delle Amazzoni, destinata a durare per il secolo successivo.", "83ae5281"]},
"OLAYLAR_AMERIKA0920:1718-05-01:0":{"b": ["Fondata la missione di San Antonio de Valero — nucleo del Texas spagnolo", "ca9bd147"], "d": ["In risposta alla penetrazione francese verso ovest dalla Louisiana, la Spagna decise di stabilire un insediamento stabile in Texas. Padre Olivares fondò la missione di San Antonio de Valero sulle rive del fiume San Antonio; pochi giorni dopo il governatore Alarcón vi collocò accanto il presidio di San Antonio de Béxar. L'edificio della missione sarà poi noto come Alamo.", "74e48544"]},
"OLAYLAR_AMERIKA0920:1774-01-01:0":{"b": ["Fondata Refugio (l'odierna Matamoros) — popolamento della foce del Rio Grande", "f3b86da7"], "d": ["Il programma di colonizzazione di Nuevo Santander condotto da José de Escandón dagli anni 1740 popolò il basso bacino del Rio Grande di fattorie e cittadine. Nuestra Señora del Refugio de los Esteros fu fondata sulla riva meridionale del fiume come uno degli ultimi anelli di questo programma; nel XIX secolo prese il nome di Matamoros.", "913bb307"]},
"OLAYLAR_AMERIKA0920:1821-09-15:0":{"b": ["Atto di indipendenza dell'America Centrale — la Capitaneria Generale del Guatemala si separa dalla Spagna", "f998089a"], "d": ["Dopo il Piano di Iguala in Messico, l'assemblea riunita in Guatemala proclamò l'indipendenza della Capitaneria Generale dalla Spagna; il capitano generale Gabino Gaínza rimase a capo dell'amministrazione di transizione. Così terminò il dominio spagnolo sui territori dell'odierno Guatemala, El Salvador, Honduras, Nicaragua e Costa Rica. La regione, dopo essere stata per breve tempo annessa all'Impero messicano, fondò nel 1823 le Province Unite dell'America Centrale.", "c4e39cd1"]},
"OLAYLAR_AMERIKA0920:1839-01-01:0":{"b": ["Fondata Nueva Helvetia — il Messico apre la valle del Sacramento alla colonizzazione", "067a1f2a"], "d": ["L'immigrato svizzero John Sutter, con il permesso e la concessione di terra ottenuti dalle autorità messicane, fondò Nueva Helvetia alla confluenza dei fiumi Sacramento e American. La fattoria fortificata divenne l'avamposto messicano più avanzato nell'interno dell'Alta California; con la scoperta dell'oro nel 1848 sarebbe diventata il centro dell'immigrazione in California.", "1c5eab3d"]},
"OLAYLAR_EBUKIR0919:1798-08-01:0":{"b": ["Battaglia navale di Abukir (del Nilo) — distruzione della flotta di Napoleone", "be4ad8d8"], "d": ["La flotta francese che aveva trasportato in Egitto l'esercito di Napoleone, mentre attendeva all'ancora nella baia di Abukir, fu sorpresa dalla flotta dell'ammiraglio britannico Nelson e distrutta in una battaglia durata una notte; la nave ammiraglia L'Orient esplose. Così Nelson privò dell'appoggio navale l'esercito francese di terra in Egitto: l'esercito non poteva né ricevere rinforzi né tornare indietro. Cinque settimane dopo anche lo Stato ottomano dichiarò guerra alla Francia.", "9f27937f"]},
"OLAYLAR_EBUKIR0919:1799-07-25:0":{"b": ["Battaglia terrestre di Abukir — sconfitta di Köse Mustafa Pascià", "35a695f3"], "d": ["Napoleone, tornato sconfitto da San Giovanni d'Acri, sconfisse a Abukir le forze ottomane al comando di Köse Mustafa Pascià e la fortezza di Abukir cadde in mano ai Francesi. Questa costa, dove un anno prima era stata affondata la flotta francese, sarebbe stata due anni dopo anche il luogo dello sbarco dell'esercito britannico venuto a cacciare i Francesi dall'Egitto (8 marzo 1801).", "da0b6c57"]},
"OLAYLAR_EK10:1402-07-28:0":{"b": ["Dopo la disfatta di Ankara il voivoda di Valacchia Mircea riprende la Dobrugia — Silistra, Costanza, Babadag, Isaccea", "5eaefc68"], "d": ["La sconfitta di Yıldırım Bayezid da Tamerlano ad Ankara scosse il dominio ottomano lungo il Danubio. Il voivoda di Valacchia Mircea, approfittando di questo vuoto, rientrò in Dobrugia; Silistra, i dintorni di Costanza e Babadag e Isaccea, sulla riva del Danubio, rimasero in mano sua per tutti gli anni dell'Interregno. Mircea sostenne Mûsâ Çelebi contro Çelebi Mehmed. Tenne Silistra fino alla morte nel 1418.", "58dabbe8"]},
"OLAYLAR_EK10:1416-01-01:0":{"b": ["Passaggio di Babadag e dintorni agli Ottomani — Mircea e il figlio Mihail sconfitti", "bfda2c60"], "d": ["Çelebi Mehmed, dopo aver sconfitto il voivoda di Valacchia Mircea e il figlio Mihail, pose sotto dominio ottomano Babadag e i dintorni nella Dobrugia settentrionale. Babadag era una cittadina che portava il nome di Saltuk Baba e fondata con un insediamento turcomanno del XIII secolo. Silistra, Costanza e le altre fortezze della Dobrugia circostanti rimasero invece alla Valacchia fino al 1419; cioè Babadag appare per tre anni come un'isola (exclave) staccata dal territorio ottomano.", "b1e2339a"]},
"OLAYLAR_EK10:1419-01-01:0":{"b": ["Ripresa di Silistra e della Dobrugia — dopo la morte di Mircea", "73eb6ae9"], "d": ["La confusione scoppiata in Valacchia dopo la morte del voivoda Mircea nel 1418 diede a Çelebi Sultan Mehmed l'occasione di riprendere Silistra e la Dobrugia. Nella primavera del 1419 Silistra, Costanza e gran parte della Dobrugia entrarono di nuovo sotto amministrazione ottomana; le fortezze di Enisala (Yenisale) e Isaccea furono riparate e fatte fortezze di confine (serhat); la Dobrugia da allora rimase ottomana fino al 1878.", "a2a9ad4e"]},
"OLAYLAR_EK10:1420-01-01:0":{"b": ["Chiusura del basso Danubio — annessione di Giurgiu, Turnu e Orsova", "331a0b68"], "d": ["Dopo la chiusura dell'Interregno la mossa di Çelebi Mehmed per mettere in ordine la linea del Danubio nel 1420 diede frutto. La fortezza di Giurgiu, che il voivoda di Valacchia Mircea il Vecchio aveva fatto costruire sul proprio territorio coprendone la spesa con la vendita del sale, quest'anno passò in mano ottomana (la Dobrugia era stata ripresa un anno prima, nella primavera del 1419 — TDV silistre) e furono annesse Turnu (Kule/Holovnik) sulla riva destra del Danubio e Orșova — poi detta Fetislam. Così le due rive del fiume furono messe contemporaneamente sotto controllo. L'importanza di Giurgiu è nella sua geografia: è una fortezza ottomana costruita sulla riva sinistra, cioè valacca, del Danubio e tiene le due estremità dello stesso passaggio con Ruse sulla riva opposta. I documenti ottomani scrivono apertamente questa dualità — per Ruse si dice 'Yergöğü, riva di qua', per Giurgiu 'Yergöğü, riva di là'. La fortezza sarebbe stata ripresa dai Valacchi nel 1427, nel 1449 sarebbe tornata di nuovo sotto controllo ottomano e il kaza di Giurgiu, legato al sanjak di Nicopoli, sarebbe diventato un'isola amministrata direttamente all'interno del voivodato. Qui comincia la risposta sulla mappa al perché la riva danubiana della Valacchia sia di colore scuro.", "4c3c95d4"]},
"OLAYLAR_EK10:1433-01-01:0":{"b": ["La regione di Toplica (Kuršumlija, Prokuplje) entra sotto il dominio ottomano", "e22e690d"], "d": ["Durante il fidanzamento di Murad II con Mara Branković si ritiene probabile che la regione di Dubočica e Toplica (dintorni di Leskovac, Kuršumlija e Prokuplje) sia passata al dominio ottomano; la registrazione del censimento del 1445-1447 mostra che la regione era data come timar ai sipahi ottomani. Sulla mappa Kuršumlija e Prokuplje da quest'anno sono sotto amministrazione ottomana.", "335352f1"]},
"OLAYLAR_EK10:1448-01-01:0":{"b": ["Annessione della piana di Sarajevo (Saray) — stabilimento di un avamposto ottomano all'interno della Bosnia", "be5c0f00"], "d": ["Dopo che i re di Bosnia nel 1428-1429 furono sottoposti a tributo, gli Ottomani cominciarono a insediarsi in modo stabile all'interno del regno. Tra il 1428 e il 1435 fu presa la cittadina di Hodidjed; nell'852 (1448) la provincia di Hodidjed con la piana di Saray entrò completamente sotto amministrazione ottomana. È un territorio di confine stabilito nel mezzo del regno quindici anni prima della conquista della Bosnia e amministrato dal bey di Skopje Îsâ Bey, che portava il titolo di voivoda — poiché nei dintorni c'erano ancora bey bosniaci tributari agli Ottomani, la regione era sotto doppio controllo. Anche la città stessa nacque in questo periodo: prima del 1462 İshak Bey o il figlio Îsâ Bey fondò il primo quartiere musulmano, nell'862 (1458) fu costruita a nome di Maometto il Conquistatore la Moschea Hünkâr e, bonificati i campi del villaggio di Brodec, comparve la cittadina di Saray. La conquista del 1463 abolì il Regno di Bosnia; la piana di Saray in quella data era già da quindici anni territorio ottomano.", "df377352"]},
"OLAYLAR_EK10:1457-01-01:0":{"b": ["Annessione di Podgorica ai territori ottomani — messa sotto controllo della piana della Zeta", "46e401c5"], "d": ["La cittadina, sorta a venti chilometri a nord del lago di Scutari, nella piana in cui confluiscono le acque di Morača e Ribnica, nelle fonti è ricordata per la prima volta nel 1216 come Ribnica, nel 1326 come Podgorica. Nel 1457 fu annessa ai territori ottomani e il controllo della piana della Zeta uscì così dalle mani delle dinastie Balšić-Crnojević. Maometto il Conquistatore tra il 1474 e il 1478 fece costruire una fortezza e una moschea sulle rocce scoscese alla confluenza dei due fiumi; nel 1479, dopo la conquista di Scutari, la regione fu legata al nuovo sanjak di Scutari. Podgorica, cittadina cristiana di quaranta case nel censimento del 1485, nel 1529-30 raggiunse 800 persone e una guarnigione di trentadue uomini agli ordini di un dizdar nella fortezza, nel 1582 322 case. Evliya Çelebi nel 1662 contò nella Fortezza di Fatih trecento case, magazzini, arsenali e settecento guardie. Questi registri mostrano anche la differenza tra la pianura e la montagna della Zeta: la pianura è un kaza ottomano censito, tassato e con guarnigione — eppure nel XVIII secolo la città dovrà essere fortificata con sei bastioni e mura a tre porte per prevenire le incursioni delle tribù dei monti montenegrini. Podgorica passò al Montenegro alla fine della guerra del 1876-1878 e vi rimase con il Trattato di Berlino.", "d0b08ff8"]},
"OLAYLAR_EK10:1465-01-01:0":{"b": ["Presa di Foča — apertura del primo accesso al Ducato di Erzegovina", "f098a9e6"], "d": ["Dopo l'abolizione del Regno di Bosnia nel 1463, toccò ai territori di Stjepan Vukčić-Kosača, che si era staccato dal regno fondando un proprio ducato. Foča, nella valle della Drina, al crocevia della via commerciale che collega Istanbul a Dubrovnik, nel 1465 entrò sotto amministrazione ottomana. L'importanza della città fu subito compresa: nel 1470 fu fatta centro del nuovo sanjak di Erzegovina — cioè il nucleo amministrativo dell'Erzegovina fu stabilito a Foča prima che il ducato stesso fosse abbattuto. L'annessione dell'intero ducato sarebbe durata fino al 1483. Foča da allora si sviluppò come centro commerciale e amministrativo grazie al clima favorevole e alla posizione al crocevia. Sulla mappa questa data è il giorno in cui inizia la seconda ondata verso sud dopo la conquista della Bosnia.", "9acfcdda"]},
"OLAYLAR_EK10:1469-01-01:0":{"b": ["Annessione definitiva di Livno e della Bosnia occidentale — creazione del confine con Venezia", "c14d4283"], "d": ["La fortezza sull'altopiano che domina la piana di Livno nel 1448-1454 era in mano a Stjepan Vukčić-Kosača, fondatore del Ducato di Erzegovina. Nella campagna di Bosnia del 1463 era stata occupata per breve tempo dalle forze ottomane, ma era stata ripresa nello stesso anno; nel 1466 il signore della città è Ivaniš Vlatković. Nelle parole del TDV il dominio ottomano definitivo si realizzò con grande probabilità nel 1468-1469 e il censimento del 1485 registra Livno ormai come territorio ottomano. Questa è la chiusura dell'estremità occidentale della conquista della Bosnia: Livno divenne una pericolosa cittadina di confine, confinante lungo la pianura piana con territori veneziani distanti solo trentasei chilometri, e mantenne questa posizione fino alla presa delle fortezze veneziane da parte del governatore di Bosnia Gazi Hüsrev Bey nel 1521-1522.", "8e012cb5"]},
"OLAYLAR_EK10:1476-02-01:0":{"b": ["Perdita di Böğürdelen a favore degli Ungheresi — prima breccia sulla linea della Sava", "129fe8f2"], "d": ["Nel luogo passato in mano ottomana al tempo di Maometto il Conquistatore e prima detto Zaslon, nel 1471 era stato costruito un forte di legno e terra. Poiché si trovava in un punto che minacciava Belgrado e di lì si potevano facilmente compiere incursioni nelle regioni meridionali di Ungheria e Austria, la fortezza prendeva il nome da questa funzione — Böğürdelen significa 'bastione che colpisce di fianco'. Il re d'Ungheria Mattia Corvino verso la fine del 1475 assediò la fortezza e nel febbraio 1476 la prese. L'epopea ungherese Szabács viadala, che narra l'assedio, è uno degli esempi più lunghi giunti fino a noi dei poemi storici ungheresi del XV secolo. Gli Ungheresi costituirono nella regione un banato e rifortificarono in pietra la fortezza, facendone un anello della catena di forti di confine. Gli Ottomani tentarono di riprenderla nel 1492 e non vi riuscirono; la fortezza rimase quarantacinque anni in mano ungherese.", "87ae8b15"]},
"OLAYLAR_EK10:1479-08-01:0":{"b": ["Conquista delle isole Ionie — fine del ducato dei Tocco: Ayamavra, Cefalonia, Zante, Itaca", "07b27251"], "d": ["Il Trattato di Istanbul firmato con Venezia nel gennaio dello stesso anno aveva lasciato agli Ottomani Scutari e la costa albanese; le isole Ionie invece non erano sotto l'amministrazione di Venezia ma della famiglia Tocco, che teneva la contea di Cefalonia-Zante, e furono prese con un'operazione separata. Secondo la voce Ayamavra del TDV l'ultimo duca Leonardo Tocco aveva dapprima conservato la fedeltà sposando Milica Branković, parente di Maometto il Conquistatore, ma nel 1464, alla morte della moglie, nel 1477 sposando Francesca Marzano della dinastia di Napoli aveva offeso il sultano. Due anni dopo la flotta al comando del bey di Valona Gedik Ahmed Pascià prese Ayamavra insieme a Cefalonia, a sud; Leonardo e Francesca fuggirono in Italia. La voce Gedik Ahmed Paşa registra che nella stessa operazione fu presa anche Zante (Zakynthos); Itaca, legata alla contea di Cefalonia, entrò con questo passaggio sotto amministrazione ottomana. Così la via marittima che si estende dall'imboccatura dell'Adriatico alla Morea fu interamente posta sotto controllo. Tra le isole, Zante sarebbe stata lasciata a Venezia tre anni dopo, Cefalonia e Itaca sarebbero andate perdute nel 1500, solo Ayamavra sarebbe rimasta ottomana per duecento anni.", "725a61d9"]},
"OLAYLAR_EK10:1482-01-01:0":{"b": ["Vassallaggio della Zeta dei Crnojević e Cetinje divenuta centro", "59d20267"], "d": ["Con la permanenza di Scutari agli Ottomani nel 1479 anche la regione montuosa della Zeta, nelle sue retrovie, rientrò nei confini dell'Impero. La famiglia Crnojević, che teneva la regione, dopo la morte di Maometto il Conquistatore riconobbe la sovranità di Bayezid II, salito al trono, e fu sottoposta a tributo restando libera negli affari interni; Ivan Crnojević ritirò il proprio centro dalla pianura e lo trasferì a Cetinje, ai piedi del monte Lovćen, fondando la città. Due anni dopo il monastero da lui fatto costruire qui divenne il centro religioso della regione. Così il Montenegro appare sulla mappa non come territorio ottomano diretto, ma come regione tributaria in tonalità chiara. La voce Karadağ del TDV ricorda la dinastia e il vescovato di Cetinje e scrive che il dominio nel 1514 fu trasformato in sanjak separato per mano di İskender Bey (della discendenza dei Crnojević, cresciuto a palazzo ottomano); l'anno 1482 non compare nel TDV, è la data data dalla storiografia montenegrina. Per la durezza della geografia l'amministrazione qui non funzionò mai in modo così stretto come nelle pianure.", "c61bf059"]},
"OLAYLAR_EK10:1484-07-15:0":{"b": ["Conquista della fortezza di Kilia — chiave della foce del Danubio", "ef4eca73"], "d": ["La Moldavia era un voivodato tributario che pagava duemila monete d'oro l'anno dal settembre 1455, ma i suoi due porti sul Mar Nero erano ancora in mano al voivoda e il commercio proveniente dal Danubio passava da lì. Bayezid II fece la prima grande campagna del suo regno contro questi due porti. Il comandante della fortezza di Kilia, bombardata notte e giorno per dieci giorni, fu costretto ad arrendersi. La fortezza fu posta sotto amministrazione ottomana diretta e fatta sanjak; nella seconda metà del XVI secolo, per il pericolo cosacco, fu fatta kaza e legata al sanjak di Akkerman, dipendente dal beylerbeylik di Rumelia. Da qui in poi la Moldavia appare sulla mappa a due livelli: all'interno il voivodato resta come territorio tributario in tonalità chiara, mentre i due porti sulla costa sono sanjak ottomano diretto in tonalità scura. La voce Boğdan del TDV chiama questi due 'le chiavi e le porte della Moldavia' e scrive che la regione fu legata in modo definitivo agli Ottomani al tempo di Bayezid II.", "8b039ea4"]},
"OLAYLAR_EK10:1484-08-04:0":{"b": ["Conquista di Akkerman — foce del Dnestr e chiusura della porta sul Mar Nero della Moldavia", "7cb20feb"], "d": ["Venti giorni dopo la resa di Kilia l'esercito giunse davanti ad Akkerman, alla foce del Dnestr, e la fortezza fu presa il 4 agosto. La città era il porto più attivo della Moldavia; al tempo di Maometto il Conquistatore, quando nel 1455 il voivoda Petru III aveva riconosciuto il dominio ottomano, ai mercanti di Akkerman era stato dato il permesso di commerciare, ora il porto passò direttamente allo Stato. Akkerman, fatta dopo la conquista sanjak dipendente dal beylerbeylik di Rumelia, nel 1593 fu annessa al nuovo eyalet di Özü. Così il guscio esterno della Moldavia, circondato da Hotin a nord e da Kilia e Akkerman a sud, cominciò a entrare sotto il controllo diretto degli Ottomani; il voivodato rimase libero negli affari interni ma non ebbe più sbocco sul mare. Sulla mappa non c'è una regione vuota in mezzo — i sanjak portuali in tonalità scura e il territorio del voivodato in tonalità chiara si toccano; la steppa del Bucak tra i due fa ancora parte del voivodato fino al 1538.", "23705829"]},
"OLAYLAR_EK10:1499-08-26:0":{"b": ["Resa di Lepanto (İnebahtı) — l'imboccatura del golfo di Corinto è tolta a Venezia", "2cfe0777"], "d": ["Lepanto era in mano a Venezia dal 1407 e teneva l'imboccatura del golfo di Corinto; tutta la costa all'interno del golfo era legata alla portata di questa fortezza. Nella campagna del 1499 la fortezza fu assediata da terra, mentre la flotta ottomana, che combatteva con la flotta veneziana al largo di Lepanto, aiutò dal mare le forze d'assedio. I Veneziani nella fortezza il 26 agosto consegnarono la cittadina agli Ottomani. La città da allora rimase ottomana per centottantotto anni, nel 1687 con la perdita della Morea passò di nuovo a Venezia, nel 1715 fu ripresa. La battaglia navale della stessa estate e questa resa sono due eventi distinti: lo scontro navale si svolse all'estremità occidentale della Morea, nelle acque di Sapienza-Zonchio; Lepanto cadde invece con un assedio terrestre all'imboccatura del golfo di Corinto.", "49c0fbd8"]},
"OLAYLAR_EK10:1512-01-01:0":{"b": ["Annessione del banato di Srebrenik — prima rottura della linea ungherese nella Bosnia settentrionale", "6d98c725"], "d": ["Dopo l'abbattimento del Regno di Bosnia nel 1463 Mattia Corvino era passato al contrattacco e a nord del regno aveva costituito due banati che fermavano l'avanzata ottomana: a ovest Jajce, a nordest Srebrenik. Erano la linea di difesa avanzata dell'Ungheria in Bosnia e chiudevano il corridoio tra Sava e Bosna. Il banato di Srebrenik fu preso nel 1512; così il fianco orientale della linea crollò e il sanjak di Zvornik poté estendersi verso nord. Jajce, sul fianco occidentale, avrebbe resistito per altri sedici anni e poté essere presa solo dopo Mohács, nel 1528.", "0d4ad0e7"]},
"OLAYLAR_EK10:1521-07-07:0":{"b": ["Conquista di Böğürdelen — la prima fortezza presa da Solimano il Legislatore e il luogo in cui fu decisa la presa di Belgrado", "85177a90"], "d": ["Nella prima campagna d'Ungheria di Solimano il Legislatore, le forze del beylerbey di Rumelia Ahmed Pascià, inviato nella regione, dopo un violento assedio presero la fortezza il 7 luglio 1521. Böğürdelen è la prima fortezza conquistata nel regno di Solimano il Legislatore. Il sultano dopo la conquista entrò personalmente nella fortezza e ordinò la ricostruzione della città; qui furono prese anche le decisioni sulla conquista di Belgrado — cioè il piano di Belgrado, che sarebbe caduta il 29 agosto 1521, fu fatto a Böğürdelen. La fortezza da allora rimase per quasi duecento anni in mano ottomana; fu legata dapprima alla Rumelia, dal 1580 all'eyalet di Bosnia, poi per breve tempo a Smederevo e infine al sanjak di Zvornik. Sulla mappa questa data è il giorno in cui la linea della Sava si chiude a favore degli Ottomani.", "8c0178ad"]},
"OLAYLAR_EK10:1594-08-28:0":{"b": ["Inizio della rivolta dei tre voivodati — la Transilvania passa alla Lega Santa, arrestati i bey filo-ottomani", "68a33800"], "d": ["Nel secondo anno della Lunga Guerra la fascia vassalla ottomana in Europa centrale si sciolse all'improvviso. Alla Lega Santa, costituita sotto la protezione di papa Clemente VIII, alla fine dell'estate passarono Moldavia e Transilvania: il voivoda di Moldavia Aron Vodă il 16 agosto 1594 formalizzò con un documento la propria adesione alla parte cristiana, e il principe di Transilvania Zsigmond Báthory il 28 agosto 1594 spezzò l'opposizione interna liquidando i bey filo-ottomani contrari alla guerra. Il voivoda di Valacchia Michele il Coraggioso aderì all'alleanza nell'autunno dello stesso anno. Così i tre principati tributari dell'Impero ottomano a nord del Danubio — tre voivodati che pagavano tributo da centocinquant'anni e il cui voivoda era confermato da Istanbul — passarono tutti insieme dalla parte opposta nello stesso autunno. La decisione fu formalizzata con il trattato firmato a Praga il 28 gennaio 1595. Fu lo scossone più grave subito dall'ordinamento di amministrazione indiretta ottomano nel nord dei Balcani; la rivolta sarebbe stata repressa ma la fedeltà dei tre principati non sarebbe più stata così salda come tra il 1526 e il 1593.", "32a29f3a"]},
"OLAYLAR_EK10:1594-11-01:0":{"b": ["Rivolta di Bucarest e attacco alle fortezze del Danubio", "18971100"], "d": ["La decisione della Lega Santa fu applicata un mese dopo con il sangue: Michele il Coraggioso a Bucarest passò a fil di spada il reparto di guardia ottomano e i creditori levantini della città. La rivolta nello stesso inverno si estese alla linea del Danubio; le forze valacche attaccarono Giurgiu, Brăila, Hârșova e Silistra, mentre dalla parte della Moldavia Aron Vodă fece la stessa incursione contro le guardie ottomane a Bender. La scelta dei luoghi colpiti non è casuale: erano tutte fortezze e kaza non del territorio del voivodato ma legati lungo il Danubio all'amministrazione ottomana diretta — il kaza di Yergöğü (Giurgiu) al sanjak di Nicopoli, Brăila direttamente allo Stato dal 1538, Bender ancora dal 1538 al sanjak del Bucak. Cioè la rivolta non aveva colpito l'interno vassallo, ma il guscio ottomano diretto che circonda quella regione. Senza forare questo guscio il triangolo Transilvania-Valacchia-Moldavia non poteva essere legato al fronte asburgico.", "95f2286f"]},
"OLAYLAR_EK10:1595-08-23:0":{"b": ["Battaglia di Călugăreni — campagna di Valacchia di Koca Sinan Pascià", "201210a1"], "d": ["Con la perdita di tutti e tre i voivodati il gran visir Koca Sinan Pascià attraversò il Danubio con un grande esercito e marciò per ricondurre la Valacchia all'obbedienza. Michele il Coraggioso, sapendo di non poter resistere in battaglia aperta, attese l'esercito a Călugăreni, nel passaggio paludoso del Neajlov, e attaccò di sorpresa le forze strette nel terreno angusto. Dopo l'attacco, non potendo resistere all'esercito ottomano numericamente superiore, si ritirò a nord, sui monti; Sinan Pascià occupò Bucarest e Târgoviște e tentò di legare la Valacchia all'amministrazione diretta. Călugăreni per questo non fu per gli Ottomani una sconfitta, ma un attacco che ritardò il completamento della campagna; ma il fatto che Michele avesse potuto conservare il proprio esercito gli permise, poche settimane dopo, di passare al contrattacco con l'aiuto giunto dalla Transilvania.", "a2263c60"]},
"OLAYLAR_EK10:1595-10-01:0":{"b": ["Ritirata dalla Valacchia e incursione di Giurgiu — il fallimento della campagna di repressione", "118806e1"], "d": ["Per il contrattacco di Michele il Coraggioso, unitosi alle forze del principe di Transilvania, Sinan Pascià evacuò Târgoviște e Bucarest e si ritirò verso il Danubio. Il momento più costoso della ritirata si ebbe al punto di passaggio: nell'ottobre 1595 gli akıncı che inseguivano l'esercito di ritorno dalla Valacchia subirono a Giurgiu l'attacco di Michele. La campagna terminò così senza raggiungere l'obiettivo di legare la Valacchia all'amministrazione diretta e il voivodato rimase di fatto perduto. L'autorità ottomana in questo triangolo poté essere riparata solo negli anni, a pezzi; il ritorno all'obbedienza della Transilvania avrebbe atteso la rivolta di Bocskai nel 1604, la chiusura completa del fronte il Trattato di Zsitvatorok del 1606.", "ab33575c"]},
"OLAYLAR_EK10:1713-06-24:0":{"b": ["Distacco di Hotin dalla Moldavia — sanjak ottomano diretto in mezzo al voivodato", "947517cb"], "d": ["Nella campagna del Prut il passaggio del voivoda di Moldavia Dimitrie Cantemir alla parte russa mostrò che il confine settentrionale del voivodato non poteva più essere lasciato al voivoda. Perciò Hotin dopo il 1711 fu tolta alla Moldavia e posta sotto amministrazione ottomana diretta; le fu dato dapprima lo statuto di nahiye, poi di sanjak. Dopo la temporanea occupazione russa del 1713 la fortezza fu riparata e ampliata sotto la supervisione di una commissione tecnica ottomana e francese inviata da Istanbul e divenne la più forte fortificazione ottomana a nord del Danubio. Sulla mappa il fatto che da questa data Hotin esca dalla tonalità di voivodato tributario e torni al colore ottomano diretto, e stia come un'isola nel mezzo della Moldavia tributaria, è precisamente la corrispondenza di questa separazione amministrativa — non è un errore di disegno. La stessa struttura esisteva già nel Bucak dal 1538 e a Kilia e Akkerman dal 1484: voivodato libero negli affari interni, fortezze di confine dello Stato.", "7c5d350f"]},
"OLAYLAR_EK10:1788-04-24:0":{"b": ["Seconda occupazione austriaca di Böğürdelen — apertura del fronte della Sava", "063b3ad0"], "d": ["Dopo l'entrata in guerra dell'Austria al fianco della Russia il 9 febbraio 1788 la linea della Sava tornò a essere fronte e Böğürdelen passò il 24 aprile 1788 sotto dominio austriaco. La fortezza era stata già lasciata all'Austria senza guerra il 17 agosto 1717 e tenuta fino al Trattato di Belgrado (1739); in quel periodo la popolazione si era ridotta al punto che in città erano rimaste trentaquattro case cristiane e nessun musulmano. Nel periodo ottomano 1739-1788 la popolazione era risalita a 1500-2000. La seconda occupazione sarebbe terminata con il Trattato di Sistova (4 agosto 1791) e la fortezza sarebbe stata restituita agli Ottomani.", "de07456b"]},
"OLAYLAR_EK10:1806-01-26:0":{"b": ["Consegna di Böğürdelen a Karađorđe — prima fortezza nella Prima rivolta serba", "5c913eb4"], "d": ["Durante la prima rivoluzione serba, iniziata nel 1804 come reazione alla pressione dei dahi e dei yamak di Belgrado e poi divenuta di carattere nazionalista, la fortezza di Böğürdelen fu consegnata a Karađorđe il 26 gennaio 1806. Questa fortezza sulla Sava è la prima grande fortificazione ottomana presa dai ribelli e preannuncia la caduta di Belgrado. Quando la rivolta fu repressa nel 1813 e Belgrado fu ripresa, la fortezza tornò sotto amministrazione ottomana; ma con la condizione di guarnigione del firmano del 1830 Böğürdelen fu definita, insieme a Belgrado, Smederevo e Fetislam, una delle quattro fortezze entro la Serbia autonoma in cui rimaneva la truppa ottomana, e restò in questo statuto fino al ritiro della guarnigione nel 1867.", "092a75b8"]},
"OLAYLAR_EK10:1832-01-01:0":{"b": ["Lamia (İzdin) resta entro i confini della Grecia — linea Arta-Volos", "930f63b8"], "d": ["Il confine settentrionale dello Stato greco indipendente fu tracciato nel 1832 sulla linea che si estende dal golfo di Arta al golfo di Volos. Lamia (İzdin), centro di kaza dipendente dal sanjak di Negroponte in epoca ottomana (1424-1832), restando a sud di questa linea passò alla Grecia; il resto della Tessaglia (Larissa, Trikala) rimase ottomano fino al 1881.", "577080e0"]},
"OLAYLAR_EK10:1877-04-24:0":{"b": ["Dichiarazione di guerra della Russia — inizio della Guerra del '93", "ac548ab8"], "d": ["La repressione della Rivolta bulgara del 1876 aveva suscitato grande indignazione nell'opinione pubblica europea e la Russia l'aveva sfruttata fino in fondo per isolare la Sublime Porta. Dopo che la proposta della Conferenza di Istanbul (dei Cantieri) di dividere la Bulgaria in due province autonome e poi il Protocollo di Londra del 31 marzo 1877 furono respinti dall'Impero ottomano, la Russia il 24 aprile 1877 dichiarò guerra e il suo esercito entrò nei territori del Principato di Romania, da essa attratto dalla propria parte (la mappa mostra Valacchia e Moldavia da questo momento fino all'Armistizio di Edirne con la copertura tratteggiata dell'avanzata russa). Poiché cadeva nell'anno 1293 del calendario rûmî la guerra è detta Guerra del '93. L'operazione si svolse su due fronti, Danubio e Anatolia orientale: sul Danubio l'esercito ottomano di 180.000 uomini aveva considerato la riva sinistra del fiume prima linea di difesa e i monti Balcani seconda; a oriente i 55.000 soldati di Ahmed Muhtar Pascià si erano attestati tra Ardahan e Doğubayazıt. Questa guerra è sulla mappa l'evento che avviò il crollo della Rumelia ottomana — gli odierni confini di Bulgaria, Serbia, Montenegro e Romania sono tutti il prodotto di questi quindici mesi.", "a71008f1"]},
"OLAYLAR_EK10:1877-05-21:0":{"b": ["Proclamazione dell'indipendenza della Romania — fine della dipendenza di Valacchia e Moldavia", "bdd164b3"], "d": ["Due settimane dopo la dichiarazione della Guerra del '93, il Principato di Romania proclamò l'indipendenza ed entrò in guerra al fianco della Russia; la sua parte nell'assedio di Plevna fu determinante nella sconfitta ottomana. La dipendenza di Valacchia e Moldavia, durata oltre quattrocento anni, ebbe così fine di fatto; l'indipendenza ottenne il riconoscimento internazionale al Congresso di Berlino (1878). La mappa da questa data mostra la Romania non come tributaria ma come Stato indipendente con il proprio colore. Con la dichiarazione d'indipendenza l'intera Valacchia e Moldavia (Iași, Galați, Brăila, Giurgiu, Calafat, Botoșani ecc.) divenne Romania indipendente.", "9e037d13"]},
"OLAYLAR_EK10:1877-06-27:0":{"b": ["L'esercito russo attraversa il Danubio — caduta di Sistova e Tărnovo", "811367b1"], "d": ["I Russi, entrati con l'inizio della guerra nei territori della Romania e avendo attratto dalla propria parte questo principato, avanzarono su due colonne, una in direzione della Dobrugia e l'altra di Bucarest. Il Danubio fu attraversato tra Ruse e Nicopoli e il 27 giugno furono prese Sistova e il 1° luglio l'antica capitale bulgara Tărnovo. Poiché, benché ne fosse stata ordinata l'evacuazione, non si era prestata attenzione a questo, anche Nicopoli resistette per un po' e poi si arrese. L'apertura della prima linea di difesa in una settimana provocò grande panico a Istanbul; si diffusero persino voci di un trasferimento del centro del sultanato a Bursa e la conduzione della guerra fu affidata a un consiglio militare costituito nella capitale.", "f266b11c"]},
"OLAYLAR_EK10:1877-07-19:0":{"b": ["Evacuazione del Passo di Shipka — sfondamento della linea dei Balcani", "1f45e50a"], "d": ["Le forze ottomane a Shipka, il più strategico dei passi che attraversano i monti Balcani, opposero violenta resistenza agli attacchi russi; ma convintesi che sarebbero state sconfitte evacuarono segretamente il passo il 19 luglio. Così fu aperta anche la seconda linea di difesa e il generale Gurko il 22 luglio prese Stara Zagora. Süleyman Pascià, giunto dalla parte del Montenegro, sconfisse Gurko e riprese i luoghi occupati a sud dei Balcani, ma nonostante gli attacchi durati mesi dal 21 agosto non poté riprendere Shipka. Sulla mappa questa è la mancata ricostituzione, mai più, dell'integrità difensiva tra il nord e il sud della catena dei Balcani: la lotta sul fronte del Danubio da ora in poi si annoderà a Plevna.", "3463a17b"]},
"OLAYLAR_EK10:1877-08-23:0":{"b": ["Lovech occupata dall'esercito russo", "70e54611"], "d": ["Nella Guerra del '93 Lovech era stata occupata dai Russi il 5 giugno 1877 e le forze ottomane al comando di Rifat Pascià il 15 giugno avevano respinto i Russi; la città il 23 agosto fu abbandonata dagli Ottomani ed entrò di nuovo sotto occupazione russa. La mappa mostra Lovech da questo giorno fino al Trattato di Berlino sotto occupazione russa (tratteggiata); giuridicamente continua a essere territorio ottomano.", "45e61a80"]},
"OLAYLAR_EK10:1877-11-18:0":{"b": ["Caduta di Kars — dissoluzione del fronte orientale e fortificazioni di Aziziye", "53fc3bf5"], "d": ["In Anatolia orientale i Russi, avanzati su tre colonne verso Kars, Doğubayazıt e Ardahan, il 30 aprile avevano preso Doğubayazıt ed erano entrati ad Ardahan, ma, mentre marciavano su Erzurum, il 15 luglio erano stati sconfitti e cacciati oltre il confine. Questo successo, che aveva valso ad Ahmed Muhtar Pascià il titolo di \"Gazi\", si rovesciò ad agosto con il nuovo attacco del generale Lazarev e il 18 novembre cadde Kars. Le forze ottomane, ritiratesi a Erzurum per una difesa più adatta, mostrarono grande resistenza presso le fortificazioni di Aziziye, con l'incoraggiamento alla popolazione di Nene Hatun. Kars, Ardahan e Batum sarebbero state lasciate alla Russia otto mesi dopo a Berlino in corrispondenza di una parte dell'indennità di guerra.", "07faf844"]},
"OLAYLAR_EK10:1912-10-08:0":{"b": ["Inizio della Prima guerra balcanica — dichiarazione di guerra del Montenegro", "c0c2697e"], "d": ["Gli Stati balcanici, rimossa l'ostacolo maggiore tra loro con la soluzione della questione delle chiese da parte di Unione e Progresso con la legge del 3 luglio 1911, per l'istigazione della Russia nel corso del 1912 avevano firmato tra loro trattati di alleanza (13 marzo Serbia-Bulgaria, 29 maggio Bulgaria-Grecia, in agosto Montenegro-Bulgaria, 6 ottobre Montenegro-Serbia). La Sublime Porta non se ne accorse; anzi, fidandosi delle garanzie della Russia, congedò 120 battaglioni addestrati in Rumelia. I quattro Stati il 3 ottobre presentarono una nota comune chiedendo autonomia per Macedonia, Albania e Creta; non ricevendo risposta, le operazioni iniziarono con la dichiarazione di guerra del Montenegro l'8 ottobre 1912. Il 13 ottobre furono consegnati i passaporti agli ambasciatori di Serbia e Bulgaria, il giorno dopo questi due Stati e poi la Grecia dichiararono guerra. Durante la guerra le divergenze politiche all'interno dell'esercito ebbero un grande ruolo nella sconfitta.", "33b60249"]},
"OLAYLAR_EK10:1912-10-20:0":{"b": ["Nei Rodopi il Distaccamento di Kırcaali è sconfitto, Kırcaali cade", "8cf59b7f"], "d": ["Dopo la dichiarazione di guerra bulgara le forze bulgare scese dai Rodopi, sconfitto il Distaccamento di Kırcaali di Mehmed Yaver Pascià, entrarono a Kırcaali. Il distaccamento sconfitto si ritirò in direzione di Komotini; la parte orientale dei Rodopi andò perduta nella prima settimana di guerra.", "c675e240"]},
"OLAYLAR_EK10:1912-10-23:0":{"b": ["Disfatta dell'Armata d'Oriente e ritirata sulla linea di Çatalca — perdita di Kumanovo e Salonicco", "cf95591a"], "d": ["L'Armata d'Oriente ottomana il 23 ottobre 1912, sconfitta dall'esercito bulgaro tre volte più numeroso, si ritirò fino alla linea di Çatalca, trenta chilometri a ovest di Istanbul; la capitale nel primo mese di guerra fu direttamente minacciata. Negli stessi giorni l'Armata d'Occidente il 23-24 ottobre fu sconfitta dai Serbi a Kumanovo e Tahsin Pascià con il suo esercito di 35.000 uomini si arrese ai Greci a Salonicco. Per queste disfatte il 29 ottobre si dimise il gabinetto di Gazi Ahmed Muhtar Pascià; Abdülhamid II, che viveva in esilio a Salonicco, il 1° novembre fu trasferito a Istanbul. La linea di Çatalca fu tenuta fino alla fine della guerra — la geografia ottomana di cinquecento anni della Rumelia fu ridotta in poche settimane a questa stretta fascia.", "376c6d31"]},
"OLAYLAR_EK10:1912-10-23:1":{"b": ["Il principe Alessandro entra nel centro del sanjak di Novi Pazar", "326d0616"], "d": ["Le forze serbe nella prima settimana di guerra presero Novi Pazar e si unirono alle forze montenegrine giunte da ovest. Il sanjak di Novi Pazar, che per cento anni aveva separato Serbia e Montenegro, divenne così un ponte tra i due alleati.", "afe8a034"]},
"OLAYLAR_EK10:1912-10-24:0":{"b": ["Dopo la battaglia di Kırkkilise cade Kırklareli", "eda4c759"], "d": ["In Tracia orientale, con la sconfitta dell'Armata d'Oriente nella battaglia di Kırkkilise (Lozengrad), la città difesa da Kölemen Abdullah Pascià fu lasciata alle forze bulgare. La città fu liberata dall'occupazione di nove mesi solo nella Seconda guerra balcanica, il 21 luglio 1913.", "ee5cf8d2"]},
"OLAYLAR_EK10:1912-10-26:0":{"b": ["Skopje (Üsküp), centro della provincia del Kosovo, lasciata senza resistenza", "455d9b71"], "d": ["Dopo la disfatta di Kumanovo (23-24 ottobre) Skopje, centro della provincia del Kosovo, rimase indifesa. Poiché la popolazione non voleva combattimenti intorno alla città, le forze serbe al comando del principe Alessandro, invitate tramite i consoli, entrarono in città senza resistenza la sera del 26 ottobre.", "3992a650"]},
"OLAYLAR_EK10:1912-10-28:0":{"b": ["Perdita di Köprülü (Veles) sul Vardar", "73d20b7d"], "d": ["Due giorni dopo la caduta di Skopje l'esercito serbo, sceso a sud lungo il Vardar, prese Köprülü. La porta della valle del Vardar verso Salonicco passò così ai Serbi.", "e762a0e1"]},
"OLAYLAR_EK10:1912-10-29:0":{"b": ["Bacino del Bregalnica: il generale Stefanović entra a Štip (İştip)", "70a84256"], "d": ["Le unità serbe al comando del generale Stefanović presero Štip senza incontrare resistenza; in città entrarono dapprima bande irregolari. Dopo Kumanovo il bacino del Bregalnica della Macedonia orientale passò sotto controllo serbo.", "3b2e609b"]},
"OLAYLAR_EK10:1912-10-29:1":{"b": ["Dopo il passo di Sarantaporo Karaferye (Veria) passa sotto dominio greco", "02a68e02"], "d": ["L'esercito greco, che avanzava verso nord dalla Tessaglia, dopo aver superato il passo di Sarantaporo (Kırkgeçit) prese possesso di Karaferye. Una parte della popolazione musulmana della città in questo periodo lasciò la regione.", "a76cea57"]},
"OLAYLAR_EK10:1912-10-31:0":{"b": ["Perdita di Vodena sulla ferrovia Salonicco-Monastir", "fc15b917"], "d": ["Vodena, sulla ferrovia Salonicco-Monastir, passò in mano all'esercito greco. Con la partenza forzata delle popolazioni slava e turca la popolazione della città in breve tempo diminuì seriamente.", "e28f0a57"]},
"OLAYLAR_EK10:1912-11-02:0":{"b": ["Battaglia di Yenice — Yenice-i Vardar passa ai Greci", "8f6cb76e"], "d": ["L'8° Corpo d'armata composito di Hasan Tahsin Pascià fu sconfitto dall'esercito greco a Yenice (Giannitsa), a ovest di Salonicco, e si ritirò nella zona di Salonicco. Durante la battaglia gran parte della cittadina bruciò; la strada di Salonicco fu aperta all'esercito greco.", "d0f12da4"]},
"OLAYLAR_EK10:1912-11-03:0":{"b": ["Prizren, nel sud-ovest del Kosovo, si arrende", "bae6b1b9"], "d": ["Prizren, nel sud-ovest del Kosovo, si arrese alle forze serbe. L'atteggiamento delle unità entrate in città verso la popolazione musulmana fu registrato come una delle pagine più gravi della guerra in Kosovo.", "8cf0b7ae"]},
"OLAYLAR_EK10:1912-11-05:0":{"b": ["Il colonnello Mitov proclama la legge marziale a Strumica", "bcad75cc"], "d": ["Il colonnello bulgaro Mitov, entrato a Strumica, proclamò la legge marziale; partendo il giorno dopo lasciò la cittadina a un kaymakam bulgaro e a un comandante serbo. Strumica durante la guerra passò di mano tra gli alleati e nel 1913 fu legata alla Bulgaria.", "acfc04ac"]},
"OLAYLAR_EK10:1912-11-08:0":{"b": ["Hasan Tahsin Pascià lascia Salonicco ai Greci", "1738933c"], "d": ["Hasan Tahsin Pascià, ritiratosi a Salonicco dopo la sconfitta di Yenice, mentre l'esercito bulgaro si avvicinava da nord lasciò la città ai Greci; l'esercito greco entrò in città l'8 novembre verso mezzogiorno. Salonicco, il maggiore porto della Rumelia ottomana e luogo di nascita di Unione e Progresso, andò così perduta.", "e65f92fc"]},
"OLAYLAR_EK10:1912-11-21:0":{"b": ["Komotini (Gümülcine), centro della Tracia occidentale, aperta ai Bulgari", "96eec25f"], "d": ["Per il ritiro verso Fere del distaccamento di Yaver Pascià, ritiratosi da Kırcaali, Komotini si arrese alle forze bulgare. Il centro della Tracia occidentale era tra i primi dei territori che alla fine della guerra sarebbero stati lasciati alla Bulgaria.", "dab74d84"]},
"OLAYLAR_EK10:1912-11-28:0":{"b": ["I Serbi giunti a Elbasan entrano lo stesso giorno a Debar", "16720246"], "d": ["Le forze serbe avanzate da Monastir verso ovest, il giorno in cui giunsero a Elbasan, entrarono anche a Debar e scesero verso l'Adriatico. Lo stesso giorno a Valona veniva proclamata l'indipendenza dell'Albania.", "6e52cff7"]},
"OLAYLAR_EK11:1401-01-01:0":{"b": ["Tamerlano occupa Baghdad per la seconda volta — distrutti i quartieri abbasidi della città", "04b68a24"], "d": ["Tamerlano prese Baghdad due volte a otto anni di distanza. Nella prima occupazione del 1393 la città non aveva subito molti danni; la seconda, del 1401, è considerata il secondo duro colpo inferto alla vita culturale di Baghdad — la popolazione fu passata a fil di spada, la maggior parte dei quartieri e degli edifici rimasti dall'epoca abbaside fu distrutta. Il sovrano jalayiride Ahmed, tornato in città nel 1405, cercò di riparare le mura e i bazar distrutti ma non ne ebbe il tempo; Baghdad nel 1410 passò in mano ai turcomanni Qara Qoyunlu. Queste due occupazioni sono uno dei passi più concreti che mostrano quanto Tamerlano si fosse avvicinato ai confini ottomani e mamelucchi sulla via che porta alla Battaglia di Ankara.", "b24ba76b"]},
"OLAYLAR_EK11:1422-01-01:0":{"b": ["Cüneyd Bey torna alla guida dell'Aydın-ili — gli Aydınidi di nuovo indipendenti", "63281658"], "d": ["Çelebi Mehmed nel 1414-15, preso İzmir, aveva inviato Cüneyd Bey al sanjak-beylik di Nicopoli legando l'Aydın-ili all'amministrazione ottomana. Cüneyd, dopo la morte di Çelebi Mehmed, ricomparve sulla scena al fianco di Mustafa Çelebi, avanzato da Bisanzio come pretendente al trono, e fu persino suo visir. Murad II lo separò da questa alleanza con la promessa di restituirgli il suo antico beylicato; Cüneyd tornò a İzmir, prese Ayasuluk e, uccidendo Aydınoğlu Mustafa Bey, si pose alla testa del beylicato. Così l'Aydın-ili nacque, dall'interno della crisi del Falso Mustafa, uscito dall'amministrazione ottomana.", "c5020860"]},
"OLAYLAR_EK11:1426-01-01:0":{"b": ["Esecuzione di Cüneyd Bey e della sua famiglia — fine del beylik degli Aydınoğlu", "efa684ba"], "d": ["Poiché Cüneyd Bey, tornato a dominare l'Aydın-ili, incitava i bey anatolici e cercava contatti con Venezia, Murad II inviò contro di lui il beylerbey dell'Anatolia, Hamza Bey. Dopo che suo figlio Kurd Hasan fu sconfitto presso Akhisar e fatto prigioniero, Cüneyd si ritirò a İpsili, di fronte all'isola di Samo; non giungendo l'aiuto atteso dai Karamanoğlu e venendo bloccato dal mare dai Genovesi, che agivano insieme agli Ottomani, fu costretto ad arrendersi e fu eliminato con tutta la sua stirpe. I territori degli Aydınoğlu passarono così interamente sotto l'amministrazione ottomana.", "662b578c"]},
"OLAYLAR_EK11:1502-01-01:0":{"b": ["Erzurum e il bacino di Van passano ai Safavidi — crolla il fianco settentrionale degli Aqquyunlu", "b418875f"], "d": ["Dopo aver sconfitto Alvand Bey a Şerûr ed essere entrato a Tabriz nell'estate del 1501, Shah Ismail l'anno seguente avanzò verso nord-ovest e pose sotto il proprio dominio la fascia che va da Erzurum al bacino del lago di Van. Lo Stato degli Aqquyunlu, dopo la morte di Uzun Hasan, era già diviso in due dalle lotte per il trono: Alvand Bey teneva l'Azerbaigian e Diyarbekir, il cugino paterno Murad l'Iraq persiano (Irak-ı Acem) e il Fars. Questa divisione facilitò l'avanzata safavide; la regione cambiò di mano in dieci registrazioni nel giro di un anno. Erzurum rimase poi per sedici anni in mano safavide ed entrò sotto il dominio ottomano solo dopo Çaldıran, nel 1518-19. In quest'anno (1502) Aşkale e Pasinler (Hasankale), insieme alla regione di Erzurum, passarono dagli Aqquyunlu ai Safavidi (giorno non confermato).", "2f80b39d"]},
"OLAYLAR_EK11:1503-01-01:0":{"b": ["Sconfitta di Murad Bey a Hamadan: l'Iraq persiano e il Fars passano ai Safavidi", "8de07a31"], "d": ["Il sultano Murad, secondo pretendente al trono degli Aqquyunlu, subì una pesante sconfitta nella battaglia contro Shah Ismail presso Hamadan e fuggì a Baghdad. Con questa sola battaglia le regioni dell'Iraq persiano, del Fars e del Kirman entrarono sotto l'amministrazione safavide; sulla mappa queste regioni cambiano di mano nello stesso momento. È il singolo passo più grande nella dissoluzione dello Stato degli Aqquyunlu: la perdita di Tabriz aveva lasciato la dinastia senza capitale, la sconfitta di Hamadan la lasciò senza territorio.", "f9d2ba4d"]},
"OLAYLAR_EK11:1504-12-06:0":{"b": ["Shah Ismail entrò a Yazd: cadde l'ultima roccaforte dei resti degli Aqquyunlu nell'Iran centrale", "6f9835df"], "d": ["Dopo la sconfitta di Hamadan del 1503, benché l'Iraq persiano e il Fars fossero passati ai Safavidi, Yazd era rimasta separata, in mano a Bayındırlı Murad Bey della dinastia degli Aqquyunlu. La città cadde dopo un assedio di un mese e si chiuse così l'ultima isola aqquyunlu nell'Iran centrale. Annotazione del TDV: \"Shah Ismail entrò in città il 28 Cemâziyelâhir 910 (6 dicembre 1504), dopo un assedio di un mese.\"", "577a0ec7"]},
"OLAYLAR_EK11:1507-01-01:0":{"b": ["Campagna di Shah Ismail a Diyarbekir: caddero gli ultimi centri degli Aqquyunlu", "b6d8504e"], "d": ["Dopo aver conquistato l'Azerbaigian e l'altopiano iranico, nel 1507 Shah Ismail si volse a occidente, verso la regione di Diyarbekir, dove era nata la dinastia degli Aqquyunlu. La fascia che va da Âmid a Mardin, da Urfa a Harput passò in due mosse sotto l'amministrazione safavide e gli Aqquyunlu scomparvero di fatto. Questa campagna portò per la prima volta il confine safavide a contatto con i confini ottomano e mamelucco; così si costruì il fondamento geografico della tensione che condusse a Çaldıran.", "d0346bf4"]},
"OLAYLAR_EK11:1508-01-01:0":{"b": ["Passaggio di Baghdad ai Safavidi — l'Iraq arabo (Irâk-ı Arab) cambiò di mano", "39730186"], "d": ["Inseguendo il sultano aqquyunlu Murad, che dopo la sconfitta di Hamadan si era rifugiato a Baghdad, Shah Ismail entrò nell'Iraq arabo nel 1508 e prese Baghdad. Il passaggio dei mausolei di Kerbela e Najaf sotto l'amministrazione safavide fu importante, per la pretesa confessionale del movimento, quanto la presa di Tabriz. Sulla mappa l'Iraq arabo cambia di mano nello stesso giorno; è l'ultimo e più vasto passo geografico della dissoluzione. Baghdad rimase in mano safavide fino alla campagna dei Due Iraq (Irakeyn) di Solimano il Legislatore nel 1534.", "10e3e563"]},
"OLAYLAR_EK11:1510-12-02:0":{"b": ["Battaglia di Merv: gli Uzbeki subirono una pesante sconfitta, Merv ed Herat furono prese", "f8e45aaf"], "d": ["Compiuta a occidente l'eredità degli Aqquyunlu, Shah Ismail marciò a oriente, verso il Khorasan, e inflisse agli Uzbeki una pesante sconfitta davanti a Merv; Şeybânî Khan morì sul campo di battaglia. Merv ed Herat entrarono sotto il dominio safavide e lo Stato safavide raggiunse i suoi confini, dall'Eufrate all'Oxus (Ceyhun). Così il processo iniziato con l'ingresso a Tabriz nell'estate del 1501 si compì in nove anni: l'eredità degli Aqquyunlu passò per intero all'amministrazione safavide e lo Stato ottomano si trovò ad avere a oriente come vicino un secondo Stato della propria grandezza.", "ae88b613"]},
"OLAYLAR_EK11:1539-02-24:0":{"b": ["Ingresso definitivo di Zabid sotto il dominio ottomano", "ddd971c7"], "d": ["La flotta che aveva tolto l'assedio di Diu il 5 novembre 1538 toccò sulla via del ritorno la costa dello Yemen e Zabid fu legata definitivamente all'amministrazione ottomana; Hadım Süleyman Pascià lasciò la città il 10 marzo 1539 e giunse a Gedda il 1° aprile. La città dal 1517 era governata a nome degli Ottomani dagli antichi bey mamelucchi; con questa data passò all'amministrazione diretta.", "5718f027"]},
"OLAYLAR_EK11:1581-04-16:0":{"b": ["Unione Iberica: la corona portoghese passò al re di Spagna", "1cc6dfdc"], "d": ["La disputa successoria apertasi con la morte senza eredi del cardinale-re Henrique si concluse a favore della Spagna nella battaglia di Alcântara (25 agosto 1580) e le Cortes portoghesi riunite a Tomar il 16 aprile 1581 riconobbero Filippo II come re del Portogallo. Secondo le condizioni di Tomar il Portogallo avrebbe conservato le proprie istituzioni, la moneta e la lingua, all'amministrazione sarebbero stati nominati solo Portoghesi e a Madrid vi sarebbe stato un consiglio portoghese separato — cioè l'unione fu personale, non un'annessione.", "40bd79df"]},
"OLAYLAR_EK11:1640-12-01:0":{"b": ["Restauração: il Portogallo riconquistò l'indipendenza", "64ec0738"], "d": ["Nei giorni in cui la rivolta di Catalogna teneva occupata la Spagna, a Lisbona un gruppo di nobili assalì il palazzo e rovesciò l'amministrazione spagnola, proclamando re il duca di Braganza con il nome di João IV. L'Unione Iberica di sessant'anni giunse così al termine; tuttavia Ceuta scelse di restare alla Spagna, e ciò fu riconosciuto con il trattato di Lisbona del 1668. Questa finestra, in cui il Portogallo fu trascinato nelle guerre asburgiche, è anche la cornice delle sue perdite in Asia: Ormuz fu perduta nel 1622, Malacca nel 1641, Colombo nel 1656; Tangeri e Bombay furono invece cedute all'Inghilterra come prezzo dell'indipendenza. Fonte: Britannica, History of Portugal — Restoration.", "bb04bea3"]},
"OLAYLAR_EK11:1662-01-30:0":{"b": ["Tangeri ceduta all'Inghilterra", "1f7cad6d"], "d": ["Il secondo articolo del trattato matrimoniale (23 giugno 1661), concluso per assicurarsi il sostegno inglese nella guerra d'indipendenza portoghese, lasciava Tangeri all'Inghilterra come dote di Caterina di Braganza. La flotta del conte di Sandwich gettò l'ancora il 29 gennaio 1662 e il giorno seguente, con la cerimonia del conte di Peterborough, avvenne la cessione ufficiale. Gli Inglesi avrebbero abbandonato la città nel 1684.", "9328c723"]},
"OLAYLAR_EK11:1747-06-20:0":{"b": ["Assassinio di Nadir Shah — dissoluzione del dominio afsharide", "19c218c0"], "d": ["Nadir Shah, che aveva posto fine al trono safavide e nel 1736 aveva proclamato il sultanato a proprio nome, che con la campagna d'India era giunto fino a Delhi e che dopo tre guerre con gli Ottomani aveva fatto pace con il trattato di Kerden del 1746, fu ucciso nella sua tenda dalle proprie guardie. In seguito l'Iran non poté più essere governato da un'unica mano: per quarantanove anni si divisero il paese i resti degli Afsharidi nel Khorasan, gli Zand a sud e i Qajar in ascesa a nord. Grazie a questa frammentazione il confine orientale ottomano rimase tranquillo a lungo. Nadir Shah fu ucciso il 20 giugno 1747; secondo il TDV il khanato di Erevan fu fondato nello stesso anno (1747), giorno non confermato.", "75fd6ab9"]},
"OLAYLAR_EK11:1796-01-01:0":{"b": ["I Qajar si impongono in Iran", "744b48c5"], "d": ["Agha Mohammad Khan, capo della tribù qajar, abbatté il dominio degli Zand e spezzò l'ultima resistenza afsharide nel Khorasan, riunendo di nuovo l'Iran in una sola mano e facendo di Teheran la capitale. L'epoca di frammentazione di quarantanove anni si chiuse così; da allora il vicino orientale dell'Impero ottomano sarebbe stato l'Iran qajar fino al 1923. Secondo il TDV İslâm Ansiklopedisi, Mashhad nel 1796 fu consegnata ad Agha Mohammad Shah dal sovrano afsharide Shahrokh e passò sotto il dominio qajar (il giorno non è nella fonte).", "755b544a"]},
"OLAYLAR_EK12:1527-09-23:0":{"b": ["Ferdinando prese Buda — Szapolyai cacciato dalla capitale", "99f77c29"], "d": ["Dopo Mohács sul trono d'Ungheria vi erano due re: una parte dei nobili aveva eletto János Szapolyai, un'altra Ferdinando d'Asburgo. Nel 1527 Ferdinando prese Buda e scacciò Szapolyai dalla capitale; Szapolyai chiese aiuto al sultano Solimano. Questa è la ragione per cui il primo obiettivo della campagna di Vienna del 1529 fu Buda.", "e45db1f0"]},
"OLAYLAR_EK12:1537-01-01:0":{"b": ["Campagna di Barbarossa nelle isole dell'Egeo — il Ducato di Nasso passò sotto il controllo ottomano", "722b2fea"], "d": ["Il Ducato di Nasso, governato dal 1207 da duchi latini sotto la tutela veneziana, passò sotto il controllo ottomano con la campagna di Barbaros Hayreddin Pascià nelle isole. Lo status dell'isola non fu toccato; il ducato continuò come vassallo degli Ottomani e con l'accordo ottomano-veneziano del 1540 il diritto di sovranità fu ufficialmente trasferito agli Ottomani.", "e20e29f9"]},
"OLAYLAR_EK12:1560-03-12:0":{"b": ["La flotta crociata occupò Gerba — perduta la base di Turgut Pascià", "f41b3f2a"], "d": ["La flotta crociata, composta da navi di Spagna, Papato, Malta, Genova e Firenze, prese di mira Gerba, che Turgut Reis usava dal 1551 come base per le sue incursioni. A causa di tempeste ed epidemie poté raggiungere l'isola solo all'inizio del 1560; il 12 marzo 1560 occupò l'isola e vi costruì un forte. Appresa la notizia, Piyâle Pascià il 28 marzo partì da Istanbul con una flotta di 120 galee. L'occupazione non durò a lungo: a maggio la flotta ottomana sconfisse gli alleati davanti a Gerba e il forte fu ripreso alla fine di luglio. Questa campagna è l'inizio della seconda grande operazione navale che, dopo Prevesa, consolidò la supremazia ottomana nel Mediterraneo.", "a420585e"]},
"OLAYLAR_EK12:1560-07-30:0":{"b": ["Caduta del forte di Gerba — passaggio dell'isola all'amministrazione ottomana", "f1efc0df"], "d": ["Dopo la vittoria navale di Piyâle Pascià del 14 maggio 1560, le forze crociate si chiusero nel forte costruito sull'isola; le forze di Turgut Pascià, beylerbey di Tripoli di Barberia, lo assediarono da terra. L'assedio, durato due mesi, si concluse il 30 luglio 1560 con la caduta del forte e l'isola fu legata al beylerbeylik di Tripoli. Tra la vittoria navale e la conquista del forte passano settantasette giorni; l'isola ha cambiato di fatto mano il 30 luglio, non il 14 maggio.", "50b148da"]},
"OLAYLAR_EK12:1814-02-04:0":{"b": ["A Danzica cessò il doppio potere russo-prussiano — la città libera di Napoleone tornò alla Prussia", "1ccda4d2"], "d": ["Danzica, separata dalla Prussia con la pace di Tilsit (9 luglio 1807) e resa città libera sotto protezione francese, fu lasciata dalle forze di Napoleone dopo l'assedio del 1813. Tra il 2 gennaio e il 4 febbraio 1814 in città perdurò il doppio potere russo-prussiano; quando lo zar Alessandro rinunciò al piano di prendere Danzica e la foce della Vistola, la città passò all'amministrazione prussiana.", "8d215059"]},
"OLAYLAR_EK12:1815-05-03:0":{"b": ["A Vienna Cracovia proclamata città libera, indipendente e neutrale", "19eea839"], "d": ["Al Congresso di Vienna Russia, Austria e Prussia fecero della città di Cracovia, con il suo territorio, uno Stato libero sotto la protezione delle tre potenze; l'Atto finale di Vienna sancì questo assetto.", "21a6fe2b"]},
"OLAYLAR_EK12:1846-11-11:0":{"b": ["Abolita la Città Libera di Cracovia, annessa all'Austria", "15548a14"], "d": ["Prendendo a pretesto l'insurrezione di Cracovia del febbraio 1846, Russia, Austria e Prussia decisero, in una conferenza a Vienna, di abolire la città libera e di annetterla ai territori austriaci; le obiezioni di Inghilterra e Francia non ebbero effetto.", "bf12c063"]},
"OLAYLAR_EK12:1893-01-01:0":{"b": ["Il Bornu cadde sotto il dominio di Rabih b. Zubayr", "8be4ca96"], "d": ["Il signore della guerra sudanese Rabih b. Zubayr, che aveva scosso il Baghirmi e il Wadai, si impadronì del Bornu; entro il 1896 prese l'intero paese e fece di Dikwa il proprio centro.", "466276f3"]},
"OLAYLAR_EK12:1900-04-22:0":{"b": ["Rabih b. Zubayr sconfitto e ucciso dai Francesi — dissolto il suo dominio nel Bornu", "fb5a3ace"], "d": ["Rabih, sconfitto dall'esercito coloniale francese, fu ucciso; suo figlio volle mantenere il dominio ma non resse, e il Bornu nel 1902 fu spartito tra Francia, Inghilterra e Germania.", "15789829"]},
"OLAYLAR_EK12:1913-08-31:0":{"b": ["Proclamato a Komotini il Governo provvisorio della Tracia occidentale (Garbî Trakya Hükûmet-i Muvakkatesi)", "974b2e28"], "d": ["Quando il trattato di Bucarest (10 agosto 1913) lasciò la Tracia occidentale alla Bulgaria, la popolazione turca della regione proclamò un governo provvisorio con sede a Komotini (Gümülcine); dopo la presa di Dedeağaç il governo annunciò la propria indipendenza con il nome di 'Garbî Trakya Hükûmet-i Müstakillesi'. Per l'intervento delle grandi potenze il governo ottomano non lo sostenne; il trattato di Istanbul del 29 settembre 1913 lasciò la Tracia occidentale ai Bulgari e il governo visse solo cinquantasette giorni, fino al 25 ottobre 1913.", "86d3bfee"]},
"OLAYLAR_EK12:1920-11-15:0":{"b": ["Fondata la Città Libera di Danzica sotto la protezione della Società delle Nazioni", "bd148fe8"], "d": ["Danzica, separata dalla Germania dal trattato di Versailles, dal 10 gennaio 1920 rimase sotto l'amministrazione transitoria delle grandi potenze alleate; il 15 novembre 1920 fu istituita come città libera sotto la protezione della Società delle Nazioni, in unione doganale con la Polonia.", "c74affc1"]},
"OLAYLAR_EK13:1362-03-01:0":{"b": ["Morte di Orhan Gazi — fine dei quarant'anni di passaggio da beylik a Stato", "62c59cfd"], "d": ["Orhan Gazi, che alla morte di Osman Gazi nel 1324 assunse la guida del beylik, nei suoi trentotto anni di governo trasformò gli Ottomani da beylik di frontiera in uno Stato insediato sulle due rive del Marmara: furono prese Bursa (1326), Nicea (1331) e Nicomedia (1337), annesso il beylik di Karesi, coniato il primo akçe (1327), fondata a Nicea la prima medrese (1331) e il passaggio in Rumelia divenne stabile con Çimpe (1352) e Gallipoli (1354). Nel 1357 perse in un incidente di caccia il figlio maggiore Süleyman Pascià, che conduceva la conquista della Rumelia; egli stesso morì a Bursa nel marzo 1362 e gli successe il figlio Murad I.", "9208e381"]},
"OLAYLAR_EK13:1417-01-01:0":{"b": ["Passaggio delle isole Bahrein ai Jabrid", "6a242b16"], "d": ["La voce Bahreyn del TDV annota che l'isola rimase \"sotto l'amministrazione successivamente degli Uyunidi, dei Salgharidi, dei Tabidi e dei Jabridi, e che durante l'epoca jabride la maggioranza passò dagli Sciiti ai Sunniti\"; non dà alcuna data. Nella letteratura generale la dinastia jabride fu fondata all'inizio del XV secolo rovesciando l'ultimo sovrano jarwanide a Qatif e, nel suo massimo splendore (Ajwad b. Zamil, m. 1496), controllò tutta la costa araba del Golfo Persico, Al-Hasa, Qatif e le isole Bahrein. Dopo Ajwad le isole Awal passarono a Muqrin b. Zamil — il sovrano che sarebbe stato sconfitto dai Portoghesi nel 1521.", "0c4cdac7"]},
"OLAYLAR_EK13:1471-08-24:0":{"b": ["Presa di Arzila da parte dei Portoghesi — secondo capo di sbarco sulla costa del Marocco", "83444a11"], "d": ["Alfonso V sbarcò di persona sulla costa del Marocco con una forza di 30.000 uomini e una flotta di 400 unità e prese Arzila, in mano ai Wattasidi, il 24 agosto 1471. La caduta della città spezzò la resistenza di Tangeri; Tangeri si arrese senza combattere quattro giorni dopo, il 28 agosto. Il Portogallo, dopo Ceuta (1415) e Ksar es-Seghir (1458), stabilì così sulla costa atlantica del Marocco la terza e la quarta posizione; dopo questa campagna il re fece aggiungere al proprio titolo la formula \"signore d'Africa\".", "ec8d27f5"]},
"OLAYLAR_EK13:1488-01-01:0":{"b": ["Safi entra nell'influenza portoghese", "765e703e"], "d": ["Safi, il porto più attivo dell'Atlantico per grano e pesca, entrò nell'influenza portoghese nel 1488; per un certo periodo la città fu governata sotto protezione portoghese da amministratori locali e nel 1508 fu occupata direttamente. Poiché le fonti danno peso diverso a queste due fasi, la data iniziale oscilla tra il 1488 e il 1508; entrambe sono estremi dello stesso processo. Safi rimase cinquantatré anni in mano portoghese e fu evacuata nel 1541, dopo la caduta di Agadir.", "51aa6746"]},
"OLAYLAR_EK13:1505-01-01:0":{"b": ["Fondazione di Santa Cruz do Cabo de Gué — fortezza portoghese ad Agadir", "cc22c433"], "d": ["La fortezza di Santa Cruz do Cabo de Gué, fondata per iniziativa privata sulla costa del Sous, in un punto che fino ad allora il Portogallo non aveva raggiunto, fu costruita nel 1505 e nel 1513 ceduta alla corona portoghese. Controllando il commercio di zucchero e oro della valle del Sous, la fortezza chiudeva lo sbocco sud-occidentale di Marrakech; per questo fu il primo grande obiettivo del movimento sa'diano. L'assedio del 1533 fu respinto, quello del 1541 ebbe successo e diede inizio al crollo del Portogallo in Marocco.", "6d42d1d3"]},
"OLAYLAR_EK13:1513-09-03:0":{"b": ["Presa di Azemmour — controllo della foce dell'Oum Er-Rbia", "232acd4b"], "d": ["L'esercito portoghese al comando del duca Jaime di Braganza entrò il 3 settembre 1513 ad Azemmour, alla foce del fiume Oum Er-Rbia, senza incontrare resistenza. La presa della città diede il controllo sia della foce del fiume sia della via del grano verso l'interno, e l'anno seguente aprì la strada alla fondazione della fortezza di Mazagan, a 12 km a sud-ovest. Azemmour rimase ventotto anni in mano portoghese.", "8ac983da"]},
"OLAYLAR_EK13:1514-01-01:0":{"b": ["Fondazione della fortezza di Mazagan — la posizione portoghese più longeva in Marocco", "786cdb40"], "d": ["Nell'estate del 1514, l'anno dopo la presa di Azemmour, fu costruita sulla costa la fortezza di Mazagan. Dopo il crollo generale del 1541, mentre il Portogallo abbandonava tutte le sue posizioni in Marocco, non lasciò Mazagan; al contrario fece rifare la fortezza con bastioni all'italiana e la città fu mantenuta per duecentocinquantacinque anni. Anche il grande assedio del 1562 fu respinto. Mazagan, ultima posizione portoghese in Marocco, sarebbe stata evacuata nel 1769.", "fe42a1e2"]},
"OLAYLAR_EK13:1517-05-01:0":{"b": ["Resa della fortezza di Mardin — fine della resistenza safavide a sud di Diyarbekir", "e6226de5"], "d": ["Quando Bıyıklı Mehmed Pascià, marciando dopo Çaldıran sulla regione di Diyarbekir, assediò Mardin, le forze safavidi nell'ottobre 1515 si ritirarono nella fortezza; la città cadde in mano ottomana, ma la fortezza resistette. Il contrattacco con rinforzi del governatore safavide Kara Han si concluse con la battaglia di Koçhisar (Kızıltepe) del maggio 1516 — nello scontro durato tutto il giorno nella pianura di Dede Garkın Kara Han fu decapitato e il suo esercito si disperse. La fortezza, nelle parole del TDV, si arrese \"solo nove mesi dopo\".", "791d1c1c"]},
"OLAYLAR_EK13:1521-01-01:0":{"b": ["Presa del Bahrein da parte del Portogallo — fine del dominio jabride", "315a435a"], "d": ["Poiché il sovrano jabride Muqrin b. Zamil rifiutava di pagare il tributo a Ormuz, la flotta portoghese e le forze del Regno di Ormuz, vassallo del Portogallo, sbarcarono sull'isola; Muqrin fu sconfitto in battaglia e il Bahrein nel 1521 entrò sotto l'amministrazione portoghese. L'isola fu poi governata per ottant'anni tramite Ormuz, per lo più da governatori iraniani sunniti. Le perle del Bahrein e la sua posizione strategica avrebbero fatto dell'isola un obiettivo diretto della contesa ottomano-portoghese nel Golfo.", "34a37f50"]},
"OLAYLAR_EK13:1541-03-12:0":{"b": ["Caduta di Agadir — i Sa'diani cominciano a strappare il Portogallo dal Marocco", "bb1568f6"], "d": ["Il sultano sa'diano Muhammad al-Shaykh assediò la fortezza di Santa Cruz il 16 febbraio 1541 e la prese il 12 marzo; circa seicento Portoghesi, tra cui il governatore Guterre de Monroy, furono fatti prigionieri.", "af3555a6"]},
"OLAYLAR_EK13:1541-10-01:0":{"b": ["Evacuazione di Safi e Azemmour — il Portogallo si ritira dalla costa atlantica", "4cb6099a"], "d": ["Dopo la caduta di Agadir il 12 marzo 1541 e il mancato conseguimento dell'alleanza sperata con il sultano del Marocco, João III ordinò l'evacuazione delle due grandi posizioni della costa atlantica; lo sgombero di Safi e Azemmour fu completato nell'autunno del 1541, tra settembre e ottobre. Così in un solo anno andarono perdute tre posizioni e l'espansione cinquantennale del Portogallo sulla costa marocchina si invertì; restarono Ceuta, Tangeri, Arzila, Ksar es-Seghir e la neofortificata Mazagan.", "e6d4728d"]},
"OLAYLAR_EK13:1549-01-01:0":{"b": ["Evacuazione di Arzila — il Portogallo riduce la propria costa settentrionale", "b5d18373"], "d": ["Per la combinazione di crisi finanziaria e pressione sa'diana, João III evacuò Arzila, tenuta dal 1471. La presenza portoghese in Marocco si ridusse così a Ceuta, Tangeri e Mazagan. Arzila sarebbe stata rioccupata per breve tempo nel 1577 e abbandonata definitivamente nel 1589.", "36c1d8e6"]},
"OLAYLAR_EK13:1559-01-01:0":{"b": ["Campagna ottomana in Bahrein — l'ultima grande mossa contro il Portogallo nel Golfo", "14501df3"], "d": ["L'Impero ottomano, stabilitosi sulla costa araba del Golfo con l'annessione di Bassora nel 1546 e la creazione dell'eyalet di Al-Hasa, marciò sul Bahrein al comando di Mustafa Pascià, beylerbey di Al-Hasa, prendendo di mira il commercio delle perle dell'isola e la linea portoghese di Ormuz. L'esito della campagna diverge nelle fonti: il TDV İslâm Ansiklopedisi scrive che gli Ottomani \"nel 1559 presero il Bahrein e vi stabilirono una base\" e che le isole \"in seguito passarono di nuovo all'amministrazione dei Portoghesi\"; la letteratura occidentale registra invece che l'assedio fallì, che i rinforzi portoghesi giunti per mare da Ormuz respinsero le forze ottomane e che, dopo un'epidemia di peste che colpì entrambe le parti, gli Ottomani chiesero condizioni di resa. Le due narrazioni divergono sull'esito stesso; ciò che hanno in comune è che il Bahrein non rimase stabilmente in mano ottomana.", "b35d131f"]},
"OLAYLAR_EK13:1569-01-01:0":{"b": ["Presa di Tunisi da parte di Uluç Ali Pascià — fine dell'assetto hafside-spagnolo", "d4498698"], "d": ["Quando Carlo V nel 1535 prese Tunisi, non governò la città da sé, ma rimise sul trono il sultano hafside Mulay Hasan; nelle parole del TDV la città di Tunisi rimase \\\"fino al secondo intervento degli Ottomani nel 1569 sotto la protezione degli Spagnoli e l'amministrazione di Mulay Ahmed III\\\". Uluç Ali, nominato beylerbey di Algeri il 27 giugno 1568, marciò per terra su Tunisi, sconfisse il sultano hafside a Beja ed entrò in città; Mulay Ahmed si rifugiò nel presidio spagnolo della Goletta (Halkulvâdî). Così il golfo fu diviso in due — la città ottomana, il forte del porto spagnolo — e questa divisione durò quattro anni.", "32206b3e"]},
"OLAYLAR_EK13:1573-10-10:0":{"b": ["Riconquista di Tunisi da parte di Don Juan de Austria — l'unica controparte terrestre di Lepanto", "a6f044ee"], "d": ["Dopo Lepanto (1571), benché la Lega Santa si fosse sciolta, la Spagna si caricò da sola dell'impresa nordafricana: nelle parole del TDV \"il 10 ottobre 1573 gli Spagnoli intrapresero una nuova operazione con lo scopo di assumere il controllo di Tunisi. Presa Tunisi, vi lasciarono 8000 soldati.\" Questa operazione al comando di Don Juan de Austria è l'unico luogo in cui la vittoria di Lepanto trovò un riscontro sulla terraferma; tuttavia non fu duratura e la città fu ripresa undici mesi dopo. Ciò che l'occupazione rovesciò fu un'amministrazione ottomana già stabilita: il 2 Zilhicce 980 (5 aprile 1573) il comandante di Tunisi era Kılıç Ali Pascià, il kaymakam Ramazan Pascià, il beylerbey Haydar Pascià.", "f7f9ab56"]},
"OLAYLAR_EK13:1602-01-01:0":{"b": ["Presa del Bahrein ai Portoghesi da parte dei Safavidi", "c37d982c"], "d": ["Le forze inviate da Shah Abbas I, unendosi ai ribelli dell'isola, fecero uscire dal forte la guarnigione portoghese; nelle parole del TDV le isole furono tolte ai Portoghesi \"nel 1602 da forze legate all'Iran\". Il Bahrein uscì così da ottantuno anni di amministrazione portoghese ed entrò sotto il dominio safavide, restando legato all'Iran per centoquindici anni. È il primo anello della dissoluzione del Portogallo nel Golfo; vent'anni dopo la stessa Ormuz sarebbe caduta per un'operazione congiunta anglo-iraniana.", "19e58d88"]},
"OLAYLAR_EK13:1717-01-01:0":{"b": ["Invasione omanita del Bahrein — fine del dominio safavide", "c9be5820"], "d": ["Durante la dissoluzione degli ultimi anni dello Stato safavide, la flotta dell'Oman sotto la dinastia Ya'rubide invase l'isola e il dominio safavide ebbe fine. I trentacinque anni seguenti sono il periodo più confuso del Golfo: l'isola cambiò di mano più volte tra Oman, Iran e forze arabe locali.", "b0c7f671"]},
"OLAYLAR_EK13:1753-01-01:0":{"b": ["Passaggio del Bahrein all'amministrazione degli Âl-i Mezkûr di Bushehr", "610e2f9d"], "d": ["La famiglia Âl-i Mezkûr, originaria dell'Oman, stabilitasi a Bushehr e considerata huwala, nel 1753 pose il Bahrein sotto la propria amministrazione muovendo dalle sue basi a Bushehr. La famiglia guidava le comunità arabe sulla costa iraniana del Golfo e governava l'isola a nome dell'Iran; il suo ultimo rappresentante, Nasr Âl-i Mezkûr, era stato nominato governatore del Bahrein dall'amministrazione zand. È l'ultimo governo dell'isola prima degli Âl Khalifa.", "7cc5fed2"]},
"OLAYLAR_EK13:1769-03-11:0":{"b": ["Evacuazione di Mazagan — cadde l'ultima posizione del Portogallo in Marocco", "f9e9749d"], "d": ["Di fronte all'assedio iniziato all'inizio del 1769 dal sultano alawide Muhammad III b. Abdallah, la guarnigione di 592 uomini non resse; la flotta di evacuazione partita da Lisbona il 1° febbraio imbarcò gli ultimi soldati l'11 marzo 1769 e il governatore Dinis Gregório fu l'ultimo a lasciare la città. Così la presenza portoghese in Marocco, iniziata con la presa di Ceuta nel 1415, si concluse dopo tre secoli e mezzo. Mazagan era l'unica posizione della costa atlantica tenuta dopo il crollo generale del 1541 e, con i suoi duecentocinquantacinque anni, fu il luogo che il Portogallo tenne più a lungo in Marocco.", "c0ad57bc"]},
"OLAYLAR_EK13:1783-01-01:0":{"b": ["Conquista del Bahrein da parte degli Âl Khalifa — fondazione della dinastia che regna ancora oggi", "8773b011"], "d": ["Nasr Âl-i Mezkûr, governatore zand del Bahrein, assediò Zubara, nella penisola del Qatar; le forze degli Utub al comando di Ahmad b. Muhammad b. Khalifa ruppero l'assedio e, passate al contrattacco, presero il Bahrein nello stesso anno. L'annotazione del TDV è breve: \"Nel 1783 il Bahrein entrò sotto il dominio degli Âl Khalifa della tribù degli Utub.\" Dopo questa vittoria Ahmad b. Muhammad fu chiamato con il soprannome di \"al-Fatih\" e la dinastia da lui fondata ha regnato sull'isola fino a oggi.", "470bd22f"]},
"OLAYLAR_EK13:1861-05-21:0":{"b": ["Trattato del Bahrein con l'Inghilterra — ingresso nel sistema di protezione nel Golfo", "576796b2"], "d": ["Secondo l'annotazione del TDV \\\"il 21 maggio 1861 l'Inghilterra e Ali, fratello dello sceicco Muhammad, in rappresentanza del Bahrein, firmarono un accordo che vietava nella regione la tratta degli schiavi e la pirateria\\\"; nei documenti inglesi lo stesso trattato (Perpetual Truce of Friendship and Peace) porta la data del 31 maggio 1861. Il trattato è il primo anello del sistema di protezione che legò all'Inghilterra le relazioni esterne del Bahrein, e l'isola rimase fuori da questo sistema anche dopo il nuovo insediamento ottomano ad Al-Hasa e Qatif nel 1871.", "ab2ad5ff"]},
"OLAYLAR_EK14:1281-01-01:0":{"b": ["Ahî Evran — santo patrono fondatore dell'organizzazione ahî", "3392e100"], "d": ["Ahî Evran è considerato uno dei fondatori dell'organizzazione ahî in Anatolia e il pîr dei conciatori (debbağ). La sua zâviye a Kırşehir continuò fino all'inizio del XX secolo come centro spirituale dell'organizzazione di artigiani/corporazioni in età ottomana; lo Stato confermò ufficialmente questa posizione nel 1780, 1782, 1822-23 e 1842.", "caa063df"]},
"OLAYLAR_EK14:1326-01-01:0":{"b": ["Şeyh Edebâli — legame di fondazione tra l'ahî e la dinastia ottomana", "c1186059"], "d": ["Edebâli, che aveva fondato una zâviye a Bilecik e che era anche uno sceicco dell'organizzazione ahî, secondo la tradizione interpretò il celebre sogno di Osman Gazi; in seguito Osman Gazi sposò Mâlhun Hatun, figlia di Edebâli. Edebâli è considerato anche il primo cadì e muftì ottomano.", "60c970e5"]},
"OLAYLAR_EK14:1330-06-01:0":{"b": ["Orhan Gazi destina uno spazio ai giochi del cirit dopo la conquista di Bursa", "da1becbd"], "d": ["Secondo la voce Cirit del TDV, Orhan Gazi, dopo la conquista di Bursa, destinò come fondazione pia (vakıf) un'area nei dintorni per le corse di cavalli e i giochi del cirit — uno dei primi esempi registrati di istituzionalizzazione del gioco del cirit presso gli Ottomani.", "f099d0d8"]},
"OLAYLAR_EK14:1357-06-01:0":{"b": ["Presunto inizio delle lotte di Kırkpınar", "2d93fa65"], "d": ["Secondo la tradizione, la lotta di Kırkpınar iniziò con le gare di lotta tenute tra i quaranta gazi passati in Rumelia con il conquistatore Süleyman Pascià. Le voci Güreş e Kırkpınar del TDV riportano questa tradizione ma non danno una data di fondazione certa.", "a7dedab7"]},
"OLAYLAR_EK14:1362-06-01:0":{"b": ["Fondazione del Corpo dei Giannizzeri", "f4206dce"], "d": ["Il sistema, iniziato sotto la guida di Çandarlı Kara Halil e Molla Rüstem con l'addestramento di giovani non musulmani presi tra i prigionieri di guerra in base alla legge del pençik, acquisì carattere istituzionale sotto Murad I attraverso l'Acemi Ocağı fondato a Gallipoli.", "4842eade"]},
"OLAYLAR_EK14:1402-01-01:0":{"b": ["Inizio della costruzione della Moschea Vecchia (Ulu Cami) di Edirne", "da7a22ac"], "d": ["La costruzione dell'Eski Cami, detta popolarmente anche Ulucami (Câmi-i Atîk), fu iniziata da Emir Süleyman Çelebi nel 1402-1403.", "0f5a6b9d"]},
"OLAYLAR_EK14:1414-01-01:0":{"b": ["Inizio della costruzione del complesso della Moschea Verde di Bursa", "280b8a21"], "d": ["Mehmed I, che dopo l'Interregno (Fetret Devri) aveva riunificato il trono, avviò nel 1414 la costruzione del complesso e lo collocò in un punto centrale di Bursa, in modo da distinguerlo dai complessi del nonno e del padre. Il capo architetto è Hacı İvaz Pascià.", "b820a0dd"]},
"OLAYLAR_EK14:1419-12-01:0":{"b": ["Completamento del complesso della Moschea Verde di Bursa", "bc82821f"], "d": ["Il complesso della Moschea Verde, noto per il programma di maioliche e decorazioni a cui contribuirono anche maestri di Tabriz, fu completato nel dicembre 1419. Il complesso comprende moschea, mausoleo (Yeşil Türbe), medrese, imaret e hammam; è uno degli esempi più ricchi della prima architettura ottomana.", "b3e76f7c"]},
"OLAYLAR_EK14:1421-06-01:0":{"b": ["Inizio dell'applicazione effettiva del sistema devşirme", "fa835172"], "d": ["Il sistema devşirme, non osservato negli Stati islamici precedenti, iniziò dapprima come uso dei giovani prigionieri di guerra non musulmani in base alla legge del pençik. Secondo il TDV \"si comprende che fu applicato ai tempi di Çelebi Mehmed, ma che fu codificato nell'epoca di suo figlio Murad II.\"", "be8c415b"]},
"OLAYLAR_EK14:1425-01-01:0":{"b": ["Istituzione della carica di şeyhülislam — muftiato di Bursa di Molla Fenârî", "2a8ee2b9"], "d": ["La nomina, nel 1425, a muftì di Bursa del dotto Molla Fenârî, per molti anni cadì di Bursa, è considerata, nelle parole del TDV, \"l'inizio del muftiato e dello şeyhülislamato presso gli Ottomani\". Il TDV precisa tuttavia che ciò non è identico alla carica di şeyhülislam pienamente istituzionalizzata del XVI secolo, rappresentante di tutta l'organizzazione dei dotti (ilmiye).", "3c8f9c61"]},
"OLAYLAR_EK14:1432-06-01:0":{"b": ["Istituzionalizzazione del sistema timar", "dc267780"], "d": ["I primi riferimenti documentati al timar risalgono all'epoca di Orhan Bey; la codificazione sistematica avvenne invece sotto Murad II. I registri riassuntivi del timar (icmal defterleri) preparati in questo periodo mostrano che tutti i principi fondamentali del sistema si erano formati; i documenti relativi al 1432 circa provano che le leggi erano pienamente in vigore.", "6494e2c1"]},
"OLAYLAR_EK14:1447-01-01:0":{"b": ["Completamento della moschea Üç Şerefeli e del suo complesso", "cde6993e"], "d": ["La moschea Üç Şerefeli, fatta costruire da Murad II dai maestri Muslihuddin e Şehâbeddin nell'arco di dieci anni (1437-1447), è considerata il primo esempio di moschea a pianta centrale nell'architettura ottomana e una delle svolte dell'architettura di transizione precedente all'epoca classica.", "daf1585b"]},
"OLAYLAR_EK14:1451-06-01:0":{"b": ["Istituzionalizzazione del Divan-ı Hümayun con la legge di Mehmed il Conquistatore", "e8443e77"], "d": ["Il Divan, regolato da norme stabili a Edirne sotto Murad II, cominciò ad acquisire l'identità di \"Dîvân-ı Hümâyun\". La vera trasformazione venne con la legge di Mehmed il Conquistatore: la novità maggiore fu l'abolizione completa della presidenza del divan da parte del sultano e il suo trasferimento al gran visir.", "e776b01d"]},
"OLAYLAR_EK14:1453-06-01:0":{"b": ["Mehmed il Conquistatore destina l'Okmeydanı agli arcieri", "342a9fd5"], "d": ["Mehmed il Conquistatore, che durante la conquista di Istanbul aveva posto il proprio quartier generale sulle alture di Kasımpaşa, aveva usato questo luogo anche come campo di addestramento per gli arcieri; dopo aver preso la città destinò l'area in modo permanente agli arcieri. Questa destinazione è l'inizio del ruolo dell'Okmeydanı come centro della tradizione arcieristica ottomana destinata a durare secoli.", "0c85baff"]},
"OLAYLAR_EK14:1502-06-01:0":{"b": ["Bursa raggiunge l'apice nel commercio della seta iraniana", "f1324cdf"], "d": ["Le carovane provenienti da Tabriz portavano a Bursa le sete di Gilan, Astarabad e Sari, dove mercanti genovesi, veneziani, fiorentini ed ebrei le compravano in concorrenza. Nel 1479 il valore della seta importata dall'Iran raggiunse 150.000 ducati veneziani; nel 1502 in città lavoravano più di 1000 telai.", "0f47c417"]},
"OLAYLAR_EK14:1504-01-01:0":{"b": ["Bayezid II conferisce grandi premi ai lottatori di Kırkpınar", "d745b882"], "d": ["Secondo la voce Güreş del TDV, Bayezid II nel 1504 conferì ai lottatori premi di 3.000 e 1.500 kuruş; è uno dei primi esempi registrati del patrocinio della corte ottomana allo sport della lotta.", "cc00554e"]},
"OLAYLAR_EK14:1505-10-13:0":{"b": ["Completamento della moschea e del complesso di Beyazıt", "eb9ab65b"], "d": ["La costruzione della moschea e del complesso di Beyazıt, fatti costruire per Bayezid II, iniziò nel 906 (1500) secondo un documento d'archivio e fu completata il 14 Cemâziyelevvel 911 (13 ottobre 1505). L'architetto è discusso: sulla base dell'annotazione di Ayvansarâyî fu a lungo ritenuta opera di Mimar Hayreddin, poi fu attribuita a Mimar Kemâleddin, secondo alcuni i due lavorarono insieme; lo stesso documento indica invece come maestro Yakub Shah b. Sultan Shah. La moschea è considerata uno dei monumenti importanti del passaggio dall'architettura ottomana pre-classica all'epoca classica.", "9b7591c4"]},
"OLAYLAR_EK14:1515-01-01:0":{"b": ["Trasferimento del Tersâne-i Âmire a Istanbul (Kasımpaşa/Corno d'Oro)", "f36e3675"], "d": ["Sotto Selim il Severo il nuovo arsenale, la cui costruzione era iniziata nella baia a ovest delle mura di Galata, fu completato nel 1515 con 160 scali; così le attività dell'arsenale, con sede a Gallipoli, furono trasferite a Istanbul. L'istituzione assunse poi ufficialmente il nome di \"Tersâne-i Âmire\" sotto Barbaros Hayreddin Pascià.", "baedf596"]},
"OLAYLAR_EK14:1520-01-01:0":{"b": ["Morte dello sceicco Hamdullah ed eredità della scuola calligrafica", "f5ed4d09"], "d": ["Lo sceicco Hamdullah di Amasya, maestro di calligrafia di Bayezid II, portò alla maturità la scuola dell'aklâm-ı sitte (le sei scritture) e divenne il fondatore di uno stile calligrafico ottomano destinato a dominare in tutto il mondo islamico. Alla sua morte nel 1520 lasciò dietro di sé un'ampia cerchia di allievi.", "26c5c5fc"]},
"OLAYLAR_EK14:1521-01-01:0":{"b": ["Piri Reis completa la prima versione del Kitâb-ı Bahriye", "fd6cc1ff"], "d": ["Piri Reis completò nel 1521 la prima versione (in prosa) del Kitâb-ı Bahriye, che raccoglie le coste, i porti e le informazioni di navigazione del Mediterraneo. Questa prima versione non era ancora stata presentata al sultano e aveva il carattere di una bozza da ampliare negli anni successivi.", "72e9151d"]},
"OLAYLAR_EK14:1526-01-01:0":{"b": ["Piri Reis amplia il Kitâb-ı Bahriye e lo presenta a Solimano il Legislatore", "d4abf0b7"], "d": ["Piri Reis ampliò il Kitâb-ı Bahriye, in parte in forma poetica, e lo presentò nel 1526 a Solimano il Legislatore. In questa forma l'opera si diffuse come la più completa guida di navigazione della marineria ottomana.", "7209606f"]},
"OLAYLAR_EK14:1534-01-01:0":{"b": ["Matrakçı Nasuh raffigura nel Beyân-ı Menâzil l'itinerario della campagna dei Due Iraq (Irakeyn)", "aa012278"], "d": ["Matrakçı Nasuh, che partecipò alla prima campagna di Persia (Irakeyn) intrapresa da Solimano il Legislatore nel 1534, raffigurò con la tecnica della miniatura-mappa ogni tappa dell'itinerario dell'esercito da Istanbul a Tabriz e da lì a Baghdad. Questo lavoro fu raccolto nell'opera intitolata Beyân-ı Menâzil-i Sefer-i Irâkeyn ed è l'esempio più originale del genere del menzilname presso gli Ottomani.", "9ea08eae"]},
"OLAYLAR_EK14:1534-12-04:0":{"b": ["Fuzûlî presenta una qasida al Legislatore dopo la conquista di Baghdad", "1ef0653f"], "d": ["Dopo la conquista di Baghdad da parte di Solimano il Legislatore nel 1534, Fuzûlî presentò al sultano ottomano cinque qasida, compresa la celebre qasida che si apre con il verso \"Geldi burc-ı evliyâya pâdişâh-ı nâmdâr\"; così, uscito dalla protezione safavide, cercò il patrocinio degli statisti ottomani.", "b8e9e300"]},
"OLAYLAR_EK14:1535-01-01:0":{"b": ["Fuzûlî completa il masnavi Leylâ vü Mecnûn", "e3ef4085"], "d": ["Leylâ vü Mecnûn, considerato uno dei più bei masnavi della letteratura turca classica, fu scritto e completato da Fuzûlî nel 1535, su richiesta dei poeti di Istanbul che avevano partecipato alla campagna di Baghdad del Legislatore.", "bdb0a098"]},
"OLAYLAR_EK14:1538-01-01:0":{"b": ["Nomina di Mimar Sinan ad architetto capo di corte (hassa mimarbaşı)", "7a753f0e"], "d": ["Secondo la voce Sinan del TDV İslâm Ansiklopedisi, alla morte nel 1537 dell'hassa mimarbaşı Acem Alisi, Sinan, che si era fatto notare per il ponte costruito sul fiume Prut durante la campagna di Moldavia, fu posto in questo incarico per apprezzamento del gran visir Lutfi Pascià. Iniziò così il periodo di Sinan come architetto capo, che sarebbe durato oltre cinquant'anni.", "e99864c8"]},
"OLAYLAR_EK14:1543-06-01:0":{"b": ["Inizio della costruzione della moschea e del complesso Şehzade", "1a70ddfd"], "d": ["Solimano il Legislatore ordinò nel 1543 la costruzione del complesso a nome del figlio, lo şehzade Mehmed, perduto in un'epidemia di peste; i lavori iniziarono nel giugno 1543, completando prima il mausoleo e passando poi alla costruzione della moschea. Quest'opera è, nelle parole stesse di Mimar Sinan, \"la mia opera da apprendista\".", "3f3d7e67"]},
"OLAYLAR_EK14:1547-01-01:0":{"b": ["Completamento del complesso di Üsküdar İskele (Mihrimah Sultan)", "3769007f"], "d": ["La costruzione del complesso nella piazza dell'İskele di Üsküdar iniziò nei primi anni del 1540 e fu completata nel 1547. È cronologicamente la prima delle due grandi moschee che Mihrimah Sultan fece costruire a Mimar Sinan; la seconda (Edirnekapı) sarebbe stata completata circa vent'anni dopo.", "01e5c0ad"]},
"OLAYLAR_EK14:1548-06-01:0":{"b": ["Venezia apre un consolato ad Aleppo", "3aad8b9e"], "d": ["Nel XVI secolo il baricentro commerciale degli Europei si spostò da Damasco ad Aleppo. Come segno concreto di questo cambiamento Venezia aprì un consolato ad Aleppo nel 1548; la seguirono la Francia nel 1557 e l'Inghilterra nel 1586. La città divenne il principale mercato in cui si scambiavano i panni di lana e l'argento d'Europa con le spezie indiane e, alla fine del secolo, con la seta iraniana.", "1c077dea"]},
"OLAYLAR_EK14:1548-08-01:0":{"b": ["Apertura al culto della moschea Şehzade", "2bb3f4b2"], "d": ["Dopo una costruzione durata circa cinque anni, la moschea Şehzade fu aperta al culto nell'agosto 1548. Con il suo schema planimetrico a cupola centrale e doppio minareto è considerata l'annuncio delle successive grandi opere di Mimar Sinan; il complesso comprende moschea, mausoleo, medrese, imaret, tabhane e caravanserraglio.", "591f4ecf"]},
"OLAYLAR_EK14:1554-01-01:0":{"b": ["Inizio della costruzione della linea di adduzione delle acque di Kırkçeşme", "14124b59"], "d": ["Mimar Sinan, per ordine del Legislatore, esaminò l'adduzione dell'acqua a Istanbul dalle foreste di Belgrado e ne dichiarò la fattibilità; la costruzione del grande impianto idrico iniziò nel 1554 e fu terminata prima del 1563. Il TDV definisce questa opera di Sinan \"la più importante sotto il profilo ingegneristico e la più grande per volume\".", "dc29aa04"]},
"OLAYLAR_EK14:1554-06-01:0":{"b": ["Apertura dei primi caffè a Istanbul", "85c12f9f"], "d": ["L'ingresso del caffè nella vita urbana ottomana iniziò con i caffè aperti a Tahtakale dal mercante aleppino Hakem e da un certo Şems di Damasco. In breve nacque un nuovo spazio pubblico in cui si riunivano persone di ogni strato della società; negli ultimi anni del Legislatore a Istanbul vi erano cinquanta caffè.", "e1289ca2"]},
"OLAYLAR_EK14:1555-06-01:0":{"b": ["Ebüssuûd Efendi esamina giuridicamente la questione del gedik (diritto di monopolio degli artigiani)", "5d4e2930"], "d": ["La questione del \"gedik\", diritto di monopolio e privilegio riconosciuto a un numero determinato di persone nell'artigianato, tornò all'ordine del giorno ai tempi del Legislatore; lo şeyhülislam Ebüssuûd Efendi nel 1555-56 esaminò a fondo la materia e presentò al sultano la legittimità della pratica.", "a4bf6dee"]},
"OLAYLAR_EK14:1557-01-01:0":{"b": ["Seydi Ali Reis completa a Istanbul il Mir'âtü'l-Memâlik", "ee8640e1"], "d": ["Seydi Ali Reis completò a Istanbul nel gennaio 1557 l'opera di viaggio intitolata Mir'âtü'l-Memâlik, scritta lungo il viaggio di ritorno a partire da Baghdad. L'opera è una fonte di prima mano che racconta il ritorno in patria, via terra attraverso l'Asia centrale, di un marinaio ottomano proveniente dall'Oceano Indiano.", "3affe91e"]},
"OLAYLAR_EK14:1561-01-01:0":{"b": ["Costruzione del complesso (moschea) di Rüstem Pascià", "02e30725"], "d": ["Il complesso che Rüstem Pascià, genero e gran visir del Legislatore, fece costruire a Mimar Sinan fu edificato tra il 1555 e il 1561. L'edificio è noto per la sua architettura originale, impostata su una piattaforma sopraelevata con botteghe a volta al di sotto, e per le ricche maioliche di İznik.", "3a9a7e0b"]},
"OLAYLAR_EK14:1566-01-01:0":{"b": ["Completamento del ponte di Mostar", "e7f434af"], "d": ["Il celebre ponte di Mostar sul fiume Neretva fu costruito da Mimar Hayreddin intorno al 1566-67; la menzione del ponte in un documento ufficiale del 1568 conferma che era già completato. L'edificio è uno degli esempi più noti della classica architettura ottomana dei ponti, a un'unica arcata a sesto acuto.", "62de5c2a"]},
"OLAYLAR_EK14:1566-01-01:1":{"b": ["Completamento della moschea di Edirnekapı (Mihrimah Sultan)", "f2d21a82"], "d": ["La costruzione della moschea, iniziata dopo il permesso di costruzione confermato nel 1563 per Mihrimah Sultan, figlia del Legislatore, fu completata nel 1566; l'atto di fondazione (vakfiye) del complesso fu redatto nel 1570-71. L'edificio è una delle grandi opere di Mimar Sinan più vicine alle mura di Istanbul.", "0f9e5ecd"]},
"OLAYLAR_EK14:1566-09-08:0":{"b": ["Bâkî scrive un'elegia per Solimano il Legislatore", "7aa6665f"], "d": ["Quando giunse da Szigetvár la notizia della morte di Solimano il Legislatore, Bâkî, il \"sultânü'ş-şuarâ\" (sultano dei poeti) dell'epoca, scrisse una delle più celebri elegie della letteratura ottomana.", "1328fbfd"]},
"OLAYLAR_EK14:1566-09-30:0":{"b": ["Bâkî presenta un cülûsiye a Selim II", "6027f034"], "d": ["Subito dopo la salita al trono di Selim II, Bâkî presentò al nuovo sultano un \"cülûsiye\" (poema di ascesa al trono) — secondo il TDV, immediatamente dopo l'elegia scritta per la morte del Legislatore.", "1417fae7"]},
"OLAYLAR_EK14:1567-01-01:0":{"b": ["Completamento del ponte di Büyükçekmece", "5f49b3c5"], "d": ["Il ponte, avviato per ordine di Solimano il Legislatore, fu fatto completare nel 1567-68 dal figlio Selim II dopo la morte del sovrano durante la campagna di Szigetvár. Mimar Sinan riparò di persona anche le parti del ponte, costruito nel punto in cui il lago di Büyükçekmece si unisce al mare, danneggiate da una piena.", "4478b56a"]},
"OLAYLAR_EK14:1568-01-01:0":{"b": ["Inizio della costruzione della moschea Selimiye (Edirne)", "07e18c9e"], "d": ["La costruzione della Selimiye, che Mimar Sinan chiamava \"la mia opera da maestro\", iniziò nel 1568 a nome di Selim II e, durata sei anni, fu completata nel 1574 (il completamento è già registrato nella cronologia). Le botteghe occidentali dell'arasta e la scuola elementare (sıbyan mektebi) furono invece completate da Davud Agha sotto Murad III, dopo la morte di Selim II.", "a3d4551b"]},
"OLAYLAR_EK14:1572-01-22:0":{"b": ["Morte di Kınalızâde Ali Çelebi — autore dell'Ahlâk-ı Alâî, il testo classico della filosofia morale ottomana", "dd921873"], "d": ["Kınalızâde Ali Çelebi, autore dell'Ahlâk-ı Alâî, il più noto testo classico della filosofia morale ottomana, morì il 22 gennaio 1572 mentre era kazasker dell'Anatolia. Della sua opera esistono più di settanta copie nelle biblioteche di Istanbul.", "8aa682b5"]},
"OLAYLAR_EK14:1573-01-01:0":{"b": ["Costruzione del complesso di Piyâle Pascià", "75411278"], "d": ["Piyâle Pascià, capitano pascià (kaptan-ı deryâ) e genero di Selim II, acquistò nel 1573 il terreno del complesso e lo fece costruire a Mimar Sinan. Il complesso fu concepito come un vasto insieme composto da moschea, medrese, tekke, mausoleo, cimitero, scuola elementare (sıbyan mektebi), fontana, bazar e hammam.", "91e37e16"]},
"OLAYLAR_EK14:1577-01-01:0":{"b": ["Completamento del ponte sulla Drina (Sokollu Mehmed Pascià)", "1d668c73"], "d": ["Il ponte, costruito da Mimar Sinan sotto il patrocinio del gran visir Sokollu Mehmed Pascià, fu completato nel 1577-78 secondo la data della sua iscrizione; alcuni studiosi sostengono che i lavori siano iniziati nel 1571-72. Il ponte è il simbolo del legame di Sokollu con Višegrad, dove era nato.", "cbbd4b7e"]},
"OLAYLAR_EK14:1577-01-01:1":{"b": ["Costruzione della moschea di Azapkapı (Sokollu Mehmed Pascià)", "f7b57feb"], "d": ["La moschea, situata accanto al pilastro del ponte di Unkapanı dal lato di Şişhane, fu fatta costruire a Mimar Sinan dal gran visir Sokollu Mehmed Pascià. L'edificio è una delle due moschee di Sinan costruite a nome di Sokollu (l'altra è la moschea di Kadırga).", "badb6241"]},
"OLAYLAR_EK14:1578-01-02:0":{"b": ["Murad III dà l'ordine di redigere lo Hünernâme", "b125710d"], "d": ["Murad III, con un firmano del 2 gennaio 1578, ordinò a Seyyid Lokman di redigere lo Hünernâme, che tratta la vita dei sultani da Osman Gazi fino alla sua epoca; le miniature dell'opera furono preparate da Nakkaş Osman e dalla sua squadra.", "5b7078bd"]},
"OLAYLAR_EK14:1580-01-01:0":{"b": ["Completamento della moschea di Zal Mahmud Pascià", "732f75bc"], "d": ["Nella costruzione del complesso, iniziata dopo il matrimonio del 1574 tra Zal Mahmud Pascià e Şah Sultan, la costruzione della moschea fu completata nel 1580; le medrese durarono fino al 1582 e la fontana fino al 1590. Il complesso si distingue per la sua pianta originale con due minareti simmetrici sulle alture di Eyüp.", "9cf44e2d"]},
"OLAYLAR_EK14:1588-01-01:0":{"b": ["Completamento del secondo volume dello Hünernâme", "70a1e741"], "d": ["Il secondo volume dello Hünernâme fu completato nel gennaio 1588; con 65 miniature divenne una delle opere più preziose, dal punto di vista documentario, della storiografia ottomana. Entrambi i volumi furono illustrati nel laboratorio di Nakkaş Osman.", "148989eb"]},
"OLAYLAR_EK14:1592-01-01:0":{"b": ["Davud Agha diventa architetto capo di corte", "8cdc7f53"], "d": ["Dopo il breve intervallo seguito alla morte di Mimar Sinan nel 1588, Davud Agha a partire dal 1592 cominciò a essere menzionato nei documenti ufficiali come hassa mimarbaşı. Davud Agha, che si occupò di alcuni elementi complementari del complesso della Selimiye e della prima costruzione della Yeni Cami, è uno dei maggiori architetti dell'epoca.", "cca50071"]},
"OLAYLAR_EK14:1598-04-09:0":{"b": ["Posa delle fondamenta della Yeni Cami (Eminönü)", "d3cddc01"], "d": ["Sotto il patrocinio di Safiye Sultan, madre di Mehmed III, le fondamenta della moschea furono poste con blocchi di pietra, dopo aver consolidato il terreno con pali. Due distinte voci del TDV danno date diverse per questo evento (la voce Yenicami Külliyesi il 9 aprile 1598, la voce Dâvud Ağa il 23 agosto 1597); qui si è adottata la data della voce specifica dell'edificio.", "744933c0"]},
"OLAYLAR_EK14:1598-09-01:0":{"b": ["Morte di Davud Agha per la peste e interruzione della costruzione della Yeni Cami", "81f2cd04"], "d": ["Davud Agha, morto nell'epidemia di peste del settembre 1598 quando aveva innalzato la Yeni Cami da terra solo di uno zira, fu sostituito come architetto capo da Dalgıç Ahmed Çavuş. Il TDV segnala che in una versione alternativa, basata su un poema cronogrammatico, la data di morte figura come 1599-1600 e che la data esatta non è stata accertata.", "02ee24e4"]},
"OLAYLAR_EK14:1599-06-01:0":{"b": ["Forte esportazione del sof di Ankara verso l'Europa", "3f37018d"], "d": ["Il sof e lo şâl tessuti ad Ankara erano esportati, oltre che ai mercati interni come Istanbul, Bursa, Damasco e Aleppo, a Venezia, in Polonia, in Inghilterra e in Francia. Nell'esempio fornito dal TDV, nel 1599 diciotto mercanti acquistarono 162 carichi di sof per un valore di 5.700.000 akçe e li spedirono ad Aleppo e Venezia.", "966119b2"]},
"OLAYLAR_EK14:1603-12-20:0":{"b": ["Arresto della costruzione della Yeni Cami per la morte di Mehmed III", "5acef053"], "d": ["Dopo la morte nel 1603 di Mehmed III, figlio della sua fondatrice Safiye Sultan, Safiye Sultan fu mandata al Vecchio Palazzo (Eski Saray) e la costruzione della Yeni Cami rimase incompiuta; l'edificio in questo stato attese circa sessant'anni senza essere completato.", "6d8a4c2b"]},
"OLAYLAR_EK14:1633-01-01:0":{"b": ["Kâtib Çelebi inizia a Aleppo le ricerche per il Keşfü'z-Zünûn", "094e6870"], "d": ["Kâtib Çelebi iniziò nel 1633 ad Aleppo a raccogliere il materiale del Keşfü'z-Zünûn, che sarebbe diventato il suo capolavoro bibliografico. Durante questo lavoro, che sarebbe durato vent'anni, passò al vaglio una per una le biblioteche e le librerie delle città in cui si recò.", "92278c89"]},
"OLAYLAR_EK14:1635-01-01:0":{"b": ["Esecuzione di Nef'î per le sue satire", "5e459c60"], "d": ["Nef'î, poeta di divan noto per le sue satire, fu giustiziato per ordine di Murad IV nel 1635 a causa della raccolta satirica intitolata Sihâm-ı Kazâ. Il gran visir Bayram Pascià lo consegnò; Nef'î fu strangolato nella legnaia del palazzo e il suo cadavere gettato in mare.", "e3b52153"]},
"OLAYLAR_EK14:1640-01-01:0":{"b": ["Evliya Çelebi intraprende il primo viaggio — inizio del Seyahatnâme", "ca3ce3f9"], "d": ["Evliya Çelebi, con il suo primo viaggio fuori da Istanbul, a Bursa nel 1640, iniziò quarant'anni di vita di viaggi che avrebbero costituito la base del suo Seyahatnâme in dieci volumi. L'opera, poiché l'autore morì intorno al 1684, si interrompe bruscamente nel decimo volume senza essere stata completata.", "1db7969c"]},
"OLAYLAR_EK14:1640-06-01:0":{"b": ["Redazione del registro di narh più completo", "6c1e231b"], "d": ["Benché la pratica del narh (calmiere) risalga a tempi molto antichi presso gli Ottomani, il registro di narh più completo giunto fino a noi è datato 1640; questo registro, che comprende generi alimentari, abbigliamento, servizi, standard e condizioni igieniche, \"funzionò, nelle parole del TDV, come una vera e propria legge di regolamentazione del mercato.\"", "3f704851"]},
"OLAYLAR_EK14:1648-01-01:0":{"b": ["Kâtib Çelebi inizia per la prima volta a scrivere il Cihannümâ", "554c6734"], "d": ["Kâtib Çelebi iniziò nel 1648 la prima stesura del Cihannümâ allo scopo di colmare la lacuna della conoscenza geografica ottomana di fronte alle scoperte geografiche dell'Occidente. Questa prima versione rimase incompiuta perché non si trovarono fonti sufficienti su alcuni paesi europei.", "aa7d5e31"]},
"OLAYLAR_EK14:1650-01-01:0":{"b": ["Maturazione del sistema dell'iltizam con il passaggio al monopolio della classe militare", "2c587934"], "d": ["Il metodo dell'iltizam (appalto della riscossione delle imposte a privati dietro corrispettivo) era in uso dalla seconda metà del XV secolo, ma dall'inizio del XVI secolo si diffuse rapidamente. Secondo il TDV il processo con cui il settore passò interamente al monopolio dei membri della classe militare si completò nel 1650; l'iltizam divenne così il principale metodo fiscale che sostituì il sistema timar.", "d50f2237"]},
"OLAYLAR_EK14:1654-12-01:0":{"b": ["Kâtib Çelebi si accinge a riscrivere da capo il Cihannümâ", "e9c68110"], "d": ["Kâtib Çelebi, che aveva lasciato incompiuta la prima stesura, si accinse alla fine del 1654 a riscrivere da capo il Cihannümâ. Anche questa seconda versione non poté essere completata; quando l'opera era giunta a Van rimase incompiuta per la morte dell'autore nel 1657 e fu stampata in questa forma solo nel 1732 da İbrahim Müteferrika.", "5a96db0a"]},
"OLAYLAR_EK14:1665-10-30:0":{"b": ["Completamento e apertura al culto della Yeni Cami", "d6d86c82"], "d": ["La costruzione della Yeni Cami, rimasta incompiuta per oltre sessant'anni, fu completata sotto la direzione dell'architetto capo Meremetçi Mustafa Agha, nominato nel 1661 da Hatice Turhan Valide Sultan, e fu aperta al culto con la preghiera del venerdì del 30 ottobre 1665.", "0ec54cd6"]},
"OLAYLAR_EK14:1675-01-01:0":{"b": ["Mehmed IV fa giocare il cirit per giorni alla festa di circoncisione di Edirne", "3638a5b6"], "d": ["Mehmed IV, alla festa di circoncisione dei suoi principi organizzata a Edirne nel 1675, fece tenere gare di cirit durate giorni; è citato in modo particolare nella voce Cirit del TDV come uno degli esempi più appariscenti del sostegno della corte ottomana allo sport del cirit.", "57c8c183"]},
"OLAYLAR_EK14:1679-01-01:0":{"b": ["Hâfız Osman sviluppa il proprio stile calligrafico", "93081cb3"], "d": ["Hâfız Osman, appartenente alla linea dello sceicco Hamdullah, nel 1679 sviluppò nell'aklâm-ı sitte uno stile proprio, che sarebbe poi stato chiamato \"scuola di Hâfız Osman\". Questo stile è durato fino ai giorni nostri in due rami distinti.", "8d00a956"]},
"OLAYLAR_EK14:1695-01-01:0":{"b": ["Hâfız Osman nominato maestro di calligrafia di Mustafa II", "d976cda4"], "d": ["Hâfız Osman, considerato il più abile calligrafo dell'epoca, nel 1695 fu nominato maestro di calligrafia di Mustafa II, appena salito al trono. Nel corso della vita formò circa cinquanta calligrafi e copiò 25 esemplari del Corano.", "c70668d5"]},
"OLAYLAR_EK14:1711-01-01:0":{"b": ["Morte di Itrî", "62750526"], "d": ["Buhûrîzâde Mustafa Itrî Efendi, uno dei più grandi compositori della musica turca, morì nel 1711 secondo fonti vicine all'epoca. Con opere come il tekbir in segâh e il na't in rast lasciò capolavori della musica di moschea e di tekke.", "a2ccc3ba"]},
"OLAYLAR_EK14:1718-01-01:0":{"b": ["Nedîm si afferma come precursore della poesia dell'Età dei Tulipani", "d3c40dbb"], "d": ["Durante l'Età dei Tulipani (Lâle Devri, 1718-1730) Nedîm sviluppò un nuovo stile poetico che si distingueva per perfezione espressiva, ricerca di semplicità e stile arguto. Questo stile, sviluppatosi attorno al gran visir Nevşehirli Damad İbrahim Pascià, è considerato il massimo rappresentante della corrente di localizzazione (yerlileşme) nella poesia di divan.", "0521666a"]},
"OLAYLAR_EK14:1720-01-01:0":{"b": ["Levnî illustra il Surnâme-i Vehbî", "8c127866"], "d": ["Il pittore di corte Levnî illustrò con 137 miniature il Surnâme-i Vehbî, che narra la festa di circoncisione dei principi di Ahmed III nel 1720. A differenza degli esempi precedenti, non confinò i festeggiamenti all'Atmeydanı ma li raffigurò in diversi angoli della città, avviando una nuova concezione nell'arte della miniatura ottomana.", "bd655b91"]},
"OLAYLAR_EK14:1727-06-01:0":{"b": ["Affermazione ufficiale del gedik come ordinamento artigianale basato sul monopolio", "cd0f79a7"], "d": ["Secondo il TDV la trasformazione sistematica in cui il diritto di gedik acquistò il significato di \"monopolio, privilegio e una sorta di brevetto\" si osserva a partire dal 1727; questo ordinamento, che riconosceva il diritto di lavorare a un numero determinato di persone nell'artigianato, si affermò, nella maggior parte delle botteghe di proprietà vakıf, con il nome di \"diritto di gedik\".", "18446662"]},
"OLAYLAR_EK14:1730-09-25:0":{"b": ["Distruzione di Sâdâbâd nella rivolta di Patrona Halil", "8a30f9a0"], "d": ["Durante la rivolta di Patrona Halil scoppiata il 25 settembre 1730 furono distrutti centinaia di padiglioni ed edifici a Sâdâbâd; questo complesso, simbolo dell'Età dei Tulipani, non riacquistò mai più l'antico splendore.", "a26b72e6"]},
"OLAYLAR_EK14:1730-10-28:0":{"b": ["Morte di Nedîm durante la rivolta di Patrona Halil", "06bf909e"], "d": ["Nedîm, müderris presso la Medrese di Sekban Ali Pascià quando scoppiò la rivolta di Patrona Halil, morì nei giorni successivi alla rivolta. Il giorno della morte non è noto; ma poiché l'atto di spartizione (kassam hüccet) della sua eredità fu redatto il 15 Rebîülâhir 1143 (28 ottobre 1730), morì prima di questa data. Sulla causa della morte esistono versioni diverse: una parte delle fonti scrive che morì di paura (illet-i vehîme) o di una malattia con tremori causata dall'alcol e dall'oppio, mentre Müstakimzâde scrive che durante la rivolta, per la paura, salì sul tetto di casa e morì cadendo da lì. Con la sua morte lo splendore culturale dell'Età dei Tulipani ebbe di fatto fine.", "49085a6c"]},
"OLAYLAR_EK14:1732-01-01:0":{"b": ["Morte di Levnî", "dd48b56e"], "d": ["Levnî, considerato l'ultimo grande rappresentante dell'arte della miniatura ottomana, morì nel 1732. La maggior parte delle sue opere si trova oggi nel Museo del Palazzo di Topkapı.", "25f589a6"]},
"OLAYLAR_EK14:1749-01-19:0":{"b": ["Posa delle fondamenta della moschea e del complesso di Nuruosmaniye", "397ec798"], "d": ["Le fondamenta del complesso di Nuruosmaniye furono poste da Mahmud I il 19 gennaio 1749. Questo edificio è considerato la prima grande applicazione dello stile barocco europeo nell'architettura ottomana e si discosta nettamente dallo schema classico del complesso.", "c1e0698f"]},
"OLAYLAR_EK14:1755-12-05:0":{"b": ["Inaugurazione della moschea e del complesso di Nuruosmaniye", "15d83731"], "d": ["L'inaugurazione del complesso, avviato da Mahmud I che non ne vide il completamento, avvenne il 5 dicembre 1755 sotto il fratello Osman III. La moschea prese il nome, con riferimento a Osman III che compì l'inaugurazione, dal significato \"Luce di Osman\".", "4722cd6a"]},
"OLAYLAR_EK14:1775-04-29:0":{"b": ["Apertura della Mühendishâne-i Bahrî-i Hümâyun", "a2fab1cd"], "d": ["La Mühendishâne-i Bahrî-i Hümâyun, prima scuola moderna di ingegneria navale ottomana, fu aperta il 29 aprile 1775 sotto Abdülhamid I, durante il gran vizierato di Derviş Mehmed Pascià, secondo i documenti d'archivio francesi.", "cafb2bf9"]},
"OLAYLAR_EK14:1775-06-01:0":{"b": ["Istituzione del sistema esham", "eabd8ece"], "d": ["Di fronte al peso dell'indennità di 7,5 milioni di kuruş imposta dal trattato di Küçük Kaynarca, nel 1775 fu istituito il sistema esham. In questo metodo, concepito per superare i limiti del malikâne, il reddito della mukātaa era suddiviso in quote e, a differenza del malikâne, anche donne, non musulmani e gente comune potevano essere detentori di quote.", "01a12eaa"]},
"OLAYLAR_EK14:1778-01-09:0":{"b": ["Nascita di Hammâmîzâde İsmail Dede Efendi", "c033f039"], "d": ["Hammâmîzâde İsmail Dede Efendi, uno dei compositori più prolifici della musica turca, nacque il 9 gennaio 1778 nel quartiere di Şehzadebaşı a Istanbul. Nel corso della vita compose più di 500 opere, di cui circa 294 sono giunte fino a noi.", "0b7fc673"]},
"OLAYLAR_EK14:1793-07-14:0":{"b": ["Inizio della costruzione della Mühendishâne-i Berrî-i Hümâyun", "4f5d521a"], "d": ["La costruzione della Mühendishâne-i Berrî-i Hümâyun, una delle più importanti istituzioni delle riforme del Nizâm-ı Cedîd di Selim III, iniziò il 14 luglio 1793. L'edificio fu completato e aperto all'istruzione nel settembre 1795; l'istituzione era la seconda scuola di ingegneria militare ottomana, modellata sulle accademie militari europee.", "79c0131c"]},
"OLAYLAR_EK14:1794-06-01:0":{"b": ["Selim III inizia ad abolire il monopolio di alcune corporazioni di artigiani", "008f4a7d"], "d": ["Secondo la voce Esnaf del TDV, nell'ordinamento delle corporazioni ottomano, intrecciato fin dalla fondazione con l'organizzazione ahî, funzionari come \"ahî baba\" e \"şeyh\" guidarono le corporazioni fino all'inizio del XIX secolo; quando nel XVIII secolo le corporazioni, con il monopolio, portarono i prezzi al di sopra del narh creando una pressione economica, Selim III dal 1794 cominciò ad abolire il monopolio delle corporazioni dei generi alimentari di base.", "35d33c12"]},
"OLAYLAR_EK14:1812-01-01:0":{"b": ["Dede Efendi accolto a palazzo come musâhib-i şehriyârî", "0cb99ac3"], "d": ["Dede Efendi, che sotto Selim III aveva attirato l'attenzione del sovrano con una composizione in bûselik, nel 1812 fu accolto da Mahmud II tra i \"musâhib-i şehriyârî\" (compagni di consiglio privato del sultano) e poco dopo salì a capo dei muezzin (müezzinbaşı).", "15b3c49d"]},
"OLAYLAR_EK14:1830-12-01:0":{"b": ["Primo censimento regolare della popolazione ottomana", "4f004c6c"], "d": ["Mahmud II fece eseguire per la prima volta alla fine del 1830 un censimento regolare, allo scopo di accertare la popolazione da arruolare; fu registrata solo la popolazione maschile e in Anatolia-Rumelia furono accertate circa 7,5 milioni di persone. In alcune regioni come Erzurum e Van il censimento poté essere completato solo nel 1836.", "af4a7bcf"]},
"OLAYLAR_EK14:1833-06-01:0":{"b": ["Fondazione della Feshâne-i Âmire", "971ab85a"], "d": ["Per soddisfare il fabbisogno di fez dell'esercito Asâkir-i Mansûre-i Muhammediyye, costituito dopo l'abolizione del Corpo dei Giannizzeri nel 1826, nel 1833 con un capitale di 1,5 milioni di kuruş si iniziò la produzione di fez nel Cündî Meydanı a Kadırga. Gli impianti furono trasferiti nel 1839 nel Palazzo di Hatice Sultan a Eyüp; la Feshâne costituì il fondamento dell'industria tessile ottomana.", "c8481f41"]},
"OLAYLAR_EK14:1839-05-14:0":{"b": ["La scuola di medicina assume il nome di Mekteb-i Tıbbiyye-i Adliyye-i Şâhâne", "187d60f3"], "d": ["La scuola di medicina, trasferita nell'edificio dell'Enderun Ağaları Mektebi a Galatasaray, il 14 maggio 1839, con la visita di Mahmud II, assunse il nome di \"Mekteb-i Tıbbiyye-i Adliyye-i Şâhâne\"; l'istituzione fu così registrata ufficialmente con l'identità di scuola militare-amministrativa.", "6a65292b"]},
"OLAYLAR_EK14:1846-11-29:0":{"b": ["Morte di Dede Efendi a Mina durante il pellegrinaggio", "c3e613a2"], "d": ["Hammâmîzâde İsmail Dede Efendi, colpito dal colera a Mina, dove si era recato per compiere l'obbligo del pellegrinaggio, morì il 29 novembre 1846. Con la morte dell'artista, che tra il 1824 e il 1839 aveva composto sette distinti âyin mevlevi, si chiuse un'epoca della musica classica ottomana.", "fea95526"]},
"OLAYLAR_EK14:1850-06-01:0":{"b": ["Adozione del Codice di Commercio del 1850", "8ac085fd"], "d": ["Nel quadro delle riforme giuridiche del periodo delle Tanzimat furono ricavate nuove leggi dagli Stati occidentali per traduzione e adattamento: il codice penale entrò in vigore nel 1840, il codice di commercio nel 1850, il codice fondiario nel 1857. Il Ticaret Kanunnâmesi fu la prima codificazione moderna del diritto commerciale ottomano.", "2f7aeb1b"]},
"OLAYLAR_EK14:1859-06-01:0":{"b": ["Inizio della grande ondata migratoria di Tatari di Crimea e popoli caucasici verso i territori ottomani", "8832c06d"], "d": ["Dopo che nel 1859 lo sceicco Shamil cadde prigioniero dei Russi, insieme ai Tatari di Crimea numerosi immigrati circassi e nogai dal Caucaso cominciarono a migrare nei territori ottomani. Questa ondata migratoria continuò con intensità diverse fino al periodo successivo alla guerra ottomano-russa del 1877-78.", "580ce507"]},
"OLAYLAR_EK14:1860-01-16:0":{"b": ["Istituzione della Commissione per gli Immigrati (Muhâcirîn Komisyonu)", "9717e77e"], "d": ["Per gestire l'ondata crescente di migrazione dal Caucaso, il governo ottomano istituì il 16 gennaio 1860 la Commissione per gli Immigrati. La commissione coordinò le opere di insediamento in Anatolia, nei Balcani e in Siria e rimase attiva fino al 1875.", "404d989d"]},
"OLAYLAR_EK14:1863-06-01:0":{"b": ["Ristrutturazione della Bank-ı Osmanî come Bank-ı Osmanî-i Şâhâne (Banca Ottomana)", "c3530456"], "d": ["Nel 1856, dopo la guerra di Crimea, era stata fondata la Bank-ı Osmanî, con sede a Londra e capitale inglese, per gestire i pagamenti del debito estero. Nel 1863 a un gruppo congiunto franco-inglese fu concesso il permesso di fondare una nuova banca con il nome di Bank-ı Osmanî-i Şâhâne (Banca Ottomana); l'istituzione ottenne poi anche il diritto di emettere banconote.", "72227299"]},
"OLAYLAR_EK14:1864-03-30:0":{"b": ["Fondazione della Cem'iyyet-i Tedrîsiyye-i İslâmiyye", "77ad553a"], "d": ["Il 30 marzo 1864 fu fondata la Cem'iyyet-i Tedrîsiyye-i İslâmiyye allo scopo di assumersi l'istruzione degli apprendisti musulmani poveri; questa iniziativa associativa civile è un esempio pionieristico della trasformazione della tradizione delle istituzioni di beneficenza in un progetto scolastico moderno. L'associazione avrebbe aperto nove anni dopo il Darüşşafaka.", "2ea443d2"]},
"OLAYLAR_EK14:1864-06-01:0":{"b": ["Regolamentazione del sistema dei muhtar e dei consigli degli anziani con il Regolamento dei Vilayet del 1864", "1a2e8cf2"], "d": ["Con il Regolamento dei Vilayet del 1864 l'amministrazione dei villaggi fu riorganizzata; nei villaggi in cui vivevano insieme musulmani e non musulmani fu accettato che ogni comunità eleggesse il proprio muhtar e il proprio consiglio degli anziani. Il consiglio degli anziani ottenne così per la prima volta un posto ufficiale nell'amministrazione di villaggio/quartiere.", "eee4df7d"]},
"OLAYLAR_EK14:1864-07-01:0":{"b": ["Culmine del grande esilio dei Circassi", "b2ab1874"], "d": ["Con l'occupazione russa del Caucaso tra il 1858 e il 1878, e con la massima intensità nel 1861-1864, da 1,2 a 1,5 milioni di Circassi furono costretti a migrare nei territori ottomani. Secondo il TDV, numerosi studiosi definiscono questo evento \"il primo movimento di pulizia etnica della storia moderna\".", "d1bb6d70"]},
"OLAYLAR_EK14:1869-09-01:0":{"b": ["Pubblicazione del Regolamento sull'Istruzione Pubblica (Maârif-i Umûmiyye Nizamnâmesi) del 1869", "787f6022"], "d": ["Il Maârif-i Umûmiyye Nizamnâmesi, pubblicato il 1° settembre 1869, fu il primo testo organico a regolare l'istruzione generale in provincia e al centro. Con il regolamento fu istituito il Meclis-i Kebîr-i Maârif; con questa disposizione iniziò la ristrutturazione delle scuole elementari (sıbyan mektepleri), che cessarono di essere una fase di sola istruzione religiosa per orientarsi all'insegnamento della lettura e della scrittura.", "51087b3c"]},
"OLAYLAR_EK14:1873-06-28:0":{"b": ["Inizio dell'attività didattica della scuola Darüşşafaka", "525c457c"], "d": ["Il Darüşşafaka, fondato dalla Cem'iyyet-i Tedrîsiyye-i İslâmiyye, iniziò di fatto l'insegnamento il 28 giugno 1873 per istruire gratuitamente, in regime di convitto, i bambini musulmani orfani e poveri; l'età massima di ammissione fu fissata a dieci anni.", "c4f863b5"]},
"OLAYLAR_EK14:1894-07-10:0":{"b": ["Terremoto di Istanbul del 1894", "7ae7f648"], "d": ["Il terremoto avvenuto il 10 luglio 1894 al largo del Golfo di İzmit colpì duramente Istanbul; furono danneggiati molti edifici storici e moschee, comprese le mura di Istanbul. La voce zelzele del TDV annovera questo terremoto, insieme a quelli del 1509, del 1719 e del 1766, tra i terremoti che causarono grandi perdite di vite e di beni nella regione del Marmara.", "61236a0f"]},
"OLAYLAR_EK14:1896-02-02:0":{"b": ["Apertura del Dârülaceze", "a30baf31"], "d": ["Il Dârülaceze, preparato in seguito agli ordini impartiti da Abdülhamid II dal 1890, fu aperto il 2 febbraio 1896 dal gran visir Halil Rifat Pascià. L'istituzione, che ospitava bambini senza famiglia, anziani e bisognosi, con il suo ospedale da 200 letti, i laboratori e luoghi di culto distinti come moschea, chiesa e sinagoga, era il più grande complesso di assistenza sociale della sua epoca.", "9cf12efa"]},
"OLAYLAR_EK14:1900-08-31:0":{"b": ["Ricostituzione del Dârülfünûn-ı Şâhâne come istituzione permanente", "7d6d8fc4"], "d": ["Il Darülfünun, dopo due precedenti tentativi falliti (1863 e 1870), fu rifondato il 31 agosto 1900 come istituzione permanente con il nome di Dârülfünûn-ı Şâhâne; il TDV definisce questa data il fondamento diretto dell'attuale sistema universitario turco.", "7d7fd7ca"]},
"OLAYLAR_EK15:1337-09-09:0":{"b": ["I Sarbadar presero Sabzevar — il primo Stato dopo gli Ilkhanidi nel Khorasan", "af997fec"], "d": ["Quando con la morte di Abu Said (30 novembre 1335) crollò l'autorità centrale ilkhanide, la reazione accumulata nel Khorasan contro i funzionari delle imposte esplose a Bâştîn: Abdürrezzâk si ribellò il 13 marzo 1337 e il 9 settembre 1337 (12 Safer 738) prese Sabzevar. Il nome \\\"Sarbadar\\\" — \\\"testa sulla forca\\\" — è una loro stessa espressione, che dice come fossero pronti a essere impiccati se sconfitti.", "c0abed9c"]},
"OLAYLAR_EK15:1359-01-01:0":{"b": ["I Sayyid di Mar'ash presero Amol — dominio dei sayyid nel Mazandaran", "c0e03266"], "d": ["Il sayyid Kıvâmüddin Mar'aşî, seguendo la via aperta dai Sarbadar nel Khorasan, nel 760 (1359) prese Amol e fondò uno Stato di sayyid sulla costa meridionale del Caspio. La dinastia si estese a Sari, Barfurush e dintorni; fu scossa dalle campagne di Tamerlano e fu dissolta sotto il safavide Shah Abbas I.", "d93ea1fd"]},
"OLAYLAR_EK15:1371-01-01:0":{"b": ["Fondazione della dinastia Karkiya a Gilan — gli ultimi sovrani indipendenti della costa del Caspio", "6e5f9db7"], "d": ["Ali Kiya, tornato a Gilan con la sua famiglia, fondò nel 773 (1371-72) il dominio dei Karkiya con centro a Lahijan; la dinastia tenne per più di due secoli la costa sud-occidentale del Caspio e durò fino all'annessione della regione da parte del safavide Shah Abbas I nel 1592.", "670fc7fd"]},
"OLAYLAR_EK15:1400-01-01:0":{"b": ["Passaggio del dominio dei Daju nel Darfur ai Tunjur", "6eb22a2a"], "d": ["Secondo la voce Dârfûr del TDV İslâm Ansiklopedisi, i primi a insediarsi nella regione e a fondare il primo Stato furono la tribù dei Daju; i Daju, che la dominarono durante il XIII e il XIV secolo, persero il dominio commerciale a favore dei Tunjur e nel XV secolo la situazione, soprattutto nella regione centrale, si capovolse completamente a favore dei Tunjur.", "2709880c"]},
"OLAYLAR_EK15:1564-01-01:0":{"b": ["La Spagna riprende lo scoglio di Bâdis (Peñón de Vélez)", "0dc52728"], "d": ["La voce Sa'dîler del TDV annota che la presa di Bâdis da parte degli Spagnoli fu un duro colpo per la marineria del Maghreb (1564). Questa posizione rocciosa sulla costa del Marocco settentrionale serviva da appoggio alla pirateria nel Mediterraneo occidentale e alla contesa ottomano-spagnola.", "110ee39e"]},
"OLAYLAR_EK15:1610-01-01:0":{"b": ["Cessione di al-Arâiş (Larache) alla Spagna", "7b8f6e27"], "d": ["Negli anni della guerra civile in cui la dinastia sa'diana si disgregava, il porto atlantico di al-Arâiş fu lasciato alla Spagna. La voce Sa'dîler del TDV annota che in questo periodo il paese fu diviso in due emirati, Marrakech (sud) e Fez (nord), e che le parti in lotta per il trono cercarono aiuto dall'esterno. Il porto sarebbe rimasto per quasi ottant'anni in mano spagnola e sarebbe stato ripreso da Mulay Ismail nel 1689.", "597cc620"]},
"OLAYLAR_EK15:1614-01-01:0":{"b": ["Passaggio di Mamûra (Mehdiye) in mano spagnola", "c8fd494e"], "d": ["Il porto di Mamûra (Ma'mûre / Mehdiye), alla foce del fiume Sebou, fu preso dagli Spagnoli nel 1614 e fortificato con il nome di San Miguel de Ultramar. La voce Mevlây İsmâil del TDV annota che il porto fu ripreso agli Spagnoli con un improvviso assalto nell'anno 1092 (1681) — cioè il dominio spagnolo durò sessantasette anni.", "3f87063c"]},
"OLAYLAR_EK15:1659-01-01:0":{"b": ["Fine della dinastia sa'diana — inizio del periodo alawide (filalide) in Marocco", "b1afa579"], "d": ["Il TDV İslâm Ansiklopedisi definisce la voce Sa’dîler \\\"dinastia islamica che regnò in Marocco (1511-1659)\\\". La dinastia, che nel 1549 pose fine al dominio wattaside riunificando tutto il Marocco, che nel 1578 annientò l'esercito portoghese a Wadi al-Makhazin e che in nessun periodo fu vassalla degli Ottomani, si concluse nel 1659 dopo lunghe lotte per il trono. Al suo posto subentrarono gli sceriffi alawidi (filalidi) venuti da Tafilalt; Mulay Rashid entrò a Fez nel 1666 consolidando la nuova dinastia e suo fratello Mulay Ismail ripulì le posizioni europee sulla costa atlantica.", "1e7caacc"]},
"OLAYLAR_EK15:1673-01-01:0":{"b": ["Occupazione spagnola delle isole di al-Husayma (Alhucemas)", "954ca998"], "d": ["Le isole di al-Husayma, sulla costa mediterranea, furono occupate dalla flotta spagnola nel 1673. Insieme a Bâdis e Ceuta, sono tra le posizioni che la Spagna tiene sulla costa del Marocco settentrionale e che sono rimaste in suo possesso fino a oggi. Nello stesso anno Mulay Rashid, fratello maggiore di Mulay Ismail, era entrato a Marrakech e aveva ricevuto il giuramento di fedeltà della popolazione, e il dominio filalide si era consolidato nel sud — questa perdita sulla costa mostra che l'unificazione interna non aveva ancora un riscontro sul fronte esterno.", "b67d415f"]},
"OLAYLAR_EK15:1689-01-01:0":{"b": ["Mulay Ismail riprende al-Arâiş agli Spagnoli", "a54bc6ee"], "d": ["La voce Mevlây İsmâil del TDV è esplicita: \"Nel 1100 (1689), ripresa Arâîş agli Spagnoli, presero 200 cannoni e due anni dopo ripresero Asîle.\" È uno degli anelli della catena di pulizia della costa del sultano filalide — Tangeri fu ripresa agli Inglesi nel 1678, Mamûra nel 1681, al-Arâiş nel 1689, Asîle nel 1691. Il porto, abbandonato ottant'anni prima nella guerra civile sa'diana, tornò così al Marocco.", "cd2b390d"]},
"OLAYLAR_EK15:1695-01-01:0":{"b": ["Fondazione del Sultanato del Darfur — dinastia Keira e Sulayman Solong", "0fc1c112"], "d": ["Secondo il TDV la fondazione del Sultanato del Darfur cade dopo il disordine seguito all'invasione della regione da parte di Bumû al-Kasîr alla fine del XVII secolo. I Fur, sotto la guida della dinastia Kîrâ (Keira), con a capo Sulayman Solong, tolsero il dominio ai Daju e ai Tunjur e costruirono un'amministrazione solida. Sulayman Solong regnò tra il 1695 e il 1715. I sultani del Darfur nei secoli successivi corrisposero con la Sublime Porta; Abdülmecid e Abdülaziz confermarono il loro regno.", "58155fc4"]},
"OLAYLAR_EK15:1792-09-22:0":{"b": ["Proclamazione della Prima Repubblica in Francia — fine della monarchia", "d53d49b0"], "d": ["Nella prima seduta della Convenzione Nazionale la monarchia fu abolita e il giorno seguente fu proclamata la Prima Repubblica; l'anno primo del nuovo calendario fu fatto cominciare da questo giorno. Per gli Ottomani l'interlocutore non cambiò, ma cambiò la natura dell'interlocutore: negli anni del Nizâm-ı Cedîd di Selim III la Francia non era più una dinastia ma un regime, ed era l'esercito di quel regime che nel 1798 sarebbe sbarcato in Egitto.", "a16f5b39"]},
"OLAYLAR_EK15:1857-07-11:0":{"b": ["Caduta della Grande Cabilia — cattura di Lalla Fatma N'Soumer", "0f61ff08"], "d": ["La voce Cezayir del TDV annota che con l'occupazione della regione montuosa della Cabilia (Bilâdü'l-kabâil) al termine delle campagne del 1853, 1854 e 1857 l'occupazione francese dell'Algeria si può dire in gran parte completata. La campagna del 1857 spezzò la linea di Tizi Ouzou e Akbou; Lalla Fatma N'Soumer, simbolo della resistenza, fu catturata. Dopo la resa dell'emiro Abd al-Qadir nel 1847, si spense così l'ultimo grande focolaio di resistenza rimasto.", "6d14160e"]},
"OLAYLAR_EK15:1899-12-29:0":{"b": ["Occupazione francese di Aïn Salah (Tidikelt)", "1e28d1d0"], "d": ["Aïn Salah, centro del gruppo di oasi del Tidikelt nel mezzo del Sahara, fu presa dalle forze francesi il 29 dicembre 1899. È il primo grande passo, spostatosi nel deserto, dell'espansione francese che scendeva a sud dalla costa algerina; entro due anni Touat e Gourara avrebbero seguito la stessa via.", "99e7ecb6"]},
"OLAYLAR_EK15:1901-02-21:0":{"b": ["Annessione alla Francia delle oasi di Touat · Gourara · Tidikelt", "d412838b"], "d": ["La fascia di oasi di Touat, Gourara e Tidikelt, nel sud-ovest dell'Algeria, fu ufficialmente annessa alla Francia il 21 febbraio 1901. Questo nodo di rotte carovaniere, su cui il sultano del Marocco avanzava pretese nominali — compresi Adrar, Timimoun, Reggane e Beni Abbès — fu così unito all'Algeria; è l'inizio della controversia di confine tra il Marocco e l'Algeria francese.", "c50f9569"]},
"OLAYLAR_EK15:1903-11-11:0":{"b": ["Istituzione del posto francese di Béchar (Colomb-Béchar)", "4d44d252"], "d": ["L'oasi di Béchar, al confine con il Marocco, fu presa dalle forze francesi l'11 novembre 1903 e trasformata in avamposto con il nome di Colomb-Béchar. Questo passo, che viene due anni dopo l'annessione della fascia del Touat, è uno degli ultimi anelli dell'avanzata francese dall'Algeria verso il Marocco; apre la via al protettorato sul Marocco del 1912.", "bd1a7ae2"]},
"OLAYLAR_EK16:1283-01-01:0":{"b": ["Fondazione del Principato di Mosca — Daniil I", "49549309"], "d": ["Daniil, il figlio minore di Aleksandr Nevskij, cominciò a governare Mosca come principato indipendente. A quell'epoca Mosca era un centro piccolo e insignificante delle terre di Vladimir-Suzdal'; la storiografia russa considera questa data il punto di partenza della successiva ascesa.", "10cf92d1"]},
"OLAYLAR_EK16:1297-01-01:0":{"b": ["Fondazione dei beylik di Karesi e dei Hamidoğulları", "3905da93"], "d": ["Secondo la voce Karesioğulları del TDV, Karesi Bey, dichiarata la propria indipendenza nell'organizzazione di frontiera selgiuchide dissoltasi con la morte del padre Kalem Bey, dal 696 (1296-97) fece di Balıkesir il proprio centro e in breve tempo tolse a Bisanzio l'intera Misia, compresi Erdek, Biga, Edremit e Bergama. Nello stesso anno (1297) Hamid Bey fondò il beylik dei Hamidoğulları facendo di Uluborlu la sede del governo; Isparta, Burdur, Eğirdir e Yalvaç, dalla regione di frontiera selgiuchide in dissoluzione, furono incluse nei primi confini del beylik. Entrambi i beylik sono il prodotto dello stesso crollo nell'Anatolia occidentale — la dissoluzione dell'autorità centrale selgiuchide.", "7d297343"]},
"OLAYLAR_EK16:1301-01-01:0":{"b": ["Il principe di Mosca Daniil annette a Mosca Kolomna e Serpuchov", "6d82dccd"], "d": ["Daniil prese al principato di Rjazan' Kolomna (il principe di Rjazan', fatto prigioniero, cedette la fortezza per essere liberato) e Serpuchov; Mosca raggiunse il fiume Oka e fu la prima espansione territoriale del Principato di Mosca.", "f6b7a96c"]},
"OLAYLAR_EK16:1304-01-01:0":{"b": ["Mozajsk tolta al Principato di Smolensk e annessa a Mosca", "462055a0"], "d": ["Il Principato di Mosca prese a Smolensk Mozajsk, nel bacino superiore del fiume Moscova, avvicinando il proprio confine occidentale alla Lituania.", "3002aa5d"]},
"OLAYLAR_EK16:1307-01-01:0":{"b": ["Il Principato di Polack passa al Granducato di Lituania", "04a26a6f"], "d": ["Polack, Vitebsk e i dintorni rimasero fino al 1307 all'interno della dinastia principesca russa; l'espansione della Lituania verso est prima di Gediminas si fa evidente con questo passaggio (data della scheda dell'atlante 1307; il passaggio effettivo di Vitebsk ≈1320 è discusso).", "52bf8042"]},
"OLAYLAR_EK16:1308-01-01:0":{"b": ["Fondazione del beylik degli Aydınoğlu — presa di Smirne, Ayasuluk, Tire", "69a021ae"], "d": ["Secondo la voce Aydınoğulları del TDV, Mübârizüddin Gazi Mehmed Bey, togliendo questa regione a Sasa Bey, bey di frontiera dei Germiyanoğlu, nel 1308 prese il dominio nell'Aydın-ili; conquistò la parte musulmana di Smirne insieme ad Ayasuluk (Selçuk), Tire e Bodemya. Fece di Ayasuluk una base navale e spartì i territori conquistati tra i suoi cinque figli — il beylik nei decenni seguenti, in particolare sotto il figlio Umur Bey, sarebbe diventato la potenza decisiva della marineria egea.", "9c871e7d"]},
"OLAYLAR_EK16:1308-01-01:1":{"b": ["Fine di fatto dello Stato selgiuchide d'Anatolia — amministrazione diretta ilkhanide", "00f85ecb"], "d": ["Secondo la voce Mesud II del TDV, Gıyâseddin Mesud II, morto a Kayseri nel 708 (1308) dopo una lunga malattia, è, secondo l'opinione comunemente accettata, l'ultimo sovrano dello Stato selgiuchide d'Anatolia — i candidati posti sul trono dopo la sua morte non ottennero il riconoscimento né delle cariche interne né degli Ilkhanidi. La regione, già durante il sultanato di Mesud, era di fatto amministrata da funzionari ilkhanidi; con la sua morte questa amministrazione diretta perse anche il suo velo formale in centri come Konya, Niğde e Aksaray.", "80f4e444"]},
"OLAYLAR_EK16:1309-01-01:0":{"b": ["Espansione del beylik dei Candaroğlu a Kastamonu-Çankırı-Bartın-Safranbolu", "64e39ad0"], "d": ["Secondo la voce Candaroğulları del TDV, il beylik fu fondato all'inizio del XIV secolo nell'area di Kastamonu-Sinope da Şemseddin Yaman Candar, al quale il sovrano ilkhanide Gaykhatu aveva dato in iqta' Eflani e i dintorni; per la scarsità delle fonti la data esatta della fondazione non è nota. Süleyman Bey, successore di Candar, è ricordato come un sovrano che subentrò al beylik dei Çobanoğlu — cioè l'area di Kastamonu e Çankırı passò ai Candaroğlu dai Çobanoğlu, la linea Bartın-Safranbolu-Eflani dall'amministrazione diretta ilkhanide.", "72e44d66"]},
"OLAYLAR_EK16:1310-08-15:0":{"b": ["Conquista di Rodi e del Dodecaneso da parte dei cavalieri di San Giovanni (Ospitalieri)", "67885b4b"], "d": ["La voce Rodos del TDV annota che l'isola passò nel 1309 ai cavalieri di San Giovanni (Hospitalier/İsbitâriyye); la storia ospitaliera standard (cfr. J. Riley-Smith, The Knights Hospitaller) precisa che l'assedio iniziò nell'estate del 1306 e che la città di Rodi, che resistette a lungo con rinforzi bizantini, cadde solo il 15 agosto 1310 ad opera delle forze del Gran Maestro Foulques de Villaret. L'isola da questa data sarebbe stata il centro dei cavalieri fino alla conquista ottomana del 1522; anche il Dodecaneso circostante passò nello stesso processo da Bisanzio al dominio ospitaliero.", "c1422e2c"]},
"OLAYLAR_EK16:1313-01-01:0":{"b": ["I cavalieri di Livonia riprendono alla Lituania la fortezza di Dünaburg", "92119516"], "d": ["I Lituani intorno al 1281 avevano preso Jersika e l'avevano scambiata con la fortezza di Dünaburg dell'Ordine. La fortezza nel 1313 passò di nuovo ai cavalieri di Livonia e rimase come sede di commenda dell'Ordine.", "0cdd86e0"]},
"OLAYLAR_EK16:1315-01-01:0":{"b": ["Presa di Coo (Kos) da parte dei cavalieri di San Giovanni", "445666f7"], "d": ["Secondo la voce İstanköy del TDV, i cavalieri di San Giovanni, dopo essersi stabiliti a Rodi, presero anche Coo (1315) e vi costruirono nuove fortezze. L'isola entrò così nel dominio dei cavalieri, che durò fino al 1523; sotto quale amministrazione si trovasse Coo dopo la caduta della città di Rodi nel 1310 non è precisato nel TDV.", "145d1bad"]},
"OLAYLAR_EK16:1325-01-01:0":{"b": ["La sede metropolitana trasferita a Mosca", "d20099f8"], "d": ["Il metropolita Petr, capo della Chiesa ortodossa russa, trasferì a Mosca il proprio centro religioso. Fu l'inizio dell'ascesa di Mosca come centro non solo politico ma anche religioso e rafforzò la legittimità del principato.", "4e31c42f"]},
"OLAYLAR_EK16:1330-01-01:0":{"b": ["L'Ordine di Livonia diventa signore della città di Riga", "21453047"], "d": ["L'arcivescovato di Riga e la città, che combattevano contro l'Ordine con il sostegno dei granduchi lituani Vytenis e Gediminas, furono sconfitti nel 1330; l'Ordine di Livonia divenne signore della città. Con il trattato di Salaspils del 1452 Riga passò sotto la signoria congiunta dell'Ordine e dell'arcivescovo.", "28788282"]},
"OLAYLAR_EK16:1335-01-01:0":{"b": ["Fondazione del beylik degli Eretna — Anatolia centrale dopo gli Ilkhanidi", "a67bacd9"], "d": ["Secondo la voce Eretnaoğulları del TDV, Alâeddin Eretna, funzionario ilkhanide di origine uigura, dopo la morte nel 1335 del sovrano ilkhanide Abu Said Bahadur Khan trasformò il governatorato ilkhanide in Anatolia in un'amministrazione di fatto indipendente; apparendo dapprima come vice del sultano mamelucco, nel 1340 tolse il nome mamelucco dalla khutba e intorno al 1341 proclamò la piena indipendenza. Il beylik, con centro dapprima a Sivas e poi a Kayseri, fino alla sua morte (1352) costituì un ampio dominio nell'Anatolia centrale comprendente Amasya, Tokat, Çorum, Niğde, Aksaray ed Erzincan, e fu posto fine nel 1381 da Kadı Burhâneddin.", "04978a80"]},
"OLAYLAR_EK16:1335-05-01:0":{"b": ["Gli Asburgo prendono la Carniola e la Carinzia (Lubiana)", "039918d3"], "d": ["Con la morte senza eredi, il 2 aprile 1335 nel Castello del Tirolo, di Enrico VI, duca di Carinzia e conte del Tirolo, in base a un accordo segreto concluso il 23 novembre 1330 con Ludovico il Bavaro, i fratelli asburgici Alberto II e Ottone IV ricevettero con investitura imperiale il Ducato di Carinzia e la Carniola, ad esso legata (la regione in cui si trova anche l'odierna Lubiana); il Tirolo rimase invece separato attraverso la figlia di Enrico. Fu uno dei primi grandi passi dell'espansione asburgica nella regione alpina e la Carniola sarebbe rimasta (con interruzioni) in mano asburgica/austriaca fino al 1918.", "4dbed85a"]},
"OLAYLAR_EK16:1340-01-01:0":{"b": ["Fondazione dello Stato dei Jalayiridi — Azerbaigian dopo gli Ilkhanidi", "a13ada90"], "d": ["Secondo la voce Celâyirliler del TDV, Hasan-ı Büzürg, nipote dell'emiro ilkhanide Noyan, approfittando delle lotte per il trono scoppiate con la morte del sovrano ilkhanide Abu Said Bahadur Khan, nel 1340 fondò uno Stato indipendente con centro a Tabriz. I Jalayiridi divennero così la prima grande dinastia a riempire il vuoto post-ilkhanide in Azerbaigian e dintorni; sotto il successore Uways (1356-1374) i loro territori si sarebbero estesi fino a Mosul e Diyarbekir.", "224cbb81"]},
"OLAYLAR_EK16:1341-01-01:0":{"b": ["Fondato il Granducato di Nižnij Novgorod-Suzdal' — il khan concede lo yarlyk a Konstantin Vasil'evič", "c69f5198"], "d": ["Il khan dell'Orda d'Oro Özbek (nella scheda Özbek/Canibek) concesse al principe di Suzdal' Konstantin Vasil'evič il principato di Nižnij Novgorod-Gorodec; il principato divenne rivale di Mosca e nel 1392 fu annesso a Mosca da Vasilij I.", "4b281b04"]},
"OLAYLAR_EK16:1346-01-01:0":{"b": ["La Danimarca vende l'Estonia settentrionale (Reval e Narva) all'Ordine di Livonia", "6861ba55"], "d": ["Il regno di Danimarca vendette all'Ordine di Livonia i propri territori dell'Estonia settentrionale insieme a Reval e Narva. La regione rimase in mano all'Ordine fino alla guerra di Livonia.", "0723514c"]},
"OLAYLAR_EK16:1348-01-01:0":{"b": ["Trattato di Bolotovo — Novgorod riconobbe l'indipendenza di Pskov", "08eca44d"], "d": ["Novgorod riconobbe Pskov come 'fratello minore'; Pskov visse con la propria veče e il proprio posadnik come repubblica cittadina indipendente fino all'annessione a Mosca nel 1510.", "12f9ce2f"]},
"OLAYLAR_EK16:1392-01-01:0":{"b": ["Vasilij I annette a Mosca il Principato di Nižnij Novgorod-Suzdal'", "5ecf441b"], "d": ["Con lo yarlyk ottenuto dal khan Toqtamish, Vasilij I legò a Mosca Nižnij Novgorod, Gorodec e Suzdal'; iniziò l'apertura di Mosca verso il bacino del Volga e dell'Oka.", "ac83ac55"]},
"OLAYLAR_EK16:1404-01-01:0":{"b": ["Vytautas prende Smolensk — il Principato di Smolensk annesso alla Lituania", "1a68300c"], "d": ["Vytautas conquistò Smolensk; la città rimase nel Granducato di Lituania fino al passaggio a Mosca nel 1514.", "3ed5ce14"]},
"OLAYLAR_EK16:1411-01-01:0":{"b": ["Passaggio di Baghdad ai Qaraquyunlu — sconfitta del sultano jalayiride Ahmad", "a42ebe92"], "d": ["Secondo la voce Karakoyunlular del TDV, Kara Yusuf il 28 Rebîülâhir 813 (30 agosto 1410) inflisse una pesante sconfitta presso Tabriz al sultano jalayiride Ahmad; dopo la morte di Ahmad, nell'814 (1411) proclamò sultano a Tabriz il figlio Pîr Budak e nello stesso anno il figlio maggiore Shah Mehmed conquistò Baghdad. Così Baghdad, capitale jalayiride per circa un secolo, entrò sotto il dominio qaraquyunlu insieme alla fascia circostante Bassora-Mosul-Kirkuk.", "30b86113"]},
"OLAYLAR_EK16:1422-01-01:0":{"b": ["Erzincan e Kemah passano agli Aqquyunlu — Karayülük Osman Bey", "122460d4"], "d": ["Dopo la morte di Kara Yusuf, per volontà della popolazione di Erzincan, Yâr Ali, nipote di Mutahharten, era diventato governatore della città. Ai suoi tempi il bey aqquyunlu Karayülük Osman prese Erzincan e la aggiunse ai territori aqquyunlu. Da allora Erzincan divenne un luogo che passava di mano ora tra Aqquyunlu e Qaraquyunlu, ora tra i principi aqquyunlu.", "83183da6"]},
"OLAYLAR_EK16:1438-01-01:0":{"b": ["Fondazione del Khanato di Kazan — Ulugh Muhammad Khan si separa dall'Orda d'Oro", "335a7408"], "d": ["Secondo la voce Kazan Hanlığı del TDV, Ulugh Muhammad Khan, che aveva perso il trono a Saray, capitale dell'Orda d'Oro, con la famiglia e circa 3000 soldati si ritirò dapprima a Belev, nel 1437-1438 lottò contro il knez russo Vasilij II e poi si stabilì nella città di Kazan; con il sostegno della popolazione locale vi gettò le basi di un nuovo khanato. Il TDV precisa che il processo di fondazione si completò tra il 1437 e il 1445 e che dal 1445 il khanato acquisì piena indipendenza — la mappa assume come inizio di questo processo il 1438, anno in cui Ulugh Muhammad si stabilì a Kazan.", "d65b36b3"]},
"OLAYLAR_EK16:1441-01-01:0":{"b": ["Fondazione del Khanato di Crimea — Hacı Giray si rende indipendente dall'Orda d'Oro", "5728223e"], "d": ["Secondo la voce Kırım del TDV, il Khanato di Crimea nacque come prodotto della frammentazione dell'Orda d'Oro per le lotte di trono nella seconda metà del XIV secolo; la più antica moneta coniata da Hacı Giray, vero fondatore del khanato, porta la data 845 (1441-42), considerata la data ufficiale di fondazione del khanato. Nello stesso anno Hacı Giray consolidò la propria posizione in Crimea stabilendo rapporti di amicizia con Mosca, e le famiglie di bey locali, a cominciare dalla tribù degli Şirin, si schierarono con lui.", "dbd052d0"]},
"OLAYLAR_EK16:1450-01-01:0":{"b": ["Jahan Shah prese Erzincan — dominio dei Qaraquyunlu", "0c928cc4"], "d": ["Il sovrano qaraquyunlu Jahan Shah nell'854 (1450) inviò un esercito a Erzincan e tolse la città agli Aqquyunlu. Questa perdita portò alla rottura tra il bey aqquyunlu Jahangir Mirza e il fratello Hasan Bey (Uzun Hasan).", "203c5c2e"]},
"OLAYLAR_EK16:1452-01-01:0":{"b": ["Il qaraquyunlu Jahan Shah si impadronisce dell'Iran timuride (Rayy, Isfahan, Fars, Kirman)", "c6fbb3f5"], "d": ["Secondo la voce Karakoyunlular del TDV, il sovrano qaraquyunlu Jahan Shah, approfittando delle lotte per il trono tra i principi timuridi, negli anni 856-857 (1452-1453) pose sotto la propria amministrazione le province di Rayy, Isfahan, Fars e Kirman; è il culmine del processo di espansione iniziato dopo la morte di Shahrukh Mirza nel 1447 e aperto con l'annessione di Sultaniyya-Qazvin. I territori dei Timuridi nell'Iran centro-meridionale passarono così ai Qaraquyunlu; il dominio di Jahan Shah nel 1466 avrebbe raggiunto un'estensione comprendente Azerbaigian, Arran, Iraq persiano, Iraq arabo, Fars, Kirman e Anatolia orientale.", "3f6a6c37"]},
"OLAYLAR_EK16:1452-10-23:0":{"b": ["Riconquista inglese di Bordeaux — l'ultima campagna di John Talbot in Guascogna", "01b2b7be"], "d": ["Bordeaux, perduta a favore dei Francesi nel 1451, nella notte tra il 22 e il 23 ottobre 1452, con la rivolta della popolazione contro la guarnigione francese e l'apertura delle porte, si arrese all'esercito inglese guidato dall'anziano comandante John Talbot; fu l'ultima e breve vittoria dell'Inghilterra in Guascogna nella Guerra dei Cent'anni. Bordeaux sarebbe tornata definitivamente alla Francia un anno dopo, in seguito alla battaglia di Castillon.", "f6945d27"]},
"OLAYLAR_EK16:1453-10-19:0":{"b": ["Ritorno definitivo di Bordeaux alla Francia — fine di fatto della Guerra dei Cent'anni", "b0a86f6c"], "d": ["Il 17 luglio 1453, con la morte di John Talbot nella battaglia di Castillon e la distruzione del suo esercito, la resistenza inglese in Guascogna crollò; Bordeaux, assediata, il 19 ottobre 1453 si arrese alle forze francesi. Questa resa è considerata il momento in cui la Guerra dei Cent'anni, durata 116 anni, finì di fatto (non fu mai firmato un trattato di pace ufficiale) e ridusse il dominio inglese sul continente europeo a Calais.", "1c632d46"]},
"OLAYLAR_EK16:1457-01-01:0":{"b": ["Uzun Hasan riprese Erzincan — di nuovo aqquyunlu", "550d010a"], "d": ["Uzun Hasan, sconfitti i Qaraquyunlu, riportò Erzincan sotto il dominio aqquyunlu. La città rimase entro i confini aqquyunlu anche dopo la battaglia di Otlukbeli del 1473.", "d778fa85"]},
"OLAYLAR_EK16:1466-10-19:0":{"b": ["Secondo trattato di Thorn — Danzica (Gdańsk) e la Prussia Occidentale legate alla Polonia", "e2152dae"], "d": ["Il Secondo trattato di Thorn (Toruń), che pose fine alla Guerra dei Tredici anni iniziata con la rivolta della Confederazione prussiana contro il dominio dei Cavalieri Teutonici (Teutonic Order) nel 1454, fu firmato il 19 ottobre 1466; i Cavalieri lasciarono al Regno di Polonia la Pomerania orientale, con Danzica (Gdansk), la foce della Vistola, con Elbing (Elbląg), e la regione di Kulm — questi territori presero il nome di 'Prussia Reale'. La Prussia Orientale sarebbe invece rimasta ai Cavalieri fino al 1525.", "831685a9"]},
"OLAYLAR_EK16:1474-01-01:0":{"b": ["Ivan III acquista la metà rimasta del Principato di Rostov", "5203244f"], "d": ["La metà in mano ai principi di Rostov fu ceduta a Mosca; insieme all'altra metà passata a Mosca nel 1332, la terra di Rostov fu interamente legata a Mosca.", "ab0eeae6"]},
"OLAYLAR_EK16:1485-09-12:0":{"b": ["Il Granducato di Tver' annesso a Mosca — Ivan III prende la città", "fa3f924e"], "d": ["Sotto l'assedio dell'esercito moscovita l'ultimo granduca di Tver', Michail Borisovič, fuggì in Lituania e Tver' si arrese a Ivan III; il più potente rivale di Mosca scomparve così.", "b9942526"]},
"OLAYLAR_EK16:1489-02-26:0":{"b": ["La regina Caterina Cornaro cede Cipro a Venezia — fine dello Stato crociato", "e24d3f3a"], "d": ["Caterina Cornaro, veneziana, che dopo la morte del marito re Giacomo II nel 1473 governava Cipro come regina reggente, non avendo eredi, sotto la pressione del governo veneziano il 26 febbraio 1489 abdicò e cedette i diritti di sovranità sull'isola al doge e alla Repubblica di Venezia; in cambio conservò il titolo di regina e ricevette la contea di Asolo nella Terraferma. Con questa cessione ebbero fine il dominio della dinastia dei Lusignano, in vigore dal 1192, e l'ultimo Stato crociato; l'isola rimase sotto l'amministrazione veneziana fino alla conquista ottomana del 1570-71.", "7f769951"]},
"OLAYLAR_EK16:1492-01-02:0":{"b": ["Caduta di Granada — fine dell'ultimo Stato musulmano nella Penisola Iberica", "46e5201b"], "d": ["Abu Abdallah (Boabdil), ultimo sovrano dell'Emirato nasride di Granada, indebolito da un assedio graduale durato dieci anni e da divisioni interne, il 2 gennaio 1492, in base alle generose condizioni di resa firmate nel novembre 1491 (Capitolazioni di Granada), consegnò le chiavi della città ai Re Cattolici Ferdinando e Isabella; dopo Boabdil, che lasciava l'Alhambra, ebbe fine l'ultimo Stato musulmano nella Penisola Iberica e la Reconquista fu completata. Nello stesso anno sarebbero seguiti l'espulsione degli ebrei (marzo) e il viaggio di Cristoforo Colombo (agosto).", "5dc28ef8"]},
"OLAYLAR_EK16:1500-07-14:0":{"b": ["Battaglia di Vedroša — Mosca sconfigge l'esercito lituano; le terre di Brjansk e Severia restano a Mosca", "d3f61400"], "d": ["Nella guerra moscovita-lituana del 1500-1503 l'esercito moscovita al comando di Daniil Ščenja sbaragliò sul fiume Vedroša, presso Dorogobuž, l'esercito dell'etmano Konstanty Ostrogski e catturò l'etmano. Le città di Brjansk e Severia, prese nella primavera dello stesso anno, restarono in mano a Mosca; alla fine della guerra circa un terzo dei territori lituani era passato a Mosca.", "e5879803"]},
"OLAYLAR_EK16:1503-04-02:0":{"b": ["Tregua Mosca-Lituania — la regione di Černigov-Severia passa a Mosca", "8e4c56f9"], "d": ["La guerra moscovita-lituana del 1500-1503 si concluse con una tregua di sei anni mediata da Ladislao II, re d'Ungheria e Boemia; il Granducato di Lituania dovette cedere al Granducato di Mosca una vasta area che costituiva circa un terzo del Granducato, compresa la regione di Černigov-Severia (Černigov, Novgorod-Severskij, Starodub, dintorni di Brjansk) e alcuni territori nei dintorni di Smolensk e Polack. Fu uno dei maggiori guadagni singoli di Mosca nel processo di 'raccolta' delle terre russe.", "4cb77b9b"]},
"OLAYLAR_EK16:1507-05-24:0":{"b": ["Şeybânî Khan prende Herat e il Khorasan ai Timuridi", "a81d8575"], "d": ["Secondo la voce Şeybânî Han del TDV, il sovrano uzbeko Şeybânî Khan, dopo aver preso tra il 1503 e il 1505 Andijan, Fergana, Hisar, Kunduz e Balkh, nel 913 (1507) conquistò anche Herat, capitale timuride; la voce Khorasan dell'Encyclopaedia Iranica dà la data esatta di questa conquista — la città cadde l'8 Muharrem 913 (20 maggio 1507) e una settimana dopo, il 15 Muharrem (27 maggio), la conquista fu ufficializzata con la lettura della khutba a nome di Şeybânî Khan. L'intero Khorasan, compresa Mashhad, passò nello stesso anno dai Timuridi agli Shaybanidi; ciò significava che la dinastia timuride, dopo la Transoxiana, perdeva anche l'ultima grande roccaforte in Iran.", "cb60730c"]},
"OLAYLAR_EK16:1509-05-17:0":{"b": ["Caduta di Orano in mano spagnola — la campagna nordafricana del cardinale Cisneros", "86ed8ac1"], "d": ["Wahran (Orano), che controllava la rotta marittima del Mediterraneo occidentale ed era il porto di Tlemcen, era cresciuta nel 1492 con il rifugio dei musulmani ed ebrei andalusi fuggiti da Granada. All'inizio del XVI secolo il Regno di Castiglia, che prendeva uno a uno i porti della costa del Maghreb, il 17 maggio 1509 occupò Wahran; la maggior parte della popolazione fu massacrata, il resto fatto prigioniero e in città non rimase popolazione musulmana ed ebraica. Gli Spagnoli ampliarono le mura e le fortezze; Wahran rimase in mano spagnola fino al 1708.", "be7b3b1b"]},
"OLAYLAR_EK16:1514-08-01:0":{"b": ["Smolensk si arrende a Mosca — Vasilij III entra in città", "46c61446"], "d": ["Nel terzo assedio della guerra moscovita-lituana del 1512-1522 la guarnigione lituana si arrese il 31 luglio; l'esercito moscovita entrò solennemente in città il 1° agosto e la popolazione giurò fedeltà a Vasilij III. Smolensk è il maggiore guadagno di Vasilij a occidente; la sconfitta subita poche settimane dopo a Orša non fece riprendere la città.", "803c9255"]},
"OLAYLAR_EK16:1516-01-23:0":{"b": ["I Paesi Bassi legati alla corona spagnola — morte di Ferdinando, ascesa al trono di Carlo V", "fbe0dbd2"], "d": ["Con la morte di Ferdinando II d'Aragona il 23 gennaio 1516, il nipote Carlo V, che già governava dal 1506 come duca di Borgogna i Paesi Bassi (gli attuali Belgio-Olanda-Lussemburgo e parte della Francia settentrionale), divenne erede anche dei troni di Castiglia e Aragona e il 14 marzo 1516 fu proclamato a Bruxelles re di Spagna. Così questi territori, per unione personale, cominciarono a essere considerati legati non al ramo tedesco/austriaco degli Asburgo ma direttamente alla corona spagnola — con l'elezione di Carlo V a imperatore del Sacro Romano Impero nel 1519 le due identità (re di Spagna e imperatore romano-germanico) si sarebbero riunite nella stessa persona, mentre il legame della regione con la Spagna sarebbe durato fino al 1556, quando Carlo V abdicò lasciando l'eredità al figlio Filippo II.", "61f77359"]},
"OLAYLAR_EK16:1527-01-01:0":{"b": ["Il Sultanato di Demak distrugge Majapahit e domina la costa di Giava", "7da602b5"], "d": ["Secondo la voce Demak del TDV, il Sultanato di Demak, primo Stato musulmano indipendente di Giava, fu fondato nell'ultimo quarto del XV secolo da Raden Patah; secondo le fonti giavanesi il Regno indù-buddista di Majapahit, in declino, fu eliminato dagli attacchi di Demak. Nel 1527 Demak conquistò Tuban, che le fonti cinesi ricordano fin dall'XI secolo come importante porto dei sovrani di Majapahit — è l'anno in cui anche gli ultimi resti di Majapahit furono assoggettati a Demak, e segna la svolta nel processo di islamizzazione di gran parte di Giava.", "538d28fb"]},
"OLAYLAR_EK16:1537-01-01:0":{"b": ["La Norvegia ridotta a provincia legata alla corona danese", "8e2f274e"], "d": ["Il re di Danimarca Cristiano III, nel capitolato di incoronazione del 1536 (håndfæstning), dichiarò che la Norvegia non sarebbe più stata considerata un regno separato ma sarebbe stata governata come provincia della Danimarca e che il Consiglio di Stato norvegese (riksråd) era abolito; questa decisione divenne effettiva nel 1537 con l'applicazione anche alla Norvegia dell'Ordinanza ecclesiastica danese, e fu spezzata la resistenza del vescovo Olav Engelbriktsson. Anche se la Norvegia in pratica conservò ancora per un certo tempo le proprie leggi e istituzioni, il suo status politico non era più quello di regno indipendente ma di provincia legata alla corona danese — situazione che sarebbe durata fino al 1814.", "a8c9dee7"]},
"OLAYLAR_EK16:1558-05-01:0":{"b": ["Narva presa dai Russi — la prima grande città della guerra di Livonia", "c21130d7"], "d": ["Gli eserciti di Ivan IV presero Narva; la Russia raggiunse la costa del Baltico. Narva rimase in mano russa fino al passaggio alla Svezia nel 1581.", "8057148b"]},
"OLAYLAR_EK16:1558-07-01:0":{"b": ["Dorpat (Tartu) presa dai Russi", "f941a504"], "d": ["Gli eserciti russi nella campagna estiva del 1558 presero Dorpat (Tartu) e le fortezze circostanti; la città rimase sotto amministrazione russa fino alla Tregua di Jam Zapol'skij del 1582.", "35503ef9"]},
"OLAYLAR_EK16:1561-06-01:0":{"b": ["Reval (Tallinn) passa sotto la protezione svedese — l'Estonia settentrionale passa alla Svezia", "3c183267"], "d": ["Durante la dissoluzione della Confederazione di Livonia, il consiglio cittadino di Reval nel 1561 presentò fedeltà al re di Svezia Erik XIV; l'Estonia settentrionale rimase svedese fino alla Grande guerra del Nord (1721).", "cb752659"]},
"OLAYLAR_EK16:1561-11-28:0":{"b": ["Trattato di Vilnius — dissoluzione della Confederazione di Livonia, Curlandia e Livonia legate alla Polonia-Lituania (esclusa la città di Riga)", "d1ceaad5"], "d": ["Gotthard Kettler, ultimo grande maestro della Confederazione di Livonia, dissoltasi sotto la pressione russa durante la guerra di Livonia, con il trattato firmato a Vilnius il 28 novembre 1561 (Pacta Subiectionis) si pose sotto la protezione di Sigismondo II Augusto, granduca di Lituania e re di Polonia; la maggior parte della Livonia, esclusa la città di Riga, fu legata alla Polonia-Lituania e Kettler divenne il primo duca del Ducato di Curlandia. Fu l'ultimo atto del passaggio dell'Ordine dei Cavalieri di Livonia dal Medioevo all'età moderna.", "bcd4efe9"]},
"OLAYLAR_EK16:1581-01-01:0":{"b": ["La Svezia prende Narva alla Russia", "5a7f7a6a"], "d": ["Negli ultimi anni della guerra di Livonia le forze svedesi presero Narva, in mano russa dal 1558; la città rimase svedese fino al 1704.", "5fee4227"]},
"OLAYLAR_EK16:1581-01-01:1":{"b": ["La città libera di Riga legata alla Polonia-Lituania", "77dba329"], "d": ["Riga, rimasta città libera durante tutta la guerra di Livonia, nel 1581 fu legata alla Confederazione polacco-lituana; la città rimase nella Confederazione fino al passaggio alla Svezia nel 1621.", "ecdf652d"]},
"OLAYLAR_EK16:1581-07-26:0":{"b": ["Atto di abiura (Plakkaat van Verlatinghe) — i Paesi Bassi dichiarano l'indipendenza dalla Spagna", "a632aaee"], "d": ["Mentre proseguivano le guerre degli Ottant'anni, gli Stati Generali (Staten-Generaal) delle province olandesi aderenti all'Unione di Utrecht, con l'Atto di abiura adottato il 26 luglio 1581, dichiararono 'tiranno' il re di Spagna Filippo II e rifiutarono la fedeltà a lui; questo documento è considerato la dichiarazione di fondazione delle Province Unite (Repubblica Olandese) di fatto indipendenti. Il riconoscimento definitivo da parte della Spagna avrebbe atteso Westfalia nel 1648, ma la rottura effettiva è in questo giorno.", "cd96ed5f"]},
"OLAYLAR_EK16:1611-06-13:0":{"b": ["Caduta di Smolensk in mano polacco-lituana — fine dell'assedio di 20 mesi", "4e9678e3"], "d": ["Durante il Periodo dei Torbidi (Smuta) l'esercito del re di Polonia Sigismondo III, il 13 giugno 1611, aprì una breccia nelle mura di Smolensk, assediata dal settembre 1609, facendo esplodere una mina, e prese la città; la resistenza di 20 mesi ebbe fine. Smolensk rimase alla Polonia-Lituania fino al 1654 e questa caduta preparò il terreno della Tregua di Deulino (1618), che sarebbe stata firmata sette anni dopo.", "25d6488d"]},
"OLAYLAR_EK16:1611-07-16:0":{"b": ["Novgorod presa dall'esercito svedese — nel Periodo dei Torbidi la Russia nord-occidentale passa sotto controllo svedese", "a8ab28bb"], "d": ["L'esercito svedese di Jacob De la Gardie prese Novgorod; la città fino al 1617 fu capitale dello 'Stato di Novgorod' sotto protezione svedese e Carlo Filippo fu indicato come candidato zar.", "281592c2"]},
"OLAYLAR_EK16:1617-03-09:0":{"b": ["Trattato di Stolbovo — la Russia perde la costa baltica (Ingria) a favore della Svezia", "175dc175"], "d": ["Il trattato di Stolbovo, che pose fine alla guerra d'Ingria, fu firmato il 27 febbraio 1617 nel villaggio di Stolbovo, a sud del lago Ladoga; mentre la Russia riprendeva Novgorod e gli altri territori del nord, la Svezia tenne la Carelia e l'Ingria (tra Estonia e Finlandia, comprese le fortezze di Ivangorod, Jam, Kopor'e e Orešek) e l'accesso diretto della Russia al Baltico fu tagliato. Questa interruzione sarebbe durata fino alla fondazione di San Pietroburgo da parte di Pietro il Grande nella stessa regione nel 1703.", "7e70e3e6"]},
"OLAYLAR_EK16:1617-03-09:1":{"b": ["Trattato di Stolbovo — la Russia lascia l'Ingria alla Svezia, Novgorod restituita", "e0bcbc7a"], "d": ["La Russia lasciò alla Svezia le rive della Neva e una parte della Carelia (Jam, Kopor'e, Ivangorod, Orešek) e fu tagliata fuori dalla costa del Baltico; la Svezia restituì Novgorod. Questa situazione durò fino alla Grande guerra del Nord di Pietro I.", "bf517525"]},
"OLAYLAR_EK16:1618-12-11:0":{"b": ["Tregua di Deulino — Smolensk, Černigov e Novgorod-Severskij lasciate alla Polonia", "6880d2c1"], "d": ["La Tregua di Deulino, che pose fine alla guerra polacco-russa del 1609-1618, fu firmata l'11 dicembre 1618 e assicurò un armistizio di 14 anni e mezzo; la Russia dovette cedere alla Confederazione polacco-lituana Smolensk (esclusa Vjaz'ma) e 29 città nelle regioni di Černigov e Novgorod-Severskij — fu la perdita territoriale più grave del Periodo dei Torbidi (Smuta). La regione sarebbe rimasta alla Polonia fino alla Tregua di Andrusovo del 1667.", "5c52de5a"]},
"OLAYLAR_EK16:1625-01-01:0":{"b": ["La Svezia prende Tartu (Dorpat) alla Polonia — seconda fase della campagna di Livonia", "46b7c86a"], "d": ["Gustavo II Adolfo nella campagna del 1625 conquistò l'Estonia meridionale e la Livonia settentrionale; Tartu divenne la città svedese in cui nel 1632 sarebbe stata fondata l'Accademia Gustaviana.", "b58d9bd1"]},
"OLAYLAR_EK16:1654-01-18:0":{"b": ["Rada di Perejaslav — i Cosacchi zaporoghi giurano fedeltà allo zar russo", "bcd8f8ef"], "d": ["Bohdan Chmel'nyc'kyj, hetman dei Cosacchi zaporoghi, ribelli dal 1648 contro la Polonia-Lituania, nella Rada di Perejaslav del 18 gennaio 1654 (8 gennaio giuliano), alla quale partecipò la delegazione giunta da Mosca guidata da Vasilij Buturlin, giurò fedeltà allo zar Aleksej Michajlovič; è considerato l'inizio dell'ingresso dell'Etmanato cosacco ucraino sotto la protezione russa e spostò dalla Polonia alla Russia il controllo effettivo della regione di Černigov-Severia — il confine ufficiale sarebbe stato tracciato con la Tregua di Andrusovo del 1667.", "b15d1501"]},
"OLAYLAR_EK16:1654-10-03:0":{"b": ["Riconquista di Smolensk da parte della Russia", "bf0eca92"], "d": ["Durante la guerra polacco-russa iniziata nel 1654, l'esercito russo riprese Smolensk, assediata da luglio, il 3 ottobre 1654 con la resa della guarnigione polacca; la città perduta a favore della Polonia nel 1611 tornò alla Russia dopo 43 anni. Fu uno dei passi più importanti del processo con cui la Russia invertì le perdite del Periodo dei Torbidi e divenne definitivo con la Tregua di Andrusovo del 1667.", "57ca40e6"]},
"OLAYLAR_EK16:1667-02-09:0":{"b": ["Tregua di Andrusovo — Kiev e l'Ucraina della riva sinistra passano alla Russia", "799be067"], "d": ["La Tregua di Andrusovo, che pose fine alla guerra polacco-russa del 1654-1667, assicurò un armistizio di 13 anni e mezzo; la Russia ottenne Smolensk, la regione di Černigov-Severia e l'Ucraina sulla riva sinistra del Dnepr e — inizialmente per due anni, di fatto in modo permanente — la città di Kiev. Questo trattato pose la base giuridica della divisione dei territori ucraini lungo il Dnepr tra Polonia e Russia (e della permanenza di Kiev in Russia).", "94445e3a"]},
"OLAYLAR_EK16:1702-10-22:0":{"b": ["La Russia prende Nöteborg (Orešek) alla Svezia — la prima fortezza sulla Neva della Grande guerra del Nord", "28d180eb"], "d": ["Gli eserciti di Pietro I assediarono e presero Nöteborg (in russo Orešek), all'uscita del Ladoga, e la chiamarono Šlisselburg ('Fortezza-Chiave'); ciò aprì la strada alla Neva e alla fondazione di San Pietroburgo nel 1703.", "3017c2be"]},
"OLAYLAR_EK16:1703-05-27:0":{"b": ["Fondazione di San Pietroburgo — la finestra della Russia sull'Occidente", "ba196be0"], "d": ["Durante la Grande guerra del Nord, sull'isola delle Lepri nel delta della Neva, da poco ripreso alla Svezia, Pietro il Grande il 16/27 maggio 1703 pose le fondamenta della Fortezza di Pietro e Paolo; questo giorno è considerato la data di fondazione della città di San Pietroburgo. Pietro concepì il delta paludoso come una 'finestra' aperta sull'Occidente e la città nel 1712 divenne la nuova capitale della Russia — la regione sarebbe stata ufficialmente legata alla Russia con il trattato di Nystad del 1721.", "24c24aaf"]},
"OLAYLAR_EK16:1708-09-29:0":{"b": ["Presa di Minorca da parte delle forze anglo-olandesi", "3ca66a83"], "d": ["Durante la guerra di successione spagnola le forze anglo-olandesi, che agivano come alleate dell'arciduca d'Austria Carlo VI, al comando del generale James Stanhope il 14 settembre 1708 sbarcarono sull'isola e il 28-29 settembre, crollata la difesa spagnola, presero il controllo di Minorca (la resa ufficiale della fortezza principale, Fort St. Philip, giunse il 24 novembre). Il porto strategico di Minorca, Mahón, sarebbe stato per il secolo seguente il fulcro della contesa anglo-franco-spagnola.", "9188937e"]},
"OLAYLAR_EK16:1714-03-07:0":{"b": ["Trattato di Rastatt — fine della guerra di successione spagnola, i Paesi Bassi spagnoli e Milano passano all'Austria", "3c0e086f"], "d": ["Il trattato di Rastatt, che pose fine tra Francia e Austria alla guerra di successione spagnola, fu firmato il 7 marzo 1714 (Utrecht nel 1713 aveva regolato i rapporti tra Inghilterra e Francia); con il trattato gli Asburgo d'Austria ricevettero i Paesi Bassi spagnoli (l'odierno Belgio) e in Italia Napoli, Milano e la Sardegna. Fu la maggiore espansione territoriale della storia dell'Austria e aggiunse al peso della dinastia asburgica in Europa centrale un nuovo fronte nell'Europa occidentale e meridionale.", "b27fb416"]},
"OLAYLAR_EK16:1721-09-10:0":{"b": ["Trattato di Nystad — fine della Grande guerra del Nord, le coste del Baltico passano alla Russia", "068ffd06"], "d": ["Il trattato di Nystad, che pose fine alla Grande guerra del Nord durata 21 anni, fu firmato in Finlandia il 10 settembre 1721 (30 agosto giuliano); la Svezia cedette alla Russia l'Estonia, la Livonia (compresa Riga), l'Ingria e una parte della Finlandia sud-orientale (Carelia), mentre in cambio riebbe il resto della Finlandia e fu pagato un indennizzo. Il trattato è considerato la fine dello status di grande potenza della Svezia e la sanzione ufficiale dell'ascesa della Russia come impero europeo — Pietro I dopo questa vittoria assunse il titolo di 'Imperatore'.", "f0c4fc4a"]},
"OLAYLAR_EK16:1772-08-05:0":{"b": ["Prima spartizione della Polonia — perdita di territori a favore di Russia e Austria", "2c56a0d8"], "d": ["Con il trattato firmato il 5 agosto 1772 tra Russia, Prussia e Austria fu spartito circa un terzo dei territori della Confederazione polacco-lituana: la Russia prese parte dell'odierna Bielorussia e della Lettonia (compresi Dünaburg, Polack, Vitebsk), l'Austria annesse la Galizia (Leopoli e Podolia occidentale, compresa Yazlovets), la Prussia ricevette la regione costiera, la Prussia Reale. La Dieta polacca ratificò il trattato solo il 30 settembre 1773, sotto pressione. Fu la prima delle tre spartizioni che sarebbero durate fino al 1795.", "6f2b4118"]},
"OLAYLAR_EK16:1793-01-23:0":{"b": ["Seconda spartizione della Polonia — perdita di territori a favore di Russia e Prussia", "31750484"], "d": ["Poiché le riforme costituzionali del 1791 inquietavano Russia e Prussia, i due Stati con il trattato firmato a San Pietroburgo il 23 gennaio 1793 spartirono di nuovo la Polonia: la Russia prese la maggior parte della Lituania-Bielorussia e l'Ucraina occidentale (compresi Kam'janec', Bar, Minsk), la Prussia annesse la Grande Polonia, con Danzica e Poznań — in totale 307.000 km². La Dieta polacca, sotto pressione, dovette ratificare il trattato nello stesso anno; fu una spartizione di breve durata che rinviò di due anni la completa annessione della Polonia. In questo giorno (23 gennaio 1793), con la Seconda spartizione della Polonia, l'Ucraina della riva destra, con Berdyčiv, Fastiv, Žytomyr, Kaniv, Kostjantyniv, Uman' e Čerkasy, passò alla Russia.", "656e71c2"]},
"OLAYLAR_EK16:1795-03-28:0":{"b": ["Il Ducato di Curlandia e Semigallia annesso alla Russia — l'ultimo duca Peter von Biron rinuncia", "8d0e410f"], "d": ["Nel corso della Terza spartizione della Polonia la nobiltà di Curlandia presentò fedeltà a Caterina, il duca Peter von Biron abdicò; la Curlandia divenne un governatorato della Russia (nelle fonti compare anche il 24 ottobre 1795).", "4682774b"]},
"OLAYLAR_EK16:1795-10-24:0":{"b": ["Terza spartizione della Polonia — scomparsa totale dello Stato", "e3c02d6b"], "d": ["Russia, Prussia e Austria con la convenzione a tre firmata a San Pietroburgo il 24 ottobre 1795 spartirono completamente i territori rimasti della Confederazione polacco-lituana: la Russia prese la Lituania (compresi Vilnius e Kaunas) e il resto della Bielorussia, la Prussia la Polonia centrale con Varsavia, l'Austria annesse la regione meridionale con Cracovia. I tre Stati si garantirono inoltre militarmente i reciproci nuovi territori e presero precauzioni contro l'eventualità di una ricostituzione della Polonia. È la scomparsa completa dello Stato polacco-lituano come paese indipendente; non sarebbe stato ricostituito fino al XX secolo.", "a66df675"]},
"OLAYLAR_EK16:1797-05-12:0":{"b": ["Fine della Repubblica di Venezia — il Maggior Consiglio si sciolse", "5efed589"], "d": ["Quando l'esercito della campagna d'Italia di Napoleone invase le acque territoriali veneziane e lanciò un ultimatum alla repubblica, il Maggior Consiglio (Maggior Consiglio) il 12 maggio 1797 accettò di sciogliersi con 512 voti contro 20; l'ultimo doge Ludovico Manin si dimise e il governo aristocratico della Repubblica di Venezia, che durava senza interruzione da oltre 1.100 anni, ebbe fine. I suoi territori furono lasciati dapprima a un'amministrazione democratica provvisoria, poi, con il trattato di Campoformio dell'ottobre 1797, ufficialmente all'Austria.", "8852717b"]},
"OLAYLAR_EK16:1797-06-14:0":{"b": ["Fine della Repubblica di Genova — Napoleone fonda la Repubblica Ligure", "3d3e59ee"], "d": ["Al posto della Repubblica di Genova, affidata a un'amministrazione provvisoria all'inizio di giugno 1797 per la pressione di Napoleone durante la campagna d'Italia, il 14 giugno 1797 fu proclamata la 'Repubblica Ligure' con una costituzione di modello francese; l'antica Repubblica di Genova divenne di fatto uno degli Stati satelliti della Francia. La repubblica sarebbe stata annessa direttamente alla Francia nel 1805 e lasciata al Regno di Sardegna-Piemonte con il Congresso di Vienna del 1815.", "38af1e4b"]},
"OLAYLAR_EK16:1797-10-17:0":{"b": ["Trattato di Campoformio — spartizione di Venezia tra Austria e Francia", "9f29678c"], "d": ["Il trattato di Campoformio, firmato il 17 ottobre 1797 tra Napoleone Bonaparte e il rappresentante austriaco conte Cobenzl, abolì ufficialmente la millenaria Repubblica di Venezia e ne spartì i territori: la parte a est dell'Adige, l'Istria e la costa dalmata (compresi Spalato, Zara, Sebenico e Cattaro) furono lasciate all'Austria, mentre le Isole Ionie (Corfù, Cefalonia, Zante, Leucade e le basi veneziane sulla costa albanese-moreota, comprese Prevesa e Parga) passarono alla Francia. L'Austria cedette inoltre alla Francia i propri territori nei Paesi Bassi (l'odierno Belgio).", "296ee82f"]},
"OLAYLAR_EK16:1800-09-05:0":{"b": ["Resa di Malta all'Inghilterra — fine del blocco francese di due anni", "fedc2867"], "d": ["Malta, presa da Napoleone nel 1798 durante la campagna d'Egitto, poco dopo, con la rivolta della popolazione dell'isola, fu posta sotto il blocco navale della flotta inglese; dopo un assedio e una fame di due anni il comandante francese generale Vaubois si arrese il 5 settembre 1800 al generale inglese Pigot. Malta passò così dalla Repubblica Francese alla protezione inglese e sarebbe stata ufficialmente legata alla corona britannica con il trattato di Parigi del 1814 — divenne la più importante base navale inglese nel Mediterraneo.", "6f406ae3"]},
"OLAYLAR_EK16:1802-03-25:0":{"b": ["Trattato di Amiens — Minorca restituita alla Spagna", "f341e4b8"], "d": ["Il trattato di Amiens (25 marzo 1802), firmato tra Francia, Spagna, Paesi Bassi e Inghilterra, pose temporaneamente fine alla guerra della Seconda coalizione; l'Inghilterra restituì quasi tutti i territori presi durante la guerra (esclusi Ceylon e Trinidad) — tra questi anche Minorca, presa alla Spagna nel 1798. La pace durò un solo anno, nel maggio 1803 la guerra scoppiò di nuovo, ma Minorca dopo questo trattato non passò mai più in mano inglese.", "7986aead"]},
"OLAYLAR_EK16:1809-09-17:0":{"b": ["Trattato di Fredrikshamn (Hamina) — la Svezia cede la Finlandia alla Russia", "c0d407bc"], "d": ["Il trattato di Fredrikshamn (oggi Hamina), che pose fine alla guerra russo-svedese del 1808-1809, fu firmato il 17 settembre 1809; la Svezia cedette alla Russia l'intera Finlandia, comprese le Isole Åland. La Finlandia ottenne lo status di Granducato con ampia autonomia legato all'Impero russo e conservò la fede luterana e il diritto svedese. Ciò significava la fine di fatto dello status di grande potenza della Svezia nel Baltico. Con questo trattato sei province della Finlandia e il Västerbotten fino al fiume Torne (Kokkola, Joensuu, Savonlinna, Tornio, Rovaniemi, Inari e altre) passarono al Granducato di Finlandia legato alla Russia.", "fb46c9a1"]},
"OLAYLAR_EK16:1810-03-04:0":{"b": ["Annessione del Regno di Imereti — il re Salomone II deposto", "5ad36bff"], "d": ["Poiché Salomone II, ultimo re del Regno georgiano occidentale di Imereti, costretto nel 1804 con il Trattato di Elaznauri ad accettare il vassallaggio russo, continuava a resistere alla crescente pressione russa, le truppe russe il 20 febbraio 1810 presero la capitale Kutaisi, deposero Salomone e costrinsero la nobiltà locale a giurare fedeltà allo zar Alessandro I; il Regno di Imereti ebbe così fine di fatto e fu legato all'amministrazione diretta russa. Salomone, fuggito nei territori ottomani, morì in esilio (1815).", "fdccc40f"]},
"OLAYLAR_EK16:1814-01-14:0":{"b": ["Trattato di Kiel — la Danimarca cede la Norvegia alla Svezia", "59ab1601"], "d": ["La Svezia, che dopo la sconfitta di Napoleone a Lipsia aveva attaccato la Danimarca da sud, con il trattato di Kiel firmato il 14 gennaio 1814 ricevette la Norvegia (esclusi Islanda, Isole Fær Øer e Groenlandia) — l'unione dano-norvegese, durata dal 1380, ebbe così ufficialmente fine. In cambio la Svezia lasciò alla Danimarca i propri territori in Pomerania; la Danimarca cedette inoltre Helgoland all'Inghilterra. La Norvegia resistette al trattato con le armi e proclamò la propria costituzione, e la Svezia dovette riconoscerla — il risultato fu un'unione personale (real union) destinata a durare fino al 1905. La Svezia non poté prendere di fatto la Norvegia: il trattato non fu accettato in Norvegia e l'amministrazione rimase a Christian Frederik; l'esercito svedese entrò in Norvegia solo il 26 luglio 1814.", "223aed9a"]},
"OLAYLAR_EK16:1815-06-09:0":{"b": ["Atto finale del Congresso di Vienna — ridisegnata la mappa dell'Europa dopo Napoleone", "fca1c676"], "d": ["L'Atto finale del Congresso di Vienna, firmato tra le grandi potenze (Austria, Russia, Prussia, Inghilterra, Francia) che posero fine alle guerre napoleoniche, fu adottato il 9 giugno 1815 (9 giorni prima di Waterloo) e ridisegnò nel suo insieme la mappa del continente: gli ex Paesi Bassi spagnoli/austriaci e le Province Unite furono riuniti nel 'Regno Unito dei Paesi Bassi', la Repubblica di Genova fu annessa al Regno di Sardegna-Piemonte, la maggior parte del Ducato di Varsavia fu legata alla Russia con il nome di 'Polonia del Congresso' e la Pomerania svedese (Stralsund) passò alla Prussia. Questo solo giorno è considerato l'inizio ufficiale dell'equilibrio europeo del dopoguerra (Concerto d'Europa). Con questo atto Łódź, Częstochowa, Kielce, Radom, Lublin, Chełm e Zamość (Ducato di Varsavia) passarono al Regno di Polonia legato alla Russia, Poznań (Granducato di Posen) alla Prussia, Maastricht e Roermond al Regno dei Paesi Bassi.", "b0c34466"]},
"OLAYLAR_EK16:1820-01-08:0":{"b": ["Trattato Generale di Pace Marittima — i Qawasim e gli altri sceiccati del Golfo vincolati da un trattato con l'Inghilterra", "fc499e19"], "d": ["L'Inghilterra, dopo aver bombardato Ras al-Khaimah nel 1819 e disperso la flotta 'pirata' dei Qasimi, impose il Trattato Generale di Pace Marittima, iniziato l'8 gennaio 1820 e completato entro marzo con la firma a uno a uno degli sceiccati della regione; il trattato vietava la pirateria e la schiavitù e rendeva obbligatorio per le navi portare una bandiera rosso-bianca simile a quella inglese. Con questo trattato la 'Costa dei Pirati' si trasformò col tempo in 'Costa della Tregua' (Trucial Coast); l'egemonia inglese, approfondita dalla tregua marittima perpetua del 1853 e dai trattati di esclusività del 1892, fu l'inizio di un rapporto destinato a durare fino al 1971.", "0b50923a"]},
"OLAYLAR_EK16:1861-02-13:0":{"b": ["Fine dell'assedio di Gaeta — crollo del Regno delle Due Sicilie", "121ae580"], "d": ["Dopo il crollo iniziato con lo sbarco di Garibaldi in Sicilia nel maggio 1860, il re borbonico Francesco II, fuggito da Napoli, fu assediato nella sua ultima fortezza, Gaeta, dal 3 novembre 1860; con il ritiro della flotta francese dalla zona nel gennaio 1861 il blocco navale italiano si strinse e il 13 febbraio 1861 Gaeta si arrese. Francesco II abbandonò il trono e andò in esilio; l'ultimo punto di resistenza del Regno delle Due Sicilie, Civitella del Tronto, sarebbe caduto solo il 20 marzo 1861. Con il crollo del regno i territori in Sicilia (Palermo, Messina, Siracusa, Trapani, Misilmeri) e in Campania (compresa Nola) non erano più sotto l'amministrazione borbonica.", "bb89dfd9"]},
"OLAYLAR_EK16:1861-03-17:0":{"b": ["Proclamazione del Regno d'Italia — unificazione di Sardegna, Toscana e Italia meridionale", "12e52f70"], "d": ["Nella prima seduta del parlamento italiano a Torino, il 17 marzo 1861, fu ufficialmente proclamato il Regno d'Italia e il re di Sardegna-Piemonte Vittorio Emanuele II divenne il primo re dell'Italia unita. Il nuovo regno univa al Regno di Sardegna i territori di Toscana, Emilia-Romagna, Napoli e Sicilia (Due Sicilie), aggregati l'anno precedente con plebisciti; Roma (Stato Pontificio) e Venezia (Austria) restavano ancora fuori — si sarebbero aggiunte rispettivamente nel 1870 e nel 1866.", "d044a9c0"]},
"OLAYLAR_EK16:1866-10-18:0":{"b": ["Caduta di Jizzakh in mano russa — l'ultima fortezza dell'Emirato di Bukhara sulla linea del Syr Darya", "21205a6e"], "d": ["Durante l'avanzata russa in Asia centrale, dopo il tentativo fallito del generale Černjaev nel febbraio 1866, le forze russe al comando del generale Dmitrij Romanovskij, designato al suo posto, nell'ottobre 1866 con un assedio di sette giorni e un violento assalto presero Jizzakh, ultima grande fortezza dell'Emirato di Bukhara nella valle del Syr Darya; questa caduta pose fine di fatto alla resistenza di Bukhara nella regione e aprì all'esercito russo la strada verso Samarcanda.", "b95ba993"]},
"OLAYLAR_EK16:1868-05-14:0":{"b": ["L'esercito russo prende Samarcanda — la città passa dall'Emirato di Bukhara al governatorato generale del Turkestan", "321473be"], "d": ["Le forze russe presero Samarcanda, in mano all'Emirato di Bukhara, e la annetterono alla circoscrizione amministrativa generale del Turkestan. Samarcanda era una città rimasta all'ombra di Bukhara durante l'epoca dei khan uzbeki; con l'amministrazione russa divenne una nuova tappa dell'avanzata russa in Asia centrale.", "3bc56bbe"]},
"OLAYLAR_EK16:1870-09-28:0":{"b": ["Resa di Strasburgo: le truppe tedesche occupano la città", "ef3281f3"], "d": ["Dopo sei settimane di assedio e bombardamento il generale Uhrich firmò di notte la capitolazione a Koenigshoffen; al mattino le porte e la Cittadella furono consegnate alle truppe prussiane e badesi. La città rimase sotto occupazione militare fino al trattato di Francoforte (10 maggio 1871).", "38c8361d"]},
"OLAYLAR_EK16:1870-10-29:0":{"b": ["Resa di Metz: l'esercito di Bazaine depone le armi, le truppe tedesche prendono la fortezza", "8dd66f58"], "d": ["Il protocollo di capitolazione dell'Armata del Reno assediata fu firmato la sera del 27 ottobre; la mattina del 29 ottobre le bandiere prussiane furono issate sui forti e le truppe francesi lasciarono la fortezza. Metz rimase sotto occupazione militare fino al trattato di Francoforte (10 maggio 1871).", "112e1a60"]},
"OLAYLAR_EK16:1882-03-10:0":{"b": ["Passaggio di Assab alla proprietà dello Stato italiano — fondamento della prima colonia italiana", "15ab8732"], "d": ["Il porto di Assab, sulla costa del Mar Rosso, nel 1869 era stato acquistato dai capi afar locali da una compagnia di navigazione privata italiana (Rubattino); con l'assenso dell'Inghilterra il governo italiano il 10 marzo 1882 assunse la proprietà diretta dello Stato sul porto e con la legge emanata in luglio dichiarò ufficialmente Assab prima colonia dell'Italia. Fu il punto di partenza dell'espansione italiana sulla costa del Mar Rosso, che si sarebbe poi trasformata nella Colonia Eritrea (1890).", "ba606490"]},
"OLAYLAR_EK16:1884-02-08:0":{"b": ["Annientamento della guarnigione di Sinkat — Sinkat passa alle forze mahdiste", "e175a94e"], "d": ["La guarnigione di Sinkat, assediata da mesi dalle forze di Osman Digna e priva ormai di scorte, insieme al suo comandante Tawfiq Bey tentò di rompere l'assedio per raggiungere Suakin; l'8 febbraio 1884 fu annientata fuori dalla fortezza e Sinkat passò nelle mani delle forze mahdiste. La notizia giunse a Suakin il 12 febbraio.", "abf8611c"]},
"OLAYLAR_EK16:1884-02-09:0":{"b": ["Legge marziale a Suakin — la città passa al comando inglese", "801f6a81"], "d": ["Dopo la disfatta del 4 febbraio a El Teb della forza di Baker per il soccorso di Tokar, l'ammiraglio Hewett il 6 febbraio sbarcò fanti di marina a Suakin. Il 9 febbraio 1884 fu proclamata in città la legge marziale e agli ufficiali inglesi fu data piena autorità militare e civile sulla città; il giorno seguente la responsabilità della città fu ufficialmente trasferita da Baker a Hewett.", "92798eb8"]},
"OLAYLAR_EK16:1884-02-20:0":{"b": ["Resa di Tokar alle forze mahdiste", "0e21fd24"], "d": ["La guarnigione assediata di Tokar il 19 febbraio 1884 entrò in trattative con le forze mahdiste e il giorno dopo, il 20 febbraio, consegnò la città. La notizia giunse il 24 febbraio alla forza inglese a Trinkitat; l'operazione di soccorso di Graham era giunta in ritardo.", "0ebad590"]},
"OLAYLAR_EK16:1884-07-14:0":{"b": ["La Gran Bretagna stabilisce il protettorato sulla costa somala settentrionale — inizio del Somaliland", "f301ea94"], "d": ["Secondo la voce Somali del TDV, Zeila, Berbera e Tadjoura nel 1884 furono colonizzate dagli Inglesi con il nome di Somaliland; secondo la fonte accademica standard questo processo iniziò con il trattato firmato a Berbera con la tribù Habar Awal il 21 Ramazan 1301 (14 luglio 1884) e si estese nel 1884-1886 con la firma di trattati simili con le tribù Gadabursi, Habar Tolcaala, Habar Gerhajis, Issa e Warsangeli; l'Inghilterra in cambio promise protezione militare. Questa catena di trattati preparò il terreno per la proclamazione ufficiale del Protettorato del Somaliland britannico nel 1887.", "1bce7d3e"]},
"OLAYLAR_EK16:1891-01-01:0":{"b": ["Battaglia di Mulayda — fine del Secondo Stato saudita, il Najd passa ai Rashidi", "1cd3b213"], "d": ["Con i rapporti ormai compromessi per una disputa sulla zakat e per l'arresto di un inviato rashidide, l'esercito dell'emiro del Jebel Shammar Muhammad bin Rashid il 21 gennaio 1891 inflisse a Mulayda, nella regione di Qasim, una pesante sconfitta alle forze saudite guidate da Abd al-Rahman bin Faisal e ai loro alleati; fu la fine di fatto del Secondo Stato saudita, la famiglia Al Saud andò in esilio in Kuwait e l'intero Najd entrò sotto il dominio rashidide; erano compresi anche, a sud, le zone di Dilam (Kharj), Hawta (Hawtat Bani Tamim) e Layla (Aflaj). Il dominio sarebbe durato fino alla ripresa di Riyad da parte del giovane Abd al-Aziz bin Saud nel 1902 (Incursione su Riyad, 16 gennaio 1902).", "b77d8161"]},
"OLAYLAR_EK16:1891-02-19:0":{"b": ["Riconquista di Tokar da parte delle forze anglo-egiziane — ritirata di Osman Digna", "80a2c26a"], "d": ["Tokar, sulla costa del Mar Rosso, in mano dal 1884 a Osman Digna, comandante locale del movimento mahdista, fu ripresa nel febbraio 1891 con le operazioni delle forze anglo-egiziane; Osman Digna dovette ritirarsi sulle montagne. Fu un duro colpo alla presenza dello Stato mahdista sulla costa del Mar Rosso e la regione passò sotto l'amministrazione congiunta anglo-egiziana.", "07bd31cf"]},
"OLAYLAR_EK16:1891-03-03:0":{"b": ["Passaggio della colonna Grenfell per Sinkat — Sinkat esce dal dominio mahdista e torna all'amministrazione anglo-egiziana", "b7539a44"], "d": ["Dopo la ripresa di Tokar nel febbraio 1891 la colonna anglo-egiziana al comando di Grenfell il 3 marzo 1891 partì da Afafit passando per Sinkat e il 7 marzo giunse a Suakin; la colonna trovò completamente sgombra dal nemico la regione in cui non si era più potuto entrare dal 1884. L'8 marzo agli sceicchi riuniti a Suakin fu proclamata, a nome del Chedivè, un'amnistia generale e Sinkat fu di nuovo legata all'amministrazione anglo-egiziana.", "5e77e2d3"]},
"OLAYLAR_EK16:1905-01-01:0":{"b": ["Passaggio della Somalia italiana all'amministrazione diretta dello Stato — liquidazione della Compagnia del Benadir", "8c7d085b"], "d": ["Secondo la voce Somali del TDV, l'Italia aveva stabilito nel 1889-1891 il proprio dominio sulla costa della Somalia meridionale (Benâdir) con accordi con il Sultanato di Zanzibar e con l'Inghilterra e ne aveva inizialmente affidato l'amministrazione a una compagnia commerciale privilegiata (Benadir Company); secondo la fonte accademica standard la concessione di questa compagnia terminò il 24 gennaio 1905 e lo Stato italiano, acquistando la sovranità diretta sulla costa del Benadir (compresi Mogadiscio, Merca, Brava), stabilì l'amministrazione coloniale ufficiale. L'espansione effettiva della colonia verso l'interno (Bardera, Baidoa) si sarebbe completata con il decreto istitutivo del 1908 e negli anni seguenti.", "3ebbbdd3"]},
"OLAYLAR_EK16:1905-06-07:0":{"b": ["Scioglimento dell'Unione Norvegia-Svezia — dichiarazione unilaterale di indipendenza dello Storting", "aaba2935"], "d": ["Dopo che il re Oscar II pose il veto alla richiesta del governo norvegese di istituire consolati separati e dichiarò di non poter formare un nuovo governo, lo Storting (il parlamento) norvegese il 7 giugno 1905 decise all'unanimità che il re di fatto non esercitava più le funzioni di re di Norvegia e che l'unione in vigore dal trattato di Kiel del 1814 era sciolta. Nel plebiscito del 13 agosto 1905 quasi la totalità degli elettori (371.000 contro 184 voti) approvò lo scioglimento; la Svezia, dopo i colloqui di Karlstad, riconobbe ufficialmente l'indipendenza il 26 ottobre 1905.", "94eda38c"]},
"OLAYLAR_EK16:1915-05-08:0":{"b": ["Libau (Liepāja) presa dalle forze tedesche — inizia l'occupazione della Curlandia", "fdb10548"], "d": ["Nell'offensiva estiva tedesca del 1915 si entrò in Curlandia; Libau era la base navale russa sulla costa del Baltico. La maggior parte della Curlandia passò sotto il comando di Ober Ost (fino alla fine del 1918).", "98e7ef58"]},
"OLAYLAR_EK16:1915-08-01:0":{"b": ["Mitau (Jelgava) presa dalle forze tedesche", "eb491281"], "d": ["Mitau, antica capitale ducale della Curlandia, passò sotto controllo tedesco; il fronte di Riga si congelò sulla linea della Daugava rimanendo fermo fino al 1917.", "05882415"]},
"OLAYLAR_EK16:1915-08-18:0":{"b": ["La fortezza di Kovno (Kaunas) presa dai Tedeschi — la Lituania passa sotto occupazione", "9849405b"], "d": ["La 10ª Armata tedesca prese la più grande fortezza della Russia sul Nemunas; la regione della Lituania passò sotto l'amministrazione di Ober Ost e nel 1918 la Taryba proclamò l'indipendenza sotto questa occupazione.", "1f9a43bc"]},
"OLAYLAR_EK16:1915-09-18:0":{"b": ["Vilna (Vilnius) presa dalle forze tedesche", "2781858b"], "d": ["Durante la Grande Ritirata Vilna passò alle forze tedesche e fu legata alla Regione della Lituania di Ober Ost; la città cambiò di mano fino al 1919 tra forze tedesche, sovietiche e polacche.", "d9dddcbb"]},
"OLAYLAR_EK16:1916-11-03:0":{"b": ["Trattato anglo-qatariano — il Qatar passa sotto la protezione inglese", "f61c4e49"], "d": ["Durante la Prima guerra mondiale, con il trattato firmato il 3 novembre 1916 tra il maggiore Percy Cox, rappresentante politico inglese nel Golfo Persico, e lo sceicco del Qatar Abdullah bin Jassim Al Thani, il Qatar accettò di subordinare le proprie relazioni esterne all'approvazione dell'Inghilterra, ottenendo in cambio la garanzia di protezione inglese contro gli attacchi dal mare; questo trattato costituì la base giuridica del rapporto di protezione inglese sul Qatar, destinato a durare fino al 1971, e fu ratificato ufficialmente nel 1918.", "abf30185"]},
"OLAYLAR_EK16:1917-09-03:0":{"b": ["Riga presa dall'8ª Armata tedesca", "df95df19"], "d": ["Le forze tedesche attraversarono la Daugava e presero Riga; la città rimase sotto controllo tedesco fino al novembre 1918 e l'indipendenza lettone fu proclamata sotto questa occupazione (18 novembre 1918).", "e0339705"]},
"OLAYLAR_EK16:1918-11-18:0":{"b": ["Il Consiglio del Popolo di Lettonia proclama l'indipendenza", "fc72a7f7"], "d": ["Il Consiglio del Popolo di Lettonia, riunito al Teatro Nazionale di Riga, proclamò la Repubblica di Lettonia indipendente dall'Impero russo; fu costituito un governo provvisorio guidato da Kārlis Ulmanis. Poche settimane dopo (dicembre 1918) la Russia sovietica attaccò e iniziò la Guerra d'indipendenza. Con questa proclamazione Riga, Jelgava, Liepāja, Ventspils, Cēsis, Daugavpils e Rēzekne furono considerate territorio della Repubblica di Lettonia.", "615adeb0"]},
"OLAYLAR_EK16:1919-01-05:0":{"b": ["L'Armata Rossa entra a Vilnius — il governo lituano evacua la città", "889a97b3"], "d": ["Il governo lituano evacuò Vilnius all'avvicinarsi dell'Armata Rossa; le forze sovietiche entrarono in città e nel febbraio 1919 da lì fu proclamata la Repubblica Sovietica di Lituania-Bielorussia (Litbel). La città sarebbe stata presa dalle forze polacche nell'aprile 1919.", "c3a0c216"]},
"OLAYLAR_EK16:1919-04-21:0":{"b": ["Le forze polacche prendono Vilnius (Wilno) ai Sovietici", "32d36c4a"], "d": ["Le truppe di Józef Piłsudski nell'aprile 1919 presero Wilno all'Armata Rossa; la Lituania continuò a rivendicare la città e la questione di Vilnius avvelenò i rapporti lituano-polacchi del periodo tra le due guerre.", "85e7c434"]},
"OLAYLAR_EK16:1920-10-12:0":{"b": ["Żeligowski proclama la Lituania Centrale — Vilnius capitale di uno Stato fantoccio sostenuto dalla Polonia", "11400510"], "d": ["Il generale Lucjan Żeligowski con il suo 'ammutinamento' prese Vilnius e proclamò la Repubblica della Lituania Centrale; lo Stato durò fino al 24 marzo 1922.", "d8050fe5"]},
"OLAYLAR_EK16:1922-02-28:0":{"b": ["L'Inghilterra revoca il protettorato sull'Egitto e dichiara l'Egitto indipendente", "f8faab66"], "d": ["L'Inghilterra con la dichiarazione del 28 febbraio 1922 pose fine unilateralmente al protettorato in vigore dal 1914 e dichiarò l'Egitto Stato indipendente; questioni come la difesa, le vie di comunicazione e il Sudan furono riservate all'Inghilterra. Due settimane dopo la dichiarazione (15 marzo 1922) il sultano Ahmed Fuad assunse il titolo di re. Sulla mappa lo strato di occupazione inglese nelle città egiziane termina in questo giorno.", "8cde4005"]},
"OLAYLAR_EK16:1922-03-24:0":{"b": ["La Lituania Centrale annessa alla Polonia — Vilnius diventa polacca", "e929fa20"], "d": ["La Dieta di Wilno il 20 febbraio 1922 votò l'annessione; la Dieta polacca la ratificò il 24 marzo 1922. La Conferenza degli Ambasciatori riconobbe il confine nel 1923, la Lituania non lo riconobbe.", "4a067568"]},
"OLAYLAR_EK16:1939-03-22:0":{"b": ["La Lituania accetta l'ultimatum tedesco — la Regione di Memel ceduta alla Germania", "149fb0b2"], "d": ["Per l'ultimatum di Ribbentrop la Lituania lasciò alla Germania la Regione di Klaipėda (Memel); Hitler entrò a Memel il 23 marzo. La regione fu presa dall'Armata Rossa il 28 gennaio 1945.", "75afd979"]},
"OLAYLAR_EK16:1939-09-19:0":{"b": ["L'Armata Rossa occupa Vilnius", "5b25d037"], "d": ["L'Armata Rossa, entrata il 17 settembre nella Polonia orientale, nella notte tra il 18 e il 19 settembre entrò a Vilnius, in mano polacca. Con il patto di mutua assistenza sovietico-lituano del 10 ottobre la città sarebbe stata lasciata alla Lituania e l'esercito lituano vi sarebbe entrato il 28 ottobre.", "285aa71c"]},
"OLAYLAR_EK16:1939-10-28:0":{"b": ["La Lituania riceve Vilnius — il prezzo del patto di mutua assistenza sovietico-lituano", "37ba5976"], "d": ["Vilnius, presa dall'Armata Rossa il 19 settembre 1939, fu lasciata alla Lituania con il patto di mutua assistenza del 10 ottobre 1939; l'esercito lituano entrò in città il 28 ottobre. In cambio guarnigioni sovietiche si stabilirono in Lituania e nel 1940 seguì l'annessione.", "60d2f2bf"]},
"OLAYLAR_EK16:1941-06-23:0":{"b": ["La Germania occupò Grodno", "b7ca9378"], "d": ["Fronte orientale: Barbarossa 1941 e Bagration 1944.", "c6101096"]},
"OLAYLAR_EK16:1941-06-23:1":{"b": ["La Germania occupò Brest-Litovsk", "25898c65"], "d": ["Fronte orientale: Barbarossa 1941 e Bagration 1944.", "c6101096"]},
"OLAYLAR_EK16:1941-07-09:0":{"b": ["Pskov presa dall'esercito tedesco — inizia l'occupazione dei territori russi", "d9822e30"], "d": ["Nella terza settimana di Barbarossa la Wehrmacht entrò a Pskov; la città rimase sotto amministrazione militare tedesca fino al 23 luglio 1944. Fonte: cronologia della città di Pskov, memorialmuseums.org «Memorials in Pskov» — sintesi di ricerca [sintesi].", "c875c7b2"]},
"OLAYLAR_EK16:1941-07-11:0":{"b": ["Vitebsk presa dall'esercito tedesco", "e1e4d7d0"], "d": ["Il Gruppo d'armate Centro prese Vitebsk nelle prime settimane di Barbarossa; la città rimase sotto amministrazione militare tedesca fino al giugno 1944 e gran parte della sua popolazione scomparve.", "aeb95ab0"]},
"OLAYLAR_EK16:1941-07-16:0":{"b": ["Smolensk presa dall'esercito tedesco", "5a7f4e2a"], "d": ["Il Gruppo d'armate Centro prese Smolensk; questa città sulla strada di Mosca rimase occupata per 26 mesi, fino al 25 settembre 1943, e subì grandi distruzioni.", "1cff2f04"]},
"OLAYLAR_EK16:1941-07-26:0":{"b": ["Mogilëv presa dall'esercito tedesco", "4362b7a1"], "d": ["Mogilëv cadde in mano alla Wehrmacht dopo una difesa di 23 giorni; la città rimase occupata fino al 28 giugno 1944.", "082ca73b"]},
"OLAYLAR_EK16:1941-07-28:0":{"b": ["Istituito il Reichskommissariat Ostland — i paesi baltici e la Bielorussia sotto amministrazione civile tedesca", "052d4c08"], "d": ["Con la decisione di Hitler del 17 luglio 1941 i territori occupati dell'Est furono trasferiti all'amministrazione civile; l'Ostland, guidato da Hinrich Lohse, comprendeva Estonia, Lettonia, Lituania e Bielorussia (centro Riga). L'amministrazione civile dell'Estonia fu istituita il 5 dicembre 1941, mentre l'est della Bielorussia rimase sotto amministrazione militare.", "83f60be8"]},
"OLAYLAR_EK16:1941-08-17:0":{"b": ["Narva presa dalle forze tedesco-estoni", "60fc2b6a"], "d": ["Nella Guerra d'estate i volontari estoni e la Wehrmacht presero Narva; la città fu inclusa nell'Ostland e rimase sotto amministrazione tedesca fino al 26 luglio 1944.", "0f32445c"]},
"OLAYLAR_EK16:1941-08-19:0":{"b": ["Novgorod presa dall'esercito tedesco", "4f599b62"], "d": ["Il Gruppo d'armate Nord prese Novgorod; una delle più antiche città della Russia rimase occupata fino al gennaio 1944 e fu in gran parte distrutta.", "ac0d4ff0"]},
"OLAYLAR_EK16:1941-08-19:1":{"b": ["Gomel' presa dall'esercito tedesco", "9d78eb92"], "d": ["Tre giorni dopo l'attacco della Wehrmacht a Gomel' l'Armata Rossa si ritirò completamente dalla città; la città rimase occupata fino al 26 novembre 1943.", "56a11e36"]},
"OLAYLAR_EK16:1941-08-28:0":{"b": ["Tallinn presa dalla 18ª Armata tedesca", "a855ad0d"], "d": ["Con la sanguinosa evacuazione della Flotta sovietica del Baltico a Kronštadt Tallinn cadde; l'Estonia divenne Generalbezirk Estland all'interno dell'Ostland (amministrazione civile il 5 dicembre 1941).", "859cfaf1"]},
"OLAYLAR_EK16:1941-10-03:0":{"b": ["Orël presa dall'esercito tedesco", "3127f454"], "d": ["Nell'operazione Brjansk-Vjaz'ma la 2ª Armata corazzata tedesca prese Orël; la città rimase sotto occupazione fino al 5 agosto 1943.", "f5465227"]},
"OLAYLAR_EK16:1941-10-06:0":{"b": ["Brjansk presa dall'esercito tedesco", "20fa93f8"], "d": ["Al termine della battaglia di Brjansk le forze tedesche entrarono in città; la città rimase sotto occupazione fino al 17 settembre 1943.", "f4a24f91"]},
"OLAYLAR_EK16:1941-11-03:0":{"b": ["Kursk presa dall'esercito tedesco", "a723a00a"], "d": ["Per ordine del comando sovietico Kursk fu evacuata e la 2ª Armata tedesca entrò in città; la città rimase occupata fino all'8 febbraio 1943.", "0d07184e"]},
"OLAYLAR_EK16:1943-02-08:0":{"b": ["Kursk liberata dall'Armata Rossa", "1ac03fba"], "d": ["Al termine dell'offensiva invernale sovietica (la direzione Kursk-Char'kov, seguita all'operazione Voronež-Kastornoe) Kursk fu ripresa; nel luglio dello stesso anno il nome della città fu dato alla battaglia di Kursk.", "68d51be4"]},
"OLAYLAR_EK16:1943-08-05:0":{"b": ["Orël ripresa dall'Armata Rossa — il primo saluto sovietico dopo Kursk", "80bfc68d"], "d": ["La conquista del saliente di Orël e, insieme a Belgorod, il primo saluto di artiglieria a Mosca.", "5714054b"]},
"OLAYLAR_EK16:1943-09-17:0":{"b": ["Brjansk ripresa dall'Armata Rossa", "d0f2a35f"], "d": ["Con l'operazione di Brjansk la città fu ripresa il 17 settembre 1943.", "e6b7799d"]},
"OLAYLAR_EK16:1943-09-25:0":{"b": ["Smolensk liberata dall'Armata Rossa", "6516d85a"], "d": ["Al culmine dell'Operazione Smolensk del 7 agosto-2 ottobre 1943 la città fu ripresa; Smolensk nel 1985 ricevette il titolo di 'città eroe'.", "e355d898"]},
"OLAYLAR_EK16:1943-11-26:0":{"b": ["Gomel' liberata dall'Armata Rossa", "280268c2"], "d": ["Il Fronte bielorusso riprese la città nell'operazione Gomel'-Rečica; è una delle prime grandi liberazioni di città in Bielorussia.", "3402c1b4"]},
"OLAYLAR_EK16:1944-01-20:0":{"b": ["Novgorod liberata dall'Armata Rossa", "52962012"], "d": ["Durante l'operazione Leningrado-Novgorod, Velikij Novgorod fu ripresa il 20 gennaio 1944.", "75ea1a61"]},
"OLAYLAR_EK16:1944-06-26:0":{"b": ["Vitebsk liberata dall'Armata Rossa — Operazione Bagration", "b06be69c"], "d": ["Il 1º Fronte baltico e il 3º Fronte bielorusso circondarono e presero Vitebsk; fu la prima grande liberazione di una città nell'Operazione Bagration.", "9b4d6042"]},
"OLAYLAR_EK16:1944-06-28:0":{"b": ["Mogilëv liberata dall'Armata Rossa — Operazione Bagration", "52fa985d"], "d": ["Il 2º Fronte bielorusso prese Mogilëv e superò la linea del Dnepr.", "22c05c20"]},
"OLAYLAR_EK16:1944-07-03:0":{"b": ["L'Armata Rossa riprende Minsk — Operazione Bagration", "87dc1fb5"], "d": ["Nell'Operazione Bagration, iniziata il 22 giugno, i fronti bielorussi sfondarono il Gruppo d'armate Centro e circondarono Minsk; la città fu ripresa il 3 luglio e a est quasi 50 mila soldati tedeschi rimasero accerchiati. L'amministrazione civile tedesca della Bielorussia (Generalbezirk Weißruthenien) crollò.", "1c35549f"]},
"OLAYLAR_EK16:1944-07-13:0":{"b": ["L'Armata Rossa prende Vilnius", "0172450e"], "d": ["Nell'Operazione Vilnius del 5-13 luglio il 3º Fronte bielorusso circondò la guarnigione tedesca e prese la città (l'operazione «Ostra Brama» dell'Armia Krajowa polacca fu simultanea). Vilnius divenne la capitale della RSS Lituana.", "aaf124b7"]},
"OLAYLAR_EK16:1944-07-16:0":{"b": ["L'Armata Rossa liberò Grodno dall'occupazione tedesca", "1d134151"], "d": ["Fronte orientale: Barbarossa 1941 e Bagration 1944.", "c6101096"]},
"OLAYLAR_EK16:1944-07-23:0":{"b": ["Pskov ripresa dall'Armata Rossa", "f18103aa"], "d": ["Dopo oltre tre anni di occupazione tedesca Pskov fu ripresa dall'Armata Rossa.", "b6fb3c84"]},
"OLAYLAR_EK16:1944-07-26:0":{"b": ["L'Armata Rossa prende Narva", "64854ae3"], "d": ["Narva, rimasta in rovina sulla linea del fronte dal febbraio 1944, fu presa dalle forze sovietiche nell'Operazione Narva del luglio 1944; il nord-est dell'Estonia uscì dall'amministrazione civile tedesca (Generalbezirk Estland).", "74009a05"]},
"OLAYLAR_EK16:1944-07-27:0":{"b": ["Rēzekne presa dall'Armata Rossa — liberata la Lettonia orientale", "e9efd12d"], "d": ["Il 2º Fronte baltico prese Rēzekne; la regione lettone di Latgale uscì dall'amministrazione tedesca.", "eac95aa6"]},
"OLAYLAR_EK16:1944-07-27:1":{"b": ["Daugavpils liberata dall'Armata Rossa", "b4ee6622"], "d": ["La 360ª Divisione di fanteria del 2º Fronte baltico prese Daugavpils (Dünaburg); la seconda città di Latgale uscì dall'amministrazione tedesca.", "b8a7bd0d"]},
"OLAYLAR_EK16:1944-07-27:2":{"b": ["Šiauliai presa dall'Armata Rossa — Operazione Šiauliai", "ccb20729"], "d": ["Il 1º Fronte baltico prese Šiauliai, nodo ferroviario nel nord della Lituania; l'operazione durò dal 5 luglio al 29 agosto 1944 e si giunse al Golfo di Riga.", "444f3101"]},
"OLAYLAR_EK16:1944-07-28:0":{"b": ["L'Armata Rossa liberò Brest-Litovsk dall'occupazione tedesca", "6d5a837a"], "d": ["Fronte orientale: Barbarossa 1941 e Bagration 1944.", "c6101096"]},
"OLAYLAR_EK16:1944-08-01:0":{"b": ["Kaunas presa dall'Armata Rossa — la capitale provvisoria della Lituania esce dall'amministrazione tedesca", "5c2b2c16"], "d": ["Il 3º Fronte bielorusso prese Kaunas; l'ordine del giorno di Stalin del 1° agosto ne annunciò la presa. La città fu capitale provvisoria della Lituania dal 1919 al 1939.", "795fab27"]},
"OLAYLAR_EK16:1944-08-25:0":{"b": ["Tartu presa dall'Armata Rossa — Operazione Tartu", "cc8069ab"], "d": ["Il 3º Fronte baltico ruppe la difesa della 18ª Armata tedesca e prese Tartu; la città rimase per alcune settimane sulla linea del fronte e l'Operazione Tartu si concluse il 6 settembre 1944.", "3e9ef2ba"]},
"OLAYLAR_EK16:1944-09-22:0":{"b": ["L'Armata Rossa entra a Tallinn — le forze tedesche abbandonano la città", "41ae1ec5"], "d": ["Durante l'Operazione Tallinn i Tedeschi lasciarono la città; il governo del Comitato Nazionale Estone, che il 18 settembre aveva preso gli edifici governativi, non riuscì a mantenere l'amministrazione all'ingresso dell'Armata Rossa. L'Estonia tornò sotto amministrazione sovietica.", "a229e09c"]},
"OLAYLAR_EK16:1945-01-28:0":{"b": ["L'Armata Rossa prende Memel (Klaipėda)", "d01ad3dc"], "d": ["Nell'operazione sovietica diretta verso la Prussia Orientale e la costa baltica, il porto di Memel (Klaipėda) fu tolto alla Germania e legato alla RSS Lituana. La regione, ceduta alla Germania nel 1939, uscì così dall'amministrazione tedesca.", "65cf6a00"]},
"OLAYLAR_EK16:1945-05-08:0":{"b": ["Si arrende la Sacca di Curlandia — il Gruppo d'armate Curlandia firma la resa a Govorov", "3c88889b"], "d": ["Il Gruppo d'armate Curlandia tedesco, accerchiato dall'ottobre 1944 nei dintorni di Liepāja-Ventspils, si arrese; la Lettonia occidentale passò sotto controllo sovietico.", "a7bfcc52"]},
"OLAYLAR_EK16:1955-12-01:0":{"b": ["Le forze del sultano dell'Oman entrano nei principali centri dell'Oman interno; l'imamato ibadita termina di fatto", "9a9962a5"], "d": ["Nel dicembre 1955 il sultano dell'Oman si mosse per ristabilire la propria autorità e le sue forze entrarono nei principali centri abitati dell'Oman interno (Bahla, Izki, Nizwa); l'amministrazione dell'imamato ibadita sull'Oman interno terminò di fatto. La fonte dà solo il mese; sulla mappa è indicato il 1° dicembre 1955.", "31f8761e"]},
"OLAYLAR_EK16:1961-06-19:0":{"b": ["Il Kuwait esce dal protettorato britannico e ottiene la piena indipendenza", "e9a86d04"], "d": ["Con lo scambio di note tra Kuwait e Regno Unito del 19 giugno 1961 ebbe fine il protettorato britannico in vigore dall'accordo del 1899 e il Kuwait divenne pienamente indipendente. Sulla mappa lo strato britannico in Kuwait termina in questo giorno.", "eb64fb65"]},
"OLAYLAR_EK16:1971-09-03:0":{"b": ["Il Qatar proclama l'indipendenza con la fine dei trattati con l'Inghilterra", "8f288cc6"], "d": ["Dopo la data in cui ebbero termine i trattati di protezione con la Gran Bretagna, il Qatar il 3 settembre 1971 proclamò l'indipendenza. Sulla mappa lo strato britannico a Doha termina in questo giorno.", "997a4b35"]},
"OLAYLAR_EK17:1369-01-01:0":{"b": ["Le fortezze dell'Istranca: conquista di Pınarhisar, Kırkkilise (Kırklareli) e Vize", "c6b1a9c1"], "d": ["Murad I, che aveva trascorso l'inverno del 1369 nel Palazzo di Edirne, in primavera si mosse di nuovo contro Bisanzio e prese le fortezze di Pınarhisar, Kırkkilise e Vize ai piedi dei monti Istranca. Queste conquiste causarono panico a Istanbul e l'imperatore Giovanni V decise di andare dal papa in cerca di aiuto.", "61aac0e3"]},
"OLAYLAR_EK17:1485-01-01:0":{"b": ["Tashkent passa sotto l'amministrazione di Yunus Khan, khan del Moghulistan", "a37ee010"], "d": ["Durante la lotta per il trono tra i principi timuridi Tashkent e i dintorni passarono nelle mani di Yunus Khan, khan del Chagatai orientale (Moghulistan). Due anni dopo, alla morte di Yunus Khan, gli successe il figlio Mahmud Khan; la città rimase ai khan moghul fino a quando gli Uzbeki di Şeybânî Khan la presero nel 1503.", "07459832"]},
"OLAYLAR_EK17:1504-01-01:0":{"b": ["Babur lascia la Fergana agli Uzbeki e va a Kabul", "69df593c"], "d": ["Babur il Timuride, figlio di Umar Shaykh Mirza, lasciò agli Uzbeki la Fergana, su cui regnava dal 1494, dopo le guerre con Muhammad Şeybânî Khan, e, attraversato l'Hindu Kush, si stabilì a Kabul.", "21d1ed8c"]},
"OLAYLAR_EK17:1513-01-01:0":{"b": ["Piri Reis disegna la più antica mappa del mondo giunta fino a noi", "6ef941f5"], "d": ["Piri Reis a Gallipoli disegnò la mappa del mondo datata 919 (1513); secondo il TDV İslâm Ansiklopedisi tra le fonti della mappa vi sono anche 'le antiche mappe che gli giunsero dal mondo orientale e occidentale e la mappa di Cristoforo Colombo' — cioè si ritiene che porti le tracce della carta nautica originale di Colombo, allora considerata perduta. Presentò la mappa nel 923 (1517) al Cairo a Selim il Severo. Ci è giunto solo un frammento che mostra le coste occidentali/atlantiche (Spagna, Portogallo, Africa occidentale, costa orientale dell'America meridionale); questo frammento fu riportato alla luce nel Palazzo di Topkapı nel 1929 ed è nell'elenco della Memoria del Mondo dell'UNESCO.", "78561b0b"]},
"OLAYLAR_EK17:1534-06-01:0":{"b": ["Consolidamento dei dintorni di Kars: Şüregel, Arpaçay e Digor passano sotto l'amministrazione ottomana", "10f16b5c"], "d": ["Durante la campagna dei Due Iraq (Irakeyn) le fortezze di Pasin, Şüregel e Oltu passarono in mano agli Ottomani; è molto probabile che in quel momento fosse stata annessa anche la fortezza di Kars. L'area di Arpaçay e Digor, a nord e a est di Kars, entrò sotto il controllo ottomano con la stessa operazione.", "f8a4288a"]},
"OLAYLAR_EK17:1538-10-01:0":{"b": ["Fine degli Shirvanshah: Elqas Mirza cattura Shahrukh, lo Shirvan diventa provincia safavide", "e6d64114"], "d": ["Elqas Mirza, inviato da Shah Tahmasp, saccheggiò lo Shirvan, prese la fortezza di Baykurd e catturò lo Shirvanshah Shahrukh, di quindici anni, portandolo a Tabriz. L'amministrazione degli Shirvanshah, che aveva mantenuto a lungo il dominio nella regione, ebbe così fine; lo Shirvan divenne una provincia dello Stato safavide.", "47532c27"]},
"OLAYLAR_EK17:1552-01-01:0":{"b": ["Espansione dell'Odjak di Algeri verso il Sahara — Touggourt-Ouargla resi tributari, conquista definitiva di Tlemcen", "705ec920"], "d": ["Secondo la voce Tilimsan del TDV, nel 960 (1553) un grande esercito inviato da Algeri, al comando di Salih Reis, prese definitivamente la città e pose fine alla dinastia zayyanide, di tre secoli. Nello stesso periodo (1552) Salih Reis organizzò una campagna contro i sultanati indipendenti di Touggourt e Ouargla; le forze ottomane presero Touggourt, avanzarono su Ouargla, i due sultanati furono resi tributari e a Biskra, sulla strada, fu lasciata una guarnigione ottomana permanente. Così il confine dell'Odjak di Algeri per la prima volta superò l'Atlante Telliano e giunse alla riva del Sahara. La grande battaglia davanti a Mostaganem avvenne invece non in quest'anno ma nel 1558: Hasan Pascià vi sconfisse il conte spagnolo di Alcaudete e pose fine agli attacchi spagnoli nel Nord Africa.", "da55aa7d"]},
"OLAYLAR_EK17:1557-01-01:0":{"b": ["Fondazione dell'Eyalet di Abissinia (Habeş) — la costa del Mar Rosso entra nell'amministrazione ottomana", "7dd470ec"], "d": ["L'eyalet, istituito per impedire l'infiltrazione del Portogallo nel Mar Rosso attraverso l'Abissinia, secondo la voce Habeş Eyaleti del TDV fu formalmente fondato il 15 Şâban 962 (5 luglio 1555) e il centro del sanjak fu Suakin. Özdemir Pascià iniziò le operazioni nell'autunno 1555; prese le isole Dahlak, che controllano il porto di Massaua, e il 2 aprile 1557 la città di Massaua, poi Arkiko. La conquista proseguì con l'ingresso della provincia del Tigre nel dominio ottomano nel 1558 e di Debarwa nel 1559.", "7bb5b28b"]},
"OLAYLAR_EK17:1606-10-11:0":{"b": ["Sedefkâr Mehmed Agha nominato architetto capo — l'architetto della moschea del Sultano Ahmed", "27b66fce"], "d": ["Mehmed Agha, preso a palazzo come devşirme tra il 1562 e il 1563 dalla cittadina albanese di Elbasan, formatosi accanto a Mimar Sinan, l'11 ottobre 1606 fu nominato architetto capo ottomano. Il TDV İslâm Ansiklopedisi riporta che una fonte contemporanea lo descrive come 'mite, umile, uomo di parola, devoto e intelligente'. Mehmed Agha, che tre anni dopo per ordine di Ahmed I avrebbe intrapreso la costruzione della moschea del Sultano Ahmed, firmò un'opera vasta, dai restauri alla Kaaba a numerose fontane e moschee a Istanbul e a Edirne. È un racconto popolare diffuso che i sei minareti abbiano provocato una discussione sulla 'parità' con la Kaaba della Mecca; le fonti enciclopediche non lo confermano e definiscono la disposizione solo come 'mai tentata fino ad allora'.", "a4c538fd"]},
"OLAYLAR_EK17:1617-11-22:0":{"b": ["Il nuovo sultano Mustafa I: un prigioniero del 'kafes' dal volto pallido e lo sguardo assente sul trono", "c487b0d1"], "d": ["Mustafa I, salito al trono con la morte di Ahmed I, come primo principe lasciato in vita dal fratello aveva vissuto per anni chiuso a palazzo sotto stretta sorveglianza; il TDV İslâm Ansiklopedisi lo descrive come 'dal volto pallido, dalla barba rada, dai grandi occhi neri e dallo sguardo spento' e annota che questa lunga prigionia aggravò il suo stato psicologico. In questo primo regno di novantasei giorni non fu in grado di condurre gli affari di Stato; si racconta invece che uscisse spesso a caccia, visitasse l'arsenale e perfino gettasse monete d'oro in acqua per guardare i pesci. I Giannizzeri e gli ulema, ritenendolo inadatto al trono, il 26 febbraio 1618 lo deposero e misero al suo posto il nipote quattordicenne Osman II.", "f2d36b20"]},
"OLAYLAR_EK17:1630-08-19:0":{"b": ["Il sogno di viaggio di Evliya Çelebi — dire 'Seyahat' invece di 'Şefaat'", "2d863e22"], "d": ["Secondo il TDV İslâm Ansiklopedisi, Evliya Çelebi lega l'inizio della sua vita di viaggio, che sarebbe durata quarant'anni, a un sogno fatto nella notte di Ashura del Muharrem del 1040 (19 agosto 1630): nel sogno vede il Profeta nella moschea di Ahî Çelebi a Istanbul insieme a una folta congregazione e, per l'emozione, invece di 'şefaat yâ Resûlellah' dice 'seyahat yâ Resûlellah'. Secondo la tradizione il Profeta, sorridendo di questo lapsus, gli annuncia la buona novella dell'intercessione, del viaggio e della visita. Non si sposò mai e dedicò la vita a questa promessa di 'viaggio'.", "ede1feb4"]},
"OLAYLAR_EK17:1632-01-01:0":{"b": ["Le contraddizioni di Murad IV: il divieto dell'alcol di un sultano dedito al bere, il polso del lottatore, l'orecchio del compositore", "3d2ea5e0"], "d": ["Nei primi anni di Murad IV, salito al trono a undici anni, fu determinante l'influenza della madre Kösem Sultan; il TDV İslâm Ansiklopedisi riporta che Kösem, temendo la tendenza al potere del figlio, 'lo spingeva al divertimento, lo distraeva con regali e feste'. Quando verso i vent'anni prese di fatto in mano l'amministrazione, era un sovrano alto, dalle spalle larghe, imponente — si racconta che sollevasse un uomo forte prendendolo per la cintura e lo portasse più volte in giro nella Camera Privata. La contraddizione sorprendente annotata dal TDV è questa: il sultano, di cui si dice che detestasse il tabacco e l'oppio, era eccessivamente dedito al bere, ma ciò nonostante prima delle campagne vietò il caffè, il tabacco e più tardi lo stesso alcol; al tempo stesso possedeva una conoscenza musicale tale da comporre secondo la tradizione dei makam.", "f2aba572"]},
"OLAYLAR_EK17:1632-01-01:1":{"b": ["Il volo con il razzo di Lâgarî Hasan Çelebi — una tradizione di cui Evliya Çelebi è l'unica fonte", "1f02e3f2"], "d": ["Secondo il Seyahatnâme di Evliya Çelebi, Lâgarî Hasan Çelebi, alla presenza di Murad IV, a Sarayburnu costruì con cinquanta oka di polvere da sparo un congegno a razzo a sette canne e, dicendo 'Mio sultano, ti affido a Dio, vado a parlare con il profeta Gesù', salì sul razzo. Secondo la tradizione Hasan Çelebi, salito di circa 250 metri, planò sul mare con strumenti simili ad ali di falco, nuotò e tornò dal sultano e in cambio ottenne un posto di sipahi con uno stipendio giornaliero di settanta akçe.", "ef620ef6"]},
"OLAYLAR_EK17:1638-12-24:0":{"b": ["Kemankeş Kara Mustafa Pascià diventa gran visir — inizia il periodo di riforma finanziaria", "583846a4"], "d": ["Kemankeş Kara Mustafa Pascià, divenuto gran visir il 17 Şâban 1048 (24 dicembre 1638) dopo il martirio di Tayyar Mehmed Pascià nella campagna di Baghdad, sotto il sultano Ibrahim applicò una dura disciplina finanziaria: ridusse a un terzo gli effettivi di giannizzeri e sipahi, corresse il titolo della moneta, rafforzò il sistema del narh. Con la cifra data dal TDV questo risparmio raggiunse 6000 kese all'anno — ma questo stretto controllo gli procurò nemici nell'ambiente del palazzo.", "2de299c2"]},
"OLAYLAR_EK17:1639-01-20:0":{"b": ["Mustafa I morì dopo quindici anni di oblio", "b4c872cd"], "d": ["Mustafa I, deposto per la seconda volta il 10 settembre 1623, fino alla morte visse per quindici anni in una stanza in cui era tenuto chiuso; sugli anni di questo periodo le fonti non danno alcuna informazione. Morì il 15 Ramazan 1048 (20 gennaio 1639) — una parte delle fonti lo considera morte naturale, un'altra sostiene la mano di Murad IV.", "f153eced"]},
"OLAYLAR_EK17:1644-01-01:0":{"b": ["'Ibrahim il Folle' o una malattia altalenante?", "2abc230f"], "d": ["Il TDV İslâm Ansiklopedisi respinge apertamente l'etichetta di 'Ibrahim il Folle' diffusasi nel XX secolo; riporta che il sultano nelle proprie lettere si lamentava di dolori, inappetenza, debolezza alle gambe, sensazione di nebbia in testa, oppressione al petto e svenimenti. D'altra parte le sue risposte coerenti e ragionevoli durante il processo di deposizione contraddicono l'affermazione di uno squilibrio continuo; la voce conclude che la sua condizione 'non era costante ma di gravità variabile'. In questo periodo le responsabilità di Kösem Sultan aumentarono gradualmente e il fatto che Cinci Hoca, chiamato a palazzo, offrisse al sultano conforto spirituale con 'preghiere efficaci' accrebbe il suo potere di intervenire nella politica.", "f3705d31"]},
"OLAYLAR_EK17:1647-01-01:0":{"b": ["L'Incidente della Zibellina (Samur Vak'ası) — la tassa sulle pellicce del gran visir Ahmed Pascià preparò la fine di Ibrahim", "a2a47d62"], "d": ["Mentre la passione del sultano Ibrahim per le pellicce di zibellino e per l'ambra cresceva a palazzo, il gran visir Ahmed Pascià verso il 1647-1648 avviò una pratica che riscuoteva a forza dai dignitari dello Stato il prezzo delle pellicce di zibellino; il TDV İslâm Ansiklopedisi annota che i funzionari la vedevano come un aperto 'haraç'. Quando gli ufficiali giannizzeri rifiutarono in blocco il pagamento, questa resistenza fu la causa scatenante diretta del processo che portò alla deposizione del sultano — i funzionari riuniti la mattina del 7 agosto 1648 uccisero dapprima Ahmed Pascià e il giorno dopo deposero Ibrahim.", "596c6d08"]},
"OLAYLAR_EK17:1648-05-01:0":{"b": ["'Lo Stato lo governano le donne' — la ribellione di Varvar Ali Pascià da Sivas", "5b027357"], "d": ["Varvar Ali Pascià, beylerbey di Sivas, rifiutò di pagare i 30.000 kuruş che Istanbul chiedeva a titolo di 'bayramiye', dicendo 'il reddito annuo di Sivas non copre questa somma'; secondo il TDV İslâm Ansiklopedisi la motivazione della sua rivolta era l'affermazione che, per la malattia del sultano, gli affari di Stato erano passati nelle mani delle donne e che ciò, con i frequenti cambi di governatori, generava instabilità. Nel maggio 1648, benché dapprima avesse ottenuto un successo militare, fu sconfitto da İpşir Mustafa Pascià; fu giustiziato il 20 maggio 1648 e la sua testa fu inviata a Istanbul.", "e45166db"]},
"OLAYLAR_EK17:1686-08-30:0":{"b": ["Perdita di Anabolu (Nauplia) a favore di Venezia — svolta della Guerra di Morea", "9d400557"], "d": ["Secondo la voce Anabolu del TDV, durante l'assedio i musulmani della città che sopravvissero fuggirono nelle isole vicine e in Anatolia (1686). Secondo la fonte accademica standard (Setton, Venice, Austria, and the Turks in the Seventeenth Century) le forze di Königsmarck per due settimane respinsero gli attacchi dell'esercito ottomano di soccorso; quando il 29 agosto l'attacco di İsmail Pascià si concluse con una pesante sconfitta, la fortezza si arrese in pochi giorni. Anabolu era un territorio ottomano acquisito con trattato nel 1540; con la sua perdita il passaggio della penisola di Morea a Venezia si accelerò.", "592908a0"]},
"OLAYLAR_EK17:1687-08-01:0":{"b": ["Mehmed IV rinunciò alla caccia — l'ultimo sussulto alla vigilia della deposizione", "7daa904b"], "d": ["Dopo la disfatta di Mohács (agosto 1687) l'esercito, a cui non era stata pagata la paga (ulûfe), si ribellò e marciò su Istanbul. Mehmed IV fece uccidere Süleyman Pascià, che aveva fatto sparire il sigillo del gran vizierato, e ne mostrò la testa ai soldati e, disperdendo gli attrezzi da caccia e i levrieri, annunciò di essersi pentito — ma questo gesto non bastò a salvare il suo trono e pochi mesi dopo fu deposto.", "3f079bcd"]},
"OLAYLAR_EK17:1688-01-17:0":{"b": ["Resa della fortezza di Munkács (Mukačevo) all'Austria dopo tre anni di assedio", "ca2efc3d"], "d": ["La fortezza di Munkács, assediata dalle forze imperiali alla fine del 1685, resistette per tre anni sotto la guida di Ilona Zrínyi, moglie di Imre Thököly; secondo numerose opere di consultazione pubblicate la fortezza fu consegnata il 17 gennaio 1688 al generale Antonio Caraffa. Fu la caduta di una delle ultime grandi fortezze della resistenza filo-ottomana in Ungheria sul fronte ottomano-asburgico.", "d72ac109"]},
"OLAYLAR_EK17:1711-07-21:0":{"b": ["Baltacı Mehmed Pascià e la tradizione della zarina Caterina", "c1b739f1"], "d": ["Il racconto popolare che lega la salvezza dell'esercito russo assediato sul Prut ai doni/alla tangente inviati da Caterina I a Baltacı Mehmed Pascià fu ripetuto per secoli.", "f28badd1"]},
"OLAYLAR_EK17:1711-07-21:1":{"b": ["La discussione sull'«occasione perduta» sul Prut — due opinioni", "61ee699c"], "d": ["Che ci si accontentasse della pace mentre l'esercito ottomano aveva completamente circondato l'esercito russo fu oggetto di discussione tra gli storici subito dopo il trattato — nelle parole stesse del TDV, 'si è compreso che era stata perduta una grande occasione e questa tesi è stata sviluppata intensamente da chi era di opinione contraria.' Secondo i critici lo zar poteva essere catturato e le armi dell'esercito russo requisite; secondo i difensori, invece, per impedire il rafforzamento della Svezia nell'Europa settentrionale era una 'politica più saggia' indebolire la Russia in modo limitato. Il TDV riporta entrambe le opinioni senza prendere posizione.", "d9f3213c"]},
"OLAYLAR_EK17:1725-01-01:0":{"b": ["Istituito il comitato di trentadue persone per la scienza e la traduzione", "0e3a713c"], "d": ["Durante il gran vizierato di Damad İbrahim Pascià fu istituito a Istanbul un comitato di trentadue dotti-scribi, che, nelle parole del TDV, 'si può considerare l'accademia dell'epoca'. Il comitato rese in turco opere di storia, filosofia e geografia dall'arabo, dal persiano, dal greco e dal latino — tra queste la traduzione della Fisica di Aristotele da parte di Yanyalı Esad Efendi con una squadra di venticinque persone e la presidenza del poeta Nedim di un comitato di traduzione storica. Il giorno non è indicato nel TDV, l'anno è dichiarato.", "69ac19ac"]},
"OLAYLAR_EK17:1730-11-25:0":{"b": ["Mahmud I attirò Patrona Halil a palazzo facendolo cadere in una trappola", "6147059f"], "d": ["Sette settimane dopo l'ascesa al trono Mahmud I, tramite uomini di fiducia — a palazzo Hacı Beşir Agha, fuori il khan di Crimea Kaplan Giray I — attirò dalla propria parte i capi militari e spezzò l'influenza di Patrona Halil. Il 25 novembre 1730 a Topkapı Patrona Halil, Muslu Beşe e Kel Mehmed Agha, convocati a una riunione nella Camera della Circoncisione, furono fatti entrare; al cenno del gran visir Silâhdar Mehmed Pascià trentadue uomini armati, nascosti in precedenza, uscirono e li uccisero tutti e tre. Mahmud I prese così completamente il controllo della rivolta.", "e3d9bb3d"]},
"OLAYLAR_EK17:1731-01-01:0":{"b": ["Humbaracı Ahmed Pascià (Bonneval) posto a capo del Corpo degli Humbaracı", "27b0b1d7"], "d": ["L'ufficiale di origine francese, il cui vero nome era Claude-Alexandre conte di Bonneval, dopo aver servito dapprima negli eserciti francese e austriaco, si convertì all'Islam a Sarajevo prendendo il nome di Ahmed e nel 1729 si rifugiò presso lo Stato ottomano. Ahmed Pascià, posto nel 1731 sotto Mahmud I a capo del Corpo degli Humbaracı, addestrò circa 300 soldati portati dalla Bosnia nella caserma da lui fatta costruire a Üsküdar Ayazma; il loro numero superò presto i 600 e lui stesso diede anche lezioni di matematica. Il tentativo di rivolta intrapreso in Ungheria con Rákóczi a favore della Francia scosse la sua influenza e nel 1738 fu esiliato a Kastamonu. Morì a Istanbul il 23 maggio 1747 e la sua tomba si trova nel cimitero della Mevlevîhâne di Galata.", "5bfbc961"]},
"OLAYLAR_EK17:1738-08-01:0":{"b": ["Ripresa di Semendire (Smederevo) dalle mani degli Asburgo (corona del Regno d'Ungheria) — Guerra del 1737-39", "63dcf604"], "d": ["Secondo la voce Semendire del TDV, la fortezza, lasciata all'Austria nel 1717 con Passarowitz, fu ripresa con l'avanzata ottomana sul fronte Danubio-Sava della guerra ottomano-austriaca iniziata nel 1737; le forze asburgiche (corona del Regno d'Ungheria) poterono resistere nella regione fino all'agosto 1738, dopo di che Semendire rientrò nell'amministrazione ottomana. Il trattato di Belgrado firmato un anno dopo (18-09-1739) avrebbe sancito questo guadagno — insieme a Belgrado e alla Serbia settentrionale.", "9ca857ec"]},
"OLAYLAR_EK17:1738-08-01:1":{"b": ["Ritorno della valle della Morava all'amministrazione ottomana — Jagodina, Kragujevac e Čačak", "b219d3c9"], "d": ["Con la ripresa di Semendire nell'agosto 1738 anche la valle della Morava, rimasta tra Semendire e il corpo principale ottomano, tornò all'amministrazione ottomana: Jagodina, Kragujevac e Čačak sono considerate ottomane da questa data. Le fonti non datano né ricordano separatamente il ritorno di questi tre luoghi; la mappa si basa sul giorno di Semendire. Il trattato di Belgrado (18-09-1739) sancì questa situazione.", "4b38fa55"]},
"OLAYLAR_EK17:1789-04-07:0":{"b": ["Abdülhamid I muore di paralisi leggendo la notizia della caduta di Özi", "6ac60365"], "d": ["Secondo la voce abdulhamid-i del TDV İslâm Ansiklopedisi, Abdülhamid I, la cui salute si era aggravata per l'andamento duro della guerra russo-austriaca, morì per una paralisi improvvisa mentre leggeva il rapporto del gran visir che annunciava l'occupazione della fortezza di Özi da parte dei Russi (11 Receb 1203 / 7 aprile 1789). Il suo corpo fu sepolto a Istanbul, a Bahçekapı, nel mausoleo da lui fatto costruire. Lo stesso giorno salì al trono il nipote Selim III.", "e0b9fc27"]},
"OLAYLAR_EK17:1799-01-03:0":{"b": ["Alleanza difensiva ottomano-russa — difesa comune contro la Francia", "c87079d1"], "d": ["Con l'invasione dell'Egitto da parte di Napoleone, Selim III e lo zar russo Paolo I stipularono un'alleanza difensiva di quattordici articoli e otto anni. Le parti si impegnarono ad avere amici e nemici comuni, all'aiuto reciproco e a non fare paci separate.", "41183e81"]},
"OLAYLAR_EK17:1799-01-21:0":{"b": ["Alleanza difensiva ottomano-Due Sicilie (Napoli) — causa comune contro la Francia", "1d2be816"], "d": ["Di fronte all'occupazione francese dell'Italia, di Malta e dell'Egitto lo Stato ottomano e il Regno delle Due Sicilie stipularono un'alleanza difensiva di nove articoli. Le parti si impegnarono a condurre la guerra insieme, a non fare paci separate e a darsi reciproco aiuto per terra e per mare.", "5a755b31"]},
"OLAYLAR_EK17:1800-04-02:0":{"b": ["Fondata la Repubblica delle Sette Isole — le Isole Ionie sotto protezione russo-ottomana", "08839694"], "d": ["Nel 1799 la flotta congiunta russo-ottomana aveva scacciato i Francesi dalle Isole Ionie (la fortezza di Corfù cadde il 5 marzo 1799); con la convenzione di dodici articoli del 21 marzo 1800 le isole furono costituite come Cezâyir-i Seb'a-i Müctemia Cumhuru (Repubblica delle Sette Isole), autonoma negli affari interni e legata agli Ottomani in quelli esterni. Il periodo tra il 05-03-1799 e questo giorno è un periodo di occupazione congiunta.", "a9d3379e"]},
"OLAYLAR_EK17:1807-07-07:0":{"b": ["Tilsit — i diritti russi sulla Repubblica delle Sette Isole ceduti alla Francia", "98a78beb"], "d": ["Con l'accordo raggiunto a Tilsit tra Russia e Francia la Russia lasciò alla Francia i propri diritti sulle Sette Isole; le truppe francesi si stabilirono sulle isole nell'estate del 1807 e la Repubblica delle Sette Isole scomparve.", "4561dfb9"]},
"OLAYLAR_EK17:1815-11-05:0":{"b": ["Passaggio di Santa Maura (Leucade) e delle Isole Ionie sotto protezione britannica — assetto post-napoleonico", "0af821dc"], "d": ["Santa Maura e le altre Isole Ionie, passate alla Francia nel 1797, dopo la sconfitta definitiva di Napoleone con un trattato speciale firmato a Parigi il 5 novembre 1815 tra Inghilterra, Russia, Austria e Prussia furono lasciate sotto protezione britannica con il nome di 'Stati Uniti delle Sette Isole' — è un documento distinto dal trattato generale di Parigi del 20 novembre 1815. La protezione sarebbe durata fino al 1864, poi le isole sarebbero state cedute alla Grecia.", "b76e9e11"]},
"OLAYLAR_EK18:1455-06-20:0":{"b": ["Conquista di Prizren — centro di sanjak ottomano in Kosovo", "f84c220f"], "d": ["Il 4 Receb 859 (20 giugno 1455) l'esercito ottomano al comando di Mehmed il Conquistatore prese Prizren dopo la guerra con il despota serbo Đurađ Branković — nelle fonti ottomane Vılkoğlu. La città a metà del XIII secolo era passata da Bisanzio al Regno serbo ed era stata residenza reale sotto il re Milutin, lo zar Dušan e il re Uroš; dopo la morte di Dušan la sua importanza era diminuita. Dopo la conquista fu fatta centro di un sanjak e conservò questa qualità per quattro secoli e mezzo, fino al 1912. Prizren, prima della dissoluzione della Jugoslavia, era l'unica città dei Balcani in cui si parlavano insieme tre lingue — albanese, turco e serbo.", "82ab4141"]},
"OLAYLAR_EK19:1789-07-14:0":{"b": ["La caduta della Bastiglia — inizio della Rivoluzione francese", "96e931f1"], "d": ["Nel clima di furia e di crisi economica provocato dal licenziamento del ministro delle finanze Necker da parte di re Luigi XVI (11 luglio 1789), il popolo di Parigi marciò sulla fortezza della Bastiglia chiedendo armi e polvere da sparo. Negli scontri iniziati nel pomeriggio, la fortezza, difesa da un centinaio di guardie soltanto contro oltre tremila insorti, si arrese verso le 17:00; alcuni funzionari, tra cui il governatore Bernard-René de Launay, furono uccisi e sette prigionieri liberati. Quasi vuota e già destinata alla demolizione, la fortezza era il simbolo della tirannia regia — si racconta che a Luigi XVI fu riferito: «No, sire, non è una rivolta, è una rivoluzione». Il 14 luglio è oggi la festa nazionale francese e l'evento è considerato l'inizio simbolico del movimento popolare, che si estese rapidamente a tutto il paese, e della Rivoluzione francese (1789-1799) — la quale, nel decennio successivo, abbattendo la monarchia assoluta avrebbe cambiato in modo duraturo la carta politica dell'Europa e gli equilibri internazionali di cui faceva parte anche l'Impero ottomano.", "ecc8db63"]},
"OLAYLAR_EK20:1315-04-28:0":{"b": ["L'esercito mamelucco entra a Malatya — la città passa dagli Ilkhanidi all'amministrazione mamelucca", "2540363d"], "d": ["I Mamelucchi inviarono su Malatya un esercito al comando di Seyfeddin Tengiz, vice di Damasco; l'esercito entrò in città il 22 Muharrem 715 (28 aprile 1315). Malatya fino ad allora era sotto il dominio ilkhanide ed era il punto chiave della linea ad ovest dell'Eufrate in cui si toccavano le sfere di influenza ilkhanide e mamelucca. Il passaggio di mano della città mostra l'avanzata dei Mamelucchi verso l'Alto Eufrate nella lunga contesa tra i due Stati. Dopo questa data Malatya sarebbe passata per un certo tempo sotto l'amministrazione degli Eretnaoğlu e, dal 1338, sarebbe tornata di nuovo sotto il dominio mamelucco.", "e762cf2c"]},
"OLAYLAR_EK20:1326-10-09:0":{"b": ["Fine del beylik degli Eşrefoğlu — Beyşehir e Seydişehir passano agli Hamidoğlu", "e4e70846"], "d": ["Demirtaş, figlio dell'emiro Çoban, governatore generale ilkhanide dell'Anatolia, si mosse contro i beylik turcomanni che avevano dichiarato la propria indipendenza ed entrò a Beyşehir facendo uccidere Eşrefoğlu Süleyman Şah, che un tempo si era lamentato di lui (9 ottobre 1326). Il beylik degli Eşrefoğlu, fondato alla fine del XIII secolo nella zona di Beyşehir e Seydişehir, ebbe così fine. La voce Hamîdoğulları del TDV dà il seguito: Beyşehir, Seydişehir, Akşehir e Doğanhisar, appartenenti agli Eşrefoğlu eliminati da Demirtaş, furono aggiunte ai confini del beylik di Hamid. Nello stesso anno anche Dündar Bey degli Hamidoğlu fu consegnato a Demirtaş e ucciso. Questi territori nel 1381 sarebbero stati venduti a Murad I per 80.000 monete d'oro e sarebbero passati all'amministrazione ottomana.", "af867ff8"]},
"OLAYLAR_EK20:1338-01-01:0":{"b": ["Malatya torna sotto il dominio mamelucco — fine dell'amministrazione degli Eretnaoğlu", "08b80aa2"], "d": ["Malatya, entrata nell'amministrazione mamelucca nel 1315, negli anni della dissoluzione dello Stato ilkhanide era passata per un certo tempo nelle mani degli Eretnaoğlu. La voce Malatya del TDV dà il ritorno in una frase: dal 1338 la città fu di nuovo dominata dai Mamelucchi. È uno spaccato degli anni in cui nell'Anatolia sud-orientale il vuoto post-ilkhanide era spartito tra Mamelucchi ed Eretna.", "fdd56a26"]},
"OLAYLAR_EK20:1344-10-28:0":{"b": ["Perdita del porto di Smirne a favore della flotta crociata — spezzata la potenza navale degli Aydınoğlu", "775c65fe"], "d": ["La flotta crociata, composta da navi di Venezia, Genova, del Regno di Cipro, dei cavalieri di Rodi e del duca di Nasso su incoraggiamento di papa Clemente VI, tolse il porto di Smirne agli Aydınoğlu (28 ottobre 1344). Il porto era stato preso nel 1328-1329 dal padre di Umur Bey, Mehmed Bey, al genovese Martino Zaccaria ed era la base della potenza navale degli Aydınoğlu nell'Egeo. Nel settembre del 1334 una flotta crociata giunta con lo stesso scopo aveva dovuto ritirarsi; questa seconda spedizione ebbe successo. Umur Bey continuò la resistenza e, unito agli altri beylik turchi, sconfisse la flotta crociata il 17 gennaio 1345, ma il porto non poté essere ripreso.", "de5df043"]},
"OLAYLAR_EK20:1366-01-01:0":{"b": ["Alâeddin Bey dei Karamanoğlu aggiunge Konya, Aksaray e Niğde ai territori dei Karaman", "2b8b0f70"], "d": ["Alâeddin Bey dei Karamanoğlu, che volle approfittare del fatto che il Sultanato mamelucco avesse posto fine al Regno armeno annettendo tutta la Cilicia e dei disordini scoppiati nello Stato degli Eretna nell'Anatolia centrale, aggiunse ai territori karamanidi, in primo luogo Konya (1366-1367), poi Niğde Karahisarı (Yeşilhisar), Aksaray, Akşehir, Ilgın, İshaklı e Kayseri. Konya, per il peso che portava come capitale selgiuchide, per i Karamanoğlu non era solo una città ma una pretesa di legittimità.", "986c1d2e"]},
"OLAYLAR_EK20:1467-01-01:0":{"b": ["Uzun Hasan pose fine allo Stato dei Qaraquyunlu — il bacino del lago di Van passa agli Aqquyunlu", "d8d6c2e8"], "d": ["Il sovrano aqquyunlu Uzun Hasan, nel 1467, cogliendo di sorpresa il suo implacabile nemico, il sovrano qaraquyunlu Jahan Shah, che marciava contro di lui, pose fine allo Stato dei Qaraquyunlu. Con la scomparsa di Jahan Shah, che regnava dal 1438, il bacino del lago di Van — Van, Bitlis, Bargiri (Muradiye), Hoşap e Kotur — passò dai Qaraquyunlu all'amministrazione aqquyunlu. Questa vittoria fece dello Stato aqquyunlu l'unica grande potenza in Anatolia orientale e in Iran e mise Uzun Hasan sulla strada che una generazione dopo lo avrebbe portato a fronteggiare gli Ottomani.", "4d0ea428"]},
"OLAYLAR_EK20:1489-03-04:0":{"b": ["Cem Sultan portato a Roma — diplomazia degli ostaggi e 40.000 ducati l'anno", "1c6715a8"], "d": ["Papa Innocenzo VIII, d'accordo con Pierre d'Aubusson, capo dei cavalieri di Rodi, fece portare Cem Sultan a Roma (4 marzo 1489). Cem si era rifugiato a Rodi il 29 luglio 1482, da lì era passato in territorio sabaudo e infine sotto la custodia papale. Bayezid II aveva accettato di pagare ai cavalieri 40.000 ducati l'anno e di concedere loro libertà di commercio nei territori ottomani in cambio della custodia del fratello. Questo pagamento non era un tributo, ma il prezzo per tenere immobile in Europa il legittimo rivale al trono: se Cem fosse stato libero avrebbe potuto raccogliere un esercito in Anatolia e per di più diventare fonte di legittimità di una crociata. Così una questione dinastica divenne per trent'anni il principale vincolo della politica estera ottomana — è la ragione della prudenza di Bayezid in Occidente. Con la morte di Cem nel 1495 questo vincolo venne meno.", "60ca67f8"]},
"OLAYLAR_EK20:1490-01-01:0":{"b": ["Il Regno di Georgia diviso in tre — Kartli, Kakheti e Imereti con centro Kutaisi", "f9c5f798"], "d": ["Il Regno unito di Georgia, governato dalla dinastia dei Bagratidi, dopo una lunga lotta interna fu ufficialmente diviso in tre regni: a est Kartli, con centro Tbilisi, a nord-est Kakheti e a ovest Imereti, con centro Kutaisi. La voce Gürcistan del TDV conferma la divisione — 'la Georgia fu divisa in tre regni (Kartliya, Kahetya, İmeretiya) e cinque principati'. La divisione fu decisiva nella contesa ottomano-safavide del secolo successivo: secondo il trattato di Amasya del 1555 Imereti, Dadiani, Gurieli e Daveli furono lasciati agli Ottomani; Kartli, Kakheti e Meskheti ai Safavidi. Cioè il fatto che l'atlante leghi la Georgia occidentale e quella orientale a padroni diversi nasce da questa divisione. Selim il Severo, quando era ancora governatore di Trebisonda, nel 1508 aveva reso il Regno di Imereti (Açıkbaş) vassallo e tributario.", "6b0aaa55"]},
"OLAYLAR_EK20:1510-07-25:0":{"b": ["Occupazione di Tripoli di Barberia da parte degli Spagnoli — fine del dominio hafside", "de319d23"], "d": ["Dopo gli Ammaridi, il dominio degli Hafsidi a Tripoli di Barberia durò fino al 1510. In quell'anno la città fu occupata dagli Spagnoli al comando di don Pedro Navarro, conte di Oliveto; i musulmani scampati al massacro lasciarono la città. L'occupazione fu l'estremità orientale della catena di fortezze spagnole sulla costa nordafricana, da Melilla a Tripoli. La popolazione di Tripoli di Barberia nel 925 (1519) avrebbe inviato una delegazione a Istanbul per chiedere aiuto agli Ottomani contro l'invasione spagnola e la città nel 1551 sarebbe stata presa da Turgut Reis e Sinan Pascià ed entrata nell'amministrazione ottomana.", "f65b0ba2"]},
"OLAYLAR_EK20:1530-03-24:0":{"b": ["Malta e Tripoli date ai cavalieri di San Giovanni — nuova base dell'ordine cacciato da Rodi", "2595729e"], "d": ["I cavalieri di San Giovanni (Hospitalier), scacciati da Rodi da Solimano il Legislatore nel 928 (1522), dopo otto anni senza patria furono stabiliti a Malta da Carlo V, re di Spagna e Germania; con la stessa donazione fu affidata all'ordine anche la difesa di Tripoli di Barberia. Malta, con i suoi porti ideali, divenne una base adatta ai cavalieri, efficaci sui mari: si stabilirono dapprima a Birgu, fortificarono il Forte Sant'Angelo e costruirono il Forte San Michele sulla punta di Senglea. Questo insediamento generò una base nemica permanente al centro del Mediterraneo, che tagliava le rotte marittime ottomane; i conflitti, iniziati con l'incursione di Turgut Reis a Gozo nel 947 (1540), sarebbero durati fino all'assedio di Malta del 1565.", "3992bdbc"]},
"OLAYLAR_EK20:1648-10-24:0":{"b": ["Pace di Westfalia — finiscono le guerre dei Trent'anni, l'unità del Sacro Romano Impero si dissolve", "d7719f05"], "d": ["I trattati che posero fine alla guerra dei Trent'anni (1618-1648) furono firmati lo stesso giorno a Münster e a Osnabrück (24 ottobre 1648). Circa trecento principati del Sacro Romano Impero ottennero il diritto di condurre una politica estera propria; l'impero cessò di essere uno Stato e divenne una cornice. La Svezia prese la Pomerania Occidentale e Stettino, il Brandeburgo ottenne la Pomerania Orientale e l'aspettativa sull'arcivescovato di Magdeburgo — qui inizia l'accumulo di territori degli Hohenzollern che nel 1701 avrebbe marciato verso la monarchia. L'indipendenza dei Paesi Bassi e della Svizzera fu ufficialmente riconosciuta. Per gli Ottomani l'importanza è indiretta ma grande: quando gli Asburgo si ritirarono dal fronte occidentale nacque in Europa centrale una potenza in grado di rivolgersi di nuovo a est.", "21478661"]},
"OLAYLAR_EK20:1701-01-18:0":{"b": ["Proclamato il Regno di Prussia — Federico I incoronato a Königsberg", "337a9f74"], "d": ["Federico III, elettore di Brandeburgo, con l'assenso dell'imperatore Leopoldo I si fece incoronare a Königsberg e assunse il titolo di «Re in Prussia» (18 gennaio 1701). Il titolo era tratto dalla Prussia Orientale, perché essa era al di fuori del Sacro Romano Impero e un elettore soggetto all'imperatore poteva essere re solo fuori dai confini dell'impero. I territori sparsi della dinastia degli Hohenzollern da questa data cominciarono a essere designati con il nome di un solo Stato.", "203ac1b3"]},
"OLAYLAR_EK20:1720-09-02:0":{"b": ["La Sardegna passa dalla Spagna alla dinastia dei Savoia — nasce il Regno di Sardegna", "adf778b7"], "d": ["Nell'ultimo anello degli assetti che chiusero la guerra di successione spagnola l'isola di Sardegna fu tolta alla Spagna e data alla dinastia dei Savoia; il duca di Savoia in cambio lasciò la Sicilia e assunse il titolo di re di Sardegna. Cagliari e Sassari uscirono così da due secoli di amministrazione spagnola. Il Regno di Sardegna che ne nacque è il nucleo dello Stato che un secolo e mezzo dopo avrebbe fondato l'unità italiana — cioè la radice del Regno d'Italia che entrò a Roma nel 1870 discende da qui.", "a73abd0e"]},
"OLAYLAR_EK20:1768-05-15:0":{"b": ["La Corsica venduta da Genova alla Francia — Trattato di Versailles", "770343df"], "d": ["La Repubblica di Genova cedette alla Francia la Corsica, che teneva da secoli ma che a causa delle rivolte non riusciva di fatto a controllare. La voce Korsika del TDV dà l'evento in una frase: Genova nel 1768 vendette alla Francia quest'isola di cui non riusciva a prendersi molta cura. La cessione segna il ritiro di Genova dall'ultimo grande possedimento territoriale nel Mediterraneo; l'isola nel 1796 sarebbe passata per un certo tempo in mano inglese, poi sarebbe stata restituita alla Francia. Il fatto che l'isola fosse territorio francese rese suddito francese Napoleone Bonaparte, che sarebbe nato a Ajaccio un anno dopo. In quest'anno (1768) la Corsica, compresa Bastia, fu venduta da Genova alla Francia (TDV Korsika; giorno non confermato).", "c6214397"]},
"OLAYLAR_EK20:1807-07-09:0":{"b": ["Trattato di Tilsit — la Prussia perde metà dei suoi territori, fondato il Ducato di Varsavia", "d30bb2cc"], "d": ["Dopo la disfatta di Jena-Auerstedt la Prussia dovette accettare con Napoleone a Tilsit una pace gravosa (9 luglio 1807). Lasciò tutti i territori a ovest dell'Elba e i territori polacchi ottenuti con le spartizioni del 1793 e del 1795; da questi ultimi fu costituito il Ducato di Varsavia e la zona di Białystok fu data alla Russia. La Prussia perse circa metà della popolazione e del territorio e il suo esercito fu limitato a 42.000 uomini. Nell'atlante Poznań e Toruń da questo giorno passano al Ducato di Varsavia e Białystok alla Russia. Con questo trattato Łódź e Częstochowa (province polacche passate alla Prussia dopo il 1772) passarono al Ducato di Varsavia; Danzica (Gdańsk) divenne città libera indipendente.", "e484982c"]},
"OLAYLAR_EK20:1870-09-20:0":{"b": ["Le truppe italiane entrano a Roma — fine dello Stato Pontificio e compimento dell'unità italiana", "a3689f2e"], "d": ["Quando, con la caduta di Napoleone III nella guerra franco-prussiana, la guarnigione francese a protezione di Roma si ritirò, le truppe italiane entrarono in città e il papa si ritirò in Vaticano. Così lo Stato Pontificio, esistente da oltre mille anni, ebbe fine e il Regno d'Italia, che includeva nell'unità anche Roma, si affacciò come forza politica sulla scena europea e mondiale. È un evento con conseguenze dirette per l'ultimo mezzo secolo dell'atlante: l'Italia unificata è lo Stato che nel 1911 avrebbe preso agli Ottomani Tripoli di Barberia e il Dodecaneso.", "6d9c3e10"]},
"OLAYLAR_EK20:1887-01-07:0":{"b": ["Battaglia di Çelenko — fine dell'Emirato di Harar e occupazione abissina", "5671a0d9"], "d": ["Quando Dâvud divenne imam di Aussa, Harar, rimasta in mezzo ai territori governati dagli Oromo, era tornata a essere un emirato indipendente e aveva conservato questa condizione fino all'occupazione abissina del 1887. L'emiro Abdullah, dichiarato il jihad, il 7 gennaio 1887 con 5000 uomini affrontò gli Abissini a Şeleneko (Çelenko); capito che sarebbe stato sconfitto, fuggì nella regione dell'Ogaden, a sud di Harar. La battaglia mostrò lo squilibrio tra l'esercito abissino dotato di armi da fuoco e le forze dell'emirato e fece scomparire uno degli ultimi emirati musulmani indipendenti al di là del Mar Rosso. Harar, Jijiga e Degehabur furono così annesse all'Abissinia.", "73175130"]},
"OLAYLAR_EK21:1509-01-01:0":{"b": ["Presa di Derbent da parte di Shah Ismail — il dominio safavide raggiunse la porta del Caucaso", "305542c4"], "d": ["Con la sconfitta e l'uccisione dello Shirvanshah Farrukh Yassar nel 1500 Baku e Shamakhi erano passate ai Safavidi, mentre Derbent era rimasta separata ancora per un po'. Shah Ismail nel 1509 prese la città e vi insediò una delle tribù rumlu; così il dominio safavide raggiunse la porta settentrionale del Caucaso, lo stretto passaggio tra il Caspio e le montagne. Con l'ingresso dello Shirvan nel 1538 sotto l'amministrazione safavide diretta il legame si stabilizzò. Derbent sarebbe passata agli Ottomani nella campagna del 1578 e fino al 1607 sarebbe stata il centro di un beylerbeylik di sette sanjak. L'annotazione del TDV è questa: \\\"La fondazione e lo sviluppo dello Stato safavide segnarono l'inizio di una nuova epoca a Derbent. Shah Ismail nel 1509 prese la città e vi insediò una delle tribù rumlu. Quando nel 1538 lo Shirvan entrò sotto il dominio safavide diretto...\\\"", "e301b4f1"]},
"OLAYLAR_EK21:1537-01-01:0":{"b": ["Annessione definitiva di Kars ai territori ottomani — il chiodo della frontiera orientale", "6235c85a"], "d": ["Dopo la distruzione dello Stato aqquyunlu da parte dei Safavidi, Kars per un certo tempo era rimasta in mano a Sevündük Khan Kurçibaşı, dei turcomanni Afshar. Durante la campagna dei Due Iraq (Irakeyn) del Legislatore (940/1534), mentre le fortezze di Pasin, Şüregel e Oltu erano prese, è molto probabile che anche la fortezza di Kars fosse stata legata agli Ottomani; tuttavia la definitiva annessione della città avvenne tre anni dopo. L'annotazione del TDV è questa: \\\"Kars fu annessa definitivamente ai territori ottomani nel 944 (1537) da Dulkadırlı Mehmed Khan, entrato al servizio ottomano.\\\" Poiché la città e la fortezza erano in gran parte in rovina per le lunghe lotte, si intraprese una rapida riparazione; mentre nel 955 (1548) la fortezza era in riparazione i Safavidi attaccarono la città e distrussero di nuovo la fortezza. Kars sarebbe poi rimasta per trecentoquaranta anni la serratura della frontiera nord-orientale ottomana e dopo la guerra del 1877-78 sarebbe stata lasciata alla Russia.", "dff46f96"]},
"OLAYLAR_EK21:1811-04-01:0":{"b": ["Ripresa di Nikopol — fine dell'occupazione russa di sei mesi", "7fb299d7"], "d": ["Le forze russe, passate sulla riva meridionale del Danubio nella guerra ottomano-russa del 1806-1812, avevano preso Nikopol nell'ottobre 1810 al comando del generale Kutuzov. Sei mesi dopo, vedendo di non poter tenere la linea del Danubio, abbandonarono la città; prima di partire fecero saltare in aria gran parte della fortezza. L'annotazione del TDV è questa: \\\"Nell'ottobre dell'anno 1810 (nel periodo della guerra turco-russa del 1808-1812) Nikopol fu presa dalle forze del celebre generale russo Michail Kutuzov. I Russi, prima di lasciare la città, nell'aprile 1811 fecero saltare in aria gran parte della fortezza e arrecarono gravi danni alla città.\\\" Dopo il ritiro delle forze russe gli Ottomani fecero ricostruire la fortezza; l'iscrizione del 1813-1814 è la registrazione di questa riparazione.", "7237449c"]},
"OLAYLAR_EK21:1811-05-01:0":{"b": ["Evacuazione di Silistra — la fortezza centrale del Danubio abbandonata con le mura demolite", "561628bb"], "d": ["Silistra, una delle più forti fortezze ottomane sul Danubio, nel 1810 era stata bombardata dall'artiglieria russa e per l'esplosione di un deposito di armi la fortezza e il sobborgo avevano subito gravi danni. Dopo aver preso la città i Russi scelsero, invece di tenerla, di distruggerne le fortificazioni: il generale Kutuzov ordinò la demolizione delle mura e nel maggio 1811 comunicò allo zar che le mura di Silistra erano state fatte saltare. L'annotazione del TDV: \\\"Nel 1810 la città fu bombardata dai Russi… Dopo la presa della città da parte dei Russi e prima del loro ritiro il generale Kutuzov ordinò la distruzione di Silistra. Nel maggio 1811 comunicò allo zar che le mura di Silistra erano state fatte saltare.\\\" La stessa fortezza sarebbe stata ripresa dai Russi nella guerra del 1827-1828 e Helmuth von Moltke avrebbe descritto in dettaglio quell'assedio.", "d18dd90e"]},
"OLAYLAR_EK22:1794-01-01:0":{"b": ["Fine della dinastia Zand — dominio qajar in Iran", "5dda30a4"], "d": ["Con la sconfitta dell'ultimo sovrano della dinastia Zand, Lotf Ali Khan, la dinastia fondata nel 1751 ebbe fine e tutto l'Iran passò nelle mani di Agha Mohammad Khan. La fondazione ufficiale dello Stato qajar si data a due anni dopo, all'incoronazione di Agha Mohammad Khan a Teheran con la corona di shahanshah (1796); tuttavia il controllo fu assunto nel 1794.", "793d45c6"]},
"OLAYLAR_EK22:1923-07-24:0":{"b": ["Differenze tra Losanna e Sèvres: da una pace imposta a una pace tra pari", "4b578583"], "d": ["Sèvres (10 agosto 1920) fu un documento imposto al governo di Istanbul e mai entrato in vigore; Losanna (24 luglio 1923) è invece la pace che Ankara firmò come parte paritaria e che la Grande Assemblea Nazionale Turca ratificò il 23 agosto 1923 (Losanna artt. 1, 143). Quanto ai confini, Sèvres riporta la frontiera europea della Turchia sulla linea di Çatalca e cede alla Grecia la Tracia orientale, Adrianopoli (Edirne) compresa, insieme a Imbro e Tenedo (Sèvres artt. 27, 84); Smirne e il suo circondario restano nominalmente sotto sovranità turca ma l'amministrazione passa alla Grecia, e dopo cinque anni il parlamento locale può chiedere l'annessione (artt. 65-83). Losanna traccia la linea Maritza-Arda, Edirne e Karaağaç restano alla Turchia, Imbro e Tenedo sono turche (Losanna artt. 2, 12, 14; Protocollo di Karaağaç). Per gli Stretti, Sèvres istituisce una commissione internazionale con competenza su tutte le acque, in cui il membro turco ha un solo voto; le fortificazioni vengono demolite e la zona è aperta all'uso degli Alleati (Sèvres artt. 36-61, 178-180). Losanna conserva il principio del libero transito ma prevede una commissione a presidenza turca, zone smilitarizzate e una guarnigione di 12.000 uomini a Istanbul (Losanna art. 23; Convenzione degli Stretti). Il riconoscimento dell'Armenia, l'arbitrato del presidente degli Stati Uniti sui confini e il piano di autonomia curda (Sèvres artt. 62-64, 88-93) non compaiono a Losanna. Per i territori arabi, l'Egitto, il Sudan e Cipro, Sèvres detta disposizioni dettagliate di cessione (Sèvres artt. 94-97 mandati, artt. 98-100 Hegiaz, artt. 101-122 rinuncia a Egitto, Sudan, Cipro, Marocco, Tunisia e Libia; anche gli intervalli di articoli del TDV sono questi); Losanna formula la rinuncia in modo più breve: le Dodecaneso vanno all'Italia, Cipro all'Inghilterra, il confine di Mossul è rinviato (Losanna artt. 3, 15-21). Sèvres ristabilisce ed estende le capitolazioni, controlla il bilancio e l'indebitamento turchi tramite la Commissione Finanziaria, limita la forza armata (gendarmeria e unità di rinforzo) a 50.000 uomini e vieta l'aviazione militare e navale (Sèvres artt. 155, 164, 191-195, 231-264, 261-263). Losanna abolisce le capitolazioni, ripartisce i debiti e non pone alcun limite separato all'esercito (Losanna artt. 28, 46-63; l'art. 113 abolisce anche gli uffici postali stranieri). Le disposizioni sulle minoranze a Sèvres sono più ampie e aperte all'intervento alleato, mentre a Losanna sono garantite dalla Società delle Nazioni e reciproche (Sèvres artt. 140-151; Losanna artt. 37-45).\n\nConfronto asse per asse:\n• Tracia orientale, Edirne, Çatalca — Sèvres: confine sulla linea di Çatalca; Tracia orientale ed Edirne alla Grecia (artt. 27, 84-85) | Losanna: confine lungo la Maritza e l'Arda; Edirne e Karaağaç restano alla Turchia (art. 2; Protocollo di Karaağaç)\n• Regione di Smirne — Sèvres: sovranità turca, amministrazione ed esercito greci, richiesta di annessione dopo cinque anni (artt. 65-83) | Losanna: nessun articolo di statuto speciale per Smirne; l'Anatolia rientra nei confini della Turchia (artt. 2-3 confine generale; nessuna prova di articolo specifico su Smirne)\n• Stretti e Istanbul — Sèvres: Commissione Internazionale degli Stretti, 1 voto turco; demolizione delle fortificazioni, zona a uso alleato; Istanbul resta in mano turca ma subordinata alla clausola sulle minoranze (artt. 36-61, 178-180) | Losanna: principio del libero transito; commissione a presidenza turca, zone smilitarizzate, guarnigione di 12.000 uomini a Istanbul (art. 23; Convenzione degli Stretti)\n• Armenia e Kurdistan — Sèvres: l'Armenia è riconosciuta, il suo confine è fissato dal presidente degli Stati Uniti; autonomia curda, richiesta di indipendenza dopo un anno (artt. 62-64, 88-93) | Losanna: nessuna disposizione in merito (non compare nei sommari degli artt. 1-143)\n• Isole dell'Egeo, Dodecaneso — Sèvres: Imbro, Tenedo e le isole dell'Egeo alla Grecia; Dodecaneso e Castellorizo (Meis) all'Italia (artt. 84, 122) | Losanna: Imbro e Tenedo alla Turchia, isole dell'Egeo orientale alla Grecia, Dodecaneso e Castellorizo all'Italia (artt. 12-15)\n• Cipro, Egitto, Sudan, territori arabi — Sèvres: mandato su Siria/Mesopotamia e Palestina, Hegiaz indipendente; protettorato sull'Egitto, Sudan, riconoscimento dell'annessione di Cipro (artt. 94-98, 101-117) | Losanna: confine siriano secondo l'accordo franco-turco del 1921, confine iracheno rinviato; rinuncia a Egitto, Sudan, Cipro (artt. 3, 16-20)\n• Capitolazioni — Sèvres: ristabilite ed estese; piano di riforma giudiziaria presso la commissione alleata (artt. 136, 261-263, 308-309) | Losanna: del tutto abolite; scompaiono gli uffici postali stranieri e il Consiglio Superiore di Sanità (artt. 28, 113-114)\n• Controllo finanziario e debiti — Sèvres: la Commissione Finanziaria Alleata controlla bilancio e indebitamento, il Debito Pubblico Ottomano (Düyun-ı Umumiye) si amplia, le risorse sono date in garanzia (artt. 231-264) | Losanna: il Debito Pubblico è ripartito tra gli Stati; i danni di guerra sono reciprocamente condonati (artt. 46-63, 58)\n• Limitazioni militari — Sèvres: esercito di 50.000 uomini, forza aerea e carri armati vietati, Commissioni Alleate di Controllo (artt. 152-207) | Losanna: nessuna limitazione generale; smilitarizzazione solo per le isole greche e le zone degli Stretti e della Tracia (art. 13; Convenzioni degli Stretti e della Tracia)\n• Minoranze — Sèvres: garanzia e diritto di intervento degli Alleati, annullamento dei beni abbandonati (Emval-i Metruke), restituzione (artt. 140-151, 86, 142-144) | Losanna: diritti garantiti dalla Società delle Nazioni alle minoranze non musulmane, diritti musulmani reciproci in Grecia; scambio di popolazioni greco-turco (artt. 37-45; Convenzione sullo scambio)\n• Status giuridico — Sèvres: firmato dal governo di Istanbul, rifiutato da Ankara, mai entrato in vigore (TDV) | Losanna: parte paritaria; ratifica della Grande Assemblea Nazionale il 2 agosto 1923, 213 voti favorevoli e 14 contrari (TDV; artt. 1, 143)", "95c8b4ce"]},
"OLAYLAR_EK2:1327-01-01:0":{"b": ["Conio del primo akçe ottomano", "38d2d638"], "d": ["Il primo akçe d'argento coniato a nome di Orhan Gazi è la proclamazione monetaria della sovranità indipendente del beylik; l'akçe rimase per cinque secoli l'unità monetaria di base.", "8729ab5b"]},
"OLAYLAR_EK2:1362-09-01:0":{"b": ["Istituito il Beylerbeylik di Rumelia", "ffa16089"], "d": ["Le conquiste sulla sponda europea furono riunite sotto un unico tetto militare e amministrativo; il sistema dei beylerbeylik divenne l'ossatura dell'organizzazione provinciale dell'impero.", "9c13c8c3"]},
"OLAYLAR_EK2:1390-01-15:0":{"b": ["Matrimonio di Yıldırım Bayezid con Despina Hatun", "4b10dc6c"], "d": ["Il vassallaggio stabilito con il despotato serbo dopo il Kosovo fu sigillato dal matrimonio di Olivera, figlia di Lazar, con Bayezid — esempio tipico di diplomazia matrimoniale delle origini.", "7d87810a"]},
"OLAYLAR_EK2:1393-01-01:0":{"b": ["Istituito il Beylerbeylik d'Anatolia", "5ef8d3a7"], "d": ["Per l'amministrazione dei territori dei beylik annessi fu organizzato il Beylerbeylik d'Anatolia; l'ordinamento amministrativo a doppia ala Rumelia-Anatolia fu completato.", "55429c02"]},
"OLAYLAR_EK2:1399-06-01:0":{"b": ["Completata la Grande Moschea di Bursa", "27bcc4a5"], "d": ["La grande moschea a venti cupole, costruita con il bottino di Nicopoli, è l'esempio monumentale dell'architettura ottomana delle origini e un museo a cielo aperto della calligrafia.", "b0e811e6"]},
"OLAYLAR_EK2:1453-06-01:0":{"b": ["Destituzione ed esecuzione di Çandarlı Halil Paşa", "5e19438f"], "d": ["Dopo la conquista fu giustiziato il gran visir della nobile famiglia Çandarlı, che si era mostrato distante dall'assedio; per la prima volta un gran visir veniva ucciso per ordine del sultano e si apriva l'epoca dei visir di origine devşirme.", "557b77f5"]},
"OLAYLAR_EK2:1456-06-01:0":{"b": ["La Moldavia resa tributaria", "25bd3693"], "d": ["Il voivodato di Moldavia accettò di pagare tributo; insieme a Valacchia e Transilvania la triplice cintura vassalla a nord del Danubio divenne il cuscinetto settentrionale dell'impero. Altri luoghi annessi nella stessa data: Yaş.", "7cea09ea"]},
"OLAYLAR_EK2:1459-03-07:0":{"b": ["Tributo di Dubrovnik (Ragusa)", "d127c78a"], "d": ["La repubblica mercantile di Ragusa, in cambio di un tributo, si garantì l'autonomia e i privilegi commerciali; si arricchì come finestra ottomana sull'Adriatico. Anche l'isola di Mljet, territorio della repubblica, condivise questo status.", "812b9f2b"]},
"OLAYLAR_EK2:1462-06-01:0":{"b": ["Campagna di Valacchia: il Voivoda Impalatore", "fd4530bb"], "d": ["Con la campagna organizzata contro Vlad Țepeș, che aveva rifiutato di pagare il tributo e ucciso gli ambasciatori, la Valacchia fu ricondotta al vassallaggio; l'attacco notturno e le scene di terrore degli impalamenti divennero leggenda in Europa. Altri luoghi annessi nella stessa data: Bükreş.", "6ae089b4"]},
"OLAYLAR_EK2:1470-12-01:0":{"b": ["Inaugurato il complesso del Conquistatore (Fatih Külliyesi)", "a150ea55"], "d": ["Il complesso, con le sue otto madrase (Sahn-ı Semân), fu il primo grande passo del programma di trasformazione di Costantinopoli in centro del sapere del mondo islamico.", "cbec7a2f"]},
"OLAYLAR_EK2:1472-01-01:0":{"b": ["Ali Kuşçu a Costantinopoli", "8508229d"], "d": ["Ali Kuşçu, l'ultimo grande rappresentante dell'osservatorio di Samarcanda, su invito del Conquistatore divenne müderris alla Madrasa di Santa Sofia; fondò a Costantinopoli la tradizione della matematica e dell'astronomia.", "fd325f60"]},
"OLAYLAR_EK2:1477-01-01:0":{"b": ["Kanunnâme del Conquistatore", "b08944c9"], "d": ["Il primo kanunname consuetudinario completo, che raccoglie l'organizzazione dello Stato, il protocollo e le pene; è discusso per il celebre articolo che consente il fratricidio «per l'ordine del mondo».", "0e654de1"]},
"OLAYLAR_EK2:1478-06-01:0":{"b": ["Conio della prima moneta d'oro ottomana (sultanî)", "2fd5c0dd"], "d": ["Fu coniata la prima moneta d'oro ottomana, equivalente al ducato veneziano; le finanze imperiali entrarono nell'ordine monetario internazionale.", "cac00614"]},
"OLAYLAR_EK2:1478-09-01:0":{"b": ["Trasferimento al Palazzo di Topkapı", "b9cd6a5e"], "d": ["Con il completamento del Nuovo Palazzo (Topkapı) il centro dell'amministrazione dello Stato vi fu trasferito; il palazzo restò per quattro secoli il cervello dell'impero.", "748ada37"]},
"OLAYLAR_EK2:1532-04-27:0":{"b": ["La Repubblica di Firenze divenne ducato — Alessandro de' Medici", "c08764e1"], "d": ["Per la pressione di papa Clemente VII la commissione di governo di Firenze (Balìa) adottò una nuova costituzione; il regime repubblicano di cinque secoli fu abolito e Alessandro de' Medici fu proclamato duca ereditario, salendo di fatto al trono il 1° maggio. Firenze passò così da città-repubblica indipendente a ducato ereditario della dinastia Medici.", "92da65c9"]},
"OLAYLAR_EK2:1534-01-01:0":{"b": ["Nozze di Solimano con Hürrem Sultan", "abc05f26"], "d": ["La celebrazione del nikâh ufficiale di Solimano con Hürrem cambiò radicalmente la tradizione di palazzo; nacque l'istituzione della «Haseki Sultan» e si aprì la porta all'epoca delle donne nella politica dinastica.", "db1f832b"]},
"OLAYLAR_EK2:1536-02-18:0":{"b": ["Prime capitolazioni complete alla Francia", "e2264e48"], "d": ["Come parte dell'alleanza con la Francia contro la morsa asburgica furono firmati privilegi commerciali tra Jean de la Forest e Makbul İbrâhim Paşa; le capitolazioni, allora strumento diplomatico, nel corso dei secoli sarebbero diventate la porta della dipendenza finanziaria.", "e7c6fd84"]},
"OLAYLAR_EK2:1538-06-13:0":{"b": ["Campagna dell'Oceano Indiano: assedio di Diu", "fcd1217a"], "d": ["La flotta partita da Suez attraversò il Mar Rosso e assediò Diu nel Gujarat; benché la fortezza non fu presa, la potenza ottomana si estese per la prima volta all'Oceano Indiano e il monopolio portoghese fu scosso.", "ce118bf7"]},
"OLAYLAR_EK2:1553-12-07:0":{"b": ["Viaggio in India di Seydi Ali Reis", "e5da3b2c"], "d": ["Seydi Ali Reis, incaricato di portare in Egitto la flotta di Bassora, fu trascinato dalle tempeste fino in India; il Mir'âtü'l-memâlik, in cui racconta l'avventura del ritorno, è uno dei primi resoconti di viaggio ottomani.", "bb472cec"]},
"OLAYLAR_EK2:1554-01-01:0":{"b": ["Esecuzione di Pîrî Reis", "63026444"], "d": ["Il grande navigatore e cartografo, tornato dalla campagna di Hormuz dopo aver lasciato la flotta a Bassora, fu giustiziato a 84 anni — una delle decisioni più discusse della nostra storia della scienza.", "e3d1ac3f"]},
"OLAYLAR_EK2:1557-10-16:0":{"b": ["Inaugurato il complesso della Süleymaniye", "1c6458b2"], "d": ["Il complesso che l'architetto Sinan chiamava «opera da compagno» divenne, con le sue madrase, il suo ospedale e la sua biblioteca, il più grande complesso educativo e caritatevole del periodo classico.", "0c203c6b"]},
"OLAYLAR_EK2:1565-05-18:0":{"b": ["Assedio di Malta", "f57f6a85"], "d": ["Malta, chiave del Mediterraneo, fu assediata per quattro mesi; Turgut Reis cadde martire e l'assedio fu tolto. Fu il primo grande passo indietro della marineria dell'epoca di Solimano.", "860ee1bc"]},
"OLAYLAR_EK2:1575-03-01:0":{"b": ["Completata la Moschea Selimiye", "3b0484e1"], "d": ["La Selimiye, che Sinan chiamava «opera da maestro» e in cui un'unica cupola domina lo spazio, è considerata il culmine dell'architettura classica ottomana (Patrimonio mondiale UNESCO).", "9d7cd43c"]},
"OLAYLAR_EK2:1577-01-01:0":{"b": ["Fondato l'Osservatorio di Costantinopoli", "169bdf5d"], "d": ["L'osservatorio di Takiyyüddin, uno dei meglio attrezzati dell'epoca, fu fatto demolire nel 1580 dopo le polemiche seguite alla cometa del 1577; l'astronomia istituzionale fu ritardata di tre secoli.", "7fb471aa"]},
"OLAYLAR_EK2:1578-08-09:0":{"b": ["Vittoria di Çıldır — inizio della guerra orientale", "13125a54"], "d": ["Con la sconfitta dell'esercito safavide a Çıldır si aprirono le porte del Caucaso; fu presa Tbilisi e la Georgia entrò sotto il dominio ottomano.", "0bf34d05"]},
"OLAYLAR_EK2:1583-05-09:0":{"b": ["Battaglia delle Torce — Şirvan definitivamente ottomano", "3bbc23bc"], "d": ["Nella battaglia così chiamata perché proseguì di notte alla luce delle torce i Safavidi furono sconfitti in modo definitivo; il dominio ottomano su Şirvan e Baku fu consolidato.", "e2aa6d1e"]},
"OLAYLAR_EK2:1585-01-01:0":{"b": ["Grande svalutazione — crisi dell'akçe", "9205c3d4"], "d": ["Sotto la pressione delle lunghe guerre e dell'argento americano il contenuto d'argento dell'akçe fu dimezzato; la rivoluzione dei prezzi alimentò la dissoluzione del sistema dei sipahi e il caos dei Celâlî.", "bd2a508f"]},
"OLAYLAR_EK2:1585-09-25:0":{"b": ["Conquista di Tabriz", "6506bdb9"], "d": ["Il serdar Özdemiroğlu Osman Paşa entrò a Tabriz; l'antica capitale dei Safavidi fu posta sotto amministrazione ottomana. Osman Paşa morì pochi settimane dopo nell'accampamento.", "e54b35bd"]},
"OLAYLAR_EK2:1590-03-21:0":{"b": ["Pace di Ferhad Paşa — i confini più estesi a oriente", "c429972f"], "d": ["Con il trattato che pose fine alla guerra di 12 anni, concluso dopo l'arrivo a Costantinopoli dell'ambasciatore dello shah Abbas, Haydar Mirza (18 gennaio 1590), a condizione che i luoghi conquistati restassero agli Ottomani, Tabriz, Karabakh, Şirvan, Georgia e Luristan rimasero agli Ottomani; l'impero raggiunse a oriente i confini più estesi della sua storia.", "41d8b058"]},
"OLAYLAR_EK2:1603-10-21:0":{"b": ["Inizio della guerra ottomano-safavide (1603-1612) — controffensiva di Shah Abbas, perdita di Tabriz", "abf27dd8"], "d": ["Shah Abbas, che aveva riorganizzato il proprio esercito, approfittando dei disordini dei Celâlî passò all'offensiva; Tabriz cadde e le conquiste del Caucaso andarono perdute nel giro di pochi anni. Altri insediamenti perduti nella stessa campagna e subito dopo: Nahçıvan, Hoy, Merend, Selmâs; anche i bey di Karacadağ (Ahar) e di Mukrî tornarono dalla parte safavide.", "b1757da9"]},
"OLAYLAR_EK2:1611-03-25:0":{"b": ["Nascita di Evliya Çelebi", "2b6051ff"], "d": ["Evliya Çelebi, che raccolse i suoi viaggi di oltre cinquant'anni nel Seyahatnâme in dieci volumi, lasciò un panorama senza pari del mondo ottomano del XVII secolo.", "bbd451a3"]},
"OLAYLAR_EK2:1612-11-20:0":{"b": ["Pace di Nasuh Paşa", "bb69e388"], "d": ["Con il trattato che pose fine alla guerra in corso dal 1603 si rinunciò alle conquiste del 1590 e si tornò al confine di Amasya del 1555; fu ristabilito l'equilibrio sul fronte orientale.", "f3ce47a7"]},
"OLAYLAR_EK2:1616-06-09:0":{"b": ["Inaugurata la Moschea del Sultano Ahmed", "e39dfd43"], "d": ["La «Moschea Blu», con i suoi sei minareti e le piastrelle blu di İznik, è l'ultimo grande complesso imperiale del periodo classico.", "c3e55fc5"]},
"OLAYLAR_EK2:1648-08-18:0":{"b": ["Uccisione del sultano İbrahim", "bc4eb452"], "d": ["Con la motivazione della prodigalità e della crisi di governo l'alleanza tra corpi e ulema depose İbrahim; dieci giorni dopo fu fatto strangolare con una fatwa. Salì al trono il settenne Mehmed IV; il potere passò di fatto nelle mani della valide sultan Kösem Sultan.", "b90693f4"]},
"OLAYLAR_EK2:1657-10-06:0":{"b": ["Morte di Kâtib Çelebi", "e167e89d"], "d": ["Vertice della storia del sapere ottomano con la bibliografia Keşfü'z-zunûn e la geografia Cihannümâ; è noto per l'approccio pionieristico che usava fonti europee.", "786ec8d5"]},
"OLAYLAR_EK2:1703-08-22:0":{"b": ["Evento di Edirne — deposizione di Mustafa II", "0291c1cd"], "d": ["La permanenza del sultano a Edirne e la collera per l'influenza di Feyzullah Efendi si trasformarono in una grande rivolta di esercito e artigiani; lo şeyhülislam fu linciato, il sultano fu deposto e il palazzo tornò a Costantinopoli.", "e8740499"]},
"OLAYLAR_EK2:1720-10-08:0":{"b": ["Ambasciatore a Parigi: Yirmisekiz Mehmed Çelebi", "26312a3f"], "d": ["La grande ambasciata inviata in Francia fu la prima osservazione sistematica dell'Occidente sul posto; il suo Sefâretnâme ispirò il rinnovamento dell'Età dei Tulipani.", "aa11c96a"]},
"OLAYLAR_EK2:1727-07-05:0":{"b": ["Fondata la prima stamperia ottomana", "4943f7e5"], "d": ["Fu concesso il permesso di stampare libri in turco; la prima opera, il Vankulu Lügati, fu stampata nel 1729. La stamperia è l'eredità più duratura del rinnovamento dell'Età dei Tulipani.", "a33e45d0"]},
"OLAYLAR_EK2:1740-05-30:0":{"b": ["Le capitolazioni rese permanenti", "d044a79e"], "d": ["I privilegi concessi alla Francia non furono più limitati al sultano ma vincolati a un trattato permanente; il regime delle capitolazioni, divenuto non denunciabile unilateralmente, poté essere abolito solo a Losanna.", "d50899dc"]},
"OLAYLAR_EK2:1773-01-01:0":{"b": ["Fondata la Mühendishâne-i Bahrî-i Hümâyun", "9bf3f439"], "d": ["Fondata dopo il disastro di Çeşme per formare ufficiali di marina moderni, la scuola di ingegneria è la prima istituzione duratura di istruzione tecnica all'occidentale; la scuola di ingegneria terrestre seguì nel 1795.", "b73b2ce6"]},
"OLAYLAR_EK2:1793-06-01:0":{"b": ["Prima ambasciata permanente a Londra", "6b5630eb"], "d": ["Nell'ambito del programma del Nizâm-ı Cedîd furono aperte ambasciate permanenti nelle capitali europee; la diplomazia ottomana passò al principio di reciprocità.", "0321b899"]},
"OLAYLAR_EK2:1808-11-16:0":{"b": ["Morte di Alemdar Mustafa Paşa", "4426534e"], "d": ["Nella rivolta dei giannizzeri iniziata la notte del 15 novembre 1808, il gran visir riformatore, assediato alla Sublime Porta, non vedendo giungere l'aiuto atteso il giorno dopo fece esplodere l'arsenale e morì insieme a centinaia di assalitori; con lui furono sepolti l'ordinamento del Sened-i İttifak e il primo tentativo di riforma.", "04420a26"]},
"OLAYLAR_EK2:1831-11-01:0":{"b": ["Prima gazzetta ufficiale: Takvîm-i Vekāyi", "c637f623"], "d": ["Cominciò la pubblicazione della gazzetta ufficiale dello Stato; è l'inizio della tradizione dell'opinione pubblica moderna e della comunicazione ufficiale.", "b4f1f627"]},
"OLAYLAR_EK2:1838-08-16:0":{"b": ["Trattato commerciale di Balta Limanı", "e790b383"], "d": ["All'Inghilterra fu riconosciuta la posizione più privilegiata anche nel commercio interno e fu abolito il sistema di yed-i vahit (monopolio); mentre la produzione locale restava senza protezione, il trattato divenne il documento della completa apertura del mercato ottomano al libero scambio.", "14089a77"]},
"OLAYLAR_EK2:1842-01-01:0":{"b": ["Fine dell'Emirato del Libano — destituzione di Beşîr Şihâb III", "f85ae454"], "d": ["L'emiro Beşîr II (III), che non riusciva a controllare la contesa cristiano-drusa e gli equilibri interni nella regione dello Shuf, fu destituito nel gennaio 1842; l'ordinamento emirale locale in vigore dal 1516 (per opera dei Ma'noğulları e poi dei Şihâboğulları) ebbe fine e la regione passò all'amministrazione ottomana diretta e poi al sistema della doppia kaymakamlık.", "205abc18"]},
"OLAYLAR_EK2:1844-01-01:0":{"b": ["Tashîh-i sikke: ordinamento Mecidiye", "c77be809"], "d": ["Con la riforma monetaria furono ritirate le monete dal titolo alterato; fu istituito un sistema bimetallico stabile basato sulla lira d'oro (Mecidiye).", "e0642ec8"]},
"OLAYLAR_EK2:1850-01-01:0":{"b": ["Fine del dominio locale della famiglia Harfûş a Baalbek", "8438f4ae"], "d": ["L'influenza della famiglia Harfûş, che dal 1521 (dopo la rivolta di Canbirdi Gazâlî) governava Baalbek come piccola dinastia locale, terminò con il nuovo riordinamento amministrativo della Sublime Porta; la città fu ridotta a ordinario centro di kaza dipendente dal vilayet di Damasco.", "106eabb2"]},
"OLAYLAR_EK2:1851-01-01:0":{"b": ["Fondata la Şirket-i Hayriyye", "462830e7"], "d": ["La società fondata per gestire i vapori sul Bosforo è considerata la prima società per azioni ottomana; gli approdi dei vapori impressero il loro segno sulla vita cittadina.", "b4203b61"]},
"OLAYLAR_EK2:1854-08-24:0":{"b": ["Primo contratto di debito estero", "9017c579"], "d": ["Per finanziare la guerra di Crimea fu contratto sul mercato di Londra il primo prestito estero; il punto raggiunto con 15 indebitamenti in 21 anni fu la moratoria del 1875 e il Düyûn-ı Umûmiyye.", "1c4f9949"]},
"OLAYLAR_EK2:1855-09-14:0":{"b": ["Linea telegrafica a Costantinopoli", "d320f39f"], "d": ["La prima linea telegrafica, stabilita per le necessità della guerra di Crimea, fu aperta al servizio; in pochi decenni l'impero ebbe una delle più estese reti telegrafiche del mondo.", "f59439a3"]},
"OLAYLAR_EK2:1858-06-06:0":{"b": ["Kanunnâme sulle terre", "6bae243a"], "d": ["Il kanunname che modernizzò il diritto fondiario legò all'atto di proprietà (tapu) il possesso effettivo delle terre mîrî; è tra i documenti fondamentali dell'ordinamento della proprietà dell'attuale Medio Oriente.", "395494dc"]},
"OLAYLAR_EK2:1863-01-13:0":{"b": ["Prime lezioni al Dârülfünun", "08f74066"], "d": ["Il Dârülfünun, destinato a impartire istruzione di livello universitario, iniziò a funzionare con lezioni pubbliche; l'istituzione, proseguita a intermittenza, fu aperta in modo permanente nel 1900 e divenne il nucleo dell'Università di Istanbul.", "6218d070"]},
"OLAYLAR_EK2:1864-11-08:0":{"b": ["Regolamento dei Vilâyet", "ad20853b"], "d": ["Al posto dell'ordinamento per eyalet fu istituita l'organizzazione dei vilayet sul modello francese; sull'esempio dell'applicazione del Vilayet del Danubio di Midhat Paşa fu esteso a tutto il paese.", "665b97d3"]},
"OLAYLAR_EK2:1867-06-21:0":{"b": ["Viaggio di Abdülaziz in Europa", "9ff0fa1e"], "d": ["Il primo viaggio in Europa di un sultano ottomano con finalità di pace; l'Esposizione di Parigi e le visite a Londra servirono da vetrina sia della diplomazia sia della modernizzazione.", "bd58ae5d"]},
"OLAYLAR_EK2:1868-09-01:0":{"b": ["Inaugurato il Mekteb-i Sultânî di Galatasaray", "f9688524"], "d": ["Il liceo con insegnamento in francese, con una composizione studentesca senza distinzione di religione e comunità, divenne il simbolo dell'ideale di uguaglianza nell'istruzione del Tanzimat.", "c9d5821d"]},
"OLAYLAR_EK2:1869-04-01:0":{"b": ["Entra in vigore il primo libro della Mecelle", "6475461c"], "d": ["La Mecelle, che raccolse con tecnica legislativa moderna il campo delle obbligazioni e dei beni del diritto islamico, è considerata il primo codice civile islamico; la commissione presieduta da Cevdet Paşa completò i 16 libri nel 1876.", "9669c96e"]},
"OLAYLAR_EK2:1876-05-30:0":{"b": ["Deposizione di Abdülaziz", "eb7397ea"], "d": ["Statisti e alti ufficiali costituzionalisti deposero Abdülaziz con un colpo di Stato silenzioso; la sua morte sospetta cinque giorni dopo e i successivi eventi di Çırağan generarono regolamenti di conti durati anni.", "9523e81b"]},
"OLAYLAR_EK2:1878-05-20:0":{"b": ["Incursione di Çırağan (caso Ali Suâvi)", "d2a9ac87"], "d": ["Il giornalista Ali Suâvi assalì Çırağan per rimettere sul trono Murad V; l'incursione fu repressa nel sangue e il regime di Abdülhamid strinse in modo permanente il cerchio della sicurezza.", "8bd8ba3f"]},
"OLAYLAR_EK2:1884-01-01:0":{"b": ["Istituita la Régie (monopolio del tabacco)", "bad9b030"], "d": ["Le entrate del tabacco furono cedute alla compagnia Régie, a capitale straniero, nell'ambito del Düyûn-ı Umûmiyye; gli scontri sul «contrabbando della Régie» tra contadini e agenti durarono decenni. Altri insediamenti perduti nella stessa data: Zeyla.", "19e84e39"]},
"OLAYLAR_EK2:1898-10-18:0":{"b": ["Visita del Kaiser Guglielmo II a Costantinopoli e Gerusalemme", "2988cd06"], "d": ["La seconda visita dell'imperatore tedesco rafforzò il riavvicinamento ottomano-tedesco; si aprì la strada alla concessione della ferrovia di Baghdad e a Damasco fu pronunciato il discorso sull'«amico dei trecento milioni di musulmani».", "2e385229"]},
"OLAYLAR_EK2:1908-09-01:0":{"b": ["La Ferrovia del Hegiaz a Medina", "95009b9c"], "d": ["La linea di 1464 km, costruita solo con donazioni musulmane e ingegneria locale, raggiunse Medina; il viaggio del pellegrinaggio si ridusse da settimane a giorni. È la più grande opera infrastrutturale dell'epoca di Abdülhamid II.", "a1c98c4c"]},
"OLAYLAR_EK2:1909-04-13:0":{"b": ["Incidente del 31 Mart", "1d7c2bb2"], "d": ["La grande rivolta antico costituzionale si impadronì di Costantinopoli; l'Armata d'Azione venuta da Salonicco soffocò la rivolta e Abdülhamid II fu deposto.", "4885dfd1"]},
"OLAYLAR_EK2:1912-10-26:0":{"b": ["Inizio dell'assedio di Edirne", "234d9b28"], "d": ["La difesa di cinque mesi di Şükrü Paşa divenne un'epopea di resistenza nel disastro balcanico; la città cadde per fame e fu ripresa nel luglio 1913.", "3c3ca395"]},
"OLAYLAR_EK2:1913-01-23:0":{"b": ["Colpo di mano della Sublime Porta", "b304d02d"], "d": ["Il governo, che si preparava a cedere Edirne, fu rovesciato da un assalto armato degli unionisti; il ministro della Guerra Nâzım Paşa fu ucciso. Iniziò il periodo di pieno potere di Unione e Progresso.", "a8a7af44"]},
"OLAYLAR_EK2:1915-07-11:0":{"b": ["Abolizione della Mutasarrıflık del Monte Libano", "b5639051"], "d": ["L'ordinamento della mutasarrıflık autonoma, istituito con il Règlement Organique del 1861 e fondato sul protocollo internazionale rinnovato nel 1864, fu denunciato unilateralmente dallo Stato ottomano durante la Prima guerra mondiale; il Ministero dell'Interno cominciò a nominare nella regione mutasarrıf musulmani direttamente. L'epoca dell'autonomia, in cui tra il 1861 e il 1915 prestarono servizio otto mutasarrıf, fu così chiusa.", "83ff35bc"]},
"OLAYLAR_EK3:1402-08-01:0":{"b": ["Spartizione del paese tra i principi", "82f26bfb"], "d": ["Dopo la disfatta di Ankara Süleyman Çelebi passò in Rumelia e proclamò il sultanato a Edirne; İsa Çelebi tenne Bursa e Çelebi Mehmed la regione di Amasya-Tokat-Sivas. Sulla mappa queste tre parti sono mostrate con colori distinti.", "08baaa0b"]},
"OLAYLAR_EK3:1403-02-01:0":{"b": ["Trattato di Gallipoli: la costa del Mar Nero fino a Misivri lasciata a Bisanzio", "a4164eca"], "d": ["Dopo la disfatta di Ankara, l'emiro Süleyman, che voleva reggersi in Rumelia, firmò a Gallipoli un trattato con l'imperatore bizantino Manuele. Lasciò a Bisanzio Kartal, Pendik e Gebze con alcune isole, in Rumelia Salonicco e la Tessaglia, e sul Mar Nero la fascia costiera fino a Misivri; fu abolito anche il tributo che Bisanzio pagava agli Ottomani. Ahtapolu, İğneada e Rezve, sulla costa dello Istranca, rimasero così per ventun anni sotto amministrazione bizantina; Murad II con la pace del 1424 riprese la maggior parte di questi luoghi.", "ad1af28a"]}
});
